def _version_callback(value: bool) -> bool:
    if value:
        console.print(f"nebius-cxcli {__version__}")
        raise typer.Exit()
    return value


def _cleanup_temp_private_key_files() -> None:
    for key_path in _TEMP_PRIVATE_KEY_FILES:
        try:
            key_path.unlink()
        except FileNotFoundError:
            continue
        except Exception:
            continue


atexit.register(_cleanup_temp_private_key_files)


@app.callback()
def main_callback(
    version: Annotated[
        bool,
        typer.Option("--version", callback=_version_callback, is_eager=True, help="Show version"),
    ] = False,
    component_sources_file: Annotated[
        Path | None,
        typer.Option(
            "--component-sources-file",
            help=(
                "Global optional override for the component sources file. "
                "Use this to point nebius-cxcli at a different component_sources.yaml path. "
                "When omitted, nebius-cxcli resolves the default file name "
                "'component_sources.yaml' from the standard search order "
                "(cwd -> env -> user/global -> repo/bundled)."
            ),
        ),
    ] = None,
    source_profile: Annotated[
        SourceProfile | None,
        typer.Option(
            "--source-profile",
            help=(
                "Global optional override for the active component source profile. "
                "Defaults to portable. portable always uses source.portable. "
                "local prefers source.local and falls back to source.portable when "
                "source.local is unset."
            ),
            case_sensitive=False,
        ),
    ] = None,
) -> None:
    global _RUNTIME_AUTH_OPERATOR_ENV_SNAPSHOT

    _ = version
    _RUNTIME_AUTH_READY_PROJECTS.clear()
    _RUNTIME_AUTH_OPERATOR_ENV_SNAPSHOT = None
    try:
        set_component_sources_file_override(component_sources_file)
        set_component_sources_profile_override(source_profile)
    except ValueError as exc:
        _exit_with_error(RuntimeError(str(exc)))


def _ensure_project_auth_identity(*, project_id: str, client_name: str) -> None:
    auth_config = SimpleNamespace(
        client_info=SimpleNamespace(
            client_name=client_name or "project",
            nebius=SimpleNamespace(project_id=project_id),
        )
    )
    _ensure_runtime_auth_material(auth_config, need_terraform=False)


def _load_context(config_path: Path) -> tuple:
    recover_project_bundle(config_path.absolute().parent)
    generic_command = _GENERIC_SOPERATOR_LIFECYCLE_COMMAND.get()
    if generic_command:
        _require_soperator_lifecycle_scope(
            _read_config_payload(config_path.resolve()),
            command=generic_command,
        )
    readonly_config = load_config(config_path, persist_normalized=False)
    if generic_command:
        _require_soperator_lifecycle_scope(readonly_config, command=generic_command)
    _ensure_runtime_auth_material(readonly_config, need_terraform=False)
    config = load_config(config_path, persist_normalized=True)
    payload = to_plain_data(config)
    if isinstance(payload, dict) and materialize_compute_boot_disk_defaults(payload):
        strip_app_chart_target_refs(payload)
        config = validate_config(payload, base_dir=config_path.parent)
    paths = resolve_project_paths(config_path)
    validate_path_alignment(config, paths)
    return config, paths


def _load_context_readonly(config_path: Path) -> tuple:
    recover_project_bundle(config_path.absolute().parent)
    generic_command = _GENERIC_SOPERATOR_LIFECYCLE_COMMAND.get()
    if generic_command:
        _require_soperator_lifecycle_scope(
            _read_config_payload(config_path.resolve()),
            command=generic_command,
        )
    config = load_config(config_path, persist_normalized=False)
    if generic_command:
        _require_soperator_lifecycle_scope(config, command=generic_command)
    _ensure_runtime_auth_material(config, need_terraform=False)
    payload = to_plain_data(config)
    if isinstance(payload, dict) and materialize_compute_boot_disk_defaults(payload):
        strip_app_chart_target_refs(payload)
        config = validate_config(payload, base_dir=config_path.parent)
    paths = resolve_project_paths(config_path)
    validate_path_alignment(config, paths)
    return config, paths


def _load_runtime_context(
    config_path: Path,
    *,
    chart_meta_cache: _ChartMetaCache | None = None,
) -> tuple:
    validation_cache = _ValidationWorkCache()
    if chart_meta_cache is not None:
        validation_cache.chart_meta_cache = chart_meta_cache
    resolved_source_profile = resolve_component_sources_profile()
    phase_defs = [
        _ValidationPhase("load-config", "Load config and component catalog"),
        _ValidationPhase("active-sources", "Validate active component catalog/settings"),
        _ValidationPhase("dependencies", "Validate component dependencies"),
        _ValidationPhase("module-schema", "Validate Terraform module inputs"),
    ]
    with _ValidationProgress(title="Pre-render validation", phases=phase_defs) as progress:
        config, paths = progress.run("load-config", lambda: _load_context(config_path))
        progress.run(
            "active-sources",
            lambda: _validate_active_component_sources(
                config,
                chart_meta_cache=validation_cache.chart_meta_cache,
            ),
        )
        dependency_issues = progress.run(
            "dependencies",
            lambda: _validate_component_dependencies(
                config,
                chart_meta_cache=validation_cache.chart_meta_cache,
            ),
        )
        if dependency_issues:
            raise RuntimeError(
                "Runtime validation failed:\n  - " + "\n  - ".join(dependency_issues)
            )
        progress.run(
            "module-schema",
            lambda: rendered_module_sources(config, source_profile=resolved_source_profile),
        )
    return config, paths


def _load_generated_context(target_path: Path) -> tuple:
    paths = resolve_generated_paths(target_path)
    return _load_manifest_backed_context(paths)


def _load_generated_infra_context(target_path: Path) -> tuple:
    paths = resolve_generated_infra_paths(target_path)
    return _load_manifest_backed_context(paths)


def _load_generated_flux_context(target_path: Path) -> tuple:
    paths = resolve_generated_flux_paths(target_path)
    return _load_manifest_backed_context(paths)


def _load_deploy_context(target_path: Path) -> tuple:
    paths = resolve_deploy_config_paths(target_path)
    return _load_manifest_backed_context(paths)


def _load_deploy_context_readonly(target_path: Path) -> tuple:
    paths = resolve_deploy_config_paths(target_path)
    manifest = load_generated_manifest(paths.generated_dir)
    config = runtime_config_from_manifest(manifest)
    generic_command = _GENERIC_SOPERATOR_LIFECYCLE_COMMAND.get()
    if generic_command:
        _require_soperator_lifecycle_scope(config, command=generic_command)
    _apply_generated_tool_version_overrides(manifest)
    _ensure_runtime_auth_material(config, need_terraform=False)
    return config, paths, manifest


def _load_source_payload(config_path: Path) -> dict[str, Any]:
    recover_project_bundle(config_path.absolute().parent)
    if not config_path.exists():
        raise ValueError(f"Config file not found: {config_path}")
    if config_path.is_dir():
        raise ValueError(
            "Expected a project config.yaml file path, but got a directory: "
            f"{config_path}. Pass <tenant-folder>/<project-folder>/config.yaml."
        )
    payload = yaml.safe_load(config_path.read_text(encoding="utf-8")) or {}
    if not isinstance(payload, dict):
        raise ValueError("config.yaml root must be a mapping")
    generic_command = _GENERIC_SOPERATOR_LIFECYCLE_COMMAND.get()
    if generic_command:
        _require_soperator_lifecycle_scope(payload, command=generic_command)
    client_name, _tenant_id, project_id, _region_id, _email = _identity_values_from_payload(payload)
    _ensure_project_auth_identity(project_id=project_id, client_name=client_name)
    return payload


def _resolve_managed_mk8s_upgrade_target(
    manifest: Mapping[str, Any],
    *,
    target_instance_id: str,
) -> dict[str, str]:
    selected_targets = _resolve_selected_deploy_targets(
        manifest,
        requested_target_ref=target_instance_id,
        all_targets=False,
    )
    if len(selected_targets) != 1:
        raise RuntimeError(f"Could not resolve MK8s target '{target_instance_id}'.")
    selected_target = selected_targets[0]
    if str(selected_target.get(DEPLOY_TARGET_KIND_FIELD, "")).strip() == EXTERNAL_MK8S_TARGET_KIND:
        raise RuntimeError(
            "upgrade v1 supports Terraform-managed infra:mk8s targets only. "
            f"Target '{target_instance_id}' is an external MK8s app-management binding."
        )
    component_id = str(selected_target.get("component_id", "")).strip()
    if component_id != MK8S_COMPONENT_ID:
        raise RuntimeError(
            "MK8s upgrade commands require a generated infra:mk8s target. "
            f"Target '{target_instance_id}' is component '{component_id or 'unknown'}'."
        )
    return selected_target


def _managed_mk8s_target_with_cluster_id(
    target: Mapping[str, str],
    *,
    cluster_id: str,
) -> dict[str, str]:
    resolved = dict(target)
    resolved["cluster_id"] = cluster_id
    return resolved


def _live_mk8s_cluster_id(cluster: Any, *, cluster_name: str) -> str:
    metadata = getattr(cluster, "metadata", None)
    cluster_id = _non_empty_text(getattr(metadata, "id", None))
    if not cluster_id:
        raise RuntimeError(f"Nebius MK8s cluster '{cluster_name}' did not return metadata.id.")
    return cluster_id


def _upgrade_interactive_prompts_enabled() -> bool:
    return _is_tty_session()


def _require_upgrade_interactive_prompts(*, missing: str) -> None:
    if _upgrade_interactive_prompts_enabled():
        return
    raise RuntimeError(
        f"Missing {missing}. Pass the required upgrade arguments/options explicitly "
        "or rerun from an interactive terminal to use the upgrade wizard."
    )


def _managed_mk8s_upgrade_target_choices(manifest: Mapping[str, Any]) -> list[OptionChoice]:
    choices: list[OptionChoice] = []
    for target in _manifest_deploy_targets(manifest):
        if str(target.get(DEPLOY_TARGET_OWNERSHIP_FIELD, "")).strip() == EXTERNAL_TARGET_OWNERSHIP:
            continue
        if str(target.get("component_id", "")).strip() != MK8S_COMPONENT_ID:
            continue
        target_ref = normalize_component_token(target.get(TARGET_REF_FIELD))
        if not target_ref:
            continue
        selector = f"infra:{MK8S_COMPONENT_ID}@{target_ref}"
        choices.append(
            OptionChoice(
                value=selector,
                label=selector,
                recommended=not choices,
            )
        )
    return choices


@dataclass(frozen=True)
class _HelmChartUpgradeTarget:
    selector: str
    chart_id: str
    target_ref: str


@dataclass(frozen=True)
class _HelmChartUpgradePlan:
    target: _HelmChartUpgradeTarget
    instance_id: str
    namespace: str
    release_name: str
    current_version: str
    target_version: str

    @property
    def mutates(self) -> bool:
        return self.current_version != self.target_version

    @property
    def target_appears_lower(self) -> bool:
        comparison = _compare_chart_versions(self.target_version, self.current_version)
        return comparison is not None and comparison < 0


@dataclass(frozen=True)
class _SoperatorUpgradeCommandResult:
    args: tuple[str, ...]
    returncode: int
    stdout: str
    stderr: str


