def _parse_helm_chart_upgrade_selector(selector: str) -> _HelmChartUpgradeTarget:
    raw = _non_empty_text(selector)
    if not raw:
        raise ValueError("App target selector is required. Use apps:<chart>@<target-ref>.")
    if not raw.startswith("apps:") or "@" not in raw:
        raise ValueError(
            "Helm chart upgrades require an explicit app target selector: "
            "apps:<chart>@<target-ref>."
        )
    chart_raw, target_raw = raw[len("apps:") :].split("@", maxsplit=1)
    chart_id = normalize_component_token(chart_raw)
    target_ref = normalize_component_token(target_raw)
    if not chart_id:
        raise ValueError("Missing app chart id. Use apps:<chart>@<target-ref>.")
    if not target_ref:
        raise ValueError("Missing app target ref. Use apps:<chart>@<target-ref>.")
    if any(char.isspace() for char in raw):
        raise ValueError("Helm chart target selector must not contain whitespace.")
    return _HelmChartUpgradeTarget(
        selector=f"apps:{chart_id}@{target_ref}",
        chart_id=chart_id,
        target_ref=target_ref,
    )


def _source_helm_chart_target_ref(
    source_payload: Mapping[str, Any],
    row: Mapping[str, Any],
) -> str:
    cluster_target_refs = set(enabled_cluster_target_refs(source_payload))
    instance_id = component_instance_id(row)
    if instance_id in cluster_target_refs:
        return instance_id
    return app_chart_target_ref(row)


def _source_helm_chart_target_choices(
    source_payload: Mapping[str, Any],
) -> list[OptionChoice]:
    apps = source_payload.get("apps")
    charts = apps.get("charts") if isinstance(apps, Mapping) else None
    if not isinstance(charts, list):
        return []
    choices: list[OptionChoice] = []
    for row in charts:
        if not isinstance(row, Mapping) or row.get("enabled") is False:
            continue
        chart_id = component_type_id(row)
        target_ref = _source_helm_chart_target_ref(source_payload, row)
        if not chart_id or not target_ref:
            continue
        version = _non_empty_text(row.get("version")) or "unversioned/local"
        selector = f"apps:{chart_id}@{target_ref}"
        choices.append(
            OptionChoice(
                value=selector,
                label=f"{selector}  (Helm chart version: {version})",
                recommended=not choices,
            )
        )
    return choices


def _prompt_upgrade_helm_chart_target_selector_if_needed(
    *,
    source_payload: Mapping[str, Any],
    target_selector: str | None,
) -> _HelmChartUpgradeTarget:
    current = _non_empty_text(target_selector)
    if current:
        return _parse_helm_chart_upgrade_selector(current)
    choices = _source_helm_chart_target_choices(source_payload)
    if not choices:
        raise RuntimeError(
            "No enabled apps.charts[] rows are declared in config.yaml. "
            "Choose an enabled Helm chart target or add one before running upgrade helm-chart."
        )
    selector = _prompt_upgrade_choice(
        "upgrade.helm_chart.target",
        recommended_choice_value(choices),
        choices=choices,
        missing="upgrade app target selector",
    )
    return _parse_helm_chart_upgrade_selector(selector)


def _validate_helm_chart_version_value(value: str, *, option_name: str = "--to-version") -> str:
    raw = _non_empty_text(value)
    if not raw:
        raise ValueError(f"{option_name} must not be empty.")
    if any(char.isspace() for char in raw):
        raise ValueError(f"{option_name} must not contain whitespace.")
    return raw


def _chart_version_numeric_key(value: str) -> tuple[tuple[int, ...], str, tuple[int, ...]] | None:
    raw = _non_empty_text(value).lstrip("vV")
    match = re.fullmatch(r"(?P<release>[0-9]+(?:\.[0-9]+)*)(?P<suffix>.*)", raw)
    if not match:
        return None
    release = tuple(int(part) for part in match.group("release").split("."))
    suffix = match.group("suffix")
    suffix_label = re.sub(r"[0-9]+", "", suffix).lower()
    suffix_numbers = tuple(int(part) for part in re.findall(r"[0-9]+", suffix))
    return release, suffix_label, suffix_numbers


def _compare_numeric_tuples(left: tuple[int, ...], right: tuple[int, ...]) -> int:
    width = max(len(left), len(right))
    padded_left = (*left, *(0 for _ in range(width - len(left))))
    padded_right = (*right, *(0 for _ in range(width - len(right))))
    if padded_left < padded_right:
        return -1
    if padded_left > padded_right:
        return 1
    return 0


def _compare_chart_versions(left: str, right: str) -> int | None:
    left_key = _chart_version_numeric_key(left)
    right_key = _chart_version_numeric_key(right)
    if left_key is None or right_key is None:
        return None
    left_release, left_suffix_label, left_suffix_numbers = left_key
    right_release, right_suffix_label, right_suffix_numbers = right_key
    release_comparison = _compare_numeric_tuples(left_release, right_release)
    if release_comparison:
        return release_comparison
    if left_suffix_label != right_suffix_label:
        return None
    return _compare_numeric_tuples(left_suffix_numbers, right_suffix_numbers)


def _prompt_upgrade_helm_chart_to_version_if_needed(
    *,
    to_version: str | None,
) -> str:
    current = _non_empty_text(to_version)
    if current:
        return _validate_helm_chart_version_value(current)
    value = _prompt_upgrade_scalar(
        "upgrade.helm_chart.to_version",
        "",
        type_hint="string",
        missing="--to-version <chart-version>",
    )
    return _validate_helm_chart_version_value(str(value))


def _source_soperator_upgrade_target_choices(
    source_payload: Mapping[str, Any],
) -> list[OptionChoice]:
    choices = [
        choice
        for choice in _source_helm_chart_target_choices(source_payload)
        if _parse_helm_chart_upgrade_selector(choice.value).chart_id == _SOPERATOR_APP_ID
    ]
    if choices and not any(choice.recommended for choice in choices):
        first = choices[0]
        choices[0] = OptionChoice(
            value=first.value,
            label=first.label,
            recommended=True,
            metadata=first.metadata,
        )
    return choices


def _parse_soperator_upgrade_target(target_ref: str) -> _HelmChartUpgradeTarget:
    raw = _non_empty_text(target_ref)
    if not raw:
        raise ValueError("Soperator target is required.")
    target = (
        _parse_helm_chart_upgrade_selector(raw)
        if raw.startswith("apps:")
        else _parse_helm_chart_upgrade_selector(f"apps:{_SOPERATOR_APP_ID}@{raw}")
    )
    if target.chart_id != _SOPERATOR_APP_ID:
        raise ValueError("Soperator upgrades require apps:soperator@<target> or --target <target>.")
    return target


def _prompt_soperator_upgrade_target_if_needed(
    *,
    source_payload: Mapping[str, Any],
    target_ref: str | None,
    interactive: bool,
) -> _HelmChartUpgradeTarget:
    current = _non_empty_text(target_ref)
    if current:
        return _parse_soperator_upgrade_target(current)
    choices = _source_soperator_upgrade_target_choices(source_payload)
    if not choices:
        raise RuntimeError(
            "No enabled apps:soperator rows are declared in config.yaml. Add or onboard "
            "Soperator before running `nebius-cxcli soperator upgrade`."
        )
    if len(choices) == 1:
        return _parse_helm_chart_upgrade_selector(choices[0].value)
    if not interactive:
        available = ", ".join(choice.value for choice in choices)
        raise RuntimeError(
            "Multiple Soperator targets are declared in config.yaml. Pass "
            f"--target <target>. Available targets: {available}"
        )
    selector = _prompt_upgrade_choice(
        "soperator.upgrade.target",
        recommended_choice_value(choices),
        choices=choices,
        missing="Soperator target",
    )
    return _parse_helm_chart_upgrade_selector(selector)


def _resolve_soperator_command_target(
    source_payload: Mapping[str, Any],
    *,
    target_ref: str | None,
    interactive: bool,
) -> tuple[_HelmChartUpgradeTarget, Mapping[str, Any] | None, bool]:
    """Resolve one Soperator target and its registered infrastructure ownership."""

    target = _prompt_soperator_upgrade_target_if_needed(
        source_payload=source_payload,
        target_ref=target_ref,
        interactive=interactive,
    )
    available_selectors = {
        choice.value for choice in _source_soperator_upgrade_target_choices(source_payload)
    }
    if target.selector not in available_selectors:
        raise ValueError(f"Could not find enabled {target.selector} in config.yaml apps.charts[].")
    target_row = soperator_registration_target(
        source_payload,
        target_ref=target.target_ref,
    )
    is_onboarded = bool(
        isinstance(target_row, Mapping)
        and (
            deploy_target_is_external_mk8s(target_row)
            or _non_empty_text(target_row.get(DEPLOY_TARGET_OWNERSHIP_FIELD)).lower()
            == EXTERNAL_TARGET_OWNERSHIP
        )
    )
    if is_onboarded:
        validate_soperator_registration(
            source_payload,
            target_ref=target.target_ref,
        )
    return target, target_row, is_onboarded


def _prompt_upgrade_choice(
    path_label: str,
    current: object,
    *,
    choices: list[OptionChoice],
    required: bool = True,
    missing: str,
) -> str:
    value = _prompt_upgrade_choice_or_back(
        path_label,
        current,
        choices=choices,
        required=required,
        missing=missing,
    )
    if _wizard_backtrack_requested(value):
        raise RuntimeError("Upgrade wizard cancelled.")
    return str(value or "").strip()


def _prompt_upgrade_choice_or_back(
    path_label: str,
    current: object,
    *,
    choices: list[OptionChoice],
    required: bool = True,
    missing: str,
) -> str | object:
    _require_upgrade_interactive_prompts(missing=missing)
    value, should_stop = _prompt_scalar_override(
        path_label,
        current,
        choices=choices,
        required=required,
    )
    if should_stop:
        raise RuntimeError("Upgrade wizard cancelled.")
    if _wizard_backtrack_requested(value):
        return _WIZARD_BACKTRACK
    return str(value or "").strip()


def _prompt_upgrade_scalar(
    path_label: str,
    current: object,
    *,
    type_hint: str | None = None,
    required: bool = True,
    missing: str,
    prompt_hint: str | None = None,
) -> object:
    value = _prompt_upgrade_scalar_or_back(
        path_label,
        current,
        type_hint=type_hint,
        required=required,
        missing=missing,
        prompt_hint=prompt_hint,
    )
    if _wizard_backtrack_requested(value):
        raise RuntimeError("Upgrade wizard cancelled.")
    return value


def _prompt_upgrade_scalar_or_back(
    path_label: str,
    current: object,
    *,
    type_hint: str | None = None,
    required: bool = True,
    missing: str,
    prompt_hint: str | None = None,
) -> object:
    _require_upgrade_interactive_prompts(missing=missing)
    value, should_stop = _prompt_scalar_override(
        path_label,
        current,
        type_hint=type_hint,
        required=required,
        prompt_hint=prompt_hint,
    )
    if should_stop:
        raise RuntimeError("Upgrade wizard cancelled.")
    return value


def _prompt_upgrade_mk8s_target_selector_or_back_if_needed(
    *,
    manifest: Mapping[str, Any],
    target_selector: str | None,
    path_label: str = "upgrade.node_template.target",
) -> str | object:
    current = _non_empty_text(target_selector)
    if current:
        return current
    choices = _managed_mk8s_upgrade_target_choices(manifest)
    if not choices:
        raise RuntimeError(
            "No Terraform-managed infra:mk8s targets are declared in the generated bundle. "
            "Run render first and choose a managed MK8s target."
        )
    return _prompt_upgrade_choice_or_back(
        path_label,
        recommended_choice_value(choices),
        choices=choices,
        missing="upgrade target selector",
    )


def _cluster_control_plane_minor_version(cluster: Any, *, cluster_id: str) -> str:
    version = _non_empty_text(
        getattr(getattr(getattr(cluster, "spec", None), "control_plane", None), "version", None)
    )
    if not version:
        raise RuntimeError(
            f"MK8s cluster '{cluster_id}' did not return spec.control_plane.version."
        )
    return parse_k8s_version(version).minor_text


def _selected_node_template_live_groups(
    *,
    source_component: Mapping[str, Any],
    live_node_groups: Sequence[Any],
    node_group: str,
) -> tuple[LiveNodeGroup, ...]:
    groups = live_node_groups_from_sdk(
        source_component=source_component,
        live_node_groups=live_node_groups,
    )
    return select_live_node_groups_for_node_template(groups, node_group=node_group)


def _single_selected_live_value(
    groups: Sequence[LiveNodeGroup],
    *,
    attr: str,
    option_name: str,
    value_label: str,
) -> str:
    values = tuple(
        dict.fromkeys(
            _non_empty_text(getattr(group, attr, None))
            for group in groups
            if _non_empty_text(getattr(group, attr, None))
        )
    )
    if len(values) == 1:
        return values[0]
    if not values:
        raise RuntimeError(
            f"Could not resolve the current live {value_label} for selected node groups. "
            f"Pass {option_name} explicitly."
        )
    raise RuntimeError(
        f"Selected node groups have multiple live {value_label} values "
        f"({', '.join(values)}). Pass {option_name} explicitly."
    )


def _default_node_template_gpu_stack_preset(
    groups: Sequence[LiveNodeGroup],
    *,
    to_gpu_stack_preset: str | None,
    prompt_gpu_stack: bool,
) -> str:
    current = _non_empty_text(to_gpu_stack_preset)
    if current:
        return validate_node_template_field_value(current, flag_name="--to-gpu-stack-preset")
    if prompt_gpu_stack:
        return ""
    nebius_image_groups = tuple(
        group for group in groups if node_group_uses_nebius_gpu_image(group)
    )
    if not nebius_image_groups:
        return ""
    return validate_node_template_field_value(
        _single_selected_live_value(
            nebius_image_groups,
            attr="drivers_preset",
            option_name="--to-gpu-stack-preset",
            value_label="Nebius-image GPU stack preset",
        ),
        flag_name="--to-gpu-stack-preset",
    )


def _node_template_version_choices(
    *,
    current_version: str,
    supported_versions: tuple[str, ...],
) -> list[OptionChoice]:
    current = parse_k8s_version(current_version)
    by_minor: dict[str, Any] = {current.minor_text: current}
    for raw_version in supported_versions:
        try:
            parsed = parse_k8s_version(raw_version)
        except ValueError:
            continue
        if parsed.major != current.major or parsed.minor < current.minor:
            continue
        if parsed.minor > current.minor + 1:
            continue
        by_minor.setdefault(parsed.minor_text, parsed)
    recommended = f"{current.major}.{current.minor + 1}"
    if recommended not in by_minor:
        recommended = current.minor_text
    choices: list[OptionChoice] = []
    for minor_text in sorted(by_minor, key=lambda item: parse_k8s_version(item).minor):
        if minor_text == current.minor_text:
            label = f"{minor_text}  (current/live; reconcile source and generated state)"
        else:
            label = (
                f"{minor_text}  (next supported minor; "
                "upstream Kubernetes does not support skipped minors)"
            )
        choices.append(
            OptionChoice(
                value=minor_text,
                label=label,
                recommended=minor_text == recommended,
            )
        )
    return choices


def _prompt_upgrade_node_template_to_version_if_needed(
    *,
    cluster: Any,
    cluster_id: str,
    supported_versions: tuple[str, ...],
    to_version: str | None,
    path_label: str = "upgrade.node_template.to_version",
) -> str:
    value = _prompt_upgrade_node_template_to_version_or_back_if_needed(
        cluster=cluster,
        cluster_id=cluster_id,
        supported_versions=supported_versions,
        to_version=to_version,
        path_label=path_label,
    )
    if _wizard_backtrack_requested(value):
        raise RuntimeError("Upgrade wizard cancelled.")
    return str(value or "").strip()


def _prompt_upgrade_node_template_to_version_or_back_if_needed(
    *,
    cluster: Any,
    cluster_id: str,
    supported_versions: tuple[str, ...],
    to_version: str | None,
    path_label: str = "upgrade.node_template.to_version",
) -> str | object:
    current = _non_empty_text(to_version)
    if current:
        return parse_k8s_version(current).minor_text
    live_version = _cluster_control_plane_minor_version(cluster, cluster_id=cluster_id)
    choices = _node_template_version_choices(
        current_version=live_version,
        supported_versions=supported_versions,
    )
    if choices:
        return _prompt_upgrade_choice_or_back(
            path_label,
            recommended_choice_value(choices),
            choices=choices,
            missing="--to-version <major.minor>",
        )
    value = _prompt_upgrade_scalar_or_back(
        path_label,
        "",
        type_hint="string",
        missing="--to-version <major.minor>",
    )
    if _wizard_backtrack_requested(value):
        return _WIZARD_BACKTRACK
    return parse_k8s_version(str(value)).minor_text


def _upgrade_auto_drain_timeout_prompt_hint(disruption_policy: str) -> str:
    try:
        validate_disruption_policy(disruption_policy)
    except ValueError:
        return "auto = strategy default"
    return "auto = 30m for zero-surge/safe-surge; 10m for force-delete"


def _coerce_strategy_max_surge_count(value: object) -> int:
    if isinstance(value, bool):
        raise ValueError("--strategy-max-surge-count must be an integer.")
    try:
        return int(str(value).strip())
    except (TypeError, ValueError) as exc:
        raise ValueError("--strategy-max-surge-count must be an integer.") from exc


def _prompt_upgrade_strategy_max_surge_count_if_needed(
    *,
    path_prefix: str,
    guided: bool,
    disruption_policy: str,
    strategy_max_surge_count: int | None,
    allow_backtrack: bool = False,
) -> object:
    if disruption_policy != DISRUPTION_POLICY_SAFE:
        if strategy_max_surge_count is not None:
            resolve_strategy_max_surge_count(
                disruption_policy,
                strategy_max_surge_count,
            )
        return None
    if strategy_max_surge_count is not None:
        return resolve_strategy_max_surge_count(
            disruption_policy,
            strategy_max_surge_count,
        )
    if not guided:
        return resolve_strategy_max_surge_count(disruption_policy, None)
    prompt_func = _prompt_upgrade_scalar_or_back if allow_backtrack else _prompt_upgrade_scalar
    prompted_count = prompt_func(
        f"{path_prefix}.strategy_max_surge_count",
        SAFE_SURGE_DEFAULT_MAX_SURGE_COUNT,
        type_hint="integer",
        required=True,
        missing="--strategy-max-surge-count",
        prompt_hint="temporary extra nodes per active node group",
    )
    if _wizard_backtrack_requested(prompted_count):
        return _WIZARD_BACKTRACK
    return resolve_strategy_max_surge_count(
        disruption_policy,
        _coerce_strategy_max_surge_count(prompted_count),
    )


def _upgrade_node_group_blank_prompt_text(path_prefix: str) -> str:
    if path_prefix == "upgrade.node_template":
        return "blank = all managed node groups"
    return "blank = all eligible managed node groups"


@contextmanager
def _command_status(message: str, *, enabled: bool = True) -> Iterator[None]:
    if not enabled:
        yield
        return
    if getattr(console, "is_terminal", False) and hasattr(console, "status"):
        with console.status(message, spinner="dots"):
            yield
        return
    console.print(f"[dim]{message}[/dim]", soft_wrap=True)
    yield


@contextmanager
def _upgrade_discovery_status(message: str) -> Iterator[None]:
    with _command_status(message):
        yield


def _prompt_upgrade_disruption_options_if_guided(
    *,
    path_prefix: str,
    guided: bool,
    dry_run: bool,
    disruption_policy: str,
    drain_timeout: str,
    strategy_max_surge_count: int | None,
    skip_validations: bool,
    allow_outer_backtrack: bool = False,
) -> tuple[bool, str, str, int | None, bool] | object:
    if not guided:
        resolved_max_surge_count = _prompt_upgrade_strategy_max_surge_count_if_needed(
            path_prefix=path_prefix,
            guided=False,
            disruption_policy=disruption_policy,
            strategy_max_surge_count=strategy_max_surge_count,
        )
        return dry_run, disruption_policy, drain_timeout, resolved_max_surge_count, skip_validations

    prompt_dry_run = not dry_run
    prompt_strategy = disruption_policy == DISRUPTION_POLICY_ALLOW_UNAVAILABLE
    prompt_strategy_max_surge_count = strategy_max_surge_count is None
    prompt_drain_timeout = drain_timeout == "auto"
    prompt_validations = not skip_validations
    prompted_steps: list[str] = []
    steps = (
        "dry_run",
        "strategy",
        "strategy_max_surge_count",
        "drain_timeout",
        "run_post_upgrade_validations",
        "confirm_apply",
    )
    step_index = 0
    outer_backtrack = False

    def _backtrack() -> None:
        nonlocal outer_backtrack, step_index
        if not prompted_steps:
            if allow_outer_backtrack:
                outer_backtrack = True
                step_index = len(steps)
                return
            raise RuntimeError("Upgrade wizard cancelled.")
        previous_step = prompted_steps.pop()
        step_index = steps.index(previous_step)

    while step_index < len(steps):
        step = steps[step_index]
        try:
            if step == "dry_run":
                if not prompt_dry_run:
                    step_index += 1
                    continue
                prompted_dry_run = _prompt_upgrade_scalar_or_back(
                    f"{path_prefix}.dry_run",
                    True,
                    type_hint="bool",
                    required=True,
                    missing="--dry-run choice",
                )
                if _wizard_backtrack_requested(prompted_dry_run):
                    _backtrack()
                    if outer_backtrack:
                        break
                    continue
                dry_run = bool(prompted_dry_run)
                prompted_steps.append(step)
                step_index += 1
                continue
            if step == "strategy":
                if not prompt_strategy:
                    step_index += 1
                    continue
                prompted_policy = _prompt_upgrade_choice_or_back(
                    f"{path_prefix}.strategy",
                    disruption_policy,
                    choices=[
                        OptionChoice(
                            value=DISRUPTION_POLICY_ALLOW_UNAVAILABLE,
                            label="zero-surge  (default; no spare node quota; capacity can drop)",
                            recommended=True,
                        ),
                        OptionChoice(
                            value=DISRUPTION_POLICY_SAFE,
                            label=(
                                "safe-surge  (default 1 spare node per active node group; "
                                "preserves active capacity)"
                            ),
                        ),
                        OptionChoice(
                            value=DISRUPTION_POLICY_FORCE_DELETE,
                            label=(
                                "force-delete  (last resort; auto=10m, then deletes remaining "
                                "Pods and node)"
                            ),
                        ),
                    ],
                    missing="--strategy",
                )
                if _wizard_backtrack_requested(prompted_policy):
                    _backtrack()
                    if outer_backtrack:
                        break
                    continue
                disruption_policy = str(prompted_policy or "").strip()
                if disruption_policy != DISRUPTION_POLICY_SAFE:
                    strategy_max_surge_count = None
                prompted_steps.append(step)
                step_index += 1
                continue
            if step == "strategy_max_surge_count":
                should_prompt_count = (
                    disruption_policy == DISRUPTION_POLICY_SAFE and prompt_strategy_max_surge_count
                )
                if should_prompt_count:
                    prompted_count = _prompt_upgrade_scalar_or_back(
                        f"{path_prefix}.strategy_max_surge_count",
                        (
                            strategy_max_surge_count
                            if strategy_max_surge_count is not None
                            else SAFE_SURGE_DEFAULT_MAX_SURGE_COUNT
                        ),
                        type_hint="integer",
                        required=True,
                        missing="--strategy-max-surge-count",
                        prompt_hint="temporary extra nodes per active node group",
                    )
                else:
                    prompted_count = _prompt_upgrade_strategy_max_surge_count_if_needed(
                        path_prefix=path_prefix,
                        guided=guided,
                        disruption_policy=disruption_policy,
                        strategy_max_surge_count=strategy_max_surge_count,
                        allow_backtrack=True,
                    )
                if _wizard_backtrack_requested(prompted_count):
                    _backtrack()
                    if outer_backtrack:
                        break
                    continue
                if should_prompt_count:
                    strategy_max_surge_count = resolve_strategy_max_surge_count(
                        disruption_policy,
                        _coerce_strategy_max_surge_count(prompted_count),
                    )
                    prompted_steps.append(step)
                else:
                    strategy_max_surge_count = (
                        int(prompted_count) if prompted_count is not None else None
                    )
                step_index += 1
                continue
            if step == "drain_timeout":
                if not prompt_drain_timeout:
                    step_index += 1
                    continue
                prompted_timeout = _prompt_upgrade_scalar_or_back(
                    f"{path_prefix}.drain_timeout",
                    "auto",
                    type_hint="string",
                    required=True,
                    missing="--drain-timeout",
                    prompt_hint=_upgrade_auto_drain_timeout_prompt_hint(disruption_policy),
                )
                if _wizard_backtrack_requested(prompted_timeout):
                    _backtrack()
                    if outer_backtrack:
                        break
                    continue
                drain_timeout = str(prompted_timeout or "auto").strip() or "auto"
                prompted_steps.append(step)
                step_index += 1
                continue
            if step == "run_post_upgrade_validations":
                if not prompt_validations:
                    step_index += 1
                    continue
                run_validations = _prompt_upgrade_scalar_or_back(
                    f"{path_prefix}.run_post_upgrade_validations",
                    True,
                    type_hint="bool",
                    required=True,
                    missing="post-upgrade validation choice",
                )
                if _wizard_backtrack_requested(run_validations):
                    _backtrack()
                    if outer_backtrack:
                        break
                    continue
                skip_validations = not bool(run_validations)
                prompted_steps.append(step)
                step_index += 1
                continue
            if step == "confirm_apply":
                if dry_run:
                    step_index += 1
                    continue
                confirm_apply = _prompt_upgrade_scalar_or_back(
                    f"{path_prefix}.confirm_apply",
                    False,
                    type_hint="bool",
                    required=True,
                    missing="live apply confirmation",
                )
                if _wizard_backtrack_requested(confirm_apply):
                    _backtrack()
                    if outer_backtrack:
                        break
                    continue
                if not bool(confirm_apply):
                    raise RuntimeError("Upgrade wizard cancelled before applying live changes.")
                prompted_steps.append(step)
                step_index += 1
                continue
            step_index += 1
        except RuntimeError:
            raise
    if outer_backtrack:
        return _WIZARD_BACKTRACK
    return dry_run, disruption_policy, drain_timeout, strategy_max_surge_count, skip_validations


def _prompt_upgrade_node_group_if_guided(
    *,
    path_prefix: str,
    guided: bool,
    node_group: str,
    allow_backtrack: bool = False,
) -> str | object:
    current = _non_empty_text(node_group)
    if current or not guided:
        return current

    _require_upgrade_interactive_prompts(missing="--node-group <source-key-or-live-name>")
    value, should_stop = _prompt_scalar_override(
        f"{path_prefix}.node_group",
        None,
        type_hint="string",
        required=False,
        unset_on_skip=True,
        blank_text=_upgrade_node_group_blank_prompt_text(path_prefix),
    )
    if should_stop:
        raise RuntimeError("Upgrade wizard cancelled.")
    if _wizard_backtrack_requested(value):
        if allow_backtrack:
            return _WIZARD_BACKTRACK
        raise RuntimeError("Upgrade wizard cancelled.")
    return _non_empty_text(value)


def _prompt_upgrade_node_template_field_value_if_needed(
    *,
    path_label: str,
    value: str | None,
    option_name: str,
    choices: list[OptionChoice] | None = None,
    allow_backtrack: bool = False,
) -> str | object:
    current = _non_empty_text(value)
    if current:
        return validate_node_template_field_value(current, flag_name=option_name)
    if choices:
        selected = _prompt_upgrade_choice_or_back(
            path_label,
            recommended_choice_value(choices),
            choices=choices,
            missing=f"{option_name} <value>",
        )
        if _wizard_backtrack_requested(selected):
            if allow_backtrack:
                return _WIZARD_BACKTRACK
            raise RuntimeError("Upgrade wizard cancelled.")
        return validate_node_template_field_value(selected, flag_name=option_name)
    prompted = _prompt_upgrade_scalar_or_back(
        path_label,
        "",
        type_hint="string",
        missing=f"{option_name} <value>",
    )
    if _wizard_backtrack_requested(prompted):
        if allow_backtrack:
            return _WIZARD_BACKTRACK
        raise RuntimeError("Upgrade wizard cancelled.")
    return validate_node_template_field_value(str(prompted), flag_name=option_name)


