def _resolve_helm_chart_upgrade_options(
    *,
    guided: bool,
    dry_run: bool,
    path_prefix: str = "upgrade.helm_chart",
) -> bool:
    if guided and not dry_run:
        prompted_dry_run = _prompt_upgrade_scalar(
            f"{path_prefix}.dry_run",
            True,
            type_hint="bool",
            required=True,
            missing="--dry-run choice",
        )
        dry_run = bool(prompted_dry_run)
    if guided and not dry_run:
        confirm_apply = _prompt_upgrade_scalar(
            f"{path_prefix}.confirm_apply",
            False,
            type_hint="bool",
            required=True,
            missing="live apply confirmation",
        )
        if not bool(confirm_apply):
            raise RuntimeError("Upgrade wizard cancelled before applying live changes.")
    return dry_run


def _append_strategy_max_surge_count_arg(
    args: list[str],
    *,
    disruption_policy: str,
    strategy_max_surge_count: int | None,
) -> None:
    resolved_count = resolve_strategy_max_surge_count(
        disruption_policy,
        strategy_max_surge_count,
    )
    if disruption_policy == DISRUPTION_POLICY_SAFE:
        args.extend(["--strategy-max-surge-count", str(resolved_count)])


def _append_drain_timeout_arg(args: list[str], drain_timeout: DrainTimeout) -> None:
    raw_timeout = str(drain_timeout.raw).strip()
    if raw_timeout:
        args.extend(["--drain-timeout", raw_timeout])


def _append_upgrade_validation_args(
    args: list[str],
    *,
    skip_validations: bool = False,
    skip_validation: Sequence[str] | None = None,
) -> None:
    if skip_validations:
        args.append("--skip-validations")
    for kind in skip_validation or ():
        args.extend(["--skip-validation", kind])


def _upgrade_node_template_dry_run_command(
    *,
    config_path: Path,
    target_selector: str,
    to_version: str,
    to_os: str,
    to_gpu_stack_preset: str,
    node_group: str,
    disruption_policy: str,
    drain_timeout: DrainTimeout,
    strategy_max_surge_count: int | None = None,
    skip_validations: bool = False,
    skip_validation: Sequence[str] | None = None,
) -> str:
    args = [
        "nebius-cxcli",
        "upgrade",
        "node-template",
        str(config_path),
        target_selector,
        "--to-version",
        to_version,
        "--to-os",
        to_os,
        "--strategy",
        disruption_policy,
    ]
    _append_strategy_max_surge_count_arg(
        args,
        disruption_policy=disruption_policy,
        strategy_max_surge_count=strategy_max_surge_count,
    )
    if to_gpu_stack_preset:
        args.extend(["--to-gpu-stack-preset", to_gpu_stack_preset])
    if node_group:
        args.extend(["--node-group", node_group])
    _append_drain_timeout_arg(args, drain_timeout)
    _append_upgrade_validation_args(
        args,
        skip_validations=skip_validations,
        skip_validation=skip_validation,
    )
    args.append("--no-interactive")
    args.append("--dry-run")
    return shlex.join(args)


def _migrate_node_group_command(
    *,
    config_path: Path,
    target_selector: str,
    node_group: str,
    replacement_node_group: str,
    replacement_name: str,
    to_platform: str = "",
    to_preset: str = "",
    to_os: str = "",
    to_gpu_stack_preset: str = "",
    to_fabric: str = "",
    execute: bool = False,
    approve: bool = False,
) -> str:
    args = [
        "nebius-cxcli",
        "migrate",
        "node-group",
        str(config_path),
        target_selector,
        "--node-group",
        node_group,
        "--replacement-node-group",
        replacement_node_group,
        "--replacement-name",
        replacement_name,
    ]
    if to_platform:
        args.extend(["--to-platform", to_platform])
    if to_preset:
        args.extend(["--to-preset", to_preset])
    if to_os:
        args.extend(["--to-os", to_os])
    if to_gpu_stack_preset:
        args.extend(["--to-gpu-stack-preset", to_gpu_stack_preset])
    if to_fabric:
        args.extend(["--to-fabric", to_fabric])
    args.append("--execute" if execute else "--dry-run")
    if approve:
        args.append("--approve")
    return shlex.join(args)


@dataclass(frozen=True)
class _NodeGroupMigrationPlan:
    target_selector: str
    instance_id: str
    cluster_name: str
    node_group: str
    source_provider_name: str
    replacement_node_group: str
    replacement_name: str
    node_group_kind: str
    gpu_cluster_key: str
    target_gpu_cluster_key: str
    current_config_fabric: str
    current_state_fabric: str
    requested_target_fabric: str
    effective_target_fabric: str
    fabric_status: str
    current_platform: str
    target_platform: str
    current_preset: str
    target_preset: str
    current_os: str
    target_os: str
    current_gpu_stack_preset: str
    target_gpu_stack_preset: str
    reservation_policy: str
    reservation_ids: tuple[str, ...]
    desired_node_count: int
    autoscaling_preimage: Mapping[str, Any]
    source_group: Mapping[str, Any]
    sfs_evidence: tuple[str, ...]
    soperator_managed: bool
    quota_report: QuotaReport | None = None

    @property
    def mutates_hardware_or_fabric(self) -> bool:
        return (
            self.current_platform != self.target_platform
            or self.current_preset != self.target_preset
            or self.gpu_cluster_key != self.target_gpu_cluster_key
            or self.current_config_fabric != self.effective_target_fabric
        )

    @property
    def mutates_template_only(self) -> bool:
        return (
            self.current_os != self.target_os
            or self.current_gpu_stack_preset != self.target_gpu_stack_preset
        )


def _node_group_migration_sfs_evidence(group: Mapping[str, Any]) -> tuple[str, ...]:
    evidence: list[str] = []
    sfs_keys = group.get("sfs_filesystem_keys")
    if isinstance(sfs_keys, Sequence) and not isinstance(sfs_keys, (str, bytes)):
        for item in sfs_keys:
            text = _non_empty_text(item)
            if text:
                evidence.append(f"sfs_filesystem_keys:{text}")
    filesystems = group.get("filesystems")
    if isinstance(filesystems, Sequence) and not isinstance(filesystems, (str, bytes)):
        for index, item in enumerate(filesystems):
            if isinstance(item, Mapping):
                name = _non_empty_text(item.get("name")) or _non_empty_text(item.get("mount_tag"))
                evidence.append(f"filesystems[{index}]" + (f":{name}" if name else ""))
    return tuple(evidence)


def _node_group_migration_replacement_inputs(
    *,
    group: Mapping[str, Any],
    target_platform: str,
    target_preset: str,
    target_os: str,
    target_gpu_stack_preset: str,
    gpu_cluster_key: str,
    effective_target_fabric: str,
) -> dict[str, Any]:
    replacement_group = copy.deepcopy(to_plain_data(group))
    if not isinstance(replacement_group, dict):
        replacement_group = {}
    replacement_group["enabled"] = True
    if target_platform:
        replacement_group["platform"] = target_platform
    if target_preset:
        replacement_group["preset"] = target_preset
    if target_os:
        replacement_group["os"] = target_os
    if target_gpu_stack_preset:
        replacement_group["gpu_stack_preset"] = target_gpu_stack_preset
    if gpu_cluster_key:
        replacement_group["gpu_cluster_key"] = gpu_cluster_key
    inputs: dict[str, Any] = {"node_groups": {"replacement": replacement_group}}
    if gpu_cluster_key and effective_target_fabric:
        inputs["gpu_clusters"] = {gpu_cluster_key: {"infiniband_fabric": effective_target_fabric}}
    return inputs


def _node_group_migration_quota_report(
    *,
    source_payload: Mapping[str, Any],
    generated_config: Any,
    instance_id: str,
    group: Mapping[str, Any],
    target_platform: str,
    target_preset: str,
    target_os: str,
    target_gpu_stack_preset: str,
    gpu_cluster_key: str,
    effective_target_fabric: str,
) -> QuotaReport | None:
    tenant_id, project_id, region_id = _quota_identity_from_payload(
        source_payload, generated_config
    )
    if not project_id or not region_id:
        return None
    requirements, gaps = estimate_mk8s_quota_requirements(
        project_id=project_id,
        region=region_id,
        instance_id=f"{instance_id}-node-group-migration",
        inputs=_node_group_migration_replacement_inputs(
            group=group,
            target_platform=target_platform,
            target_preset=target_preset,
            target_os=target_os,
            target_gpu_stack_preset=target_gpu_stack_preset,
            gpu_cluster_key=gpu_cluster_key,
            effective_target_fabric=effective_target_fabric,
        ),
        context="node-group migration replacement group",
    )
    if not requirements and not gaps:
        return None
    return assess_live_quota_requirements(
        tenant_id=tenant_id,
        project_id=project_id,
        region_id=region_id,
        requirements=requirements,
        coverage_gaps=gaps,
        context="node-group migration replacement group",
    )


def _node_group_migration_fabric_status(
    *,
    current_config_fabric: str,
    effective_target_fabric: str,
) -> str:
    if not effective_target_fabric:
        return "not applicable"
    if not current_config_fabric:
        return f"target fabric required: {effective_target_fabric}"
    if current_config_fabric == effective_target_fabric:
        return "unchanged"
    return f"changing {current_config_fabric} -> {effective_target_fabric}"


def _node_group_migration_quota_blocks(plan: _NodeGroupMigrationPlan) -> bool:
    report = plan.quota_report
    if report is None:
        return False
    return bool(
        report.has_confirmed_insufficiency
        or report.unknown_checks
        or report.coverage_gaps
        or report.errors
    )


def _plan_node_group_migration(
    *,
    source_payload: Mapping[str, Any],
    generated_config: Any,
    paths: ProjectPaths,
    manifest: Mapping[str, Any],
    target_selector: str,
    node_group: str,
    replacement_node_group: str = "",
    replacement_name: str = "",
    to_platform: str = "",
    to_preset: str = "",
    to_os: str = "",
    to_gpu_stack_preset: str = "",
    to_fabric: str = "",
    to_gpu_cluster_key: str = "",
    to_reservation_policy: str = "",
    to_reservation_ids: Sequence[str] = (),
) -> _NodeGroupMigrationPlan:
    target = parse_upgrade_selector(target_selector)
    source_component = find_source_mk8s_component(source_payload, target.instance_id)
    inputs = source_component.get("inputs")
    if not isinstance(inputs, Mapping):
        raise ValueError(f"{target.selector} has no inputs mapping in config.yaml.")
    node_group_defaults = inputs.get("node_group_defaults")
    gpu_defaults = (
        node_group_defaults.get("gpu") if isinstance(node_group_defaults, Mapping) else None
    )
    if isinstance(gpu_defaults, Mapping) and "infiniband_fabric" in gpu_defaults:
        raise ValueError(
            "inputs.node_group_defaults.gpu.infiniband_fabric is no longer supported; "
            "move the value to inputs.gpu_clusters.<key>.infiniband_fabric before "
            "running migrate node-group."
        )
    raw_group = _state_mapping(inputs.get("node_groups")).get(node_group)
    if not isinstance(raw_group, Mapping):
        raise ValueError(f"{target.selector} has no node group '{node_group}' in config.yaml.")
    if raw_group.get("enabled") is False:
        raise ValueError(f"{target.selector} node group '{node_group}' is disabled.")
    replacement_key = normalize_component_token(
        replacement_node_group or f"{node_group}-replacement"
    )
    if not replacement_key or replacement_key != replacement_node_group:
        raise ValueError("--replacement-node-group must be a non-empty canonical config key.")
    if replacement_key == node_group:
        raise ValueError("--replacement-node-group must differ from --node-group.")
    existing_groups = _state_mapping(inputs.get("node_groups"))
    if replacement_key in existing_groups:
        raise ValueError(
            f"{target.selector} already has node group '{replacement_key}' in config.yaml."
        )
    replacement_provider_name = _non_empty_text(replacement_name) or replacement_key
    source_provider_name = _non_empty_text(raw_group.get("name")) or node_group
    if replacement_provider_name == source_provider_name:
        raise ValueError("--replacement-name must differ from the source provider name.")

    current_platform = _non_empty_text(raw_group.get("platform"))
    current_preset = _non_empty_text(raw_group.get("preset"))
    current_os = _non_empty_text(raw_group.get("os"))
    current_gpu_stack_preset = _non_empty_text(raw_group.get("gpu_stack_preset"))
    if not current_platform or not current_preset:
        raise ValueError(
            f"{target.selector} node group '{node_group}' requires platform and preset."
        )

    target_platform = _non_empty_text(to_platform) or current_platform
    target_preset = _non_empty_text(to_preset) or current_preset
    target_os = _non_empty_text(to_os) or current_os
    target_gpu_stack_preset = _non_empty_text(to_gpu_stack_preset) or current_gpu_stack_preset
    is_gpu_group = bool(raw_group.get("gpu", False))
    node_group_kind = "gpu" if is_gpu_group else "cpu/system"
    gpu_cluster_key = _non_empty_text(raw_group.get("gpu_cluster_key"))
    target_gpu_cluster_key = _non_empty_text(to_gpu_cluster_key) or gpu_cluster_key
    target_fabric = _non_empty_text(to_fabric)
    current_config_fabric = ""
    if gpu_cluster_key:
        gpu_clusters = inputs.get("gpu_clusters")
        cluster = gpu_clusters.get(gpu_cluster_key) if isinstance(gpu_clusters, Mapping) else None
        if not isinstance(cluster, Mapping):
            raise ValueError(
                f"{target.selector} node group '{node_group}' references gpu_cluster_key "
                f"'{gpu_cluster_key}', but inputs.gpu_clusters.{gpu_cluster_key} is missing."
            )
        current_config_fabric = _non_empty_text(cluster.get("infiniband_fabric"))

    if not is_gpu_group and target_fabric:
        raise ValueError("--to-fabric is valid only for GPU-cluster/InfiniBand node groups.")
    if is_gpu_group and not gpu_cluster_key and target_fabric:
        raise ValueError(
            "--to-fabric was provided, but the selected GPU node group is not on the "
            "GPU-cluster/InfiniBand path. Add an explicit GPU-cluster migration design "
            "before binding this node group to a fabric."
        )
    if not is_gpu_group and target_gpu_cluster_key:
        raise ValueError("--to-gpu-cluster-key is valid only for GPU node groups.")

    runtime_env = _terraform_runtime_env(generated_config)
    state_specs = _mk8s_gpu_fabric_specs_from_terraform_state(
        paths=paths,
        manifest=manifest,
        runtime_env=runtime_env,
        initialize=False,
    )
    state_spec = state_specs.get((target.instance_id, gpu_cluster_key)) if gpu_cluster_key else None
    current_state_fabric = state_spec.fabric if state_spec is not None else ""
    effective_target_fabric = ""
    if target_gpu_cluster_key:
        effective_target_fabric = target_fabric or current_config_fabric or current_state_fabric
        if not effective_target_fabric:
            raise ValueError(
                f"{target.selector} node group '{node_group}' uses GPU-cluster/InfiniBand, "
                "but no current fabric could be resolved. Pass --to-fabric explicitly."
            )

    if (
        is_gpu_group
        and target_gpu_stack_preset != current_gpu_stack_preset
        and target_platform == current_platform
        and target_preset == current_preset
        and effective_target_fabric == current_config_fabric
    ):
        raise ValueError(
            "Use upgrade node-template for Nebius-image GPU stack changes that do not "
            "also change node-group hardware platform, hardware preset, or GPU fabric."
        )
    if (
        target_os != current_os
        and target_platform == current_platform
        and target_preset == current_preset
        and effective_target_fabric == current_config_fabric
        and target_gpu_stack_preset == current_gpu_stack_preset
    ):
        raise ValueError(
            "Use upgrade node-template for OS changes that do not also change node-group "
            "hardware platform, hardware preset, or GPU fabric."
        )

    reservation = raw_group.get("reservation")
    current_reservation_policy = (
        _non_empty_text(reservation.get("policy")).upper()
        if isinstance(reservation, Mapping)
        else ""
    )
    reservation_policy = (
        _non_empty_text(to_reservation_policy).upper() or current_reservation_policy
    )
    reservation_policy = reservation_policy or "AUTO"
    if reservation_policy not in {"AUTO", "FORBID", "STRICT"}:
        raise ValueError("Replacement reservation policy must be one of: AUTO, FORBID, STRICT.")
    reservation_ids = tuple(
        sorted(
            set(
                _non_empty_text(item)
                for item in (
                    to_reservation_ids
                    or (
                        reservation.get("reservation_ids", ())
                        if isinstance(reservation, Mapping)
                        else ()
                    )
                )
                if _non_empty_text(item)
            )
        )
    )
    if reservation_policy == "STRICT" and not reservation_ids:
        raise ValueError("STRICT replacement reservation policy requires --to-reservation-id.")
    raw_autoscaling = raw_group.get("autoscaling")
    autoscaling_preimage = (
        copy.deepcopy(dict(raw_autoscaling)) if isinstance(raw_autoscaling, Mapping) else {}
    )
    desired_node_count = int(raw_group.get("node_count") or 0)
    if desired_node_count < 1 and autoscaling_preimage:
        desired_node_count = int(autoscaling_preimage.get("min_node_count") or 0)
    quota_report = _node_group_migration_quota_report(
        source_payload=source_payload,
        generated_config=generated_config,
        instance_id=target.instance_id,
        group=raw_group,
        target_platform=target_platform,
        target_preset=target_preset,
        target_os=target_os,
        target_gpu_stack_preset=target_gpu_stack_preset,
        gpu_cluster_key=target_gpu_cluster_key,
        effective_target_fabric=effective_target_fabric,
    )
    return _NodeGroupMigrationPlan(
        target_selector=target.selector,
        instance_id=target.instance_id,
        cluster_name=source_mk8s_cluster_name(source_component, fallback=target.instance_id),
        node_group=node_group,
        source_provider_name=source_provider_name,
        replacement_node_group=replacement_key,
        replacement_name=replacement_provider_name,
        node_group_kind=node_group_kind,
        gpu_cluster_key=gpu_cluster_key,
        target_gpu_cluster_key=target_gpu_cluster_key,
        current_config_fabric=current_config_fabric,
        current_state_fabric=current_state_fabric,
        requested_target_fabric=target_fabric,
        effective_target_fabric=effective_target_fabric,
        fabric_status=_node_group_migration_fabric_status(
            current_config_fabric=current_config_fabric,
            effective_target_fabric=effective_target_fabric,
        ),
        current_platform=current_platform,
        target_platform=target_platform,
        current_preset=current_preset,
        target_preset=target_preset,
        current_os=current_os,
        target_os=target_os,
        current_gpu_stack_preset=current_gpu_stack_preset,
        target_gpu_stack_preset=target_gpu_stack_preset,
        reservation_policy=reservation_policy,
        reservation_ids=reservation_ids,
        desired_node_count=desired_node_count,
        autoscaling_preimage=autoscaling_preimage,
        source_group=copy.deepcopy(dict(raw_group)),
        sfs_evidence=_node_group_migration_sfs_evidence(raw_group),
        soperator_managed=target.instance_id in set(_soperator_app_target_refs(source_payload)),
        quota_report=quota_report,
    )


def _node_group_migration_plan_from_intent(
    intent: Any,
    *,
    source_payload: Mapping[str, Any],
) -> _NodeGroupMigrationPlan:
    """Rebuild only presentation/executor state from the receipt's frozen authority."""

    target = parse_upgrade_selector(intent.target_selector)
    source_component = find_source_mk8s_component(source_payload, target.instance_id)
    source_group = copy.deepcopy(dict(intent.source_group))
    node_group_kind = "gpu" if bool(source_group.get("gpu", False)) else "cpu/system"
    return _NodeGroupMigrationPlan(
        target_selector=intent.target_selector,
        instance_id=intent.instance_id,
        cluster_name=source_mk8s_cluster_name(source_component, fallback=intent.instance_id),
        node_group=intent.source_key,
        source_provider_name=intent.source_provider_name,
        replacement_node_group=intent.replacement_key,
        replacement_name=intent.replacement_provider_name,
        node_group_kind=node_group_kind,
        gpu_cluster_key=intent.source_gpu_cluster_key,
        target_gpu_cluster_key=intent.target_gpu_cluster_key,
        current_config_fabric=intent.source_fabric,
        current_state_fabric=intent.source_fabric,
        requested_target_fabric=(
            intent.target_fabric if intent.target_fabric != intent.source_fabric else ""
        ),
        effective_target_fabric=intent.target_fabric,
        fabric_status=_node_group_migration_fabric_status(
            current_config_fabric=intent.source_fabric,
            effective_target_fabric=intent.target_fabric,
        ),
        current_platform=intent.source_platform,
        target_platform=intent.target_platform,
        current_preset=intent.source_preset,
        target_preset=intent.target_preset,
        current_os=intent.source_os,
        target_os=intent.target_os,
        current_gpu_stack_preset=intent.source_gpu_stack_preset,
        target_gpu_stack_preset=intent.target_gpu_stack_preset,
        reservation_policy=intent.reservation_policy,
        reservation_ids=intent.reservation_ids,
        desired_node_count=intent.desired_node_count,
        autoscaling_preimage=dict(intent.autoscaling_preimage),
        source_group=source_group,
        sfs_evidence=intent.shared_storage_evidence,
        soperator_managed=intent.soperator_managed,
        quota_report=None,
    )


def _format_node_group_migration_plan(
    plan: _NodeGroupMigrationPlan,
    *,
    config_path: Path,
    dry_run: bool,
) -> list[str]:
    lines = [
        "MK8s node-group migration plan",
        f"- target: {plan.target_selector}",
        f"- cluster: {plan.cluster_name}",
        f"- node group: {plan.node_group} ({plan.node_group_kind})",
        f"- replacement config key: {plan.replacement_node_group}",
        f"- replacement provider name: {plan.replacement_name}",
        f"- platform: {plan.current_platform} -> {plan.target_platform}",
        f"- hardware preset: {plan.current_preset} -> {plan.target_preset}",
        f"- OS image: {plan.current_os or '(unset)'} -> {plan.target_os or '(unchanged/unset)'}",
    ]
    if plan.node_group_kind == "gpu":
        lines.append(
            "- GPU stack preset: "
            f"{plan.current_gpu_stack_preset or '(operator-managed/driverless)'} -> "
            f"{plan.target_gpu_stack_preset or '(operator-managed/driverless)'}"
        )
    lines.extend(
        [
            f"- gpu cluster key: {plan.gpu_cluster_key or '(not applicable)'}",
            f"- current config fabric: {plan.current_config_fabric or '(not applicable)'}",
            f"- current Terraform state fabric: {plan.current_state_fabric or '(not found)'}",
            "- requested target fabric: "
            + (
                plan.requested_target_fabric
                if plan.requested_target_fabric
                else "(not provided; using current fabric when applicable)"
            ),
            f"- effective target fabric: {plan.effective_target_fabric or '(not applicable)'}",
            f"- fabric status: {plan.fabric_status}",
            f"- reservation policy: {plan.reservation_policy}",
            "- shared storage evidence: "
            + (", ".join(plan.sfs_evidence) if plan.sfs_evidence else "not found"),
            "- managed Soperator target: " + ("yes" if plan.soperator_managed else "no"),
            "- migration class: "
            + (
                "cross-fabric replacement"
                if plan.current_config_fabric
                and plan.effective_target_fabric
                and plan.current_config_fabric != plan.effective_target_fabric
                else "same-fabric replacement"
                if plan.effective_target_fabric
                else "shape replacement"
            ),
            "- execution gates:",
            "  - target shape and effective fabric must have replacement-group quota/capacity",
            "  - replacement nodes must be Ready and schedulable before old nodes are drained",
            "  - GPU groups must expose GPU resources before cutover",
            "  - InfiniBand groups must also expose RDMA resources and pass Network Operator checks",
            "  - Soperator worker groups require quiet Slurm state and PVC/SFS-backed workload data",
            "- staged phases:",
            "  - durable approved intent receipt",
            "  - preserve old Terraform-managed node-group state",
            "  - create the canonical replacement node group on the target shape",
            "  - validate CPU/GPU/RDMA/Soperator readiness as applicable",
            "  - cordon/drain old nodes only after replacement readiness",
            "  - retire old resources and reconcile config/Terraform state to a no-op final plan",
            "- recovery: pre-cutover cleanup is allowed; after scheduling cutover, retries "
            "continue forward until source retirement and final readiness",
        ]
    )
    if plan.quota_report is not None:
        quota_lines = format_quota_report_lines(
            plan.quota_report,
            phase="node-group migration",
            include_confirmed_components=True,
            markup=False,
        )
        if quota_lines:
            lines.append("- target quota/capacity preflight:")
            lines.extend(f"  {line}" for line in quota_lines)
    if _node_group_migration_quota_blocks(plan):
        lines.append(
            "- warning: target quota/capacity preflight is not clean; execute will fail before "
            "any receipt, config rewrite, render, Terraform plan/apply, or live mutation."
        )
    if plan.node_group_kind == "gpu" and plan.effective_target_fabric and not plan.sfs_evidence:
        lines.append(
            "- warning: no SFS/PVC evidence was found on the selected GPU node group; "
            "Soperator worker execute will fail before mutation until shared-storage "
            "evidence is present."
        )
    lines.append("- repeat dry-run command:")
    lines.append(
        _migrate_node_group_command(
            config_path=config_path,
            target_selector=plan.target_selector,
            node_group=plan.node_group,
            replacement_node_group=plan.replacement_node_group,
            replacement_name=plan.replacement_name,
            to_platform=plan.target_platform
            if plan.target_platform != plan.current_platform
            else "",
            to_preset=plan.target_preset if plan.target_preset != plan.current_preset else "",
            to_os=plan.target_os if plan.target_os != plan.current_os else "",
            to_gpu_stack_preset=plan.target_gpu_stack_preset
            if plan.target_gpu_stack_preset != plan.current_gpu_stack_preset
            else "",
            to_fabric=plan.requested_target_fabric,
        )
    )
    lines.append("- approved execute command:")
    lines.append(
        _migrate_node_group_command(
            config_path=config_path,
            target_selector=plan.target_selector,
            node_group=plan.node_group,
            replacement_node_group=plan.replacement_node_group,
            replacement_name=plan.replacement_name,
            to_platform=plan.target_platform
            if plan.target_platform != plan.current_platform
            else "",
            to_preset=plan.target_preset if plan.target_preset != plan.current_preset else "",
            to_os=plan.target_os if plan.target_os != plan.current_os else "",
            to_gpu_stack_preset=plan.target_gpu_stack_preset
            if plan.target_gpu_stack_preset != plan.current_gpu_stack_preset
            else "",
            to_fabric=plan.requested_target_fabric,
            execute=True,
            approve=True,
        )
    )
    if dry_run:
        lines.append(
            "Dry run only: no config.yaml write, generated bundle render, Terraform plan/apply, "
            "receipt, or live node mutation was performed."
        )
    return lines


def _upgrade_helm_chart_dry_run_command(
    *,
    config_path: Path,
    target_selector: str,
    to_version: str,
) -> str:
    return shlex.join(
        [
            "nebius-cxcli",
            "upgrade",
            "helm-chart",
            str(config_path),
            target_selector,
            "--to-version",
            to_version,
            "--no-interactive",
            "--dry-run",
        ]
    )


def _soperator_upgrade_dry_run_command(
    *,
    config_path: Path,
    target_ref: str,
    to_chart_version: str,
) -> str:
    return shlex.join(
        [
            "nebius-cxcli",
            "soperator",
            "upgrade",
            str(config_path),
            "--target",
            target_ref,
            "--to-release",
            to_chart_version,
            "--no-interactive",
            "--dry-run",
        ]
    )


def _source_helm_chart_row_path(
    payload: dict[str, Any],
    target: _HelmChartUpgradeTarget,
) -> PayloadPath | None:
    apps = payload.get("apps")
    charts = apps.get("charts") if isinstance(apps, Mapping) else None
    if not isinstance(charts, list):
        return None
    for index, row in enumerate(charts):
        if not isinstance(row, Mapping) or row.get("enabled") is False:
            continue
        if component_type_id(row) != target.chart_id:
            continue
        if _source_helm_chart_target_ref(payload, row) != target.target_ref:
            continue
        return ("apps", "charts", index)
    return None


def _source_helm_chart_row(
    payload: dict[str, Any],
    target: _HelmChartUpgradeTarget,
) -> dict[str, Any]:
    row_path = _source_helm_chart_row_path(payload, target)
    if row_path is None:
        raise ValueError(f"Could not find enabled {target.selector} in config.yaml apps.charts[].")
    row = _get_payload_value(payload, row_path)
    if not isinstance(row, dict):
        raise ValueError(f"{target.selector} row must be a mapping.")
    return row


def _plan_helm_chart_upgrade(
    *,
    payload: dict[str, Any],
    target: _HelmChartUpgradeTarget,
    target_version: str,
) -> _HelmChartUpgradePlan:
    row = _source_helm_chart_row(payload, target)
    instance_id = component_instance_id(row)
    return _HelmChartUpgradePlan(
        target=target,
        instance_id=instance_id,
        namespace=_non_empty_text(row.get("namespace")),
        release_name=_non_empty_text(row.get("release-name")) or instance_id,
        current_version=_non_empty_text(row.get("version")),
        target_version=_validate_helm_chart_version_value(target_version),
    )


def _update_source_helm_chart_version(
    payload: dict[str, Any],
    *,
    target: _HelmChartUpgradeTarget,
    target_version: str,
) -> bool:
    row = _source_helm_chart_row(payload, target)
    version = _validate_helm_chart_version_value(target_version)
    if row.get("version") == version:
        return False
    row["version"] = version
    return True


def _format_helm_chart_upgrade_plan(
    plan: _HelmChartUpgradePlan,
    *,
    dry_run: bool,
    repeat_dry_run_command: str | None = None,
) -> tuple[str, ...]:
    lines = [
        "Helm chart upgrade plan",
        f"- target: {plan.target.selector}",
        f"- chart: {plan.target.chart_id}",
        f"- target ref: {plan.target.target_ref}",
        f"- app instance: {plan.instance_id}",
        f"- namespace: {plan.namespace or 'default'}",
        f"- release: {plan.release_name}",
        f"- chart version: {plan.current_version or 'unset'} -> {plan.target_version}",
    ]
    if plan.current_version and plan.target_appears_lower:
        lines.extend(
            [
                "- warnings:",
                (
                    "  - requested chart version appears lower than the current "
                    "config version; cxcli will allow this for rollback or "
                    "recovery, but Helm chart downgrades are not guaranteed safe."
                ),
                (
                    "  - review the chart release notes, CRDs/schema migrations, "
                    "application state, and backups before applying this change "
                    "in production."
                ),
            ]
        )
    if dry_run:
        if repeat_dry_run_command:
            lines.append("- repeat dry-run command:")
            lines.append(repeat_dry_run_command)
        lines.append(
            "Dry run only: no config.yaml write, generated bundle render, "
            "or Flux apply was performed."
        )
    return tuple(lines)


def _soperator_upgrade_artifact_identity(
    source_payload: Mapping[str, Any] | None,
    *,
    target_ref: str,
    cluster_id: str = "",
    cluster_name: str = "",
    kube_context: str = "",
) -> SoperatorClusterArtifactIdentity:
    return soperator_cluster_artifact_identity_from_payload(
        source_payload or {},
        target_ref=target_ref,
        cluster_id=cluster_id,
        cluster_name=cluster_name,
        kube_context=kube_context,
    )


def _soperator_upgrade_now_iso() -> str:
    return datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z")


def _write_text_atomic(
    path: Path,
    content: str,
    *,
    encoding: str = "utf-8",
    file_mode: int | None = None,
    expected_absent: bool = False,
) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    data = content.encode(encoding)
    fd = -1
    temp_path: Path | None = None
    try:
        fd, raw_temp_path = tempfile.mkstemp(
            prefix=f".{path.name}.",
            suffix=".tmp",
            dir=path.parent,
        )
        temp_path = Path(raw_temp_path)
        with os.fdopen(fd, "wb") as handle:
            fd = -1
            if file_mode is not None:
                os.fchmod(handle.fileno(), file_mode)
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        if expected_absent:
            os.link(temp_path, path)
            temp_path.unlink()
        else:
            os.replace(temp_path, path)
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        if fd >= 0:
            os.close(fd)
        if temp_path is not None:
            temp_path.unlink(missing_ok=True)


def _soperator_upgrade_sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _soperator_upgrade_duration_seconds(value: str, *, option_name: str) -> int:
    raw = _non_empty_text(value) or "0s"
    if raw in {"0", "0s", "none"}:
        return 0
    try:
        return parse_go_duration_seconds(raw)
    except Exception as exc:
        raise RuntimeError(f"Invalid {option_name} duration {raw!r}.") from exc


def _run_soperator_upgrade_process(
    args: Sequence[str],
    *,
    input_text: str | None = None,
    timeout_seconds: int = 120,
    check: bool = True,
    extra_env: Mapping[str, str] | None = None,
) -> _SoperatorUpgradeCommandResult:
    env = os.environ.copy()
    if extra_env:
        env.update(dict(extra_env))
    result = subprocess.run(
        list(args),
        input=input_text,
        env=env,
        text=True,
        capture_output=True,
        timeout=timeout_seconds,
        check=False,
    )
    payload = _SoperatorUpgradeCommandResult(
        args=tuple(str(arg) for arg in args),
        returncode=result.returncode,
        stdout=result.stdout or "",
        stderr=result.stderr or "",
    )
    if check and result.returncode != 0:
        detail = (payload.stderr or payload.stdout or "").strip()
        raise RuntimeError(
            f"Command failed during Soperator upgrade: {shlex.join(payload.args)}"
            + (f"\n{detail}" if detail else "")
        )
    return payload


def _run_soperator_upgrade_kubectl(
    namespace: str,
    args: Sequence[str],
    *,
    kube_context: str | None = None,
    input_text: str | None = None,
    timeout_seconds: int = 120,
    check: bool = True,
    extra_env: Mapping[str, str] | None = None,
) -> _SoperatorUpgradeCommandResult:
    base_args = ["kubectl"]
    context = _non_empty_text(kube_context)
    if context:
        base_args.extend(["--context", context])
    return _run_soperator_upgrade_process(
        [*base_args, "-n", namespace, *args],
        input_text=input_text,
        timeout_seconds=timeout_seconds,
        check=check,
        extra_env=extra_env,
    )


def _run_soperator_upgrade_kubectl_cluster(
    args: Sequence[str],
    *,
    kube_context: str | None = None,
    input_text: str | None = None,
    timeout_seconds: int = 120,
    check: bool = True,
    extra_env: Mapping[str, str] | None = None,
) -> _SoperatorUpgradeCommandResult:
    base_args = ["kubectl"]
    context = _non_empty_text(kube_context)
    if context:
        base_args.extend(["--context", context])
    return _run_soperator_upgrade_process(
        [*base_args, *args],
        input_text=input_text,
        timeout_seconds=timeout_seconds,
        check=check,
        extra_env=extra_env,
    )


def _protected_data_plane_job_identity(
    manifest: Mapping[str, Any],
) -> ProtectedWorkloadIdentity:
    return protected_workload_identity(manifest)


def _ensure_protected_data_plane_job(
    manifest: Mapping[str, Any],
    *,
    kube_context: str,
    extra_env: Mapping[str, str] | None,
    allow_create: bool = True,
    expected_job_uid: str | None = None,
    expected_workload_sha256: str | None = None,
) -> tuple[str, str]:
    requested = _protected_data_plane_job_identity(manifest)
    namespace = requested.namespace
    name = requested.name
    if not str(kube_context or "").strip():
        raise RuntimeError("protected Soperator rootfs Job requires a Kubernetes context")
    env = _post_flux_subprocess_env(extra_env or {})

    def _adopt(
        payload: Mapping[str, Any],
        *,
        admitted_workload_sha256: str | None = None,
    ) -> tuple[str, str]:
        observed = _protected_data_plane_job_identity(payload)
        if (
            observed.namespace,
            observed.name,
            observed.purpose,
            observed.operation_id,
            observed.fence_epoch,
        ) != (
            requested.namespace,
            requested.name,
            requested.purpose,
            requested.operation_id,
            requested.fence_epoch,
        ):
            raise RuntimeError(
                f"recovery-required: protected rootfs Job {namespace}/{name} changed binding"
            )
        metadata = payload.get("metadata")
        metadata_map = metadata if isinstance(metadata, Mapping) else {}
        annotations = metadata_map.get("annotations")
        annotation_map = annotations if isinstance(annotations, Mapping) else {}
        requested_annotation = str(
            annotation_map.get(SOPERATOR_PROTECTED_REQUESTED_WORKLOAD_ANNOTATION) or ""
        ).strip()
        admitted_annotation = str(
            annotation_map.get(SOPERATOR_PROTECTED_ADMITTED_WORKLOAD_ANNOTATION) or ""
        ).strip()
        if (
            requested_annotation != requested.workload_sha256
            or admitted_annotation != observed.workload_sha256
            or (
                admitted_workload_sha256 is not None
                and admitted_annotation != admitted_workload_sha256
            )
        ):
            raise RuntimeError(
                f"recovery-required: protected rootfs Job {namespace}/{name} changed identity"
            )
        uid = str(metadata_map.get("uid") or "").strip()
        if not uid:
            raise RuntimeError(f"protected rootfs Job {namespace}/{name} has no UID")
        if expected_job_uid is not None and uid != expected_job_uid:
            raise RuntimeError(
                f"recovery-required: protected rootfs Job {namespace}/{name} changed UID"
            )
        if (
            expected_workload_sha256 is not None
            and observed.workload_sha256 != expected_workload_sha256
        ):
            raise RuntimeError(
                f"recovery-required: protected rootfs Job {namespace}/{name} changed "
                "admitted identity"
            )
        return uid, observed.workload_sha256

    existing = subprocess.run(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "job",
            name,
            "-o",
            "json",
        ],
        env=env,
        capture_output=True,
        text=True,
        timeout=30,
    )
    if existing.returncode == 0:
        try:
            payload = json.loads(existing.stdout or "{}")
        except json.JSONDecodeError as exc:
            raise RuntimeError("protected Soperator rootfs Job returned invalid JSON") from exc
        return _adopt(payload)
    if "notfound" not in f"{existing.stdout}\n{existing.stderr}".lower() and "not found" not in (
        f"{existing.stdout}\n{existing.stderr}".lower()
    ):
        detail = _first_non_empty_line(existing.stderr or existing.stdout or "")
        raise RuntimeError(
            f"could not inspect protected rootfs Job {namespace}/{name}"
            + (f": {detail}" if detail else "")
        )
    if not allow_create:
        raise RuntimeError(
            f"recovery-required: completed protected rootfs Job {namespace}/{name} is missing"
        )
    admitted = subprocess.run(
        [
            "kubectl",
            "--context",
            kube_context,
            "create",
            "--dry-run=server",
            "-f",
            "-",
            "-o",
            "json",
        ],
        env=env,
        input=yaml.safe_dump(dict(manifest), sort_keys=False),
        capture_output=True,
        text=True,
        timeout=60,
    )
    if admitted.returncode != 0:
        detail = _first_non_empty_line(admitted.stderr or admitted.stdout or "")
        raise RuntimeError(
            f"protected rootfs Job {namespace}/{name} failed server-side admission"
            + (f": {detail}" if detail else "")
        )
    try:
        admitted_payload = json.loads(admitted.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError("protected Soperator Job admission returned invalid JSON") from exc
    admitted_identity = _protected_data_plane_job_identity(admitted_payload)
    if (
        admitted_identity.namespace,
        admitted_identity.name,
        admitted_identity.purpose,
        admitted_identity.operation_id,
        admitted_identity.fence_epoch,
    ) != (
        requested.namespace,
        requested.name,
        requested.purpose,
        requested.operation_id,
        requested.fence_epoch,
    ):
        raise RuntimeError(
            f"protected rootfs Job {namespace}/{name} admission changed its operation binding"
        )
    bound_manifest = bind_protected_workload_identity(
        manifest,
        requested_workload_sha256=requested.workload_sha256,
        admitted_workload_sha256=admitted_identity.workload_sha256,
    )
    created = subprocess.run(
        ["kubectl", "--context", kube_context, "create", "-f", "-"],
        env=env,
        input=yaml.safe_dump(bound_manifest, sort_keys=False),
        capture_output=True,
        text=True,
        timeout=60,
    )
    if created.returncode != 0:
        detail = _first_non_empty_line(created.stderr or created.stdout or "")
        raise RuntimeError(
            f"could not create protected rootfs Job {namespace}/{name}"
            + (f": {detail}" if detail else "")
        )
    observed = subprocess.run(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "job",
            name,
            "-o",
            "json",
        ],
        env=env,
        capture_output=True,
        text=True,
        timeout=30,
    )
    if observed.returncode != 0:
        raise RuntimeError(f"created protected rootfs Job {namespace}/{name} is unreadable")
    try:
        payload = json.loads(observed.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError("created protected Soperator Job returned invalid JSON") from exc
    return _adopt(
        payload,
        admitted_workload_sha256=admitted_identity.workload_sha256,
    )


def _wait_protected_data_plane_job(
    *,
    namespace: str,
    name: str,
    uid: str,
    kube_context: str,
    extra_env: Mapping[str, str] | None,
    include_logs: bool,
    expected_workload_sha256: str,
) -> str:
    if not str(kube_context or "").strip():
        raise RuntimeError("protected Soperator rootfs Job requires a Kubernetes context")
    env = _post_flux_subprocess_env(extra_env or {})
    deadline = time.monotonic() + 2700
    payload: Mapping[str, object]
    while True:
        observed = subprocess.run(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "job",
                name,
                "-o",
                "json",
            ],
            env=env,
            capture_output=True,
            text=True,
            timeout=30,
        )
        if observed.returncode != 0:
            detail = _first_non_empty_line(observed.stderr or observed.stdout or "")
            raise RuntimeError(
                f"recovery-required: protected rootfs Job {namespace}/{name} "
                "became unreadable" + (f": {detail}" if detail else "")
            )
        try:
            decoded = json.loads(observed.stdout or "{}")
        except json.JSONDecodeError as exc:
            raise RuntimeError("protected Soperator Job returned invalid JSON") from exc
        if not isinstance(decoded, Mapping):
            raise RuntimeError("protected Soperator Job returned invalid JSON")
        payload = decoded
        metadata = payload.get("metadata")
        metadata_map = metadata if isinstance(metadata, Mapping) else {}
        if str(metadata_map.get("uid") or "") != uid:
            raise RuntimeError(f"protected rootfs Job {namespace}/{name} UID changed")
        if _protected_data_plane_job_identity(payload).workload_sha256 != expected_workload_sha256:
            raise RuntimeError(
                f"recovery-required: protected rootfs Job {namespace}/{name} drifted"
            )
        status = payload.get("status")
        status_map = status if isinstance(status, Mapping) else {}
        conditions = status_map.get("conditions")
        condition_rows = conditions if isinstance(conditions, list) else []
        failed = next(
            (
                condition
                for condition in condition_rows
                if isinstance(condition, Mapping)
                and str(condition.get("type") or "").strip().lower() == "failed"
                and str(condition.get("status") or "").strip().lower() == "true"
            ),
            None,
        )
        if failed is not None:
            details = [
                line[:500]
                for field in ("reason", "message")
                if (line := _first_non_empty_line(str(failed.get(field) or "")))
            ]
            raise RuntimeError(
                f"protected rootfs Job {namespace}/{name} failed"
                + (f": {'; '.join(details)}" if details else "")
            )
        complete = any(
            isinstance(condition, Mapping)
            and str(condition.get("type") or "").strip().lower() == "complete"
            and str(condition.get("status") or "").strip().lower() == "true"
            for condition in condition_rows
        )
        if complete:
            break
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise RuntimeError(f"protected rootfs Job {namespace}/{name} did not complete")
        time.sleep(min(5.0, remaining))
    pods = subprocess.run(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"batch.kubernetes.io/job-name={name}",
            "-o",
            "json",
        ],
        env=env,
        capture_output=True,
        text=True,
        timeout=30,
    )
    try:
        pod_payload = json.loads(pods.stdout or "{}") if pods.returncode == 0 else {}
    except json.JSONDecodeError as exc:
        raise RuntimeError("protected Soperator Job Pod inventory returned invalid JSON") from exc
    pod_items = pod_payload.get("items") if isinstance(pod_payload, Mapping) else None
    if (
        not isinstance(pod_items, list)
        or len(pod_items) != 1
        or not isinstance(pod_items[0], Mapping)
    ):
        raise RuntimeError(
            f"recovery-required: protected rootfs Job {namespace}/{name} lacks one exact Pod"
        )
    protected_job_pod_identity(job=payload, pod=pod_items[0])
    if not include_logs:
        return ""
    logs = subprocess.run(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "logs",
            f"job/{name}",
        ],
        env=env,
        capture_output=True,
        text=True,
        timeout=300,
    )
    if logs.returncode != 0:
        detail = _first_non_empty_line(logs.stderr or logs.stdout or "")
        raise RuntimeError(
            f"could not read protected rootfs inventory {namespace}/{name}"
            + (f": {detail}" if detail else "")
        )
    return logs.stdout or ""


def _verify_protected_data_plane_job_pod(
    *,
    namespace: str,
    name: str,
    uid: str,
    expected_workload_sha256: str,
    kube_context: str,
    extra_env: Mapping[str, str] | None,
) -> str:
    """Verify the persisted Job and its one exact controller-owned Pod."""

    env = _post_flux_subprocess_env(extra_env or {})
    job_result = subprocess.run(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "job",
            name,
            "-o",
            "json",
        ],
        env=env,
        capture_output=True,
        text=True,
        timeout=30,
    )
    pods_result = subprocess.run(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"batch.kubernetes.io/job-name={name}",
            "-o",
            "json",
        ],
        env=env,
        capture_output=True,
        text=True,
        timeout=30,
    )
    try:
        job = json.loads(job_result.stdout or "{}") if job_result.returncode == 0 else {}
        pods = json.loads(pods_result.stdout or "{}") if pods_result.returncode == 0 else {}
    except json.JSONDecodeError as exc:
        raise RuntimeError("protected Soperator Job/Pod evidence returned invalid JSON") from exc
    if str(job.get("metadata", {}).get("uid") or "") != uid or (
        _protected_data_plane_job_identity(job).workload_sha256 != expected_workload_sha256
    ):
        raise RuntimeError(f"recovery-required: protected rootfs Job {namespace}/{name} drifted")
    items = pods.get("items") if isinstance(pods, Mapping) else None
    if not isinstance(items, list) or len(items) != 1 or not isinstance(items[0], Mapping):
        raise RuntimeError(
            f"recovery-required: protected rootfs Job {namespace}/{name} lacks one exact Pod"
        )
    return protected_job_pod_identity(job=job, pod=items[0])


def _run_soperator_upgrade_login_command(
    namespace: str,
    command: str,
    *,
    kube_context: str | None = None,
    input_text: str | None = None,
    timeout_seconds: int = 120,
    check: bool = True,
    extra_env: Mapping[str, str] | None = None,
) -> _SoperatorUpgradeCommandResult:
    result = _run_soperator_upgrade_kubectl(
        namespace,
        [
            "exec",
            _SOPERATOR_UPGRADE_LOGIN_POD,
            "--",
            "chroot",
            "/mnt/jail",
            "bash",
            "-lc",
            command,
        ],
        kube_context=kube_context,
        input_text=input_text,
        timeout_seconds=timeout_seconds,
        check=False,
        extra_env=extra_env,
    )
    if _soperator_upgrade_needs_controller_slurm_fallback(result):
        controller_result = _run_soperator_upgrade_kubectl(
            namespace,
            [
                "exec",
                _SOPERATOR_UPGRADE_CONTROLLER_POD,
                "-c",
                _SOPERATOR_UPGRADE_CONTROLLER_CONTAINER,
                "--",
                "bash",
                "-lc",
                command,
            ],
            kube_context=kube_context,
            input_text=input_text,
            timeout_seconds=timeout_seconds,
            check=False,
            extra_env=extra_env,
        )
        if controller_result.returncode == 0:
            return controller_result
    if check and result.returncode != 0:
        detail = (result.stderr or result.stdout or "").strip()
        raise RuntimeError(
            f"Command failed during Soperator upgrade: {shlex.join(result.args)}"
            + (f"\n{detail}" if detail else "")
        )
    return result


def _soperator_upgrade_needs_controller_slurm_fallback(
    result: _SoperatorUpgradeCommandResult,
) -> bool:
    if result.returncode == 0:
        return False
    detail = f"{result.stderr}\n{result.stdout}".lower()
    return any(
        marker in detail
        for marker in (
            "could not establish a configuration source",
            "dns srv lookup failed",
            "resolve_ctls_from_dns_srv",
            "failed to fetch config",
        )
    )


def _soperator_runtime_job_policy(
    policy: str | None,
    *,
    upgrade: bool = False,
    interactive: bool | None = None,
) -> str:
    prompt_capable = _is_tty_session() and interactive is not False
    resolved = _non_empty_text(policy)
    if not resolved:
        resolved = (
            "requeue-hold-all"
            if upgrade
            else ("interactive" if prompt_capable else "wait-then-cancel")
        )
    policies = _SOPERATOR_UPGRADE_JOB_POLICIES if upgrade else _SOPERATOR_DEPLOY_JOB_POLICIES
    if resolved not in policies:
        raise RuntimeError("--job-policy must be one of: " + ", ".join(sorted(policies)))
    if resolved == "interactive" and not prompt_capable:
        raise RuntimeError(
            "--job-policy interactive requires --interactive in a prompt-capable terminal. Use "
            "wait-to-finish, wait-then-cancel, cancel-selected, cancel-all, "
            "requeue-selected, requeue-all, requeue-hold-selected, or "
            "requeue-hold-all."
        )
    return resolved


def _validate_soperator_upgrade_job_controls(
    *,
    job_policy: str | None,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    interactive: bool | None = None,
) -> str:
    selected_policy = _non_empty_text(job_policy)
    if not selected_policy and interactive is not False and _is_tty_session():
        console.print(
            "Partition Policy: pause-all-active (required; pause every active Slurm partition)"
        )
        selected_policy = _prompt_upgrade_choice(
            "soperator.upgrade.job_policy",
            "requeue-hold-all",
            choices=[
                OptionChoice(
                    value="requeue-hold-all",
                    label=("requeue-hold-all  (requeue/hold eligible batch jobs; wait for others)"),
                    recommended=True,
                ),
                OptionChoice(
                    value="wait-to-finish",
                    label="wait-to-finish  (wait without cancelling)",
                ),
                OptionChoice(
                    value="wait-then-cancel",
                    label="wait-then-cancel  (cancel after the configured timeout)",
                ),
                OptionChoice(
                    value="requeue-all",
                    label="requeue-all  (requeue eligible batch jobs; wait for others)",
                ),
                OptionChoice(
                    value="cancel-all",
                    label="cancel-all  (cancel every blocking job)",
                ),
                OptionChoice(
                    value="interactive",
                    label="interactive  (choose a per-job action in the TUI)",
                ),
            ],
            missing="Slurm job policy",
        )
    resolved_policy = _soperator_runtime_job_policy(
        selected_policy,
        upgrade=True,
        interactive=interactive,
    )
    if cancel_job_ids and resolved_policy != "cancel-selected":
        raise RuntimeError("--cancel-job is valid only with --job-policy cancel-selected.")
    if resolved_policy == "cancel-selected" and not cancel_job_ids:
        raise RuntimeError("--job-policy cancel-selected requires at least one --cancel-job.")
    selected_requeue_policies = {"requeue-selected", "requeue-hold-selected"}
    if requeue_job_ids and resolved_policy not in selected_requeue_policies:
        raise RuntimeError(
            "--requeue-job is valid only with --job-policy requeue-selected or "
            "requeue-hold-selected."
        )
    if resolved_policy in selected_requeue_policies and not requeue_job_ids:
        raise RuntimeError(f"--job-policy {resolved_policy} requires at least one --requeue-job.")
    return resolved_policy


def _soperator_upgrade_failure_disposition(
    phase: str,
    exc: Exception,
) -> SoperatorFailureDisposition:
    del phase
    return soperator_failure_disposition(exc)


_SOPERATOR_SUPERVISOR_SECRET_VALUE = re.compile(
    r"(?i)\b(authorization|bearer|token|password|passwd|secret|private[-_ ]?key)"
    r"(\s*[:=]\s*|\s+)([^\s,;]+)"
)


def _soperator_upgrade_supervisor_failure_detail(exc: BaseException) -> str:
    """Return one bounded, secret-safe line for a durable supervisor retry."""

    detail = " ".join(str(exc).split())
    if not detail:
        return type(exc).__name__
    if "-----BEGIN" in detail.upper():
        return f"{type(exc).__name__}: sensitive detail redacted"
    detail = _SOPERATOR_SUPERVISOR_SECRET_VALUE.sub(
        lambda match: f"{match.group(1)}{match.group(2)}<redacted>",
        detail,
    )
    if len(detail) > 320:
        detail = f"{detail[:317]}..."
    return f"{type(exc).__name__}: {detail}"


def _acquire_soperator_upgrade_lease(
    *,
    stack: ExitStack,
    lease: SoperatorOperationLease,
    sleep: Callable[[float], None] = time.sleep,
) -> SoperatorOperationLease:
    """Re-prove a possibly written Lease without changing holder identity."""

    parent_lease = _SOPERATOR_PARENT_OPERATION_LEASE.get()
    if parent_lease is not None:
        if (
            parent_lease.cluster_id != lease.cluster_id
            or parent_lease.kube_context != lease.kube_context
        ):
            raise RuntimeError(
                "Nested Soperator reconciliation does not match the parent operation target"
            )
        parent_lease.assert_held()
        return parent_lease
    attempt = 0
    while True:
        try:
            return stack.enter_context(lease)
        except RuntimeError as exc:
            if "locked by another operation" in str(exc).lower():
                raise
            attempt += 1
            console.print(
                "[yellow]Soperator upgrade Lease authority is not yet provable; "
                "cxcli will retry in this invocation.[/yellow]"
            )
            sleep(min(5.0 * (2 ** min(attempt - 1, 4)), 60.0))


def _soperator_upgrade_login_tcp_probe(host: str, port: int) -> bool:
    try:
        with socket.create_connection((host, port), timeout=3):
            return True
    except OSError:
        return False


def _soperator_upgrade_parse_jobs(
    output: str,
    *,
    impact_scope: str = "allocated-node",
) -> tuple[AffectedSlurmJob, ...]:
    return parse_squeue_jobs(output, impact_scope=impact_scope)


def _soperator_upgrade_parse_slurm_node_aliases(output: str) -> dict[str, str]:
    aliases: dict[str, str] = {}
    current_node = ""
    for raw_line in output.splitlines():
        tokens = str(raw_line or "").strip().split()
        if not tokens:
            continue
        for token in tokens:
            if "=" not in token:
                continue
            key, value = token.split("=", 1)
            key = key.strip()
            value = value.strip()
            if not value or value in {"(null)", "N/A"}:
                continue
            if key == "NodeName":
                current_node = value
                aliases[value] = value
                continue
            if key in {"NodeHostName", "NodeAddr", "InstanceId"} and current_node:
                aliases[value] = current_node
    return aliases


def _is_nebius_compute_instance_node_name(value: str) -> bool:
    return bool(re.fullmatch(r"computeinstance-[A-Za-z0-9-]+", value))


def _soperator_upgrade_live_kubernetes_node_names(
    *,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> set[str] | None:
    result = _run_soperator_upgrade_kubectl_cluster(
        ["get", "nodes", "-o", "json", "--request-timeout=20s"],
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=60,
        check=False,
    )
    if result.returncode != 0:
        return None
    try:
        payload = json.loads(result.stdout or "{}")
    except json.JSONDecodeError:
        return None
    items = payload.get("items")
    if not isinstance(items, list):
        return None
    names: set[str] = set()
    for item in items:
        if not isinstance(item, Mapping):
            continue
        metadata = item.get("metadata")
        if not isinstance(metadata, Mapping):
            continue
        name = str(metadata.get("name", "") or "").strip()
        if name:
            names.add(name)
    return names


def _soperator_upgrade_live_unresolved_slurm_nodes(
    *,
    nodes: Sequence[str],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> tuple[str, ...]:
    unresolved = tuple(str(node or "").strip() for node in nodes if str(node or "").strip())
    if not any(_is_nebius_compute_instance_node_name(node) for node in unresolved):
        return unresolved
    live_nodes = _soperator_upgrade_live_kubernetes_node_names(
        kube_context=kube_context,
        extra_env=extra_env,
    )
    if live_nodes is None:
        return unresolved
    return tuple(
        node
        for node in unresolved
        if not _is_nebius_compute_instance_node_name(node) or node in live_nodes
    )


def _soperator_upgrade_slurm_node_filter(
    *,
    namespace: str,
    node_names: Sequence[str],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> tuple[str, ...]:
    selected_nodes = tuple(
        str(node or "").strip() for node in node_names if str(node or "").strip()
    )
    if not selected_nodes:
        return ()
    result = _run_soperator_upgrade_login_command(
        namespace,
        "scontrol show nodes",
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        return selected_nodes
    aliases = _soperator_upgrade_parse_slurm_node_aliases(result.stdout)
    if not aliases:
        return selected_nodes
    resolved: list[str] = []
    unresolved: list[str] = []
    for node in selected_nodes:
        slurm_node = aliases.get(node)
        if not slurm_node:
            unresolved.append(node)
            continue
        if slurm_node not in resolved:
            resolved.append(slurm_node)
    if unresolved:
        unresolved = list(
            _soperator_upgrade_live_unresolved_slurm_nodes(
                nodes=unresolved,
                kube_context=kube_context,
                extra_env=extra_env,
            )
        )
    if unresolved:
        raise RuntimeError(
            "Soperator upgrade could not map Kubernetes node or worker pod name(s) to "
            "Slurm node names for job inspection: "
            + ", ".join(unresolved)
            + ". Rerun discovery/onboarding after Slurm node aliases are visible, or "
            "resolve the node identity mismatch before using --job-policy."
        )
    return tuple(resolved)


def _soperator_upgrade_worker_nodeset_pod_candidates(
    *,
    namespace: str,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> tuple[str, ...]:
    result = _run_soperator_upgrade_kubectl(
        namespace,
        ["get", "pods", "-o", "json", "--request-timeout=20s"],
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=60,
        check=False,
    )
    if result.returncode != 0:
        return ()
    try:
        payload = json.loads(result.stdout or "{}")
    except json.JSONDecodeError:
        return ()
    items = payload.get("items")
    if not isinstance(items, list):
        return ()
    selected: list[str] = []
    seen: set[str] = set()
    for item in items:
        if not isinstance(item, Mapping):
            continue
        status = item.get("status")
        if not isinstance(status, Mapping) or str(status.get("phase", "") or "") != "Running":
            continue
        metadata = item.get("metadata")
        if not isinstance(metadata, Mapping):
            continue
        labels = metadata.get("labels")
        if not isinstance(labels, Mapping):
            continue
        nodeset_name = ""
        for label_key in _SOPERATOR_NODESET_LABEL_KEYS:
            nodeset_name = str(labels.get(label_key, "") or "").strip()
            if nodeset_name:
                break
        if not normalize_component_token(nodeset_name).startswith("worker"):
            continue
        pod_name = str(metadata.get("name", "") or "").strip()
        if pod_name and pod_name not in seen:
            seen.add(pod_name)
            selected.append(pod_name)
    return tuple(selected)


def _soperator_upgrade_live_slurmcluster_exists(
    *,
    namespace: str,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> bool:
    result = _run_soperator_upgrade_kubectl(
        namespace,
        ["get", "slurmclusters", "-o", "name", "--request-timeout=20s"],
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=60,
        check=False,
    )
    return result.returncode == 0 and any(line.strip() for line in result.stdout.splitlines())


def _soperator_upgrade_live_slurmcluster_namespaces(
    *,
    extra_env: Mapping[str, str] | None = None,
) -> tuple[str, ...]:
    """Resolve the source workload namespace independently of the desired chart namespace."""

    result = _run_soperator_upgrade_kubectl_cluster(
        ["get", "slurmclusters", "-A", "-o", "json", "--request-timeout=20s"],
        extra_env=extra_env,
        timeout_seconds=60,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError("Soperator upgrade could not discover the live SlurmCluster namespace")
    try:
        payload = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            "Soperator upgrade received an invalid live SlurmCluster inventory"
        ) from exc
    items = payload.get("items") if isinstance(payload, Mapping) else None
    if not isinstance(items, list):
        raise RuntimeError("Soperator upgrade received no live SlurmCluster inventory")
    namespaces: set[str] = set()
    identities = 0
    for item in items:
        if not isinstance(item, Mapping):
            continue
        metadata = item.get("metadata")
        metadata_map = metadata if isinstance(metadata, Mapping) else {}
        namespace = _non_empty_text(metadata_map.get("namespace"))
        name = _non_empty_text(metadata_map.get("name"))
        if not namespace or not name:
            raise RuntimeError("Soperator upgrade found an incomplete live SlurmCluster identity")
        identities += 1
        namespaces.add(namespace)
    if identities != 1 or len(namespaces) != 1:
        raise RuntimeError(
            "Soperator upgrade requires exactly one live SlurmCluster before maintenance"
        )
    return tuple(sorted(namespaces))


def _soperator_upgrade_login_path_available(
    *,
    namespace: str,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> bool:
    result = _run_soperator_upgrade_login_command(
        namespace,
        "true",
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=60,
        check=False,
    )
    return result.returncode == 0


_SOPERATOR_UPGRADE_SQUEUE_FORMAT = "%i|%u|%T|%P|%N|%n|%Y|%r|%M|%l|%L|%j"
_SOPERATOR_UPGRADE_ACTIVE_SQUEUE_STATES = "RUNNING,COMPLETING,CONFIGURING,SUSPENDED,STOPPED"


def _soperator_upgrade_affected_partitions(
    *,
    namespace: str,
    node_names: Sequence[str],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> tuple[str, ...]:
    selected_nodes = tuple(_non_empty_text(node) for node in node_names if _non_empty_text(node))
    if not selected_nodes:
        return ()
    result = _run_soperator_upgrade_login_command(
        namespace,
        "scontrol show node " + ",".join(shlex.quote(node) for node in selected_nodes) + " -o",
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        detail = result.stderr.strip() or result.stdout.strip() or f"exit {result.returncode}"
        raise RuntimeError(
            "Soperator upgrade could not inspect Slurm partitions for affected nodes "
            f"{bounded_identifier_summary(selected_nodes)} "
            f"before pending-job policy evaluation: {detail}"
        )
    partitions = affected_slurm_partitions_from_scontrol_show_node(result.stdout)
    if not partitions:
        raise RuntimeError(
            "Soperator upgrade could not determine Slurm partitions for affected nodes "
            f"{bounded_identifier_summary(selected_nodes)} "
            "before pending-job policy evaluation. "
            "Resolve Slurm node partition metadata before using --job-policy."
        )
    return partitions


def _soperator_upgrade_running_jobs(
    *,
    namespace: str,
    node_names: Sequence[str],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> tuple[AffectedSlurmJob, ...]:
    node_filter = ",".join(name for name in node_names if name)
    command = (
        f"squeue -h -t {_SOPERATOR_UPGRADE_ACTIVE_SQUEUE_STATES} "
        f"-o '{_SOPERATOR_UPGRADE_SQUEUE_FORMAT}'"
    )
    if node_filter:
        command += f" -w {shlex.quote(node_filter)}"
    result = _run_soperator_upgrade_login_command(
        namespace,
        command,
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
    )
    return _soperator_upgrade_parse_jobs(result.stdout, impact_scope="allocated-node")


def _soperator_upgrade_pending_jobs(
    *,
    namespace: str,
    node_names: Sequence[str],
    partitions: Sequence[str],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
    all_jobs: bool = False,
) -> tuple[AffectedSlurmJob, ...]:
    selected_partitions = tuple(
        _non_empty_text(partition) for partition in partitions if _non_empty_text(partition)
    )
    selected_nodes = tuple(_non_empty_text(node) for node in node_names if _non_empty_text(node))
    if not selected_partitions and not selected_nodes and not all_jobs:
        return ()

    def _pending_candidates(query_partitions: Sequence[str]) -> tuple[AffectedSlurmJob, ...]:
        command = f"squeue -h -t PENDING -o '{_SOPERATOR_UPGRADE_SQUEUE_FORMAT}'"
        selected_query_partitions = tuple(
            _non_empty_text(partition)
            for partition in query_partitions
            if _non_empty_text(partition)
        )
        if selected_query_partitions:
            command += " -p " + shlex.quote(",".join(selected_query_partitions))
        result = _run_soperator_upgrade_login_command(
            namespace,
            command,
            kube_context=kube_context,
            extra_env=extra_env,
            timeout_seconds=120,
        )
        return _soperator_upgrade_parse_jobs(result.stdout, impact_scope="pending")

    candidates: list[AffectedSlurmJob] = []
    if all_jobs:
        candidates.extend(_pending_candidates(()))
    elif selected_partitions:
        candidates.extend(_pending_candidates(selected_partitions))
    if selected_nodes and not all_jobs:
        candidates.extend(_pending_candidates(()))
    if all_jobs:
        return tuple(
            replace(job, impact_scope="cluster-wide")
            for job in dedupe_slurm_jobs(candidates)
            if slurm_job_is_pending(job)
        )
    return filter_affected_pending_slurm_jobs(
        dedupe_slurm_jobs(candidates),
        affected_nodes=selected_nodes,
        affected_partitions=selected_partitions,
    )


def _soperator_upgrade_affected_jobs(
    *,
    namespace: str,
    node_names: Sequence[str],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
    include_pending: bool = True,
    all_jobs: bool = False,
) -> tuple[AffectedSlurmJob, ...]:
    selected_nodes = tuple(_non_empty_text(node) for node in node_names if _non_empty_text(node))
    if not selected_nodes and not all_jobs:
        return ()
    partitions: tuple[str, ...] = ()
    if include_pending and not all_jobs:
        partitions = _soperator_upgrade_affected_partitions(
            namespace=namespace,
            node_names=selected_nodes,
            kube_context=kube_context,
            extra_env=extra_env,
        )
    running_jobs = _soperator_upgrade_running_jobs(
        namespace=namespace,
        node_names=() if all_jobs else selected_nodes,
        kube_context=kube_context,
        extra_env=extra_env,
    )
    if not include_pending:
        return dedupe_slurm_jobs(running_jobs)
    return dedupe_slurm_jobs(
        (
            *running_jobs,
            *_soperator_upgrade_pending_jobs(
                namespace=namespace,
                node_names=() if all_jobs else selected_nodes,
                partitions=partitions,
                kube_context=kube_context,
                extra_env=extra_env,
                all_jobs=all_jobs,
            ),
        )
    )


_SOPERATOR_UPGRADE_JOBS_TABLE_TITLE = "Affected Slurm jobs blocking Soperator upgrade"


def _print_soperator_upgrade_jobs_table(jobs: Sequence[AffectedSlurmJob]) -> None:
    console.print(build_slurm_jobs_table(jobs, title=_SOPERATOR_UPGRADE_JOBS_TABLE_TITLE))


@contextmanager
def _soperator_upgrade_job_prompt_paused() -> Iterator[None]:
    pause = _SOPERATOR_UPGRADE_JOB_PROMPT_PAUSE.get()
    if callable(pause):
        with pause():
            yield
        return
    yield


def _prompt_soperator_upgrade_job_control(
    jobs: Sequence[AffectedSlurmJob],
    *,
    jobs_provider: Callable[[], Sequence[AffectedSlurmJob]] | None = None,
    action_handler: Callable[
        [str, tuple[str, ...], tuple[AffectedSlurmJob, ...]],
        Sequence[AffectedSlurmJob],
    ]
    | None = None,
    wait_timeout_seconds: int = 0,
    refresh_interval_seconds: int = 30,
) -> tuple[str, tuple[str, ...]]:
    with _soperator_upgrade_job_prompt_paused():
        return prompt_slurm_job_control(
            jobs,
            console=console,
            table_title=_SOPERATOR_UPGRADE_JOBS_TABLE_TITLE,
            is_tty=_is_tty_session(),
            text_prompt=lambda message, default, show_default: str(
                typer.prompt(message, default=default, show_default=show_default)
            ),
            jobs_provider=jobs_provider,
            action_handler=action_handler,
            wait_timeout_seconds=wait_timeout_seconds,
            poll_interval_seconds=refresh_interval_seconds,
        )


def _soperator_upgrade_cancel_jobs(
    namespace: str,
    job_ids: Sequence[str],
    *,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> None:
    selected = tuple(_non_empty_text(job_id) for job_id in job_ids if _non_empty_text(job_id))
    if not selected:
        return
    _run_soperator_upgrade_login_command(
        namespace,
        "scancel " + " ".join(shlex.quote(job_id) for job_id in selected),
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
    )


def _soperator_upgrade_requeue_jobs(
    namespace: str,
    job_ids: Sequence[str],
    *,
    hold: bool = False,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> None:
    selected = tuple(_non_empty_text(job_id) for job_id in job_ids if _non_empty_text(job_id))
    if not selected:
        return
    action = "requeuehold" if hold else "requeue"
    _run_soperator_upgrade_login_command(
        namespace,
        f"scontrol {action} " + " ".join(shlex.quote(job_id) for job_id in selected),
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
    )


