def _soperator_upgrade_wait_for_requeued_jobs_to_leave_nodes(
    *,
    namespace: str,
    node_names: Sequence[str],
    job_ids: Sequence[str],
    timeout_seconds: int,
    refresh_interval_seconds: int,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
    include_pending: bool = True,
    all_jobs: bool = False,
) -> tuple[AffectedSlurmJob, ...]:
    selected = frozenset(_non_empty_text(job_id) for job_id in job_ids if _non_empty_text(job_id))
    if not selected:
        return
    transition_timeout = min(timeout_seconds if timeout_seconds > 0 else 300, 300)
    deadline = time.monotonic() + max(transition_timeout, 1)
    while True:
        remaining = [
            job
            for job in _soperator_upgrade_affected_jobs(
                namespace=namespace,
                node_names=node_names,
                kube_context=kube_context,
                extra_env=extra_env,
                include_pending=include_pending,
                all_jobs=all_jobs,
            )
            if job.job_id in selected
        ]
        if not remaining:
            return
        if time.monotonic() >= deadline:
            raise RuntimeError(
                f"{len(remaining)} affected Slurm job(s) remain after requeue/requeuehold. "
                "Rerun after they finish or cancel them explicitly."
            )
        time.sleep(max(refresh_interval_seconds, 1))


def _soperator_upgrade_wait_for_cancelled_jobs_to_leave_nodes(
    *,
    namespace: str,
    node_names: Sequence[str],
    job_ids: Sequence[str],
    timeout_seconds: int,
    refresh_interval_seconds: int,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
    include_pending: bool = True,
    all_jobs: bool = False,
) -> tuple[AffectedSlurmJob, ...]:
    selected = frozenset(_non_empty_text(job_id) for job_id in job_ids if _non_empty_text(job_id))
    if not selected:
        return _soperator_upgrade_affected_jobs(
            namespace=namespace,
            node_names=node_names,
            kube_context=kube_context,
            extra_env=extra_env,
            include_pending=include_pending,
            all_jobs=all_jobs,
        )
    transition_timeout = min(
        timeout_seconds if timeout_seconds > 0 else _SOPERATOR_UPGRADE_CANCEL_CLEAR_TIMEOUT_SECONDS,
        _SOPERATOR_UPGRADE_CANCEL_CLEAR_TIMEOUT_SECONDS,
    )
    deadline = time.monotonic() + max(transition_timeout, 1)
    while True:
        jobs = _soperator_upgrade_affected_jobs(
            namespace=namespace,
            node_names=node_names,
            kube_context=kube_context,
            extra_env=extra_env,
            include_pending=include_pending,
            all_jobs=all_jobs,
        )
        selected_remaining = [job for job in jobs if job.job_id in selected]
        if not selected_remaining:
            return jobs
        if time.monotonic() >= deadline:
            remaining_ids = ", ".join(job.job_id for job in selected_remaining)
            raise RuntimeError(
                "Affected Slurm job(s) remain after scancel: "
                + remaining_ids
                + ". Slurm may still show them as COMPLETING while nodes return to service; "
                "rerun after they clear or ask a Slurm administrator to inspect stuck "
                "COMPLETING jobs."
            )
        time.sleep(max(refresh_interval_seconds, 1))


def _soperator_upgrade_wait_dashboard(
    jobs: Sequence[AffectedSlurmJob],
    *,
    local_elapsed_seconds: int,
    poll_interval_seconds: int,
) -> Table:
    return build_slurm_wait_dashboard(
        jobs,
        local_elapsed_seconds=local_elapsed_seconds,
        poll_interval_seconds=poll_interval_seconds,
    )


def _soperator_upgrade_wait_for_jobs_until_timeout(
    *,
    namespace: str,
    node_names: Sequence[str],
    timeout_seconds: int,
    refresh_interval_seconds: int,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
    include_pending: bool = True,
    all_jobs: bool = False,
) -> None:
    deadline = time.monotonic() + timeout_seconds if timeout_seconds > 0 else None
    poll_interval = max(refresh_interval_seconds, 1)

    def _jobs() -> tuple[AffectedSlurmJob, ...]:
        return _soperator_upgrade_affected_jobs(
            namespace=namespace,
            node_names=node_names,
            kube_context=kube_context,
            extra_env=extra_env,
            include_pending=include_pending,
            all_jobs=all_jobs,
        )

    def _timed_out() -> bool:
        return deadline is not None and time.monotonic() >= deadline

    if not getattr(console, "is_terminal", False):
        while True:
            jobs = _jobs()
            if not jobs:
                console.print("No affected Slurm jobs remain", soft_wrap=True)
                return ()
            console.print(
                _soperator_upgrade_wait_dashboard(
                    jobs,
                    local_elapsed_seconds=0,
                    poll_interval_seconds=poll_interval,
                )
            )
            for local_elapsed in range(poll_interval):
                if _timed_out():
                    return jobs
                if local_elapsed:
                    console.print(
                        _soperator_upgrade_wait_dashboard(
                            jobs,
                            local_elapsed_seconds=local_elapsed,
                            poll_interval_seconds=poll_interval,
                        )
                    )
                time.sleep(1)

    with Live(console=console, refresh_per_second=4) as live:
        while True:
            jobs = _jobs()
            if not jobs:
                live.update(Table(title="No affected Slurm jobs remain"))
                return ()
            for local_elapsed in range(poll_interval):
                live.update(
                    _soperator_upgrade_wait_dashboard(
                        jobs,
                        local_elapsed_seconds=local_elapsed,
                        poll_interval_seconds=poll_interval,
                    )
                )
                if _timed_out():
                    return jobs
                time.sleep(1)


def _soperator_upgrade_wait_for_jobs(
    *,
    namespace: str,
    node_names: Sequence[str],
    timeout_seconds: int,
    refresh_interval_seconds: int,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
    include_pending: bool = True,
    all_jobs: bool = False,
) -> None:
    remaining = _soperator_upgrade_wait_for_jobs_until_timeout(
        namespace=namespace,
        node_names=node_names,
        timeout_seconds=timeout_seconds,
        refresh_interval_seconds=refresh_interval_seconds,
        kube_context=kube_context,
        extra_env=extra_env,
        include_pending=include_pending,
        all_jobs=all_jobs,
    )
    if remaining:
        raise RuntimeError(
            "Timed out waiting for Slurm jobs to finish. Rerun with a longer "
            "--job-wait-timeout, cancel, requeue, or requeue-hold selected jobs, "
            "or use --job-policy wait-then-cancel."
        )


def _soperator_upgrade_slurm_nodes_for_rollout(
    *,
    namespace: str,
    node_group: str,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> tuple[str, ...]:
    selected_node_group = _non_empty_text(node_group)
    if selected_node_group:
        result = _run_soperator_upgrade_kubectl_cluster(
            [
                "get",
                "nodes",
                "-l",
                f"nebius.com/node-group={selected_node_group}",
                "-o",
                "jsonpath={range .items[*]}{.metadata.name}{'\\n'}{end}",
            ],
            kube_context=kube_context,
            extra_env=extra_env,
            timeout_seconds=120,
            check=False,
        )
        nodes = tuple(line.strip() for line in result.stdout.splitlines() if line.strip())
        if nodes:
            return _soperator_upgrade_slurm_node_filter(
                namespace=namespace,
                node_names=nodes,
                kube_context=kube_context,
                extra_env=extra_env,
            )
    result = _run_soperator_upgrade_login_command(
        namespace,
        "sinfo -h -N -o '%N'",
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
    )
    nodes = tuple(line.strip() for line in result.stdout.splitlines() if line.strip())
    return _soperator_upgrade_slurm_node_filter(
        namespace=namespace,
        node_names=nodes,
        kube_context=kube_context,
        extra_env=extra_env,
    )


def _soperator_upgrade_expected_static_slurm_nodes(
    values: Mapping[str, Any],
) -> tuple[str, ...]:
    """Derive the exact Slurm node names rendered by upstream static NodeSets."""

    nodesets_chart = values.get("nodesets")
    nodesets_overrides = (
        nodesets_chart.get("overrideValues") if isinstance(nodesets_chart, Mapping) else None
    )
    nodesets = (
        nodesets_overrides.get("nodesets") if isinstance(nodesets_overrides, Mapping) else None
    )
    if not isinstance(nodesets, list):
        return ()
    expected: list[str] = []
    for index, item in enumerate(nodesets):
        if not isinstance(item, Mapping):
            raise RuntimeError(f"Soperator NodeSet values[{index}] must be a mapping")
        name = _non_empty_text(item.get("name"))
        if not name:
            raise RuntimeError(f"Soperator NodeSet values[{index}] has no name")
        replicas = item.get("replicas")
        if isinstance(replicas, bool):
            raise RuntimeError(f"Soperator NodeSet {name!r} has an invalid replica count")
        try:
            replica_count = int(replicas)
        except (TypeError, ValueError) as exc:
            raise RuntimeError(f"Soperator NodeSet {name!r} has an invalid replica count") from exc
        if replica_count <= 0:
            raise RuntimeError(f"Soperator NodeSet {name!r} must have at least one replica")
        expected.extend(f"{name}-{ordinal}" for ordinal in range(replica_count))
    if len(expected) != len(set(expected)):
        raise RuntimeError("Soperator NodeSet values render duplicate Slurm node names")
    return tuple(expected)


def _verify_soperator_upgrade_slurm_worker_registration(
    *,
    namespace: str,
    values: Mapping[str, Any],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> dict[str, object]:
    """Require target NodeSet workers to exist in Slurm before scheduling restore."""

    expected = _soperator_upgrade_expected_static_slurm_nodes(values)
    if not expected:
        raise RuntimeError("Soperator product readiness has no expected static Slurm worker nodes")
    result = _run_soperator_upgrade_login_command(
        namespace,
        "scontrol show nodes -o",
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            "Soperator product readiness could not inspect registered Slurm workers: "
            + (result.stderr.strip() or result.stdout.strip() or f"exit {result.returncode}")
        )

    observed: dict[str, tuple[str, str]] = {}
    for line_number, raw_line in enumerate(result.stdout.splitlines(), start=1):
        line = raw_line.strip()
        if not line:
            continue
        name_match = re.search(r"(?:^|\s)NodeName=(\S+)", line)
        state_match = re.search(r"(?:^|\s)State=(\S+)", line)
        start_match = re.search(r"(?:^|\s)SlurmdStartTime=(\S+)", line)
        if name_match is None or state_match is None or start_match is None:
            raise RuntimeError(
                "Soperator product readiness received malformed Slurm worker evidence "
                f"on line {line_number}"
            )
        name = name_match.group(1)
        if name in observed:
            raise RuntimeError(
                f"Soperator product readiness observed duplicate Slurm worker {name!r}"
            )
        observed[name] = (state_match.group(1), start_match.group(1))

    missing = sorted(set(expected) - set(observed))
    if missing:
        raise RuntimeError(
            "Soperator product readiness is missing target Slurm worker registration: "
            + ", ".join(missing)
        )
    unregistered_markers = {"UNKNOWN", "FUTURE", "INVALID_REG", "NO_RESPOND"}
    unavailable = sorted(
        name
        for name in expected
        if unregistered_markers.intersection(
            token for token in re.split(r"[+*~,]", observed[name][0].upper()) if token
        )
        or observed[name][1].upper() in {"NONE", "N/A", "UNKNOWN"}
    )
    if unavailable:
        raise RuntimeError(
            "Soperator product readiness found target Slurm workers that have not "
            "registered successfully: " + ", ".join(unavailable)
        )
    return {
        "schema": "nebius-cxcli.soperator-slurm-worker-readiness.v1",
        "status": "ready",
        "expectedNodeCount": len(expected),
        "registeredNodeCount": len(set(expected) & set(observed)),
        "nodes": [
            {
                "name": name,
                "state": observed[name][0],
                "slurmdStartTime": observed[name][1],
            }
            for name in expected
        ],
    }


def _soperator_upgrade_node_state_snapshot(
    *,
    namespace: str,
    node_names: Sequence[str],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> dict[str, str]:
    if not node_names:
        return {}
    result = _run_soperator_upgrade_login_command(
        namespace,
        "scontrol show node " + ",".join(shlex.quote(node) for node in node_names) + " -o",
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
        check=False,
    )
    states: dict[str, str] = {}
    for line in result.stdout.splitlines():
        name_match = re.search(r"\bNodeName=(\S+)", line)
        state_match = re.search(r"\bState=(\S+)", line)
        if name_match and state_match:
            states[name_match.group(1)] = state_match.group(1)
    return states


def _soperator_upgrade_node_recovery_snapshot(
    *,
    namespace: str,
    node_names: Sequence[str],
    extra_env: Mapping[str, str] | None = None,
) -> dict[str, dict[str, str]]:
    """Capture exact node State/Reason fields for write-ahead recovery."""

    nodes = tuple(_non_empty_text(node) for node in node_names if _non_empty_text(node))
    if not nodes:
        return {}
    result = _run_soperator_upgrade_login_command(
        namespace,
        "scontrol show node " + ",".join(shlex.quote(node) for node in nodes) + " -o",
        extra_env=extra_env,
        timeout_seconds=120,
    )
    snapshot: dict[str, dict[str, str]] = {}
    for line in result.stdout.splitlines():
        name_match = re.search(r"\bNodeName=(\S+)", line)
        state_match = re.search(r"\bState=(\S+)", line)
        reason_match = re.search(r"\bReason=(\S+)", line)
        if name_match and state_match:
            snapshot[name_match.group(1)] = {
                "state": state_match.group(1),
                "reason": reason_match.group(1) if reason_match else "",
            }
    if set(snapshot) != set(nodes):
        raise RuntimeError("recovery-required: Slurm node recovery snapshot is incomplete")
    return snapshot


def _soperator_upgrade_drain_slurm_nodes(
    *,
    namespace: str,
    node_names: Sequence[str],
    checkpoint_id: str,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> tuple[str, ...]:
    nodes = tuple(_non_empty_text(node) for node in node_names if _non_empty_text(node))
    if not nodes:
        return ()
    before = _soperator_upgrade_node_state_snapshot(
        namespace=namespace,
        node_names=nodes,
        kube_context=kube_context,
        extra_env=extra_env,
    )
    owned = tuple(node for node in nodes if "DRAIN" not in before.get(node, ""))
    if not owned:
        return ()
    _run_soperator_upgrade_login_command(
        namespace,
        "scontrol update NodeName="
        + ",".join(shlex.quote(node) for node in owned)
        + " State=DRAIN Reason="
        + shlex.quote(f"cxcli-soperator-upgrade:{checkpoint_id}"),
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
    )
    return owned


def _soperator_upgrade_restore_slurm_nodes(
    *,
    namespace: str,
    node_names: Sequence[str],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> None:
    nodes = tuple(_non_empty_text(node) for node in node_names if _non_empty_text(node))
    if not nodes:
        return
    _run_soperator_upgrade_login_command(
        namespace,
        "scontrol update NodeName="
        + ",".join(shlex.quote(node) for node in nodes)
        + " State=RESUME",
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
    )


def _soperator_upgrade_partition_state_snapshot(
    *,
    namespace: str,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> tuple[SlurmPartitionState, ...]:
    result = _run_soperator_upgrade_login_command(
        namespace,
        "scontrol show partition -o",
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            "Could not inspect Slurm partition states before scheduling pause: "
            + (result.stderr.strip() or result.stdout.strip() or f"exit {result.returncode}")
        )
    states = parse_scontrol_show_partition_states(result.stdout)
    if not states:
        raise RuntimeError("Could not inspect any Slurm partition states before scheduling pause.")
    return states


def _soperator_upgrade_partition_state(
    *,
    namespace: str,
    partition: str,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
) -> SlurmPartitionState:
    snapshot = _soperator_upgrade_partition_state_snapshot(
        namespace=namespace,
        kube_context=kube_context,
        extra_env=extra_env,
    )
    for state in snapshot:
        if state.name == partition:
            return state
    raise RuntimeError(
        "recovery-required: cxcli cannot verify Slurm partition "
        f"{partition!r} because it is absent from the full live partition snapshot."
    )


def _soperator_upgrade_partition_observation_matches(
    observation: SlurmPartitionState,
    *,
    record: str,
    fingerprint: str,
) -> bool:
    try:
        expected_fingerprint = slurm_partition_record_fingerprint(record)
        owned_fields_match = slurm_partition_owned_fields_match(observation.record, record)
    except ValueError:
        return False
    return expected_fingerprint == fingerprint and owned_fields_match


def _soperator_upgrade_partition_migration_observation_matches(
    observation: SlurmPartitionState,
    *,
    record: str,
    fingerprint: str,
) -> bool:
    """Compare a journal record at the authenticated cross-version restore."""

    try:
        expected_fingerprint = slurm_partition_record_fingerprint(record)
        guarded_fields_match = slurm_partition_migration_fields_match(
            observation.record,
            record,
        )
    except ValueError:
        return False
    return expected_fingerprint == fingerprint and guarded_fields_match


def _soperator_upgrade_pause_slurm_partitions(
    *,
    namespace: str,
    node_names: Sequence[str],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
    record_recorder: Callable[[SlurmPartitionPauseRecord], None] | None = None,
    all_active_partitions: bool = False,
    restore_on_failure: bool = True,
    mutation_guard: Callable[[], object] | None = None,
) -> tuple[SlurmPartitionPauseRecord, ...]:
    selected_nodes = tuple(_non_empty_text(node) for node in node_names if _non_empty_text(node))
    if not selected_nodes and not all_active_partitions:
        return ()
    snapshot = _soperator_upgrade_partition_state_snapshot(
        namespace=namespace,
        kube_context=kube_context,
        extra_env=extra_env,
    )
    fallback_error: RuntimeError | None = None
    if all_active_partitions:
        partitions = tuple(
            state.name for state in snapshot if slurm_partition_state_token(state.state) == "UP"
        )
    else:
        fallback_partitions: tuple[str, ...] = ()
        try:
            fallback_partitions = _soperator_upgrade_affected_partitions(
                namespace=namespace,
                node_names=selected_nodes,
                kube_context=kube_context,
                extra_env=extra_env,
            )
        except RuntimeError as exc:
            fallback_error = exc
        partitions = slurm_partitions_overlapping_nodes(
            states=snapshot,
            node_names=selected_nodes,
            fallback_partitions=fallback_partitions,
        )
        if not partitions and fallback_error is not None:
            raise fallback_error
    records = slurm_partition_pause_records(partitions=partitions, states=snapshot)
    if records and record_recorder is None:
        raise RuntimeError(
            "recovery-required: Slurm scheduling pause requires a durable full-record "
            "ownership journal before State=DOWN."
        )
    applied: list[SlurmPartitionPauseRecord] = []

    def _compensate_applied() -> None:
        if not applied:
            return
        try:
            _soperator_upgrade_restore_slurm_partitions(
                namespace=namespace,
                records=applied,
                kube_context=kube_context,
                extra_env=extra_env,
            )
        except Exception as restore_exc:
            raise RuntimeError(
                "Could not restore partially paused Slurm partitions after "
                "scheduling pause failed. Inspect: "
                + _soperator_upgrade_slurm_partition_restore_command(applied)
            ) from restore_exc

    for record in records:
        authority_check_failed = False
        try:
            if record_recorder is not None:
                record_recorder(record)
            live_before = _soperator_upgrade_partition_state(
                namespace=namespace,
                partition=record.partition,
                kube_context=kube_context,
                extra_env=extra_env,
            )
            if not _soperator_upgrade_partition_observation_matches(
                live_before,
                record=record.previous_record,
                fingerprint=record.previous_record_fingerprint,
            ):
                raise RuntimeError(
                    "recovery-required: Slurm partition "
                    f"{record.partition!r} changed after cxcli persisted pause intent "
                    "and before State=DOWN. No partition mutation was issued."
                )
            if mutation_guard is not None:
                try:
                    mutation_guard()
                except BaseException:
                    authority_check_failed = True
                    raise
            result = _run_soperator_upgrade_login_command(
                namespace,
                "scontrol update PartitionName="
                + shlex.quote(record.partition)
                + " State="
                + shlex.quote(record.applied_state),
                kube_context=kube_context,
                extra_env=extra_env,
                timeout_seconds=120,
                check=False,
            )
            live_after = _soperator_upgrade_partition_state(
                namespace=namespace,
                partition=record.partition,
                kube_context=kube_context,
                extra_env=extra_env,
            )
            if _soperator_upgrade_partition_observation_matches(
                live_after,
                record=record.previous_record,
                fingerprint=record.previous_record_fingerprint,
            ):
                detail = (
                    result.stderr.strip() or result.stdout.strip() or f"exit {result.returncode}"
                    if result.returncode != 0
                    else "state stayed unchanged"
                )
                raise RuntimeError(
                    f"Could not pause Slurm scheduling for partition {record.partition}: {detail}"
                )
            try:
                applied_record = record.with_applied_observation(live_after)
            except ValueError as exc:
                raise RuntimeError(
                    "recovery-required: Slurm partition "
                    f"{record.partition!r} did not expose the exact cxcli State=DOWN "
                    "postcondition. Automatic restore is unsafe."
                ) from exc
            applied.append(applied_record)
            if record_recorder is not None:
                record_recorder(applied_record)
            if result.returncode != 0:
                raise RuntimeError(
                    "Could not pause Slurm scheduling for partition "
                    f"{record.partition}: "
                    + (
                        result.stderr.strip()
                        or result.stdout.strip()
                        or f"exit {result.returncode}"
                    )
                )
        except Exception:
            if restore_on_failure and not authority_check_failed:
                _compensate_applied()
            raise
    return tuple(applied)


def _soperator_upgrade_restore_slurm_partitions(
    *,
    namespace: str,
    records: Sequence[SlurmPartitionPauseRecord],
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
    allow_topology_migration: bool = False,
) -> None:
    observation_matches = (
        _soperator_upgrade_partition_migration_observation_matches
        if allow_topology_migration
        else _soperator_upgrade_partition_observation_matches
    )
    for record in records:
        partition = _non_empty_text(record.partition)
        previous_state = _non_empty_text(record.previous_state)
        if not partition or not previous_state:
            continue
        live_before = _soperator_upgrade_partition_state(
            namespace=namespace,
            partition=partition,
            kube_context=kube_context,
            extra_env=extra_env,
        )
        normalize_alloc_nodes = allow_topology_migration and slurm_partition_alloc_nodes_is_all(
            record.previous_record
        )
        if observation_matches(
            live_before,
            record=record.previous_record,
            fingerprint=record.previous_record_fingerprint,
        ):
            if not normalize_alloc_nodes:
                continue
            result = _run_soperator_upgrade_login_command(
                namespace,
                "scontrol update PartitionName=" + shlex.quote(partition) + " AllocNodes=ALL",
                kube_context=kube_context,
                extra_env=extra_env,
                timeout_seconds=120,
                check=False,
            )
            live_after = _soperator_upgrade_partition_state(
                namespace=namespace,
                partition=partition,
                kube_context=kube_context,
                extra_env=extra_env,
            )
            if result.returncode == 0 and observation_matches(
                live_after,
                record=record.previous_record,
                fingerprint=record.previous_record_fingerprint,
            ):
                continue
            raise RuntimeError(
                "recovery-required: Slurm did not preserve the guarded partition "
                f"view while normalizing AllocNodes=ALL for {partition!r}."
            )
        if not record.applied_record or not record.applied_record_fingerprint:
            raise RuntimeError(
                "recovery-required: cxcli will not restore Slurm partition "
                f"{partition!r}: the journal lacks a durable full post-mutation "
                "fingerprint proving cxcli owns the live change."
            )
        if not observation_matches(
            live_before,
            record=record.applied_record,
            fingerprint=record.applied_record_fingerprint,
        ):
            raise RuntimeError(
                "recovery-required: cxcli will not restore Slurm partition "
                f"{partition!r}: the live customer-owned/unknown field view differs "
                "from both the saved customer record and cxcli's recorded State=DOWN "
                "record. Only migrated topology membership, derived totals, and exact "
                "target-version defaults are ignored."
            )
        result = _run_soperator_upgrade_login_command(
            namespace,
            "scontrol update PartitionName="
            + shlex.quote(partition)
            + " State="
            + shlex.quote(previous_state)
            + (" AllocNodes=ALL" if normalize_alloc_nodes else ""),
            kube_context=kube_context,
            extra_env=extra_env,
            timeout_seconds=120,
            check=False,
        )
        live_after = _soperator_upgrade_partition_state(
            namespace=namespace,
            partition=partition,
            kube_context=kube_context,
            extra_env=extra_env,
        )
        if observation_matches(
            live_after,
            record=record.previous_record,
            fingerprint=record.previous_record_fingerprint,
        ):
            continue
        if result.returncode != 0:
            raise RuntimeError(
                result.stderr.strip() or result.stdout.strip() or f"exit {result.returncode}"
            )
        raise RuntimeError(
            "recovery-required: Slurm accepted cxcli's restore request for partition "
            f"{partition!r}, but its customer-owned/unknown field view does not match "
            "the saved pre-mutation record."
        )


def _soperator_upgrade_slurm_partition_restore_command(
    records: Sequence[SlurmPartitionPauseRecord],
) -> str:
    commands = [
        "scontrol show partition " + shlex.quote(record.partition) + " -o"
        for record in records
        if _non_empty_text(record.partition) and _non_empty_text(record.previous_state)
    ]
    return "; ".join(commands)


def _soperator_upgrade_pause_record_from_payload(
    payload: Mapping[str, Any],
) -> SlurmPartitionPauseRecord:
    partition = _non_empty_text(payload.get("partition"))
    try:
        return SlurmPartitionPauseRecord(
            partition=partition,
            previous_state=_non_empty_text(payload.get("previous_state")),
            previous_record=_non_empty_text(payload.get("previous_record")),
            previous_record_fingerprint=_non_empty_text(payload.get("previous_record_fingerprint")),
            applied_state=_non_empty_text(payload.get("applied_state")) or "DOWN",
            applied_record=_non_empty_text(payload.get("applied_record")),
            applied_record_fingerprint=_non_empty_text(payload.get("applied_record_fingerprint")),
        )
    except ValueError as exc:
        raise RuntimeError(
            "recovery-required: managed Soperator Slurm pause journal has invalid "
            f"full-record ownership evidence for {partition or 'unknown partition'}."
        ) from exc


def _soperator_upgrade_pause_records_from_payload(
    payload: Any,
) -> tuple[SlurmPartitionPauseRecord, ...]:
    if payload is None:
        return ()
    if not isinstance(payload, Sequence) or isinstance(payload, (str, bytes, bytearray)):
        raise RuntimeError(
            "recovery-required: managed Soperator Slurm pause journal must be a list."
        )
    records: list[SlurmPartitionPauseRecord] = []
    for item in payload:
        if not isinstance(item, Mapping):
            raise RuntimeError(
                "recovery-required: managed Soperator Slurm pause journal entries must be mappings."
            )
        records.append(_soperator_upgrade_pause_record_from_payload(item))
    return tuple(records)


def _merge_soperator_upgrade_pause_records(
    existing: Sequence[SlurmPartitionPauseRecord],
    incoming: Sequence[SlurmPartitionPauseRecord],
) -> tuple[SlurmPartitionPauseRecord, ...]:
    merged = {record.partition: record for record in existing}
    for record in incoming:
        current = merged.get(record.partition)
        if current is None:
            merged[record.partition] = record
            continue
        if (
            current.previous_state != record.previous_state
            or not slurm_partition_owned_fields_match(
                current.previous_record,
                record.previous_record,
            )
            or current.applied_state != record.applied_state
        ):
            raise RuntimeError(
                "recovery-required: conflicting managed Soperator Slurm pause "
                f"ownership evidence for {record.partition}."
            )
        if (
            current.applied_record
            and record.applied_record
            and not slurm_partition_owned_fields_match(
                current.applied_record,
                record.applied_record,
            )
        ):
            raise RuntimeError(
                "recovery-required: conflicting managed Soperator Slurm post-mutation "
                f"fingerprints for {record.partition}."
            )
        if record.applied_record_fingerprint and not current.applied_record_fingerprint:
            merged[record.partition] = record
    return tuple(merged.values())


def _handle_soperator_upgrade_running_jobs(
    *,
    namespace: str,
    node_group: str = "",
    node_names: Sequence[str] | None = None,
    policy: str,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    wait_timeout_seconds: int,
    refresh_interval_seconds: int,
    checkpoint_id: str,
    kube_context: str | None = None,
    extra_env: Mapping[str, str] | None = None,
    drain_nodes: bool = True,
    slurm_scheduling_pause: bool = False,
    decision_recorder: Callable[[Mapping[str, Any]], None] | None = None,
    mutation_guard: Callable[[], object] | None = None,
    all_active_partitions: bool = False,
    continue_until_clear: bool = False,
    job_control_reader: Callable[[str], SlurmJobControlRecord | None] | None = None,
) -> tuple[str, ...]:
    if policy == "wait-then-cancel" and wait_timeout_seconds <= 0:
        raise RuntimeError(
            "--job-policy wait-then-cancel requires a positive --job-wait-timeout. "
            "Use --job-policy wait-to-finish --job-wait-timeout 0s for an unlimited wait."
        )

    def _record(action: str, **details: Any) -> None:
        if decision_recorder is None:
            return
        decision_recorder(
            {
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": action,
                **details,
            }
        )

    def _job_control_record(job_id: str) -> SlurmJobControlRecord | None:
        if job_control_reader is not None:
            return job_control_reader(job_id)
        selected = _non_empty_text(job_id)
        if not selected:
            raise RuntimeError("Slurm job identity is empty")
        result = _run_soperator_upgrade_login_command(
            namespace,
            "scontrol show job " + shlex.quote(selected) + " -o",
            kube_context=kube_context,
            extra_env=extra_env,
            timeout_seconds=120,
            check=False,
        )
        return slurm_job_control_record_from_query(
            requested_job_id=selected,
            returncode=result.returncode,
            stdout=result.stdout,
            stderr=result.stderr,
        )

    selected_node_names = (
        tuple(_non_empty_text(node) for node in node_names if _non_empty_text(node))
        if node_names is not None
        else _soperator_upgrade_slurm_nodes_for_rollout(
            namespace=namespace,
            node_group=node_group,
            kube_context=kube_context,
            extra_env=extra_env,
        )
    )
    if not selected_node_names and not all_active_partitions:
        return ()

    include_pending = not slurm_scheduling_pause
    if slurm_scheduling_pause:
        if decision_recorder is None:
            raise RuntimeError(
                "recovery-required: Slurm scheduling pause requires a durable "
                "partition ownership journal before State=DOWN."
            )

        def _record_partition_evidence(record: SlurmPartitionPauseRecord) -> None:
            _record(
                "scheduling-pause-recorded",
                node_names=selected_node_names,
                partitions=[record.as_payload()],
                pending_jobs="queued-not-blocking",
            )

        if mutation_guard is not None:
            mutation_guard()
        paused_partitions: tuple[SlurmPartitionPauseRecord, ...] = ()
        while True:
            paused_now = _soperator_upgrade_pause_slurm_partitions(
                namespace=namespace,
                node_names=selected_node_names,
                kube_context=kube_context,
                extra_env=extra_env,
                record_recorder=_record_partition_evidence,
                all_active_partitions=all_active_partitions,
                restore_on_failure=not continue_until_clear,
                mutation_guard=mutation_guard,
            )
            paused_partitions = _merge_soperator_upgrade_pause_records(
                paused_partitions,
                paused_now,
            )
            if paused_now:
                _record(
                    "scheduling-pause-applied",
                    node_names=selected_node_names,
                    partitions=[record.as_payload() for record in paused_now],
                    scope="all-active" if all_active_partitions else "affected-workers",
                    pending_jobs="queued-not-blocking",
                )
            if not all_active_partitions:
                break
            remaining_up = tuple(
                state.name
                for state in _soperator_upgrade_partition_state_snapshot(
                    namespace=namespace,
                    kube_context=kube_context,
                    extra_env=extra_env,
                )
                if slurm_partition_state_token(state.state) == "UP"
            )
            if not remaining_up:
                break
        if not paused_partitions:
            _record(
                "scheduling-pause-skipped",
                node_names=selected_node_names,
                reason="no active UP partitions required cxcli changes",
                scope="all-active" if all_active_partitions else "affected-workers",
                pending_jobs="queued-not-blocking",
            )

    def _jobs() -> tuple[AffectedSlurmJob, ...]:
        return _soperator_upgrade_affected_jobs(
            namespace=namespace,
            node_names=selected_node_names,
            kube_context=kube_context,
            extra_env=extra_env,
            include_pending=include_pending,
            all_jobs=all_active_partitions,
        )

    def _cancel(job_ids: Sequence[str]) -> None:
        if mutation_guard is not None:
            mutation_guard()
        _soperator_upgrade_cancel_jobs(
            namespace,
            job_ids,
            kube_context=kube_context,
            extra_env=extra_env,
        )

    def _requeue(job_ids: Sequence[str], *, hold: bool = False) -> None:
        if mutation_guard is not None:
            mutation_guard()
        _soperator_upgrade_requeue_jobs(
            namespace,
            job_ids,
            hold=hold,
            kube_context=kube_context,
            extra_env=extra_env,
        )

    def _hold(job_ids: Sequence[str]) -> None:
        selected = tuple(_non_empty_text(job_id) for job_id in job_ids if _non_empty_text(job_id))
        if not selected:
            return
        if mutation_guard is not None:
            mutation_guard()
        _run_soperator_upgrade_login_command(
            namespace,
            "scontrol hold " + " ".join(shlex.quote(job_id) for job_id in selected),
            kube_context=kube_context,
            extra_env=extra_env,
            timeout_seconds=120,
        )

    def _release(job_ids: Sequence[str]) -> None:
        if mutation_guard is not None:
            mutation_guard()
        _soperator_upgrade_release_jobs(
            namespace,
            job_ids,
            kube_context=kube_context,
            extra_env=extra_env,
        )

    def _wait_for_requeued(job_ids: Sequence[str]) -> None:
        _soperator_upgrade_wait_for_requeued_jobs_to_leave_nodes(
            namespace=namespace,
            node_names=selected_node_names,
            job_ids=job_ids,
            timeout_seconds=wait_timeout_seconds,
            refresh_interval_seconds=refresh_interval_seconds,
            kube_context=kube_context,
            extra_env=extra_env,
            include_pending=include_pending,
            all_jobs=all_active_partitions,
        )

    def _wait_for_cancelled(job_ids: Sequence[str]) -> tuple[AffectedSlurmJob, ...]:
        return _soperator_upgrade_wait_for_cancelled_jobs_to_leave_nodes(
            namespace=namespace,
            node_names=selected_node_names,
            job_ids=job_ids,
            timeout_seconds=wait_timeout_seconds,
            refresh_interval_seconds=refresh_interval_seconds,
            kube_context=kube_context,
            extra_env=extra_env,
            include_pending=include_pending,
            all_jobs=all_active_partitions,
        )

    def _wait_for_all() -> None:
        while True:
            try:
                with _soperator_upgrade_job_prompt_paused():
                    _soperator_upgrade_wait_for_jobs(
                        namespace=namespace,
                        node_names=selected_node_names,
                        timeout_seconds=wait_timeout_seconds,
                        refresh_interval_seconds=refresh_interval_seconds,
                        kube_context=kube_context,
                        extra_env=extra_env,
                        include_pending=include_pending,
                        all_jobs=all_active_partitions,
                    )
                return
            except RuntimeError as exc:
                if not continue_until_clear:
                    raise
                _record(
                    "wait-observation-retrying",
                    failure_type=type(exc).__name__,
                    refresh_interval_seconds=refresh_interval_seconds,
                )
                time.sleep(max(refresh_interval_seconds, 1))

    def _wait_until_timeout(timeout_seconds: int) -> tuple[AffectedSlurmJob, ...]:
        with _soperator_upgrade_job_prompt_paused():
            return _soperator_upgrade_wait_for_jobs_until_timeout(
                namespace=namespace,
                node_names=selected_node_names,
                timeout_seconds=timeout_seconds,
                refresh_interval_seconds=refresh_interval_seconds,
                kube_context=kube_context,
                extra_env=extra_env,
                include_pending=include_pending,
                all_jobs=all_active_partitions,
            )

    def _wait_then_cancel() -> None:
        _record(
            "wait-then-cancel-wait-started",
            timeout_seconds=wait_timeout_seconds,
            refresh_interval_seconds=refresh_interval_seconds,
        )
        remaining = _wait_until_timeout(wait_timeout_seconds)
        if not remaining:
            _record("wait-then-cancel-wait-completed")
            return
        remaining = _jobs()
        if not remaining:
            _record("wait-then-cancel-cleared-after-timeout-refresh")
            return
        selected = tuple(job.job_id for job in remaining)
        _record(
            "wait-then-cancel-timeout",
            timeout_seconds=wait_timeout_seconds,
            job_ids=selected,
            jobs=[job.__dict__ for job in remaining],
        )
        console.print(
            "Slurm job wait timeout reached; cancelling still-affected displayed jobs: "
            + ", ".join(selected),
            soft_wrap=True,
        )
        _cancel(selected)
        _record(
            "wait-then-cancel-auto-cancel",
            job_ids=selected,
            clear_timeout_seconds=_SOPERATOR_UPGRADE_CANCEL_CLEAR_TIMEOUT_SECONDS,
        )
        still_remaining = _wait_until_timeout(_SOPERATOR_UPGRADE_CANCEL_CLEAR_TIMEOUT_SECONDS)
        if still_remaining:
            remaining_ids = tuple(job.job_id for job in still_remaining)
            _record(
                "wait-then-cancel-clear-timeout",
                job_ids=remaining_ids,
                jobs=[job.__dict__ for job in still_remaining],
            )
            raise RuntimeError(
                "Affected Slurm jobs remain after automatic cancellation: "
                + ", ".join(remaining_ids)
                + ". Clear them manually before rerunning the upgrade."
            )
        _record("wait-then-cancel-cleared", job_ids=selected)

    def _print_wait_only_jobs(
        rows: Sequence[tuple[AffectedSlurmJob, str]],
    ) -> None:
        if not rows:
            return
        table = Table(title="Slurm jobs that cxcli will wait for without mutation")
        table.add_column("Job ID")
        table.add_column("User")
        table.add_column("State")
        table.add_column("Reason")
        for job, reason in rows:
            table.add_row(job.job_id, job.user or "-", job.state or "-", reason)
        with _soperator_upgrade_job_prompt_paused():
            console.print(table)

    def _guarded_requeue(
        displayed_jobs: Sequence[AffectedSlurmJob],
        job_ids: Sequence[str],
        *,
        action: str,
        hold: bool,
    ) -> tuple[str, ...]:
        selected = selected_display_job_ids(displayed_jobs, job_ids, action=action)
        displayed_by_id = {job.job_id: job for job in displayed_jobs}
        eligible: list[tuple[AffectedSlurmJob, SlurmJobControlRecord]] = []
        wait_only: list[tuple[AffectedSlurmJob, str]] = []
        for job_id in selected:
            job = displayed_by_id[job_id]
            try:
                control = _job_control_record(job_id)
            except RuntimeError as exc:
                wait_only.append((job, "authoritative Slurm job details are unavailable"))
                _record(
                    f"{action}-wait-only",
                    job_ids=[job_id],
                    jobs=[job.__dict__],
                    reason="unproven-job-control-state",
                    failure_type=type(exc).__name__,
                )
                continue
            if control is None:
                _record(
                    f"{action}-tombstone",
                    job_ids=[job_id],
                    jobs=[job.__dict__],
                    reason="job-disappeared-before-mutation",
                )
                continue
            is_eligible, reason = slurm_requeuehold_eligibility(control)
            if not is_eligible:
                wait_only.append((job, reason))
                _record(
                    f"{action}-wait-only",
                    job_ids=[job_id],
                    jobs=[job.__dict__],
                    job_control_preimages=[control.as_payload()],
                    reason=reason,
                )
                continue
            eligible.append((job, control))
        _print_wait_only_jobs(wait_only)

        applied: list[str] = []
        late_wait_only: list[tuple[AffectedSlurmJob, str]] = []
        for job, preimage in eligible:
            latest = _job_control_record(job.job_id)
            if latest is None:
                _record(
                    f"{action}-tombstone",
                    job_ids=[job.job_id],
                    jobs=[job.__dict__],
                    job_control_preimages=[preimage.as_payload()],
                    reason="job-disappeared-during-revalidation",
                )
                continue
            if latest.identity_sha256 != preimage.identity_sha256:
                raise RuntimeError(
                    "recovery-required: Slurm job identity changed immediately before "
                    f"{action} for job {job.job_id}"
                )
            is_eligible, reason = slurm_requeuehold_eligibility(latest)
            if not is_eligible:
                late_wait_only.append((job, reason))
                _record(
                    f"{action}-wait-only",
                    job_ids=[job.job_id],
                    jobs=[job.__dict__],
                    job_control_preimages=[latest.as_payload()],
                    reason=reason,
                    revalidated=True,
                )
                continue
            _record(
                action,
                job_ids=[job.job_id],
                jobs=[job.__dict__],
                job_control_preimages=[latest.as_payload()],
            )
            _requeue((job.job_id,), hold=hold)
            _wait_for_requeued((job.job_id,))
            postimage = _job_control_record(job.job_id)
            if postimage is None:
                if hold:
                    raise RuntimeError(
                        "recovery-required: Slurm did not expose the held-job postimage "
                        f"for job {job.job_id}"
                    )
                _record(
                    f"{action}-applied",
                    job_ids=[job.job_id],
                    jobs=[],
                    satisfied_external_job_ids=[job.job_id],
                )
                applied.append(job.job_id)
                continue
            if postimage.identity_sha256 != latest.identity_sha256:
                raise RuntimeError(
                    "recovery-required: Slurm job identity changed after "
                    f"{action} for job {job.job_id}"
                )
            if hold and not slurm_job_control_is_held(postimage):
                raise RuntimeError(
                    "recovery-required: Slurm did not expose the exact held-job "
                    f"postimage for job {job.job_id}"
                )
            _record(
                f"{action}-applied",
                job_ids=[job.job_id],
                jobs=[job.__dict__],
                job_control_postimages=[postimage.as_payload()],
            )
            applied.append(job.job_id)

        _print_wait_only_jobs(late_wait_only)
        if wait_only or late_wait_only:
            _record(
                f"{action}-waiting-for-ineligible-jobs",
                job_ids=[job.job_id for job, _reason in (*wait_only, *late_wait_only)],
            )
            _wait_for_all()
        return tuple(applied)

    def _drain_after_jobs_clear() -> tuple[str, ...]:
        if not drain_nodes:
            return ()
        if mutation_guard is not None:
            mutation_guard()
        drained_nodes = _soperator_upgrade_drain_slurm_nodes(
            namespace=namespace,
            node_names=selected_node_names,
            checkpoint_id=checkpoint_id,
            kube_context=kube_context,
            extra_env=extra_env,
        )
        try:
            remaining_after_drain = _jobs()
        except Exception:
            if drained_nodes:
                _soperator_upgrade_restore_slurm_nodes(
                    namespace=namespace,
                    node_names=drained_nodes,
                    kube_context=kube_context,
                    extra_env=extra_env,
                )
            raise
        if remaining_after_drain:
            if drained_nodes and not continue_until_clear:
                _soperator_upgrade_restore_slurm_nodes(
                    namespace=namespace,
                    node_names=drained_nodes,
                    kube_context=kube_context,
                    extra_env=extra_env,
                )
            if continue_until_clear:
                _record(
                    "post-drain-jobs-detected",
                    jobs=[job.__dict__ for job in remaining_after_drain],
                )
                _wait_for_all()
            else:
                raise RuntimeError(
                    f"{len(remaining_after_drain)} affected Slurm job(s) started or remained "
                    "after the job policy completed. Rerun after they finish or cancel them "
                    "explicitly."
                )
        return drained_nodes

    def _interactive_action_handler(
        action: str,
        selected_ids: tuple[str, ...],
        displayed_jobs: tuple[AffectedSlurmJob, ...],
    ) -> tuple[AffectedSlurmJob, ...]:
        if action == "refresh":
            return _jobs()
        if action == "wait":
            return displayed_jobs
        if action == "cancel":
            selected = selected_display_job_ids(displayed_jobs, selected_ids, action=action)
            if not selected:
                raise RuntimeError("Select at least one displayed job to cancel.")
            _record(action, job_ids=selected)
            _cancel(selected)
            return _wait_for_cancelled(selected)
        if action in {"requeue", "requeue-hold"}:
            selected = selected_display_job_ids(displayed_jobs, selected_ids, action=action)
            if not selected:
                raise RuntimeError("Select at least one displayed active job to requeue.")
            _guarded_requeue(
                displayed_jobs,
                selected,
                action=action,
                hold=action == "requeue-hold",
            )
            return _jobs()
        if action in {"hold", "release"}:
            selected = selected_display_job_ids(displayed_jobs, selected_ids, action=action)
            if not selected:
                raise RuntimeError(f"Select at least one displayed job to {action}.")
            _record(action, job_ids=selected)
            (_hold if action == "hold" else _release)(selected)
            return _jobs()
        raise RuntimeError(f"Unsupported Slurm job-control action: {action}")

    jobs = _jobs()
    if not jobs:
        _record("no-blocking-jobs", policy=policy, node_names=selected_node_names)
        return _drain_after_jobs_clear()
    if policy == "interactive" and not _is_tty_session():
        raise RuntimeError(
            "--job-policy interactive requires an interactive terminal when blocking jobs "
            "need a decision. Use wait-then-cancel, wait-to-finish, cancel-selected, "
            "cancel-all, requeue-selected, requeue-all, requeue-hold-selected, or "
            "requeue-hold-all."
        )
    _record(
        "blocking-jobs-detected",
        policy=policy,
        node_names=selected_node_names,
        jobs=[job.__dict__ for job in jobs],
    )
    if policy == "interactive":
        while True:
            action, selected_ids = _prompt_soperator_upgrade_job_control(
                jobs,
                jobs_provider=_jobs,
                action_handler=_interactive_action_handler,
                wait_timeout_seconds=wait_timeout_seconds,
                refresh_interval_seconds=refresh_interval_seconds,
            )
            _record("operator-selected", selection=action, job_ids=selected_ids)
            if action == "refresh":
                jobs = _jobs()
                if not jobs:
                    _record("no-blocking-jobs-after-refresh", policy=policy)
                    return _drain_after_jobs_clear()
                continue
            if action == SLURM_JOB_CONTROL_JOBS_CLEARED:
                _record("jobs-cleared-in-tui", policy=policy)
                return _drain_after_jobs_clear()
            if action == SLURM_JOB_CONTROL_WAIT_COMPLETED:
                _record(
                    "wait-started",
                    timeout_seconds=wait_timeout_seconds,
                    refresh_interval_seconds=refresh_interval_seconds,
                )
                _record("wait-completed")
                return _drain_after_jobs_clear()
            if action == SLURM_JOB_CONTROL_WAIT_TIMEOUT:
                _record(
                    "wait-started",
                    timeout_seconds=wait_timeout_seconds,
                    refresh_interval_seconds=refresh_interval_seconds,
                )
                if continue_until_clear:
                    jobs = _jobs()
                    continue
                raise RuntimeError(
                    "Timed out waiting for Slurm jobs to finish. Rerun with a longer "
                    "--job-wait-timeout, cancel, requeue, or requeue-hold selected jobs, "
                    "or use --job-policy wait-then-cancel."
                )
            if action == "wait":
                _record(
                    "wait-started",
                    timeout_seconds=wait_timeout_seconds,
                    refresh_interval_seconds=refresh_interval_seconds,
                )
                _wait_for_all()
                _record("wait-completed")
                return _drain_after_jobs_clear()
            if action in {"cancel", "requeue", "requeue-hold", "hold", "release"}:
                try:
                    jobs = _interactive_action_handler(action, selected_ids, jobs)
                except RuntimeError as exc:
                    console.print(f"[yellow]{exc}[/yellow]")
                    continue
                if not jobs:
                    return _drain_after_jobs_clear()
                continue
            console.print("[yellow]Unknown action; use r, w, c, q, h, H, or u.[/yellow]")
    if policy == "fail":
        with _soperator_upgrade_job_prompt_paused():
            _print_soperator_upgrade_jobs_table(jobs)
        _record("fail", job_count=len(jobs))
        raise RuntimeError(
            "Affected Slurm jobs exist for the upgrade scope. Use --job-policy wait-to-finish, "
            "--job-policy wait-then-cancel, --job-policy cancel-selected with "
            "--cancel-job, --job-policy cancel-all, --job-policy requeue-selected "
            "with --requeue-job, --job-policy requeue-all, --job-policy "
            "requeue-hold-selected with --requeue-job, or --job-policy "
            "requeue-hold-all."
        )
    if policy == "wait-then-cancel":
        _wait_then_cancel()
        return _drain_after_jobs_clear()
    remaining: tuple[AffectedSlurmJob, ...] | None = None
    if policy == "cancel-selected":
        selected = selected_display_job_ids(jobs, cancel_job_ids, action=policy)
        if not selected:
            raise RuntimeError("--job-policy cancel-selected requires at least one --cancel-job.")
        _record("cancel-selected", job_ids=selected)
        _cancel(selected)
        remaining = _wait_for_cancelled(selected)
    elif policy == "cancel-all":
        selected = tuple(job.job_id for job in jobs)
        _record("cancel-all", job_ids=selected)
        _cancel(selected)
        remaining = _wait_for_cancelled(selected)
    elif policy == "requeue-selected":
        selected = selected_display_job_ids(jobs, requeue_job_ids, action=policy)
        if not selected:
            raise RuntimeError("--job-policy requeue-selected requires at least one --requeue-job.")
        _guarded_requeue(jobs, selected, action=policy, hold=False)
    elif policy == "requeue-all":
        selected = tuple(job.job_id for job in jobs)
        _guarded_requeue(jobs, selected, action=policy, hold=False)
    elif policy == "requeue-hold-selected":
        selected = selected_display_job_ids(jobs, requeue_job_ids, action=policy)
        if not selected:
            raise RuntimeError(
                "--job-policy requeue-hold-selected requires at least one --requeue-job."
            )
        _guarded_requeue(jobs, selected, action=policy, hold=True)
    elif policy == "requeue-hold-all":
        selected = tuple(job.job_id for job in jobs)
        _guarded_requeue(jobs, selected, action=policy, hold=True)
    elif policy == "wait-to-finish":
        _record(
            "wait-started",
            timeout_seconds=wait_timeout_seconds,
            refresh_interval_seconds=refresh_interval_seconds,
        )
        _wait_for_all()
        _record("wait-completed")
        return _drain_after_jobs_clear()
    remaining = remaining if remaining is not None else _jobs()
    if remaining:
        _record(
            "policy-completed-with-remaining-jobs",
            policy=policy,
            jobs=[job.__dict__ for job in remaining],
        )
        if continue_until_clear:
            _wait_for_all()
        else:
            raise RuntimeError(
                f"{len(remaining)} affected Slurm job(s) remain after job policy "
                f"{policy!r}. Rerun after they finish or cancel them explicitly."
            )
    _record("policy-cleared-jobs", policy=policy)
    return _drain_after_jobs_clear()


def _validation_report_payload(
    validations: Sequence[Mapping[str, Any]],
    *,
    reports_dir: Path,
) -> dict[str, Any]:
    if not validations:
        return {
            "overall_status": "not_run",
            "total_count": 0,
            "completed_count": 0,
            "passed_count": 0,
            "failed_count": 0,
            "not_run_count": 0,
            "results": [],
        }
    report = build_deploy_validation_report(validations, reports_dir=reports_dir)
    return {
        "overall_status": report.overall_status,
        "total_count": report.total_count,
        "completed_count": report.completed_count,
        "passed_count": report.passed_count,
        "failed_count": report.failed_count,
        "not_run_count": report.not_run_count,
        "results": [
            {
                "kind": item.kind,
                "name": item.name,
                "target_ref": item.target_ref,
                "status": item.status,
                "summary": item.summary,
                "report_file": item.report_path.name,
                "report_exists": item.report_exists,
            }
            for item in report.results
        ],
    }


def _validation_report_markdown_lines(
    validations: Sequence[Mapping[str, Any]],
    *,
    reports_dir: Path,
) -> list[str]:
    if not validations:
        return [
            "## Validations",
            "",
            "- No post-upgrade validations were configured or selected.",
            "",
        ]
    report = build_deploy_validation_report(validations, reports_dir=reports_dir)
    lines = validation_section_lines(report)
    lines.append("")
    return lines


def _write_upgrade_node_template_report(
    paths: ProjectPaths,
    *,
    plan: Mk8sNodeTemplateUpgradePlan,
    readiness: Mk8sUpgradeReadinessResult,
    validations: Sequence[Mapping[str, Any]],
) -> tuple[Path, Path]:
    paths.reports_dir.mkdir(parents=True, exist_ok=True)
    markdown_path = paths.reports_dir / UPGRADE_NODE_TEMPLATE_REPORT_FILENAME
    json_path = paths.reports_dir / UPGRADE_NODE_TEMPLATE_REPORT_JSON_FILENAME
    generated_at = _soperator_upgrade_now_iso()
    node_groups = [
        {
            "id": str(getattr(group, "id", "") or ""),
            "name": str(getattr(group, "name", "") or ""),
            "ready": bool(getattr(group, "ready", False)),
            "summary": str(getattr(group, "summary", "") or ""),
        }
        for group in getattr(readiness, "node_groups", ()) or ()
    ]
    validation_payload = _validation_report_payload(validations, reports_dir=paths.reports_dir)
    payload = {
        "schema": "nebius-cxcli-upgrade-node-template-report/v1",
        "generated_at": generated_at,
        "status": "passed",
        "target": str(getattr(getattr(plan, "target", None), "selector", "") or ""),
        "cluster_id": str(getattr(plan, "cluster_id", "") or ""),
        "cluster_name": str(getattr(plan, "cluster_name", "") or ""),
        "current_version": str(getattr(plan, "current_version", "") or ""),
        "target_version": str(getattr(plan, "target_version", "") or ""),
        "target_os": str(getattr(plan, "target_os", "") or ""),
        "target_gpu_stack_preset": str(getattr(plan, "target_gpu_stack_preset", "") or ""),
        "readiness_summary": readiness.summary() if hasattr(readiness, "summary") else "",
        "node_groups": node_groups,
        "validations": validation_payload,
    }
    _write_text_atomic(json_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    lines = [
        "# MK8s Node Template Upgrade Report",
        "",
        f"- Target: `{payload['target']}`",
        f"- Cluster: `{payload['cluster_name'] or payload['cluster_id']}`",
        f"- Kubernetes version: `{payload['current_version'] or 'unknown'}` -> `{payload['target_version'] or 'unchanged'}`",
        f"- OS image: `{payload['target_os'] or 'unchanged'}`",
        f"- GPU stack preset: `{payload['target_gpu_stack_preset'] or 'unchanged/operator-managed'}`",
        f"- Status: `{status_label(payload['status'])}`",
        f"- Generated at: `{generated_at}`",
        f"- JSON report: `{json_path.name}`",
        "",
        "## Readiness",
        "",
        f"- {payload['readiness_summary'] or 'No readiness summary recorded.'}",
    ]
    for group in node_groups:
        lines.append(
            f"- `{group['name'] or group['id']}`: "
            f"`{status_label('passed' if group['ready'] else 'failed')}` - "
            f"{group['summary'] or 'No summary recorded.'}"
        )
    lines.extend(
        ["", *_validation_report_markdown_lines(validations, reports_dir=paths.reports_dir)]
    )
    _write_text_atomic(markdown_path, "\n".join(lines).rstrip() + "\n")
    return markdown_path, json_path


