def _is_tty_session() -> bool:
    return sys.stdin.isatty() and sys.stdout.isatty()


def _configure_questionary_checkbox_symbols() -> None:
    """Use classic checkbox markers for questionary multi-select prompts."""
    try:
        from questionary.prompts import common as questionary_common

        questionary_common.INDICATOR_SELECTED = "[x]"
        questionary_common.INDICATOR_UNSELECTED = "[ ]"
    except Exception:
        # Keep questionary defaults if internals are unavailable/changed.
        return


def _ask_questionary_with_wizard_navigation(question: Any) -> Any:
    application = getattr(question, "application", None)
    bindings = getattr(application, "key_bindings", None)
    if bindings is not None:
        try:

            @bindings.add(*tuple(WIZARD_ABORT_TOKEN), eager=True)
            def _wizard_quit(event: Any) -> None:
                event.app.exit(result=_WIZARD_QUIT_CHOICE)

            @bindings.add(WIZARD_EXIT_TOKEN, eager=False)
            def _wizard_back(event: Any) -> None:
                event.app.exit(result=_WIZARD_BACK_CHOICE)

        except Exception:
            # Keep the prompt usable if questionary/prompt-toolkit internals change.
            pass
    return question.ask()


def _questionary_choice_title(choice: Any) -> str:
    title = getattr(choice, "title", "")
    if isinstance(title, list):
        return "".join(str(part[1]) for part in title if isinstance(part, tuple) and len(part) > 1)
    return str(title or "")


def _find_questionary_inquirer_control(container: Any) -> Any | None:
    stack = [container]
    seen: set[int] = set()
    while stack:
        current = stack.pop()
        current_id = id(current)
        if current_id in seen:
            continue
        seen.add(current_id)
        if (
            hasattr(current, "choices")
            and hasattr(current, "pointed_at")
            and callable(getattr(current, "is_selection_valid", None))
        ):
            return current
        children = getattr(current, "children", None)
        if children:
            stack.extend(reversed(list(children)))
        for attr in ("content", "container"):
            child = getattr(current, attr, None)
            if child is not None and child is not current:
                stack.append(child)
    return None


def _register_questionary_prefix_jump_keys(question: Any) -> None:
    application = getattr(question, "application", None)
    bindings = getattr(application, "key_bindings", None)
    layout = getattr(application, "layout", None)
    control = _find_questionary_inquirer_control(getattr(layout, "container", None))
    if bindings is None or control is None:
        return

    def _jump_to_prefix(event: Any) -> None:
        key_event = event.key_sequence[0] if getattr(event, "key_sequence", None) else None
        key = str(getattr(key_event, "key", "") or "").casefold()
        if not key:
            return
        choices = list(
            getattr(control, "filtered_choices", None) or getattr(control, "choices", ())
        )
        for index, choice in enumerate(choices):
            if getattr(choice, "disabled", False):
                continue
            if _questionary_choice_title(choice).strip().casefold().startswith(key):
                control.pointed_at = index
                return

    try:
        for key in string.ascii_letters + string.digits:
            bindings.add(key, eager=True)(_jump_to_prefix)
    except Exception:
        # Keep the prompt usable if questionary/prompt-toolkit internals change.
        return


def _ask_questionary_with_prefix_jumps(question: Any) -> Any:
    _register_questionary_prefix_jump_keys(question)
    return question.ask()


def _split_multi_value_tokens(raw_values: list[str] | None) -> list[str]:
    if not raw_values:
        return []
    tokens: list[str] = []
    for raw in raw_values:
        for part in raw.split(","):
            token = part.strip()
            if token:
                tokens.append(token)
    return tokens


def _read_config_payload(config_path: Path) -> dict[str, Any]:
    recover_project_bundle(config_path.absolute().parent)
    if not config_path.exists():
        raise ValueError(f"Config file not found: {config_path}")
    if config_path.is_dir():
        raise ValueError(
            "Expected a project config.yaml file path, but got a directory: "
            f"{config_path}. Pass <tenant-folder>/<project-folder>/config.yaml."
        )
    with config_path.open("r", encoding="utf-8") as handle:
        payload = yaml.safe_load(handle) or {}
    if not isinstance(payload, dict):
        raise RuntimeError("config.yaml root must be a mapping")
    return payload


def _load_config_payload(config_path: Path) -> dict[str, Any]:
    payload = _read_config_payload(config_path)
    client_name, _tenant_id, project_id, _region_id, _email = _identity_values_from_payload(payload)
    _ensure_project_auth_identity(project_id=project_id, client_name=client_name)
    return payload


