def _collect_grafana_status_after_flux(
    config: Any,
    *,
    extra_env: dict[str, str] | None,
    target_ref: str = "",
    timeout_seconds: float = GRAFANA_STATUS_TIMEOUT_SECONDS,
    poll_interval_seconds: float = GRAFANA_STATUS_POLL_INTERVAL_SECONDS,
) -> tuple[dict[str, Any], ...]:
    if not grafana_enabled_for_target(config, target_ref=target_ref):
        return ()
    target_label = target_ref or "current cluster"
    deadline = time.monotonic() + max(0.0, timeout_seconds)
    last_statuses: tuple[dict[str, Any], ...] = ()
    last_error: Exception | None = None
    announced_wait = False
    while True:
        try:
            statuses = collect_grafana_runtime_status(
                config,
                extra_env=extra_env,
                target_ref=target_ref,
            )
            if statuses:
                last_statuses = statuses
                last_error = None
            if statuses and all(str(status.get("base_url") or "").strip() for status in statuses):
                return statuses
        except Exception as exc:
            last_error = exc

        now = time.monotonic()
        remaining = deadline - now
        if remaining <= 0:
            if last_statuses:
                console.print(
                    f"{warning_markup('WARNING:', bold=True)} Grafana URL for {target_label} "
                    "is still pending; deploy-report.md will keep pending links until "
                    "a later deploy or flux apply can read the Gateway/LoadBalancer status."
                )
                return last_statuses
            detail = f": {last_error}" if last_error is not None else ""
            console.print(
                f"{warning_markup('WARNING:', bold=True)} Failed to resolve Grafana URL "
                f"for {target_label}{detail}"
            )
            return ()

        if not announced_wait:
            console.print(f"Waiting for Grafana Gateway/LoadBalancer address for {target_label}...")
            announced_wait = True
        time.sleep(min(max(0.1, poll_interval_seconds), remaining))


@dataclass(frozen=True)
class DeployRunSummary:
    validation_report: DeployValidationReport | None = None
    gitops_bootstrap_commands: tuple[str, ...] = ()


def _deploy_kubectl_json(
    args: Sequence[str],
    *,
    extra_env: Mapping[str, str] | None,
    timeout: int = 60,
) -> Mapping[str, Any] | None:
    completed = subprocess.run(
        ["kubectl", *args],
        env=_post_flux_subprocess_env(extra_env or {}),
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    if completed.returncode != 0:
        return None
    try:
        payload = json.loads(completed.stdout or "{}")
    except json.JSONDecodeError:
        return None
    return payload if isinstance(payload, Mapping) else None


def _deploy_wait_for_kubectl_json(
    args: Sequence[str],
    *,
    extra_env: Mapping[str, str] | None,
    timeout: int = 60,
    attempts: int = 12,
    retry_delay_seconds: float = 5.0,
) -> Mapping[str, Any] | None:
    total_attempts = max(int(attempts), 1)
    for attempt in range(1, total_attempts + 1):
        payload = _deploy_kubectl_json(args, extra_env=extra_env, timeout=timeout)
        if payload is not None:
            return payload
        if attempt < total_attempts:
            time.sleep(max(retry_delay_seconds, 0.0))
    return None


def _deploy_soperator_cluster_available(payload: Mapping[str, Any]) -> bool:
    for item in payload.get("items", []) or []:
        if not isinstance(item, Mapping):
            continue
        status = item.get("status")
        if not isinstance(status, Mapping):
            continue
        phase = str(status.get("phase", "") or "").strip().lower()
        if phase == "available":
            return True
        for condition in status.get("conditions", []) or []:
            if not isinstance(condition, Mapping):
                continue
            condition_type = str(condition.get("type", "") or "").strip().lower()
            condition_status = str(condition.get("status", "") or "").strip().lower()
            if condition_type == "available" and condition_status == "true":
                return True
    return False


def _deploy_nodeset_is_gpu_worker(item: Mapping[str, Any]) -> bool:
    metadata = item.get("metadata")
    name = str(metadata.get("name", "") if isinstance(metadata, Mapping) else "").strip()
    if not normalize_component_token(name).startswith("worker"):
        return False
    spec = item.get("spec")
    if not isinstance(spec, Mapping):
        return False
    gpu = spec.get("gpu")
    if isinstance(gpu, Mapping) and bool(gpu.get("enabled", False)):
        return True
    slurmd = spec.get("slurmd")
    resources = slurmd.get("resources") if isinstance(slurmd, Mapping) else None
    if not isinstance(resources, Mapping):
        return False
    return resources.get("gpu") not in (None, "", 0, "0") or resources.get(
        "nvidia.com/gpu"
    ) not in (
        None,
        "",
        0,
        "0",
    )


def _ensure_soperator_gpu_ephemeral_bootstrap_power_state(
    config: Any,
    *,
    target_ref: str,
    extra_env: Mapping[str, str] | None,
) -> None:
    if not _target_has_scale_from_zero_gpu_worker(config, target_ref=target_ref):
        return
    if not shutil.which("kubectl"):
        return
    for release_ref in _enabled_soperator_release_refs_for_target(config, target_ref=target_ref):
        namespace = release_ref.namespace
        clusters = _deploy_kubectl_json(
            ["-n", namespace, "get", "slurmclusters", "-o", "json"],
            extra_env=extra_env,
        )
        if not clusters or _deploy_soperator_cluster_available(clusters):
            continue
        nodesets = _deploy_kubectl_json(
            ["-n", namespace, "get", "nodesets", "-o", "json"],
            extra_env=extra_env,
        )
        if not nodesets:
            continue
        for item in nodesets.get("items", []) or []:
            if not isinstance(item, Mapping) or not _deploy_nodeset_is_gpu_worker(item):
                continue
            spec = item.get("spec")
            metadata = item.get("metadata")
            if not isinstance(spec, Mapping) or not isinstance(metadata, Mapping):
                continue
            if not bool(spec.get("ephemeralNodes", False)):
                continue
            initial_count = _state_positive_int(spec.get("initialNumberEphemeralNodes")) or 0
            if initial_count <= 0:
                continue
            name = str(metadata.get("name", "") or "").strip()
            if not name:
                continue
            power_state = _deploy_wait_for_kubectl_json(
                ["-n", namespace, "get", "nodesetpowerstate", name, "-o", "json"],
                extra_env=extra_env,
            )
            if power_state is None:
                continue
            power_spec = power_state.get("spec") if isinstance(power_state, Mapping) else None
            active_nodes = (
                power_spec.get("activeNodes") if isinstance(power_spec, Mapping) else None
            )
            if isinstance(active_nodes, list) and active_nodes:
                continue
            desired_nodes = list(range(initial_count))
            patch_payload = json.dumps({"spec": {"activeNodes": desired_nodes}})
            _run_post_flux_kubectl(
                [
                    "kubectl",
                    "-n",
                    namespace,
                    "patch",
                    "nodesetpowerstate",
                    name,
                    "--type=merge",
                    "-p",
                    patch_payload,
                ],
                env=extra_env or {},
                timeout=60,
            )
            console.print(
                "Soperator bootstrap: activated initial GPU worker ordinal(s) "
                f"{desired_nodes} for NodeSet {name}."
            )


