def _soperator_deploy_job_gate_checkpoint_id(
    *,
    command_name: str,
    target_ref: str,
    namespace: str,
) -> str:
    raw = f"{command_name}:{target_ref}:{namespace}:{time.time_ns()}"
    return _soperator_upgrade_sha256_text(raw)[:16]


def _soperator_upgrade_maintenance_reservation_name(checkpoint_id: str) -> str:
    normalized = _non_empty_text(checkpoint_id).lower()
    if not re.fullmatch(r"[0-9a-f]{16}", normalized):
        raise RuntimeError("Soperator maintenance reservation checkpoint identity is invalid")
    return f"cxcli_{normalized}"


def _soperator_upgrade_reservation_names(
    *,
    namespace: str,
    extra_env: Mapping[str, str] | None,
) -> tuple[str, ...]:
    result = _run_soperator_upgrade_login_command(
        namespace,
        "scontrol show reservation -o",
        extra_env=extra_env,
        timeout_seconds=120,
        check=False,
    )
    output = str(result.stdout or "")
    if result.returncode != 0 and "No reservations in the system" not in output:
        detail = str(result.stderr or output or f"exit {result.returncode}").strip()
        raise RuntimeError(
            "Could not inspect Slurm maintenance reservations before Soperator upgrade: " + detail
        )
    names = {
        match.group(1)
        for line in output.splitlines()
        for match in [re.search(r"\bReservationName=([^\s]+)", line)]
        if match is not None
    }
    if any(not re.fullmatch(r"[A-Za-z0-9_.-]+", name) for name in names):
        raise RuntimeError("Slurm returned an unsupported reservation name")
    return tuple(sorted(names))


def _soperator_upgrade_reservation_preimages(
    *,
    namespace: str,
    extra_env: Mapping[str, str] | None,
) -> tuple:
    result = _run_soperator_upgrade_login_command(
        namespace,
        "scontrol show reservation -o",
        extra_env=extra_env,
        timeout_seconds=120,
        check=False,
    )
    output = str(result.stdout or "")
    if result.returncode != 0:
        if "No reservations in the system" in output:
            return ()
        detail = str(result.stderr or output or f"exit {result.returncode}").strip()
        raise RuntimeError(
            "Could not capture exact Slurm reservation preimages before Soperator upgrade: "
            + detail
        )
    return parse_slurm_reservation_preimages(output)


def _soperator_upgrade_create_maintenance_reservation(
    *,
    namespace: str,
    reservation_name: str,
    extra_env: Mapping[str, str] | None,
    node_names: Sequence[str] | None = None,
) -> None:
    if not re.fullmatch(r"cxcli_[0-9a-f]{16}", reservation_name):
        raise RuntimeError("Soperator maintenance reservation identity is invalid")
    selected_nodes = tuple(
        _non_empty_text(value) for value in (node_names or ()) if _non_empty_text(value)
    )
    if any(not re.fullmatch(r"[A-Za-z0-9_.-]+", value) for value in selected_nodes):
        raise RuntimeError("Soperator maintenance reservation node identity is invalid")
    node_expression = ",".join(selected_nodes) if selected_nodes else "ALL"
    _run_soperator_upgrade_login_command(
        namespace,
        "scontrol create "
        f"ReservationName={reservation_name} StartTime=now Duration=UNLIMITED "
        f"Nodes={node_expression} Users=root Flags=MAINT,IGNORE_JOBS",
        extra_env=extra_env,
        timeout_seconds=120,
    )


def _soperator_upgrade_delete_maintenance_reservation(
    *,
    namespace: str,
    reservation_name: str,
    extra_env: Mapping[str, str] | None,
) -> None:
    if not re.fullmatch(r"cxcli_[0-9a-f]{16}", reservation_name):
        raise RuntimeError("Soperator maintenance reservation identity is invalid")
    live_names = _soperator_upgrade_reservation_names(
        namespace=namespace,
        extra_env=extra_env,
    )
    if reservation_name not in live_names:
        return
    _run_soperator_upgrade_login_command(
        namespace,
        f"scontrol delete ReservationName={reservation_name}",
        extra_env=extra_env,
        timeout_seconds=120,
    )
    if reservation_name in _soperator_upgrade_reservation_names(
        namespace=namespace,
        extra_env=extra_env,
    ):
        raise RuntimeError(
            f"Slurm maintenance reservation {reservation_name} remains after deletion"
        )


def _soperator_flux_apply_slurm_job_gate(
    config: Any,
    *,
    command_name: str,
    target_ref: str,
    extra_env: Mapping[str, str] | None,
    job_policy: str,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    job_wait_timeout_seconds: int,
    job_refresh_interval_seconds: int,
    decision_recorder: Callable[[Mapping[str, Any]], None] | None = None,
    mutation_guard: Callable[[], object] | None = None,
) -> tuple[tuple[str, tuple[str, ...]], ...]:
    drained_by_namespace: list[tuple[str, tuple[str, ...]]] = []
    upgrade_mode = command_name == "soperator upgrade"
    if upgrade_mode:
        namespaces = _soperator_upgrade_live_slurmcluster_namespaces(extra_env=extra_env)
    else:
        release_refs = _soperator_release_refs_for_job_policy(config, target_ref=target_ref)
        namespaces = tuple(release_ref.namespace for release_ref in release_refs)
        if not namespaces:
            return ()
    for namespace in namespaces:
        if not _soperator_upgrade_live_slurmcluster_exists(
            namespace=namespace,
            extra_env=extra_env,
        ):
            if upgrade_mode:
                raise RuntimeError(
                    "Soperator upgrade lost the admitted live SlurmCluster before maintenance"
                )
            console.print(
                f"Soperator Slurm job policy skipped for {namespace}: no live SlurmCluster exists."
            )
            continue
        worker_pods = _soperator_upgrade_worker_nodeset_pod_candidates(
            namespace=namespace,
            extra_env=extra_env,
        )
        if not worker_pods and not upgrade_mode:
            console.print(
                f"Soperator Slurm job policy skipped for {namespace}: no live worker NodeSet pods exist."
            )
            continue
        if not _soperator_upgrade_login_path_available(
            namespace=namespace,
            extra_env=extra_env,
        ):
            raise RuntimeError(
                f"Cannot apply {command_name} safely for Soperator namespace {namespace}: "
                "live worker NodeSet pods exist, but no Slurm login/controller exec path is available "
                "to inspect affected jobs."
            )
        worker_slurm_nodes = _soperator_upgrade_slurm_node_filter(
            namespace=namespace,
            node_names=worker_pods,
            extra_env=extra_env,
        )
        checkpoint_id = _soperator_deploy_job_gate_checkpoint_id(
            command_name=command_name,
            target_ref=target_ref,
            namespace=namespace,
        )

        def _record_decision(
            event: Mapping[str, Any],
            *,
            _namespace: str = namespace,
            _checkpoint_id: str = checkpoint_id,
        ) -> None:
            if decision_recorder is None:
                return
            decision_recorder(
                {
                    "namespace": _namespace,
                    "checkpoint_id": _checkpoint_id,
                    **dict(event),
                }
            )

        _record_decision(
            {
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": "slurm-gate-started",
                "node_names": list(worker_slurm_nodes),
            }
        )
        reservation_name = _soperator_upgrade_maintenance_reservation_name(checkpoint_id)
        existing_reservations = _soperator_upgrade_reservation_names(
            namespace=namespace,
            extra_env=extra_env,
        )
        if reservation_name in existing_reservations:
            raise RuntimeError(
                f"Slurm maintenance reservation {reservation_name} already exists before "
                "the Soperator upgrade operation"
            )
        _record_decision(
            {
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": "maintenance-reservation-recorded",
                "reservation_name": reservation_name,
                "preexisting_reservations": list(existing_reservations),
            }
        )

        _handle_soperator_upgrade_running_jobs(
            namespace=namespace,
            node_names=worker_slurm_nodes,
            policy=job_policy,
            cancel_job_ids=cancel_job_ids,
            requeue_job_ids=requeue_job_ids,
            wait_timeout_seconds=job_wait_timeout_seconds,
            refresh_interval_seconds=job_refresh_interval_seconds,
            checkpoint_id=checkpoint_id,
            extra_env=extra_env,
            drain_nodes=False,
            slurm_scheduling_pause=decision_recorder is not None,
            decision_recorder=_record_decision if decision_recorder is not None else None,
            mutation_guard=mutation_guard,
            all_active_partitions=upgrade_mode,
            continue_until_clear=upgrade_mode,
        )
        if mutation_guard is not None:
            mutation_guard()
        _soperator_upgrade_create_maintenance_reservation(
            namespace=namespace,
            reservation_name=reservation_name,
            extra_env=extra_env,
        )
        if reservation_name not in _soperator_upgrade_reservation_names(
            namespace=namespace,
            extra_env=extra_env,
        ):
            raise RuntimeError(
                f"Slurm did not expose maintenance reservation {reservation_name} after creation"
            )
        _record_decision(
            {
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": "maintenance-reservation-applied",
                "reservation_name": reservation_name,
            }
        )
        if decision_recorder is not None:
            pending_jobs = tuple(
                job
                for job in _soperator_upgrade_affected_jobs(
                    namespace=namespace,
                    node_names=worker_slurm_nodes,
                    extra_env=extra_env,
                    include_pending=True,
                    all_jobs=command_name == "soperator upgrade",
                )
                if slurm_job_is_pending(job) and not slurm_job_is_held(job)
            )
            if pending_jobs:
                pending_job_ids = tuple(job.job_id for job in pending_jobs)
                _record_decision(
                    {
                        "at": datetime.now(UTC)
                        .isoformat(timespec="seconds")
                        .replace("+00:00", "Z"),
                        "action": "pending-hold-recorded",
                        "job_ids": list(pending_job_ids),
                        "jobs": [job.__dict__ for job in pending_jobs],
                    }
                )
                if mutation_guard is not None:
                    mutation_guard()
                _soperator_upgrade_hold_jobs(
                    namespace,
                    pending_job_ids,
                    extra_env=extra_env,
                )
                held_jobs = _soperator_upgrade_require_held_job_postimage(
                    namespace=namespace,
                    job_ids=pending_job_ids,
                    extra_env=extra_env,
                )
                _record_decision(
                    {
                        "at": datetime.now(UTC)
                        .isoformat(timespec="seconds")
                        .replace("+00:00", "Z"),
                        "action": "pending-hold-applied",
                        "job_ids": list(pending_job_ids),
                        "jobs": [job.__dict__ for job in held_jobs],
                    }
                )
            else:
                _record_decision(
                    {
                        "at": datetime.now(UTC)
                        .isoformat(timespec="seconds")
                        .replace("+00:00", "Z"),
                        "action": "pending-hold-not-required",
                        "job_ids": [],
                    }
                )
        if upgrade_mode and decision_recorder is not None:

            def _record_late_partition(
                record: SlurmPartitionPauseRecord,
                *,
                _worker_slurm_nodes: tuple[str, ...] = worker_slurm_nodes,
            ) -> None:
                _record_decision(
                    {
                        "at": datetime.now(UTC)
                        .isoformat(timespec="seconds")
                        .replace("+00:00", "Z"),
                        "action": "scheduling-pause-recorded",
                        "node_names": list(_worker_slurm_nodes),
                        "partitions": [record.as_payload()],
                        "scope": "all-active-final-check",
                        "pending_jobs": "queued-not-blocking",
                    }
                )

            late_partitions = _soperator_upgrade_pause_slurm_partitions(
                namespace=namespace,
                node_names=worker_slurm_nodes,
                extra_env=extra_env,
                record_recorder=_record_late_partition,
                all_active_partitions=True,
                restore_on_failure=False,
                mutation_guard=mutation_guard,
            )
            if late_partitions:
                _record_decision(
                    {
                        "at": datetime.now(UTC)
                        .isoformat(timespec="seconds")
                        .replace("+00:00", "Z"),
                        "action": "scheduling-pause-applied",
                        "node_names": list(worker_slurm_nodes),
                        "partitions": [record.as_payload() for record in late_partitions],
                        "scope": "all-active-final-check",
                        "pending_jobs": "queued-not-blocking",
                    }
                )
        if mutation_guard is not None:
            mutation_guard()
        node_preimage = _soperator_upgrade_node_recovery_snapshot(
            namespace=namespace,
            node_names=worker_slurm_nodes,
            extra_env=extra_env,
        )
        _record_decision(
            {
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": "nodes-drain-recorded",
                "node_names": list(worker_slurm_nodes),
                "node_preimage": node_preimage,
            }
        )
        drained_nodes = _soperator_upgrade_drain_slurm_nodes(
            namespace=namespace,
            node_names=worker_slurm_nodes,
            checkpoint_id=checkpoint_id,
            extra_env=extra_env,
        )
        if drained_nodes:
            drained_by_namespace.append((namespace, tuple(drained_nodes)))
            _record_decision(
                {
                    "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "action": "nodes-drained",
                    "node_names": list(worker_slurm_nodes),
                    "owned_node_names": list(drained_nodes),
                    "node_postimage": _soperator_upgrade_node_recovery_snapshot(
                        namespace=namespace,
                        node_names=worker_slurm_nodes,
                        extra_env=extra_env,
                    ),
                }
            )
        else:
            _record_decision(
                {
                    "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "action": "nodes-drain-not-required",
                    "node_names": list(worker_slurm_nodes),
                    "owned_node_names": [],
                    "node_postimage": node_preimage,
                }
            )
        _record_decision(
            {
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": "slurm-gate-complete",
                "node_names": list(worker_slurm_nodes),
            }
        )
    return tuple(drained_by_namespace)


def _soperator_flux_apply_owned_scheduling_state(
    actions: Sequence[Mapping[str, Any]],
) -> tuple[
    dict[str, set[str]],
    dict[str, tuple[SlurmPartitionPauseRecord, ...]],
    dict[str, set[str]],
    dict[str, set[str]],
    dict[str, set[str]],
]:
    drained_by_namespace: dict[str, set[str]] = {}
    requeue_intent_by_namespace: dict[str, set[str]] = {}
    requeued_by_namespace: dict[str, set[str]] = {}
    pending_intent_by_namespace: dict[str, set[str]] = {}
    pending_held_by_namespace: dict[str, set[str]] = {}
    partition_intent_by_namespace: dict[str, tuple[SlurmPartitionPauseRecord, ...]] = {}
    partitions_by_namespace: dict[str, tuple[SlurmPartitionPauseRecord, ...]] = {}
    reservation_intent_by_namespace: dict[str, set[str]] = {}
    reservations_by_namespace: dict[str, set[str]] = {}
    gate_started: set[tuple[str, str]] = set()
    gate_completed: set[tuple[str, str]] = set()
    for event in actions:
        namespace = _non_empty_text(event.get("namespace"))
        action = _non_empty_text(event.get("action"))
        if not namespace or not action:
            continue
        checkpoint_id = _non_empty_text(event.get("checkpoint_id"))
        if action in {"slurm-gate-started", "slurm-gate-complete"}:
            if not re.fullmatch(r"[0-9a-f]{16}", checkpoint_id):
                raise RuntimeError(
                    "recovery-required: Soperator Slurm gate checkpoint identity is invalid"
                )
            marker = (namespace, checkpoint_id)
            if action == "slurm-gate-started":
                gate_started.add(marker)
            else:
                gate_completed.add(marker)
        if action == "nodes-drained":
            owned_nodes = event.get("owned_node_names", event.get("node_names", []))
            drained_by_namespace.setdefault(namespace, set()).update(
                _non_empty_text(node) for node in owned_nodes or [] if _non_empty_text(node)
            )
        if action == "nodes-drain-not-required" and event.get("owned_node_names") not in (
            [],
            (),
        ):
            raise RuntimeError(
                "recovery-required: no-op Slurm node drain evidence claims owned nodes"
            )
        if action in {"requeue-hold", "requeue-hold-selected", "requeue-hold-all"}:
            requeue_intent_by_namespace.setdefault(namespace, set()).update(
                _non_empty_text(job_id)
                for job_id in event.get("job_ids", []) or []
                if _non_empty_text(job_id)
            )
        if action in {
            "requeue-hold-applied",
            "requeue-hold-selected-applied",
            "requeue-hold-all-applied",
        }:
            requeued_by_namespace.setdefault(namespace, set()).update(
                _non_empty_text(job_id)
                for job_id in event.get("job_ids", []) or []
                if _non_empty_text(job_id)
            )
        if action == "pending-hold-recorded":
            pending_intent_by_namespace.setdefault(namespace, set()).update(
                _non_empty_text(job_id)
                for job_id in event.get("job_ids", []) or []
                if _non_empty_text(job_id)
            )
        if action == "pending-hold-applied":
            pending_held_by_namespace.setdefault(namespace, set()).update(
                _non_empty_text(job_id)
                for job_id in event.get("job_ids", []) or []
                if _non_empty_text(job_id)
            )
        if action == "scheduling-pause-recorded":
            incoming = _soperator_upgrade_pause_records_from_payload(event.get("partitions"))
            partition_intent_by_namespace[namespace] = _merge_soperator_upgrade_pause_records(
                partition_intent_by_namespace.get(namespace, ()),
                incoming,
            )
        if action == "scheduling-pause-applied":
            incoming = _soperator_upgrade_pause_records_from_payload(event.get("partitions"))
            partitions_by_namespace[namespace] = _merge_soperator_upgrade_pause_records(
                partitions_by_namespace.get(namespace, ()),
                incoming,
            )
        if action == "maintenance-reservation-recorded":
            reservation_name = _non_empty_text(event.get("reservation_name"))
            preexisting = {
                _non_empty_text(name)
                for name in event.get("preexisting_reservations", []) or []
                if _non_empty_text(name)
            }
            if not re.fullmatch(r"cxcli_[0-9a-f]{16}", reservation_name):
                raise RuntimeError(
                    "recovery-required: a Soperator maintenance reservation intent "
                    f"is invalid in namespace {namespace}"
                )
            if reservation_name in preexisting:
                raise RuntimeError(
                    "recovery-required: cxcli cannot own a pre-existing Slurm "
                    f"reservation in namespace {namespace}"
                )
            reservation_intent_by_namespace.setdefault(namespace, set()).add(reservation_name)
        if action == "maintenance-reservation-applied":
            reservation_name = _non_empty_text(event.get("reservation_name"))
            if not re.fullmatch(r"cxcli_[0-9a-f]{16}", reservation_name):
                raise RuntimeError(
                    "recovery-required: Soperator maintenance reservation applied "
                    f"evidence is invalid in namespace {namespace}"
                )
            reservations_by_namespace.setdefault(namespace, set()).add(reservation_name)

    for namespace, intended in requeue_intent_by_namespace.items():
        applied = requeued_by_namespace.get(namespace, set())
        if intended != applied:
            raise RuntimeError(
                "recovery-required: a requeue-hold mutation lacks exact applied evidence "
                f"in Soperator namespace {namespace}"
            )
    for namespace, applied in requeued_by_namespace.items():
        if not applied.issubset(requeue_intent_by_namespace.get(namespace, set())):
            raise RuntimeError(
                "recovery-required: requeue-hold applied evidence has no exact preimage "
                f"in Soperator namespace {namespace}"
            )
    for namespace, intended in pending_intent_by_namespace.items():
        applied = pending_held_by_namespace.get(namespace, set())
        if intended != applied:
            raise RuntimeError(
                "recovery-required: a pending-job hold lacks exact applied evidence "
                f"in Soperator namespace {namespace}"
            )
    for namespace, applied in pending_held_by_namespace.items():
        if not applied.issubset(pending_intent_by_namespace.get(namespace, set())):
            raise RuntimeError(
                "recovery-required: pending-job applied evidence has no exact preimage "
                f"in Soperator namespace {namespace}"
            )
    for namespace, intended in partition_intent_by_namespace.items():
        applied = partitions_by_namespace.get(namespace, ())
        if {item.partition for item in intended} != {item.partition for item in applied}:
            raise RuntimeError(
                "recovery-required: a Slurm partition pause lacks exact applied evidence "
                f"in Soperator namespace {namespace}"
            )
    for namespace, applied in partitions_by_namespace.items():
        intended = partition_intent_by_namespace.get(namespace, ())
        if {item.partition for item in applied} != {item.partition for item in intended}:
            raise RuntimeError(
                "recovery-required: Slurm partition applied evidence has no exact preimage "
                f"in Soperator namespace {namespace}"
            )
    for namespace, intended in reservation_intent_by_namespace.items():
        applied = reservations_by_namespace.get(namespace, set())
        if intended != applied:
            raise RuntimeError(
                "recovery-required: a Slurm maintenance reservation lacks exact "
                f"applied evidence in Soperator namespace {namespace}"
            )
    for namespace, applied in reservations_by_namespace.items():
        if applied != reservation_intent_by_namespace.get(namespace, set()):
            raise RuntimeError(
                "recovery-required: Slurm maintenance reservation applied evidence "
                f"has no exact preimage in Soperator namespace {namespace}"
            )
    if gate_started != gate_completed:
        raise RuntimeError(
            "recovery-required: an interrupted Soperator Slurm gate lacks its exact "
            "completion checkpoint"
        )
    overlap = {
        namespace: requeued_by_namespace.get(namespace, set())
        & pending_held_by_namespace.get(namespace, set())
        for namespace in set(requeued_by_namespace) | set(pending_held_by_namespace)
    }
    conflicting = {namespace: jobs for namespace, jobs in overlap.items() if jobs}
    if conflicting:
        raise RuntimeError(
            "recovery-required: a Slurm job is owned by both release groups: "
            + ", ".join(
                f"{namespace}={','.join(sorted(jobs))}"
                for namespace, jobs in sorted(conflicting.items())
            )
        )
    return (
        drained_by_namespace,
        partitions_by_namespace,
        requeued_by_namespace,
        pending_held_by_namespace,
        reservations_by_namespace,
    )


def _restore_soperator_flux_apply_infrastructure(
    actions: Sequence[Mapping[str, Any]],
    *,
    extra_env: Mapping[str, str] | None,
    assert_authority: Callable[[], object],
) -> dict[str, object]:
    drained_by_namespace, partitions_by_namespace, requeued, pending_held, reservations = (
        _soperator_flux_apply_owned_scheduling_state(actions)
    )
    node_intents = {
        _non_empty_text(event.get("actionId")): event
        for event in actions
        if _non_empty_text(event.get("action")) == "nodes-drain-recorded"
    }
    for event in actions:
        if _non_empty_text(event.get("action")) != "nodes-drained":
            continue
        namespace = _non_empty_text(event.get("namespace"))
        action_id = _non_empty_text(event.get("actionId"))
        intent = node_intents.get(action_id)
        owned_nodes = tuple(
            _non_empty_text(node)
            for node in event.get("owned_node_names", []) or []
            if _non_empty_text(node)
        )
        preimage = intent.get("node_preimage") if isinstance(intent, Mapping) else None
        if not namespace or not isinstance(preimage, Mapping):
            raise RuntimeError(
                "recovery-required: Slurm node restore lacks exact write-ahead evidence"
            )
        current = _soperator_upgrade_node_recovery_snapshot(
            namespace=namespace,
            node_names=owned_nodes,
            extra_env=extra_env,
        )
        operation_reason = "cxcli-soperator-upgrade:" + _non_empty_text(event.get("checkpoint_id"))
        restore_nodes: list[str] = []
        for node in owned_nodes:
            before = preimage.get(node)
            before_map = before if isinstance(before, Mapping) else {}
            observed = current[node]
            if "DRAIN" not in observed["state"]:
                continue
            if observed["reason"] != operation_reason or "DRAIN" in _non_empty_text(
                before_map.get("state")
            ):
                raise RuntimeError(
                    "recovery-required: Slurm node state changed outside cxcli ownership"
                )
            restore_nodes.append(node)
        if restore_nodes:
            assert_authority()
            _soperator_upgrade_restore_slurm_nodes(
                namespace=namespace,
                node_names=restore_nodes,
                extra_env=extra_env,
            )
            after = _soperator_upgrade_node_recovery_snapshot(
                namespace=namespace,
                node_names=restore_nodes,
                extra_env=extra_env,
            )
            if any("DRAIN" in after[node]["state"] for node in restore_nodes):
                raise RuntimeError("Soperator operation-owned Slurm node remains drained")
    for namespace, records in sorted(partitions_by_namespace.items()):
        assert_authority()
        _soperator_upgrade_restore_slurm_partitions(
            namespace=namespace,
            records=records,
            extra_env=extra_env,
            allow_topology_migration=True,
        )
    return {
        "namespaces": sorted(
            set(drained_by_namespace)
            | set(partitions_by_namespace)
            | set(requeued)
            | set(pending_held)
            | set(reservations)
        ),
        "restoredNodeCount": sum(len(nodes) for nodes in drained_by_namespace.values()),
        "restoredPartitionCount": sum(len(records) for records in partitions_by_namespace.values()),
        "activeMaintenanceReservationCount": sum(len(names) for names in reservations.values()),
    }


def _release_soperator_flux_apply_jobs(
    actions: Sequence[Mapping[str, Any]],
    *,
    group: str,
    extra_env: Mapping[str, str] | None,
    assert_authority: Callable[[], object],
) -> dict[str, object]:
    (
        _drained,
        _partitions,
        requeued_by_namespace,
        pending_held_by_namespace,
        reservations_by_namespace,
    ) = _soperator_flux_apply_owned_scheduling_state(actions)
    if group == "requeued-running":
        selected_by_namespace = requeued_by_namespace
    elif group == "other-held":
        selected_by_namespace = pending_held_by_namespace
    else:
        raise ValueError(f"unsupported Soperator Slurm release group: {group}")
    applied_actions = (
        {
            "requeue-hold-applied",
            "requeue-hold-selected-applied",
            "requeue-hold-all-applied",
        }
        if group == "requeued-running"
        else {"pending-hold-applied"}
    )
    postimages: dict[tuple[str, str], Mapping[str, Any]] = {}
    for event in actions:
        if _non_empty_text(event.get("action")) not in applied_actions:
            continue
        namespace = _non_empty_text(event.get("namespace"))
        jobs = event.get("jobs")
        if not isinstance(jobs, list):
            raise RuntimeError(
                "recovery-required: Slurm held-job journal lacks exact postimage evidence"
            )
        for item in jobs:
            if not isinstance(item, Mapping):
                raise RuntimeError("recovery-required: Slurm held-job postimage is invalid")
            job_id = _non_empty_text(item.get("job_id"))
            if not job_id or (namespace, job_id) in postimages:
                raise RuntimeError(
                    "recovery-required: Slurm held-job postimage identity is ambiguous"
                )
            postimages[(namespace, job_id)] = item
    removed_reservations = 0
    if group == "requeued-running":
        for namespace, reservation_names in sorted(reservations_by_namespace.items()):
            for reservation_name in sorted(reservation_names):
                assert_authority()
                _soperator_upgrade_delete_maintenance_reservation(
                    namespace=namespace,
                    reservation_name=reservation_name,
                    extra_env=extra_env,
                )
                removed_reservations += 1
    for namespace, job_ids in sorted(selected_by_namespace.items()):
        current = {
            job.job_id: job
            for job in _soperator_upgrade_jobs_by_id(
                namespace=namespace,
                job_ids=sorted(job_ids),
                extra_env=extra_env,
            )
        }
        release_ids: list[str] = []
        for job_id in sorted(job_ids):
            job = current.get(job_id)
            if job is None or not slurm_job_is_held(job):
                continue
            postimage = postimages.get((namespace, job_id))
            if not isinstance(postimage, Mapping) or any(
                _non_empty_text(postimage.get(field)) != _non_empty_text(getattr(job, field))
                for field in ("user", "state", "partition", "allocated_nodes", "reason", "name")
            ):
                raise RuntimeError(
                    "recovery-required: Slurm held job changed outside cxcli ownership"
                )
            release_ids.append(job_id)
        if release_ids:
            assert_authority()
            _soperator_upgrade_release_jobs(
                namespace,
                release_ids,
                extra_env=extra_env,
            )
    return {
        "group": group,
        "namespaces": sorted(selected_by_namespace),
        "releasedJobCount": sum(len(job_ids) for job_ids in selected_by_namespace.values()),
        "removedMaintenanceReservationCount": removed_reservations,
    }


def _verify_soperator_flux_apply_infrastructure_restored(
    actions: Sequence[Mapping[str, Any]],
    *,
    extra_env: Mapping[str, str] | None,
) -> dict[str, object]:
    drained, partitions, _requeued, _pending, reservations = (
        _soperator_flux_apply_owned_scheduling_state(actions)
    )
    for namespace, nodes in drained.items():
        snapshot = _soperator_upgrade_node_recovery_snapshot(
            namespace=namespace,
            node_names=sorted(nodes),
            extra_env=extra_env,
        )
        if any("DRAIN" in snapshot[node]["state"] for node in nodes):
            raise RuntimeError("Soperator operation-owned Slurm node remains drained")
    for namespace, records in partitions.items():
        for record in records:
            live = _soperator_upgrade_partition_state(
                namespace=namespace,
                partition=record.partition,
                extra_env=extra_env,
            )
            if not _soperator_upgrade_partition_migration_observation_matches(
                live,
                record=record.previous_record,
                fingerprint=record.previous_record_fingerprint,
            ):
                raise RuntimeError("Soperator operation-owned Slurm partition remains paused")
    for namespace, reservation_names in reservations.items():
        live_names = set(
            _soperator_upgrade_reservation_names(namespace=namespace, extra_env=extra_env)
        )
        if not reservation_names.issubset(live_names):
            raise RuntimeError("Soperator maintenance reservation disappeared before job release")
    return {"status": "restored", "namespaceCount": len(set(drained) | set(partitions))}


def _verify_soperator_flux_apply_jobs_released(
    actions: Sequence[Mapping[str, Any]],
    *,
    group: str,
    extra_env: Mapping[str, str] | None,
) -> dict[str, object]:
    _drained, _partitions, requeued, pending, reservations = (
        _soperator_flux_apply_owned_scheduling_state(actions)
    )
    selected = requeued if group == "requeued-running" else pending
    for namespace, job_ids in selected.items():
        live = _soperator_upgrade_jobs_by_id(
            namespace=namespace,
            job_ids=sorted(job_ids),
            extra_env=extra_env,
        )
        if any(slurm_job_is_held(job) for job in live):
            raise RuntimeError(f"Soperator {group} Slurm jobs remain held")
    if group == "requeued-running":
        for namespace, reservation_names in reservations.items():
            live_names = set(
                _soperator_upgrade_reservation_names(namespace=namespace, extra_env=extra_env)
            )
            if reservation_names & live_names:
                raise RuntimeError("Soperator maintenance reservation remains after job release")
    return {
        "status": "released",
        "group": group,
        "jobCount": sum(len(job_ids) for job_ids in selected.values()),
    }


def _resume_soperator_flux_apply_maintenance_reservations(
    actions: Sequence[Mapping[str, Any]],
    *,
    extra_env: Mapping[str, str] | None,
    decision_recorder: Callable[[Mapping[str, Any]], None],
    assert_authority: Callable[[], object],
) -> None:
    applied = {
        (_non_empty_text(event.get("namespace")), _non_empty_text(event.get("reservation_name")))
        for event in actions
        if _non_empty_text(event.get("action")) == "maintenance-reservation-applied"
    }
    for event in actions:
        if _non_empty_text(event.get("action")) != "maintenance-reservation-recorded":
            continue
        namespace = _non_empty_text(event.get("namespace"))
        checkpoint_id = _non_empty_text(event.get("checkpoint_id"))
        reservation_name = _non_empty_text(event.get("reservation_name"))
        if (
            not namespace
            or not re.fullmatch(r"[0-9a-f]{16}", checkpoint_id)
            or reservation_name != _soperator_upgrade_maintenance_reservation_name(checkpoint_id)
        ):
            raise RuntimeError(
                "recovery-required: unfinished Soperator maintenance reservation "
                "identity is invalid"
            )
        live_names = _soperator_upgrade_reservation_names(
            namespace=namespace,
            extra_env=extra_env,
        )
        if (namespace, reservation_name) in applied:
            if reservation_name not in live_names:
                assert_authority()
                _soperator_upgrade_create_maintenance_reservation(
                    namespace=namespace,
                    reservation_name=reservation_name,
                    extra_env=extra_env,
                )
                live_names = _soperator_upgrade_reservation_names(
                    namespace=namespace,
                    extra_env=extra_env,
                )
                if reservation_name not in live_names:
                    raise RuntimeError(
                        "recovery-required: cxcli could not recover its operation-owned "
                        f"Slurm maintenance reservation {reservation_name}"
                    )
                decision_recorder(
                    {
                        "namespace": namespace,
                        "checkpoint_id": checkpoint_id,
                        "at": datetime.now(UTC)
                        .isoformat(timespec="seconds")
                        .replace("+00:00", "Z"),
                        "action": "maintenance-reservation-applied",
                        "reservation_name": reservation_name,
                        "recoveryDisposition": (SlurmRecoveryDisposition.RECOVERED_APPLIED.value),
                    }
                )
            continue
        if reservation_name not in live_names:
            assert_authority()
            _soperator_upgrade_create_maintenance_reservation(
                namespace=namespace,
                reservation_name=reservation_name,
                extra_env=extra_env,
            )
            live_names = _soperator_upgrade_reservation_names(
                namespace=namespace,
                extra_env=extra_env,
            )
        if reservation_name not in live_names:
            raise RuntimeError(
                "recovery-required: cxcli could not recover its Slurm maintenance "
                f"reservation {reservation_name}"
            )
        decision_recorder(
            {
                "namespace": namespace,
                "checkpoint_id": checkpoint_id,
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": "maintenance-reservation-applied",
                "reservation_name": reservation_name,
            }
        )


def _soperator_upgrade_jobs_by_id(
    *,
    namespace: str,
    job_ids: Sequence[str],
    extra_env: Mapping[str, str] | None,
) -> tuple[AffectedSlurmJob, ...]:
    selected = tuple(_non_empty_text(job_id) for job_id in job_ids if _non_empty_text(job_id))
    if not selected:
        return ()
    result = _run_soperator_upgrade_login_command(
        namespace,
        "squeue -h -j "
        + shlex.quote(",".join(selected))
        + f" -o '{_SOPERATOR_UPGRADE_SQUEUE_FORMAT}'",
        extra_env=extra_env,
        timeout_seconds=120,
        check=False,
    )
    if (
        result.returncode != 0
        and "invalid job id" not in str(result.stderr or result.stdout or "").lower()
    ):
        raise RuntimeError("Could not classify Slurm job recovery state")
    return _soperator_upgrade_parse_jobs(result.stdout, impact_scope="recovery")


def _soperator_upgrade_require_held_job_postimage(
    *,
    namespace: str,
    job_ids: Sequence[str],
    extra_env: Mapping[str, str] | None,
) -> tuple[AffectedSlurmJob, ...]:
    selected = tuple(_non_empty_text(job_id) for job_id in job_ids if _non_empty_text(job_id))
    jobs = _soperator_upgrade_jobs_by_id(
        namespace=namespace,
        job_ids=selected,
        extra_env=extra_env,
    )
    by_id = {job.job_id: job for job in jobs}
    if set(by_id) != set(selected) or any(
        not slurm_job_is_held(by_id[job_id]) for job_id in selected
    ):
        raise RuntimeError("recovery-required: Slurm did not expose the exact held-job postimage")
    return tuple(by_id[job_id] for job_id in selected)


def _recover_soperator_slurm_action_intents(
    actions: Sequence[Mapping[str, Any]],
    *,
    extra_env: Mapping[str, str] | None,
    decision_recorder: Callable[[Mapping[str, Any]], None],
    assert_authority: Callable[[], object],
) -> None:
    """Classify or finish exact write-ahead Slurm intents after interruption."""

    resolved = {
        _non_empty_text(action.get("actionId"))
        for action in actions
        if _non_empty_text(action.get("disposition"))
        in {
            SlurmRecoveryDisposition.APPLIED.value,
            SlurmRecoveryDisposition.RECOVERED_APPLIED.value,
            SlurmRecoveryDisposition.SATISFIED_EXTERNAL.value,
            SlurmRecoveryDisposition.COMPLETE.value,
        }
    }
    for intent in actions:
        if (
            _non_empty_text(intent.get("disposition")) != SlurmRecoveryDisposition.INTENT.value
            or _non_empty_text(intent.get("actionId")) in resolved
        ):
            continue
        action_kind = _non_empty_text(intent.get("actionKind"))
        namespace = _non_empty_text(intent.get("namespace"))
        checkpoint_id = _non_empty_text(intent.get("checkpoint_id"))
        job_ids = tuple(
            _non_empty_text(job_id)
            for job_id in intent.get("job_ids", []) or []
            if _non_empty_text(job_id)
        )
        if action_kind in {
            "requeue-hold",
            "requeue-hold-selected",
            "requeue-hold-all",
            "pending-hold-recorded",
        }:
            live = {
                job.job_id: job
                for job in _soperator_upgrade_jobs_by_id(
                    namespace=namespace,
                    job_ids=job_ids,
                    extra_env=extra_env,
                )
            }
            preimages = {
                _non_empty_text(item.get("job_id")): item
                for item in intent.get("jobs", []) or []
                if isinstance(item, Mapping) and _non_empty_text(item.get("job_id"))
            }
            reapply: list[str] = []
            for job_id in job_ids:
                current = live.get(job_id)
                if current is None or slurm_job_is_held(current):
                    continue
                preimage = preimages.get(job_id)
                if not isinstance(preimage, Mapping) or any(
                    _non_empty_text(preimage.get(field)) != _non_empty_text(getattr(current, field))
                    for field in ("state", "partition", "allocated_nodes", "reason")
                ):
                    raise RuntimeError(
                        "recovery-required: Slurm job changed outside an unfinished hold intent"
                    )
                reapply.append(job_id)
            if reapply:
                assert_authority()
                if action_kind == "pending-hold-recorded":
                    _soperator_upgrade_hold_jobs(
                        namespace,
                        reapply,
                        extra_env=extra_env,
                    )
                else:
                    _soperator_upgrade_requeue_jobs(
                        namespace,
                        reapply,
                        hold=True,
                        extra_env=extra_env,
                    )
            after = {
                job.job_id: job
                for job in _soperator_upgrade_jobs_by_id(
                    namespace=namespace,
                    job_ids=job_ids,
                    extra_env=extra_env,
                )
            }
            if any(job_id in after and not slurm_job_is_held(after[job_id]) for job_id in job_ids):
                raise RuntimeError("recovery-required: Slurm hold intent remains ambiguous")
            if action_kind == "pending-hold-recorded":
                applied_action = "pending-hold-applied"
            else:
                applied_action = f"{action_kind}-applied"
            disposition = (
                SlurmRecoveryDisposition.SATISFIED_EXTERNAL
                if not after
                else SlurmRecoveryDisposition.RECOVERED_APPLIED
            )
            satisfied_external_job_ids = sorted(set(job_ids) - set(after))
            decision_recorder(
                {
                    "namespace": namespace,
                    "checkpoint_id": checkpoint_id,
                    "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "action": applied_action,
                    "job_ids": list(job_ids),
                    "jobs": [job.__dict__ for job in after.values()],
                    "satisfied_external_job_ids": satisfied_external_job_ids,
                    "recoveryDisposition": disposition.value,
                }
            )
            continue
        if action_kind == "scheduling-pause-recorded":
            records = _soperator_upgrade_pause_records_from_payload(intent.get("partitions"))
            applied_records: list[SlurmPartitionPauseRecord] = []
            for record in records:
                current = _soperator_upgrade_partition_state(
                    namespace=namespace,
                    partition=record.partition,
                    extra_env=extra_env,
                )
                if _soperator_upgrade_partition_observation_matches(
                    current,
                    record=record.previous_record,
                    fingerprint=record.previous_record_fingerprint,
                ):
                    assert_authority()
                    _run_soperator_upgrade_login_command(
                        namespace,
                        "scontrol update PartitionName="
                        + shlex.quote(record.partition)
                        + " State="
                        + shlex.quote(record.applied_state),
                        extra_env=extra_env,
                        timeout_seconds=120,
                    )
                    current = _soperator_upgrade_partition_state(
                        namespace=namespace,
                        partition=record.partition,
                        extra_env=extra_env,
                    )
                try:
                    applied_records.append(record.with_applied_observation(current))
                except ValueError as exc:
                    raise RuntimeError(
                        "recovery-required: Slurm partition pause intent is ambiguous"
                    ) from exc
            decision_recorder(
                {
                    "namespace": namespace,
                    "checkpoint_id": checkpoint_id,
                    "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "action": "scheduling-pause-applied",
                    "partitions": [record.as_payload() for record in applied_records],
                    "recoveryDisposition": SlurmRecoveryDisposition.RECOVERED_APPLIED.value,
                }
            )
            continue
        if action_kind == "nodes-drain-recorded":
            node_names = tuple(
                _non_empty_text(node)
                for node in intent.get("node_names", []) or []
                if _non_empty_text(node)
            )
            preimage = intent.get("node_preimage")
            if not isinstance(preimage, Mapping) or set(preimage) != set(node_names):
                raise RuntimeError("recovery-required: Slurm node drain preimage is incomplete")
            current = _soperator_upgrade_node_recovery_snapshot(
                namespace=namespace,
                node_names=node_names,
                extra_env=extra_env,
            )
            owned_nodes: list[str] = []
            reapply: list[str] = []
            expected_reason = f"cxcli-soperator-upgrade:{checkpoint_id}"
            for node in node_names:
                before = preimage.get(node)
                before_map = before if isinstance(before, Mapping) else {}
                observed = current[node]
                if "DRAIN" in _non_empty_text(before_map.get("state")):
                    if observed != {
                        "state": _non_empty_text(before_map.get("state")),
                        "reason": _non_empty_text(before_map.get("reason")),
                    }:
                        raise RuntimeError(
                            "recovery-required: pre-existing Slurm node drain changed"
                        )
                    continue
                owned_nodes.append(node)
                if "DRAIN" in observed["state"] and observed["reason"] == expected_reason:
                    continue
                if observed == {
                    "state": _non_empty_text(before_map.get("state")),
                    "reason": _non_empty_text(before_map.get("reason")),
                }:
                    reapply.append(node)
                    continue
                raise RuntimeError("recovery-required: Slurm node drain intent is ambiguous")
            if reapply:
                assert_authority()
                _soperator_upgrade_drain_slurm_nodes(
                    namespace=namespace,
                    node_names=reapply,
                    checkpoint_id=checkpoint_id,
                    extra_env=extra_env,
                )
            after = _soperator_upgrade_node_recovery_snapshot(
                namespace=namespace,
                node_names=node_names,
                extra_env=extra_env,
            )
            if any(
                "DRAIN" not in after[node]["state"] or after[node]["reason"] != expected_reason
                for node in owned_nodes
            ):
                raise RuntimeError("recovery-required: Slurm node drain did not converge")
            decision_recorder(
                {
                    "namespace": namespace,
                    "checkpoint_id": checkpoint_id,
                    "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "action": "nodes-drained" if owned_nodes else "nodes-drain-not-required",
                    "node_names": list(node_names),
                    "owned_node_names": owned_nodes,
                    "node_postimage": after,
                    "recoveryDisposition": SlurmRecoveryDisposition.RECOVERED_APPLIED.value,
                }
            )


def _resume_interrupted_soperator_slurm_gates(
    actions: Sequence[Mapping[str, Any]],
    *,
    job_policy: str,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    job_wait_timeout_seconds: int,
    job_refresh_interval_seconds: int,
    extra_env: Mapping[str, str] | None,
    decision_recorder: Callable[[Mapping[str, Any]], None],
    assert_authority: Callable[[], object],
    all_active_partitions: bool = False,
    continue_until_clear: bool = False,
) -> None:
    """Finish every started gate after all prior intents were classified."""

    completed = {
        (_non_empty_text(event.get("namespace")), _non_empty_text(event.get("checkpoint_id")))
        for event in actions
        if _non_empty_text(event.get("action")) == "slurm-gate-complete"
    }
    for event in actions:
        if _non_empty_text(event.get("action")) != "slurm-gate-started":
            continue
        namespace = _non_empty_text(event.get("namespace"))
        checkpoint_id = _non_empty_text(event.get("checkpoint_id"))
        if (namespace, checkpoint_id) in completed:
            continue
        node_names = tuple(
            _non_empty_text(node)
            for node in event.get("node_names", []) or []
            if _non_empty_text(node)
        )
        if not namespace or not re.fullmatch(r"[0-9a-f]{16}", checkpoint_id) or not node_names:
            raise RuntimeError("recovery-required: interrupted Slurm gate identity is incomplete")

        def _record(
            details: Mapping[str, Any],
            *,
            _namespace: str = namespace,
            _checkpoint_id: str = checkpoint_id,
        ) -> None:
            decision_recorder(
                {
                    "namespace": _namespace,
                    "checkpoint_id": _checkpoint_id,
                    **dict(details),
                }
            )

        _handle_soperator_upgrade_running_jobs(
            namespace=namespace,
            node_names=node_names,
            policy=job_policy,
            cancel_job_ids=cancel_job_ids,
            requeue_job_ids=requeue_job_ids,
            wait_timeout_seconds=job_wait_timeout_seconds,
            refresh_interval_seconds=job_refresh_interval_seconds,
            checkpoint_id=checkpoint_id,
            extra_env=extra_env,
            drain_nodes=False,
            slurm_scheduling_pause=True,
            decision_recorder=_record,
            mutation_guard=assert_authority,
            all_active_partitions=all_active_partitions,
            continue_until_clear=continue_until_clear,
        )
        reservation_name = _soperator_upgrade_maintenance_reservation_name(checkpoint_id)
        reservation_events = [
            item
            for item in actions
            if _non_empty_text(item.get("namespace")) == namespace
            and _non_empty_text(item.get("checkpoint_id")) == checkpoint_id
            and _non_empty_text(item.get("action")) == "maintenance-reservation-recorded"
        ]
        if not reservation_events:
            live_names = _soperator_upgrade_reservation_names(
                namespace=namespace,
                extra_env=extra_env,
            )
            if reservation_name in live_names:
                raise RuntimeError(
                    "recovery-required: unjournaled operation reservation already exists"
                )
            _record(
                {
                    "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "action": "maintenance-reservation-recorded",
                    "reservation_name": reservation_name,
                    "preexisting_reservations": list(live_names),
                }
            )
            assert_authority()
            _soperator_upgrade_create_maintenance_reservation(
                namespace=namespace,
                reservation_name=reservation_name,
                extra_env=extra_env,
            )
            _record(
                {
                    "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "action": "maintenance-reservation-applied",
                    "reservation_name": reservation_name,
                    "recoveryDisposition": SlurmRecoveryDisposition.RECOVERED_APPLIED.value,
                }
            )
        pending_jobs = tuple(
            job
            for job in _soperator_upgrade_affected_jobs(
                namespace=namespace,
                node_names=node_names,
                extra_env=extra_env,
                include_pending=True,
                all_jobs=all_active_partitions,
            )
            if slurm_job_is_pending(job) and not slurm_job_is_held(job)
        )
        if pending_jobs:
            pending_ids = tuple(job.job_id for job in pending_jobs)
            _record(
                {
                    "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "action": "pending-hold-recorded",
                    "job_ids": list(pending_ids),
                    "jobs": [job.__dict__ for job in pending_jobs],
                }
            )
            assert_authority()
            _soperator_upgrade_hold_jobs(namespace, pending_ids, extra_env=extra_env)
            held_jobs = _soperator_upgrade_require_held_job_postimage(
                namespace=namespace,
                job_ids=pending_ids,
                extra_env=extra_env,
            )
            _record(
                {
                    "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "action": "pending-hold-applied",
                    "job_ids": list(pending_ids),
                    "jobs": [job.__dict__ for job in held_jobs],
                    "recoveryDisposition": SlurmRecoveryDisposition.RECOVERED_APPLIED.value,
                }
            )
        node_preimage = _soperator_upgrade_node_recovery_snapshot(
            namespace=namespace,
            node_names=node_names,
            extra_env=extra_env,
        )
        _record(
            {
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": "nodes-drain-recorded",
                "node_names": list(node_names),
                "node_preimage": node_preimage,
            }
        )
        assert_authority()
        owned_nodes = _soperator_upgrade_drain_slurm_nodes(
            namespace=namespace,
            node_names=node_names,
            checkpoint_id=checkpoint_id,
            extra_env=extra_env,
        )
        _record(
            {
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": "nodes-drained" if owned_nodes else "nodes-drain-not-required",
                "node_names": list(node_names),
                "owned_node_names": list(owned_nodes),
                "node_postimage": _soperator_upgrade_node_recovery_snapshot(
                    namespace=namespace,
                    node_names=node_names,
                    extra_env=extra_env,
                ),
                "recoveryDisposition": SlurmRecoveryDisposition.RECOVERED_APPLIED.value,
            }
        )
        _record(
            {
                "at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
                "action": "slurm-gate-complete",
                "node_names": list(node_names),
                "recoveryDisposition": SlurmRecoveryDisposition.COMPLETE.value,
            }
        )


def _soperator_slurm_action_journal_path(paths: ProjectPaths, target_ref: str) -> Path:
    normalized_target = normalize_component_token(target_ref) or "default"
    return paths.reports_dir / f"soperator-slurm-actions-{normalized_target}.json"


def _soperator_slurm_operation_evidence(
    journal: Mapping[str, object],
) -> dict[str, object]:
    """Bind immutable scheduling inputs while keeping recovery events journal-owned."""

    required = (
        "schema",
        "targetRef",
        "command",
        "startedAt",
        "policy",
        "slurmPreimage",
    )
    missing = [key for key in required if key not in journal]
    if missing or not isinstance(journal.get("actions"), list):
        raise RuntimeError("Soperator Slurm journal lacks immutable operation evidence")
    return {
        **{key: journal[key] for key in required},
        # The action list is empty at first bind. Later CAS-journaled actions are
        # mutable recovery state and must not change the operation identity.
        "actions": [],
    }


def _soperator_slurm_cluster_journal_name(*, target_ref: str, cluster_id: str) -> str:
    digest = hashlib.sha256(f"{cluster_id}|{target_ref}".encode()).hexdigest()[:20]
    return f"nebius-cxcli-soperator-slurm-{digest}"


def _read_soperator_slurm_cluster_journal(
    *,
    target_ref: str,
    cluster_id: str,
    kube_context: str,
    extra_env: Mapping[str, str] | None,
) -> tuple[dict[str, Any], str] | None:
    name = _soperator_slurm_cluster_journal_name(
        target_ref=target_ref,
        cluster_id=cluster_id,
    )
    result = _run_soperator_upgrade_kubectl_cluster(
        ["-n", "kube-system", "get", "configmap", name, "-o", "json"],
        kube_context=kube_context,
        extra_env=extra_env,
        timeout_seconds=60,
        check=False,
    )
    if result.returncode != 0:
        detail = f"{result.stdout}\n{result.stderr}".lower()
        if "notfound" in detail or "not found" in detail:
            return None
        raise RuntimeError("Could not read the cluster Soperator Slurm recovery journal")
    try:
        resource = json.loads(result.stdout or "{}")
        data = resource.get("data") if isinstance(resource, Mapping) else None
        journal = (
            json.loads(str(data.get("journal.json") or "")) if isinstance(data, Mapping) else None
        )
    except json.JSONDecodeError as exc:
        raise RuntimeError("Cluster Soperator Slurm journal returned invalid JSON") from exc
    metadata = resource.get("metadata") if isinstance(resource, Mapping) else None
    resource_version = (
        str(metadata.get("resourceVersion") or "").strip() if isinstance(metadata, Mapping) else ""
    )
    if not isinstance(journal, dict) or not resource_version:
        raise RuntimeError("Cluster Soperator Slurm journal is incomplete")
    return journal, resource_version


def _write_soperator_slurm_cluster_journal(
    journal: Mapping[str, Any],
    *,
    target_ref: str,
    cluster_id: str,
    kube_context: str,
    extra_env: Mapping[str, str] | None,
) -> None:
    lease_uid = _non_empty_text(journal.get("leaseUid"))
    try:
        fencing_epoch = int(journal.get("fencingEpoch") or 0)
    except (TypeError, ValueError) as exc:
        raise RuntimeError("Soperator Slurm journal has malformed fencing authority") from exc
    if not lease_uid or fencing_epoch < 1:
        raise RuntimeError("Soperator Slurm journal has incomplete fencing authority")
    current = _read_soperator_slurm_cluster_journal(
        target_ref=target_ref,
        cluster_id=cluster_id,
        kube_context=kube_context,
        extra_env=extra_env,
    )
    if current is not None:
        current_journal = current[0]
        current_lease_uid = _non_empty_text(current_journal.get("leaseUid"))
        try:
            current_epoch = int(current_journal.get("fencingEpoch") or 0)
        except (TypeError, ValueError) as exc:
            raise RuntimeError(
                "Cluster Soperator Slurm journal has malformed fencing authority"
            ) from exc
        if not current_lease_uid or current_epoch < 1:
            raise RuntimeError("Cluster Soperator Slurm journal has incomplete fencing authority")
        if current_epoch > fencing_epoch or (
            current_epoch == fencing_epoch and current_lease_uid != lease_uid
        ):
            raise RuntimeError("Lost the cluster Soperator Slurm journal fencing authority")
    name = _soperator_slurm_cluster_journal_name(
        target_ref=target_ref,
        cluster_id=cluster_id,
    )
    metadata: dict[str, object] = {
        "name": name,
        "namespace": "kube-system",
        "labels": {
            "app.kubernetes.io/managed-by": "nebius-cxcli",
            "app.kubernetes.io/part-of": "soperator",
            "nebius-cxcli/fence-epoch": str(journal.get("fencingEpoch") or ""),
        },
    }
    if current is not None:
        metadata["resourceVersion"] = current[1]
    manifest = {
        "apiVersion": "v1",
        "kind": "ConfigMap",
        "metadata": metadata,
        "data": {"journal.json": json.dumps(journal, sort_keys=True, separators=(",", ":"))},
    }
    result = _run_soperator_upgrade_kubectl_cluster(
        ["-n", "kube-system", "replace" if current else "create", "-f", "-"],
        kube_context=kube_context,
        input_text=json.dumps(manifest, sort_keys=True),
        extra_env=extra_env,
        timeout_seconds=60,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError("Lost the cluster Soperator Slurm journal CAS authority")


def _apply_rendered_flux_with_soperator_job_policy(
    config: Any,
    paths: ProjectPaths,
    *,
    command_name: str,
    target_ref: str,
    extra_env: dict[str, str] | None,
    job_policy: str,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    job_wait_timeout_seconds: int,
    job_refresh_interval_seconds: int,
    strategy: SoperatorStrategyPlan | None = None,
    source_capability_sha256: str = "",
    operation_source_release: str | None = None,
    infrastructure_plan_sha256: str = "",
    infrastructure_receipt: SoperatorInfrastructureReceipt | None = None,
    protected_preflight_receipt: ProtectedDataPlaneReceipt | None = None,
    rootfs_admission_preflight: SoperatorRootfsAdmissionPreflight | None = None,
    slurm_preimage: SlurmUpgradePreimage | None = None,
    admission_evidence: object | None = None,
    reconcile_execution_policy: SoperatorReconcileExecutionPolicy | None = None,
    assert_authority: Callable[[], object] | None = None,
    bind_operation_spec_sha256: Callable[[str], object] | None = None,
    intervention_generation: int = 0,
    superseded_operation_spec_sha256: str = "",
    admitted_repair_reason: str = "",
    operation_started_at: float | None = None,
    upgrade_progress: SoperatorUpgradeProgress | None = None,
) -> SoperatorOperationAnchor | None:
    payload = to_plain_data(config)
    target_row = (
        soperator_registration_target(payload, target_ref=target_ref) if target_ref else None
    )
    ownership = (
        "onboarded"
        if isinstance(target_row, Mapping) and deploy_target_is_external_mk8s(target_row)
        else "managed"
    )
    release_refs = _soperator_release_refs_for_job_policy(config, target_ref=target_ref)
    if not release_refs:
        return _apply_rendered_flux(
            paths,
            config=config,
            extra_env=extra_env,
            upgrade_progress=upgrade_progress,
        )
    journal_path = _soperator_slurm_action_journal_path(paths, target_ref)
    if assert_authority is None:
        raise RuntimeError("Soperator release reconciliation requires an active authority")
    try:
        initial_authority = assert_authority()
    except Exception as exc:
        raise SoperatorSafetyPauseError(
            "Soperator Slurm gate authority is not currently provable"
        ) from exc
    if not isinstance(initial_authority, SoperatorLeaseAuthority):
        raise RuntimeError("Soperator Slurm recovery requires fencing authority")
    cluster_id = _non_empty_text((extra_env or {}).get(GRAFANA_TARGET_CLUSTER_ID_ENV))
    kube_context = _non_empty_text((extra_env or {}).get(GRAFANA_TARGET_KUBE_CONTEXT_ENV))
    if not cluster_id or not kube_context:
        raise RuntimeError("Soperator Slurm recovery requires immutable cluster id and context")
    if command_name == "soperator upgrade" and slurm_preimage is None:
        raise RuntimeError("Soperator upgrade requires its exact admitted Slurm preimage")
    slurm_preimage_payload: Mapping[str, object] = (
        slurm_preimage.as_payload() if slurm_preimage is not None else {"mode": "not-required"}
    )
    slurm_preimage_sha256 = (
        slurm_preimage.receipt_sha256
        if slurm_preimage is not None
        else soperator_sha256(slurm_preimage_payload)
    )
    expected_policy = {
        "jobPolicy": job_policy,
        "cancelJobIds": sorted(set(cancel_job_ids)),
        "requeueJobIds": sorted(set(requeue_job_ids)),
        "waitTimeoutSeconds": job_wait_timeout_seconds,
        "refreshIntervalSeconds": job_refresh_interval_seconds,
        "schedulingPause": True,
        "slurmPreimageSha256": slurm_preimage_sha256,
    }
    resume_existing = False
    journal: dict[str, Any]
    local_journal: dict[str, Any] | None = None
    if journal_path.is_file():
        try:
            loaded_journal = json.loads(journal_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise SoperatorSafetyPauseError("Soperator Slurm action journal is invalid") from exc
        if not isinstance(loaded_journal, dict):
            raise SoperatorSafetyPauseError("Soperator Slurm action journal is invalid")
        local_journal = loaded_journal
    cluster_record = _read_soperator_slurm_cluster_journal(
        target_ref=target_ref,
        cluster_id=cluster_id,
        kube_context=kube_context,
        extra_env=extra_env,
    )
    if cluster_record is None and local_journal is not None:
        raise SoperatorSafetyPauseError(
            "recovery-required: local Soperator Slurm journal has no cluster authority"
        )
    loaded_journal = cluster_record[0] if cluster_record is not None else None
    if loaded_journal is not None:
        if loaded_journal.get("schema") != SOPERATOR_SLURM_RECOVERY_SCHEMA:
            raise SoperatorSafetyPauseError(
                "Soperator Slurm action journal has an unsupported schema"
            )
        if loaded_journal.get("status") != "restored":
            if (
                loaded_journal.get("targetRef") != target_ref
                or loaded_journal.get("command") != command_name
                or loaded_journal.get("policy") != expected_policy
                or loaded_journal.get("slurmPreimage") != slurm_preimage_payload
                or not isinstance(loaded_journal.get("actions"), list)
            ):
                raise SoperatorSafetyPauseError(
                    "recovery-required: unfinished Soperator scheduling state belongs "
                    "to a different exact operation"
                )
            journal = loaded_journal
            validate_slurm_recovery_actions(journal["actions"])
            resume_existing = True
        else:
            journal = {}
    else:
        journal = {}

    def _persist_journal(payload: dict[str, Any]) -> None:
        try:
            authority = assert_authority()
        except Exception as exc:
            raise SoperatorSafetyPauseError(
                "Soperator Slurm journal fencing authority is not currently provable"
            ) from exc
        if not isinstance(authority, SoperatorLeaseAuthority):
            raise RuntimeError("Soperator Slurm journal lost fencing authority")
        payload["leaseUid"] = authority.lease_uid
        payload["fencingEpoch"] = authority.fencing_epoch
        try:
            _write_soperator_slurm_cluster_journal(
                payload,
                target_ref=target_ref,
                cluster_id=cluster_id,
                kube_context=kube_context,
                extra_env=extra_env,
            )
        except Exception as exc:
            raise SoperatorSafetyPauseError(
                "Soperator Slurm journal CAS authority is not currently provable"
            ) from exc
        _write_owner_only_json(journal_path, payload)

    def _read_controller_spool_migration() -> Mapping[str, object] | None:
        raw = journal.get("controllerSpoolMigration")
        if raw is None:
            return None
        if not isinstance(raw, Mapping):
            raise SoperatorSafetyPauseError(
                "Soperator controller spool migration journal is malformed"
            )
        return dict(raw)

    def _write_controller_spool_migration(payload: Mapping[str, object]) -> None:
        journal["controllerSpoolMigration"] = dict(payload)
        _persist_journal(journal)

    if resume_existing:
        raw_started_at = _non_empty_text(journal.get("startedAt"))
        try:
            started_at = datetime.fromisoformat(raw_started_at.replace("Z", "+00:00")).timestamp()
        except (TypeError, ValueError) as exc:
            raise RuntimeError("Soperator Slurm action journal has an invalid start time") from exc
        _persist_journal(journal)
    else:
        started_at = float(operation_started_at or time.time())
        journal = {
            "schema": SOPERATOR_SLURM_RECOVERY_SCHEMA,
            "targetRef": target_ref,
            "command": command_name,
            "startedAt": datetime.fromtimestamp(started_at, UTC).isoformat().replace("+00:00", "Z"),
            "status": "gating",
            "policy": expected_policy,
            "slurmPreimage": slurm_preimage_payload,
            "actions": [],
        }
        _persist_journal(journal)

    def _record_decision(event: Mapping[str, Any]) -> None:
        try:
            authority = assert_authority()
        except Exception as exc:
            raise SoperatorSafetyPauseError(
                "Soperator Slurm decision fencing authority is not currently provable"
            ) from exc
        if not isinstance(authority, SoperatorLeaseAuthority):
            raise RuntimeError("Soperator Slurm journal lacks fencing authority")
        actions = journal["actions"]
        assert isinstance(actions, list)
        raw_event = dict(event)
        raw_disposition = str(raw_event.pop("recoveryDisposition", "") or "")
        disposition = SlurmRecoveryDisposition(raw_disposition) if raw_disposition else None
        actions.append(
            normalize_slurm_recovery_event(
                raw_event,
                fencing_epoch=authority.fencing_epoch,
                disposition=disposition,
            )
        )
        _persist_journal(journal)

    stage_order = {
        "gated": 0,
        "infrastructure-restored": 1,
        "requeued-running-released": 2,
        "other-held-released": 3,
    }

    def _stage_completed(stage: str) -> bool:
        completed = _non_empty_text(journal.get("lastCompletedStage"))
        return stage_order.get(completed, -1) >= stage_order[stage]

    def _record_stage(stage: str, receipt_key: str, receipt: object) -> object:
        journal["lastCompletedStage"] = stage
        journal[receipt_key] = receipt
        journal["status"] = stage
        _persist_journal(journal)
        return receipt

    def _scheduling_identity() -> dict[str, object]:
        return _soperator_slurm_operation_evidence(journal)

    def _bind_operation_spec(operation_spec_sha256: str) -> None:
        expected = _non_empty_text(journal.get("operationSpecSha256"))
        if (
            expected
            and expected != operation_spec_sha256
            and (intervention_generation < 1 or expected != superseded_operation_spec_sha256)
        ):
            raise SoperatorSafetyPauseError(
                "recovery-required: the unfinished Soperator scheduling journal is bound "
                "to different immutable operation inputs"
            )
        if bind_operation_spec_sha256 is not None:
            bind_operation_spec_sha256(operation_spec_sha256)
        if expected and expected != operation_spec_sha256:
            raw_repairs = journal.get("operationRepairs")
            repairs = (
                [dict(item) for item in raw_repairs if isinstance(item, Mapping)]
                if isinstance(raw_repairs, list)
                else []
            )
            repairs.append(
                {
                    "generation": intervention_generation,
                    "previousOperationSpecSha256": expected,
                    "replacementOperationSpecSha256": operation_spec_sha256,
                }
            )
            journal["operationRepairs"] = repairs
            journal["operationSpecSha256"] = operation_spec_sha256
            _persist_journal(journal)
        if not expected:
            journal["operationSpecSha256"] = operation_spec_sha256
            _persist_journal(journal)

    try:

        def _ensure_slurm_gated() -> None:
            if resume_existing:
                actions = journal["actions"]
                assert isinstance(actions, list)
                if _stage_completed("gated"):
                    # A completed gate is an authenticated transition prefix. The
                    # target apply may already have retired the legacy login
                    # workload, so only validate the sealed journal here; live
                    # recovery is reserved for an actually interrupted gate.
                    _soperator_flux_apply_owned_scheduling_state(
                        [item for item in actions if isinstance(item, Mapping)]
                    )
                    return
                _recover_soperator_slurm_action_intents(
                    [item for item in actions if isinstance(item, Mapping)],
                    extra_env=extra_env,
                    decision_recorder=_record_decision,
                    assert_authority=assert_authority,
                )
                _resume_soperator_flux_apply_maintenance_reservations(
                    [item for item in actions if isinstance(item, Mapping)],
                    extra_env=extra_env,
                    decision_recorder=_record_decision,
                    assert_authority=assert_authority,
                )
                _resume_interrupted_soperator_slurm_gates(
                    [item for item in actions if isinstance(item, Mapping)],
                    job_policy=job_policy,
                    cancel_job_ids=cancel_job_ids,
                    requeue_job_ids=requeue_job_ids,
                    job_wait_timeout_seconds=job_wait_timeout_seconds,
                    job_refresh_interval_seconds=job_refresh_interval_seconds,
                    extra_env=extra_env,
                    decision_recorder=_record_decision,
                    assert_authority=assert_authority,
                    all_active_partitions=command_name == "soperator upgrade",
                    continue_until_clear=command_name == "soperator upgrade",
                )
                actions = journal["actions"]
                assert isinstance(actions, list)
                if not any(
                    isinstance(item, Mapping)
                    and _non_empty_text(item.get("action")) == "slurm-gate-started"
                    for item in actions
                ):
                    _soperator_flux_apply_slurm_job_gate(
                        config,
                        command_name=command_name,
                        target_ref=target_ref,
                        extra_env=extra_env,
                        job_policy=job_policy,
                        cancel_job_ids=cancel_job_ids,
                        requeue_job_ids=requeue_job_ids,
                        job_wait_timeout_seconds=job_wait_timeout_seconds,
                        job_refresh_interval_seconds=job_refresh_interval_seconds,
                        decision_recorder=_record_decision,
                        mutation_guard=assert_authority,
                    )
                    actions = journal["actions"]
                    assert isinstance(actions, list)
                _soperator_flux_apply_owned_scheduling_state(
                    [item for item in actions if isinstance(item, Mapping)]
                )
                if not _stage_completed("gated"):
                    journal["status"] = "gated"
                    journal["lastCompletedStage"] = "gated"
                    _persist_journal(journal)
                return
            _soperator_flux_apply_slurm_job_gate(
                config,
                command_name=command_name,
                target_ref=target_ref,
                extra_env=extra_env,
                job_policy=job_policy,
                cancel_job_ids=cancel_job_ids,
                requeue_job_ids=requeue_job_ids,
                job_wait_timeout_seconds=job_wait_timeout_seconds,
                job_refresh_interval_seconds=job_refresh_interval_seconds,
                decision_recorder=_record_decision,
                mutation_guard=assert_authority,
            )
            actions = journal["actions"]
            assert isinstance(actions, list)
            _soperator_flux_apply_owned_scheduling_state(
                [item for item in actions if isinstance(item, Mapping)]
            )
            journal["status"] = "gated"
            journal["lastCompletedStage"] = "gated"
            _persist_journal(journal)

        def _restore_infrastructure() -> object:
            if _stage_completed("infrastructure-restored"):
                return journal.get("infrastructureRestoreReceipt", {"status": "already-complete"})
            actions = journal["actions"]
            assert isinstance(actions, list)
            receipt = _restore_soperator_flux_apply_infrastructure(
                [item for item in actions if isinstance(item, Mapping)],
                extra_env=extra_env,
                assert_authority=assert_authority,
            )
            return _record_stage("infrastructure-restored", "infrastructureRestoreReceipt", receipt)

        def _release_requeued() -> object:
            if _stage_completed("requeued-running-released"):
                return journal.get("requeuedReleaseReceipt", {"status": "already-complete"})
            actions = journal["actions"]
            assert isinstance(actions, list)
            receipt = _release_soperator_flux_apply_jobs(
                [item for item in actions if isinstance(item, Mapping)],
                group="requeued-running",
                extra_env=extra_env,
                assert_authority=assert_authority,
            )
            return _record_stage("requeued-running-released", "requeuedReleaseReceipt", receipt)

        def _release_other_held() -> object:
            if _stage_completed("other-held-released"):
                return journal.get("heldReleaseReceipt", {"status": "already-complete"})
            actions = journal["actions"]
            assert isinstance(actions, list)
            receipt = _release_soperator_flux_apply_jobs(
                [item for item in actions if isinstance(item, Mapping)],
                group="other-held",
                extra_env=extra_env,
                assert_authority=assert_authority,
            )
            return _record_stage("other-held-released", "heldReleaseReceipt", receipt)

        def _verify_infrastructure_restored() -> object:
            actions = journal["actions"]
            assert isinstance(actions, list)
            return _verify_soperator_flux_apply_infrastructure_restored(
                [item for item in actions if isinstance(item, Mapping)],
                extra_env=extra_env,
            )

        def _verify_requeued_released() -> object:
            actions = journal["actions"]
            assert isinstance(actions, list)
            return _verify_soperator_flux_apply_jobs_released(
                [item for item in actions if isinstance(item, Mapping)],
                group="requeued-running",
                extra_env=extra_env,
            )

        def _verify_other_held_released() -> object:
            actions = journal["actions"]
            assert isinstance(actions, list)
            return _verify_soperator_flux_apply_jobs_released(
                [item for item in actions if isinstance(item, Mapping)],
                group="other-held",
                extra_env=extra_env,
            )

        def _recover_infrastructure_restored() -> object:
            try:
                receipt = _verify_infrastructure_restored()
            except RuntimeError:
                actions = journal["actions"]
                assert isinstance(actions, list)
                _resume_soperator_flux_apply_maintenance_reservations(
                    [item for item in actions if isinstance(item, Mapping)],
                    extra_env=extra_env,
                    decision_recorder=_record_decision,
                    assert_authority=assert_authority,
                )
                actions = journal["actions"]
                assert isinstance(actions, list)
                _restore_soperator_flux_apply_infrastructure(
                    [item for item in actions if isinstance(item, Mapping)],
                    extra_env=extra_env,
                    assert_authority=assert_authority,
                )
                receipt = _verify_infrastructure_restored()
            if not _stage_completed("infrastructure-restored"):
                _record_stage(
                    "infrastructure-restored",
                    "infrastructureRestoreReceipt",
                    receipt,
                )
            return receipt

        def _recover_requeued_released() -> object:
            try:
                receipt = _verify_requeued_released()
            except RuntimeError:
                _release_requeued()
                receipt = _verify_requeued_released()
            if not _stage_completed("requeued-running-released"):
                _record_stage("requeued-running-released", "requeuedReleaseReceipt", receipt)
            return receipt

        def _recover_other_held_released() -> object:
            try:
                receipt = _verify_other_held_released()
            except RuntimeError:
                _release_other_held()
                receipt = _verify_other_held_released()
            if not _stage_completed("other-held-released"):
                _record_stage("other-held-released", "heldReleaseReceipt", receipt)
            return receipt

        operation_anchor = _apply_rendered_flux(
            paths,
            config=config,
            extra_env=extra_env,
            target_ref=target_ref,
            ownership=ownership,
            strategy=strategy,
            source_capability_sha256=source_capability_sha256,
            operation_source_release=operation_source_release,
            infrastructure_plan_sha256=infrastructure_plan_sha256,
            infrastructure_receipt=infrastructure_receipt,
            protected_preflight_receipt=protected_preflight_receipt,
            rootfs_admission_preflight=rootfs_admission_preflight,
            scheduling_evidence=_scheduling_identity(),
            admission_evidence=admission_evidence,
            reconcile_execution_policy=reconcile_execution_policy,
            assert_authority=assert_authority,
            restore_infrastructure=_restore_infrastructure,
            release_requeued_jobs=_release_requeued,
            release_held_jobs=_release_other_held,
            verify_restored_infrastructure=_verify_infrastructure_restored,
            verify_requeued_jobs=_verify_requeued_released,
            verify_held_jobs=_verify_other_held_released,
            recover_restored_infrastructure=_recover_infrastructure_restored,
            recover_requeued_jobs=_recover_requeued_released,
            recover_held_jobs=_recover_other_held_released,
            bind_operation_spec_sha256=_bind_operation_spec,
            before_reconcile_mutations=_ensure_slurm_gated,
            read_controller_spool_migration=_read_controller_spool_migration,
            write_controller_spool_migration=_write_controller_spool_migration,
            intervention_generation=intervention_generation,
            superseded_operation_spec_sha256=superseded_operation_spec_sha256,
            admitted_repair_reason=admitted_repair_reason,
            upgrade_progress=upgrade_progress,
        )
        journal["status"] = "restored"
        journal["completedAt"] = (
            datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z")
        )
        _persist_journal(journal)
        return operation_anchor
    except Exception as exc:
        supervised = bool(
            reconcile_execution_policy is not None
            and reconcile_execution_policy.forward_until_complete
        )
        if supervised:
            journal["status"] = _soperator_upgrade_failure_disposition(
                "scheduling-gate",
                exc,
            ).value
        elif _stage_completed("other-held-released"):
            journal["status"] = "failed-after-restore"
        elif _stage_completed("requeued-running-released"):
            journal["status"] = "failed-after-partial-resume"
        else:
            journal["status"] = "recovery-required"
        journal["failedAt"] = datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z")
        _persist_journal(journal)
        if not _stage_completed("requeued-running-released") and journal["actions"]:
            console.print(
                "Soperator reconciliation did not pass complete product readiness; "
                "checkpoint-owned jobs remain held. Rerun the exact operation to "
                "continue from its immutable journal."
            )
        raise


def _deploy_generated_artifacts(
    config: Any,
    paths: ProjectPaths,
    manifest: Mapping[str, Any],
    *,
    skip_validations: bool,
    skip_validation_kinds: set[str],
    requested_target_ref: str | None = None,
    all_targets: bool = False,
    job_policy: str = "fail",
    cancel_job_ids: Sequence[str] = (),
    requeue_job_ids: Sequence[str] = (),
    job_wait_timeout_seconds: int = 0,
    job_refresh_interval_seconds: int = 30,
    terraform_plan_file: Path | None = None,
    expected_terraform_plan_sha256: str = "",
    skip_terraform_apply: bool = False,
    on_terraform_complete: Callable[[], None] | None = None,
    soperator_install_lease: SoperatorInstallRemoteLease | None = None,
    soperator_install_approval_fingerprint: str = "",
) -> DeployRunSummary:
    """Deploy an existing generated artifact bundle without rerendering it."""
    soperator_operation_started_at = time.time()
    soperator_infrastructure_plan_sha256 = (
        _sha256_file(terraform_plan_file) if terraform_plan_file is not None else ""
    )
    if (
        expected_terraform_plan_sha256
        and soperator_infrastructure_plan_sha256 != expected_terraform_plan_sha256
    ):
        raise RuntimeError(
            "The saved Terraform plan no longer matches its approved Soperator receipt"
        )
    if _manifest_missing_deploy_validations(manifest):
        raise RuntimeError(
            "Generated manifest is missing deploy.validations metadata. "
            f"Rerender with `nebius-cxcli render {paths.config_path}` before deploy."
        )
    declared_validations = _manifest_deploy_validations(manifest)
    _raise_if_manifest_has_unsupported_deploy_validation_kinds(
        declared_validations,
        config_path=paths.config_path,
    )
    deploy_declared_validations = _filter_deploy_validations(
        declared_validations,
        skip_validations=False,
        skip_kinds=set(),
    )
    deploy_validations = _filter_deploy_validations(
        deploy_declared_validations,
        skip_validations=skip_validations,
        skip_kinds=skip_validation_kinds,
    )
    selected_targets = _resolve_deploy_run_targets(
        manifest,
        requested_target_ref=requested_target_ref,
        all_targets=all_targets,
    )
    if soperator_install_lease is None and _payload_has_enabled_soperator(config):
        raise RuntimeError(
            "Soperator in-cluster mutation is available only through "
            "`nebius-cxcli soperator install` or `soperator upgrade`"
        )
    mysterybox_payload_env = _run_deploy_preflight(
        config,
        paths,
        manifest=manifest,
    )
    status_watchers = _manifest_status_watchers(manifest) or _enabled_status_watcher_specs(config)
    has_enabled_app_charts = _active_chart_count(config) > 0
    manifest_targets = _manifest_deploy_targets(manifest)
    report_validations = [dict(item) for item in deploy_declared_validations]
    if manifest_targets and selected_targets and len(selected_targets) < len(manifest_targets):
        report_validations = _filter_validations_for_target_refs(
            deploy_declared_validations,
            target_refs={str(target["target_ref"]) for target in selected_targets},
        )
    clear_deploy_validation_artifacts(
        declared_validations,
        reports_dir=paths.reports_dir,
    )
    gitops_bootstrap_commands: list[str] = []
    apply_kwargs: dict[str, Any] = {"initialize": False}
    apply_kwargs["manifest"] = manifest
    if terraform_plan_file is not None:
        apply_kwargs["plan_file"] = terraform_plan_file
        if expected_terraform_plan_sha256:
            apply_kwargs["expected_plan_sha256"] = expected_terraform_plan_sha256
    if status_watchers:
        apply_kwargs["status_watchers"] = status_watchers
    apply_kwargs["run_mk8s_preflight"] = False
    if mysterybox_payload_env:
        apply_kwargs["extra_env"] = mysterybox_payload_env
    terraform_required = _config_has_enabled_infra_components(config)
    if terraform_required and not skip_terraform_apply:
        try:
            _run_terraform_apply_with_status(config, paths, **apply_kwargs)
        except RuntimeError:
            with suppress(Exception):
                if _sync_mysterybox_primary_version_ids_to_config(
                    config,
                    paths,
                    initialize=False,
                    require_all=False,
                ):
                    console.print(
                        "Recovered MysteryBox primary version_id values from Terraform state; "
                        "retry deploy to continue from the refreshed generated bundle."
                    )
            raise
        if _sync_mysterybox_primary_version_ids_to_config(
            config,
            paths,
            initialize=False,
        ):
            manifest = load_generated_manifest(paths.generated_dir)
            config = runtime_config_from_manifest(manifest)
        _refresh_mysterybox_eso_flux_after_terraform(config, paths)
        if on_terraform_complete is not None:
            on_terraform_complete()
    elif terraform_required:
        console.print(
            "Soperator install infrastructure stage is already checkpointed complete; "
            "skipping Terraform plan replay."
        )
    else:
        console.print("No cxcli-managed Terraform infra is enabled; skipping Terraform apply.")
    write_inventory(config, paths, validations=report_validations)
    if skip_validations and deploy_declared_validations:
        if deploy_validations:
            console.print(
                "Skipping optional deploy-time validations for this run "
                "(--skip-validations); required validations still run."
            )
        else:
            console.print(
                "Skipping optional deploy-time validations for this run (--skip-validations)."
            )
    elif skip_validation_kinds:
        skipped_labels = _deploy_validation_skip_labels(skip_validation_kinds)
        if skipped_labels:
            console.print(
                "Skipping optional deploy-time validations for this run: "
                + ", ".join(skipped_labels)
            )
    if manifest_targets and not selected_targets:
        console.print(
            f"{warning_markup('WARNING:', bold=True)} "
            f"{_multi_cluster_handoff_skip_note(manifest_targets)}"
        )
    validation_error: Exception | None = None
    grafana_statuses: list[dict[str, Any]] = []
    if selected_targets:
        persist_local_kubeconfig = True
        set_current_context = len(selected_targets) == 1 and not all_targets
        for target in selected_targets:
            target_ref = str(target["target_ref"])
            target_paths = _paths_for_target_flux_dir(paths, target)
            target_has_apps = _active_chart_count_for_target(config, target_ref=target_ref) > 0
            target_validations = _filter_validations_for_target(
                deploy_validations,
                target_ref=target_ref,
            )
            pre_app_validations = (
                _pre_app_cluster_smoke_validations(target_validations) if target_has_apps else []
            )
            pre_soperator_validations = _pre_soperator_gpu_validations(
                config,
                target=target,
                validations=[
                    item for item in target_validations if item not in pre_app_validations
                ],
            )
            post_soperator_validations = [
                item
                for item in target_validations
                if item not in pre_app_validations and item not in pre_soperator_validations
            ]
            post_soperator_validations = _ordered_post_soperator_validations(
                config,
                target_ref=target_ref,
                validations=post_soperator_validations,
            )
            needs_cluster_ready = target_has_apps or bool(target_validations)
            if len(selected_targets) > 1:
                console.print(f"[bold]Target {target_ref}[/bold]")
            with ExitStack() as stack:
                kube_env = _prepare_cluster_handoff_kube_env(
                    config,
                    paths,
                    stack=stack,
                    target=target,
                    persist_local_kubeconfig=persist_local_kubeconfig,
                    set_current_context=set_current_context,
                )
                install_cluster_lease: SoperatorOperationLease | None = None
                install_anchor_name = ""
                install_kube_context = ""
                if soperator_install_lease is not None:
                    if kube_env is None:
                        raise RuntimeError(
                            "Soperator install could not establish target Kubernetes handoff"
                        )
                    cluster_id = _non_empty_text(kube_env.get(GRAFANA_TARGET_CLUSTER_ID_ENV))
                    install_kube_context = _non_empty_text(
                        kube_env.get(GRAFANA_TARGET_KUBE_CONTEXT_ENV)
                    )
                    if not cluster_id or not install_kube_context:
                        raise RuntimeError(
                            "Soperator install handoff omitted the immutable cluster id or context"
                        )
                    kubernetes_uid = _read_kube_system_namespace_uid(
                        kube_context=install_kube_context,
                        extra_env=kube_env,
                    )
                    if not kubernetes_uid:
                        raise RuntimeError(
                            "Soperator install could not read the kube-system namespace UID"
                        )
                    soperator_install_lease.bind_cluster_identity(
                        cluster_id=cluster_id,
                        kubernetes_uid=kubernetes_uid,
                    )
                    soperator_install_lease.assert_held()
                    install_cluster_lease = stack.enter_context(
                        SoperatorOperationLease(
                            kube_context=install_kube_context,
                            cluster_id=cluster_id,
                            operation_fingerprint=soperator_install_lease.operation_id,
                            extra_env=kube_env,
                        )
                    )
                    install_cluster_lease.assert_held()
                    install_anchor_name = _apply_soperator_install_operation_anchor(
                        extra_env=kube_env,
                        kube_context=install_kube_context,
                        cluster_id=cluster_id,
                        kubernetes_uid=kubernetes_uid,
                        operation_id=soperator_install_lease.operation_id,
                        approval_fingerprint=soperator_install_approval_fingerprint,
                    )

                def _assert_soperator_authority(
                    _cluster_lease: SoperatorOperationLease | None = (install_cluster_lease),
                    _remote_lease: SoperatorInstallRemoteLease | None = (soperator_install_lease),
                ) -> SoperatorLeaseAuthority:
                    if _cluster_lease is None or _remote_lease is None:
                        raise RuntimeError(
                            "Soperator in-cluster mutation is available only through "
                            "`nebius-cxcli soperator install` or `soperator upgrade`"
                        )
                    _remote_lease.assert_held()
                    return _cluster_lease.assert_held()

                if target_has_apps:
                    _reconcile_observability_gpu_node_labels(
                        config,
                        extra_env=kube_env,
                        target_ref=target_ref,
                    )
                    _ensure_mysterybox_eso_runtime_before_flux(
                        config,
                        extra_env=kube_env,
                        target_ref=target_ref,
                    )
                    _ensure_grafana_runtime_before_flux(
                        config,
                        extra_env=kube_env,
                        target_ref=target_ref,
                    )
                    _ensure_soperator_notifier_runtime_before_flux(
                        config,
                        extra_env=kube_env,
                        target_ref=target_ref,
                        externally_managed_secret_keys=_mysterybox_eso_rendered_secret_keys(
                            target_paths
                        ),
                    )
                    _ensure_soperator_backup_runtime_before_flux(
                        config,
                        extra_env=kube_env,
                        target_ref=target_ref,
                    )
                if needs_cluster_ready:
                    _report_cluster_nodes_status(
                        extra_env=kube_env, emit=lambda message: console.print(message)
                    )
                if target_has_apps and pre_app_validations:
                    try:
                        _run_target_deploy_validations(
                            pre_app_validations,
                            target_ref=target_ref,
                            reports_dir=paths.reports_dir,
                            extra_env=kube_env,
                        )
                    except Exception as exc:
                        validation_error = exc
                        break
                if target_has_apps:
                    if pre_soperator_validations:
                        console.print(
                            "Applying platform Flux resources before Soperator GPU validations "
                            f"for target {target_ref}..."
                        )
                        with _staged_flux_without_soperator(
                            target_paths,
                            config=config,
                            target_ref=target_ref,
                        ) as staged_target_paths:
                            _apply_rendered_flux(staged_target_paths, extra_env=kube_env)
                        try:
                            _run_target_deploy_validations(
                                pre_soperator_validations,
                                target_ref=target_ref,
                                reports_dir=paths.reports_dir,
                                extra_env=kube_env,
                            )
                        except Exception as exc:
                            validation_error = exc
                            break
                    _apply_rendered_flux_with_soperator_job_policy(
                        config,
                        target_paths,
                        command_name="deploy",
                        target_ref=target_ref,
                        extra_env=kube_env,
                        job_policy=job_policy,
                        cancel_job_ids=cancel_job_ids,
                        requeue_job_ids=requeue_job_ids,
                        job_wait_timeout_seconds=job_wait_timeout_seconds,
                        job_refresh_interval_seconds=job_refresh_interval_seconds,
                        infrastructure_plan_sha256=soperator_infrastructure_plan_sha256,
                        assert_authority=_assert_soperator_authority,
                        operation_started_at=soperator_operation_started_at,
                    )
                    _ensure_soperator_gpu_ephemeral_bootstrap_power_state(
                        config,
                        target_ref=target_ref,
                        extra_env=kube_env,
                    )
                    grafana_statuses.extend(
                        _collect_grafana_status_after_flux(
                            config,
                            extra_env=kube_env,
                            target_ref=target_ref,
                        )
                    )
                    bootstrap_command = _warn_if_flux_gitops_not_bootstrapped(
                        config,
                        target_paths,
                        extra_env=kube_env,
                        target_ref=target_ref,
                        print_command=False,
                    )
                    if bootstrap_command:
                        gitops_bootstrap_commands.append(bootstrap_command)
                if post_soperator_validations:
                    try:
                        _run_target_deploy_validations(
                            post_soperator_validations,
                            target_ref=target_ref,
                            reports_dir=paths.reports_dir,
                            extra_env=kube_env,
                        )
                    except Exception as exc:
                        validation_error = exc
                        break
                if install_cluster_lease is not None:
                    install_cluster_lease.assert_held()
                    soperator_install_lease.assert_held()
                    _complete_soperator_install_operation_anchor(
                        extra_env=kube_env or {},
                        kube_context=install_kube_context,
                        name=install_anchor_name,
                        operation_id=soperator_install_lease.operation_id,
                    )
            if validation_error is not None:
                break
    elif has_enabled_app_charts or deploy_validations:
        _report_cluster_nodes_status(extra_env=None, emit=lambda message: console.print(message))
        if has_enabled_app_charts:
            _ensure_mysterybox_eso_runtime_before_flux(
                config,
                extra_env=None,
            )
            _ensure_grafana_runtime_before_flux(config, extra_env=None)
            _ensure_soperator_notifier_runtime_before_flux(
                config,
                extra_env=None,
                externally_managed_secret_keys=_mysterybox_eso_rendered_secret_keys(paths),
            )
            _ensure_soperator_backup_runtime_before_flux(config, extra_env=None)
            _apply_rendered_flux_with_soperator_job_policy(
                config,
                paths,
                command_name="deploy",
                target_ref="",
                extra_env=None,
                job_policy=job_policy,
                cancel_job_ids=cancel_job_ids,
                requeue_job_ids=requeue_job_ids,
                job_wait_timeout_seconds=job_wait_timeout_seconds,
                job_refresh_interval_seconds=job_refresh_interval_seconds,
            )
            grafana_statuses.extend(_collect_grafana_status_after_flux(config, extra_env=None))
            bootstrap_command = _warn_if_flux_gitops_not_bootstrapped(
                config,
                paths,
                extra_env=None,
                print_command=False,
            )
            if bootstrap_command:
                gitops_bootstrap_commands.append(bootstrap_command)
        if deploy_validations:
            with console.status(
                "[cyan]Running deploy-time validations...[/cyan]",
                spinner="dots",
            ) as status:
                last_validation_phase = ""

                def _emit_validation_phase(message: str) -> None:
                    nonlocal last_validation_phase
                    status.update(message)
                    if not _console_is_terminal() and message != last_validation_phase:
                        console.print(message)
                    last_validation_phase = message

                try:
                    _run_deploy_validations(
                        deploy_validations,
                        reports_dir=paths.reports_dir,
                        extra_env=None,
                        emit=_emit_validation_phase,
                    )
                except Exception as exc:
                    validation_error = exc
    if grafana_statuses:
        write_grafana_status(
            paths,
            grafana_statuses,
            preserve_existing=bool(
                manifest_targets
                and selected_targets
                and len(selected_targets) < len(manifest_targets)
            ),
        )
    validation_report: DeployValidationReport | None = None
    if grafana_statuses or report_validations:
        artifacts = write_inventory(config, paths, validations=report_validations)
    else:
        artifacts = None
    if report_validations and artifacts is not None:
        validation_report = build_deploy_validation_report(
            report_validations,
            reports_dir=paths.reports_dir,
            markdown_path=artifacts.markdown,
        )
    if validation_error is not None:
        _print_deploy_command_footer(
            config,
            paths,
            DeployRunSummary(
                validation_report=validation_report,
                gitops_bootstrap_commands=tuple(gitops_bootstrap_commands),
            ),
            succeeded=False,
        )
        raise validation_error
    return DeployRunSummary(
        validation_report=validation_report,
        gitops_bootstrap_commands=tuple(gitops_bootstrap_commands),
    )


def _print_deploy_command_footer(
    config: Any,
    paths: ProjectPaths,
    summary: DeployRunSummary | None,
    *,
    succeeded: bool,
) -> None:
    summary = summary or DeployRunSummary()
    console.print("")
    console.print("[bold]Deployment summary[/bold]")
    console.print("[bright_magenta]Validation:[/bright_magenta]")
    for line in _deploy_footer_validation_lines(summary.validation_report):
        console.print(line)
    console.print("[bright_magenta]Copy/paste commands:[/bright_magenta]")
    for line in _deploy_footer_command_lines(config, paths, summary):
        if _deploy_footer_line_is_command(line):
            _print_copy_paste_command(line)
        else:
            console.print(line, soft_wrap=True)
    console.print("[bright_magenta]Important paths:[/bright_magenta]")
    for line in _deploy_footer_path_lines(paths, summary):
        console.print(line, soft_wrap=True)
    status_markup = "[green]Deploy completed[/green]" if succeeded else "[red]Deploy failed[/red]"
    console.print(status_markup)


def _deploy_footer_validation_lines(report: DeployValidationReport | None) -> list[str]:
    if report is None:
        return ["  No deploy-time validations were configured for this run."]
    lines = [
        (
            "  Overall: "
            f"{_deploy_footer_status_markup(report.overall_status)} "
            f"({report.completed_count}/{report.total_count} completed, "
            f"{report.not_run_count} not run)"
        )
    ]
    grouped_results: dict[str, list[Any]] = {}
    for item in report.results:
        grouped_results.setdefault(item.target_ref, []).append(item)
    show_target_groups = len(grouped_results) > 1 or any(grouped_results)
    for target_ref, items in grouped_results.items():
        indent = "  "
        if show_target_groups:
            target_label = target_ref or "unscoped"
            lines.append(f"  {escape(target_label)}:")
            indent = "    "
        for item in items:
            name = _deploy_footer_validation_name(item.name, item.target_ref)
            summary = item.footer_summary or item.summary
            lines.append(
                f"{indent}{_deploy_footer_status_markup(item.status)} "
                f"{escape(name)}: {escape(summary)}"
            )
    return lines


def _deploy_footer_status_markup(status: str) -> str:
    label = status_label(status)
    if status == "passed":
        return f"[green]{label}[/green]"
    if status == "failed":
        return f"[red]{label}[/red]"
    return label


def _deploy_footer_validation_name(name: str, target_ref: str) -> str:
    label = str(name or "").strip()
    target = str(target_ref or "").strip()
    if target:
        suffix = f" ({target})"
        if label.endswith(suffix):
            label = label[: -len(suffix)].rstrip()
    return label or "Validation"


def _deploy_footer_command_lines(
    config: Any,
    paths: ProjectPaths,
    summary: DeployRunSummary,
) -> list[str]:
    lines: list[str] = []
    for hint in wireguard_access_command_hints(config, paths):
        lines.extend([f"# {hint['label']}", hint["command"]])
    for hint in ssh_jump_access_hints(config, paths):
        lines.extend(
            [
                f"# SSH {hint['target_label']} via {hint['jump_host_label']}",
                hint["command"],
            ]
        )
    for command in _unique_texts(summary.gitops_bootstrap_commands):
        lines.extend(["# Enable GitOps sync", command])
    if not lines:
        lines.append("No immediate access or follow-up commands were derived.")
    return lines


def _deploy_footer_line_is_command(line: str) -> bool:
    text = str(line or "").strip()
    return bool(
        text
        and not text.startswith("#")
        and text != "No immediate access or follow-up commands were derived."
    )


def _deploy_footer_path_lines(paths: ProjectPaths, summary: DeployRunSummary) -> list[str]:
    return [
        f"  Generated bundle: {paths.generated_dir}",
        f"  Validation detail reports: {paths.reports_dir}",
        f"  Deploy report: {paths.reports_dir / DEPLOY_REPORT_FILENAME}",
    ]


def _unique_texts(values: Sequence[str]) -> tuple[str, ...]:
    seen: set[str] = set()
    result: list[str] = []
    for value in values:
        text = str(value).strip()
        if not text or text in seen:
            continue
        seen.add(text)
        result.append(text)
    return tuple(result)


def _validate_rendered_flux_manifests(
    paths: ProjectPaths,
    *,
    command_name: str,
    manifest: Mapping[str, Any] | None = None,
    target_ref: str = "",
) -> None:
    if not shutil.which("kubectl"):
        raise RuntimeError(f"kubectl is required for `{command_name}` but was not found in PATH")
    target_paths = (
        [_paths_for_target_flux_dir(paths, {"target_ref": target_ref})]
        if target_ref
        else [
            _paths_for_target_flux_dir(paths, target)
            for target in _manifest_deploy_targets(manifest or {})
        ]
        or [paths]
    )
    for target_path in target_paths:
        try:
            subprocess.run(
                ["kubectl", "kustomize", str(target_path.flux_dir)],
                check=True,
                capture_output=True,
                text=True,
                timeout=60,
            )
        except subprocess.CalledProcessError as exc:
            detail = _first_non_empty_line(exc.stderr or exc.stdout or "")
            raise RuntimeError(detail or str(exc)) from exc


def _run_deploy_preflight(
    config: Any,
    paths: ProjectPaths,
    *,
    manifest: Mapping[str, Any] | None = None,
) -> dict[str, str]:
    return _run_generated_bundle_validation(
        config,
        paths,
        title="Deploy preflight",
        quota_phase="deploy",
        flux_command_name="deploy",
        manifest=manifest,
        prompt_mysterybox_payload_values=_console_is_terminal(),
    )


def _run_generated_bundle_validation(
    config: Any,
    paths: ProjectPaths,
    *,
    title: str,
    quota_phase: str,
    flux_command_name: str,
    portable: bool = False,
    manifest: Mapping[str, Any] | None = None,
    prompt_mysterybox_payload_values: bool = False,
) -> dict[str, str]:
    mysterybox_payload_requirements = _mysterybox_runtime_payload_requirements(config)
    mysterybox_payload_env: dict[str, str] = {}
    if mysterybox_payload_requirements and prompt_mysterybox_payload_values:
        console.print(
            "MysteryBox payload values are required for first deploy. "
            "Input is hidden and used only for this Terraform run."
        )
        mysterybox_payload_env = _collect_mysterybox_runtime_payload_values(
            config,
            prompt=True,
        )
    phase_defs = [
        _ValidationPhase("strict-readiness", "Validate strict deployment readiness"),
    ]
    terraform_required = _config_has_enabled_infra_components(config) or bool(
        _required_runtime_component_output_specs(config)
    )
    if mysterybox_payload_requirements:
        phase_defs.append(
            _ValidationPhase(
                "mysterybox-payload-values",
                "Validate MysteryBox runtime payload values",
            )
        )
    phase_defs.append(_ValidationPhase("vpc-preflight", "Validate VPC networking preflight"))
    if has_mk8s_gpu_stack_compatibility_preflight_targets(config):
        phase_defs.append(
            _ValidationPhase("mk8s-gpu-stack", "Validate MK8s GPU stack compatibility")
        )
    if terraform_required:
        phase_defs.extend(
            [
                _ValidationPhase("backend", "Prepare Terraform backend auth"),
                _ValidationPhase("quota-readiness", "Validate live Nebius quota/capacity"),
                _ValidationPhase("terraform", "Validate generated Terraform bundle"),
            ]
        )
    active_chart_count = _active_chart_count(config)
    if active_chart_count > 0:
        phase_defs.append(_ValidationPhase("flux", "Validate rendered Flux manifests"))
    if portable:
        phase_defs.append(_ValidationPhase("portable", "Validate generated bundle portability"))

    with _ValidationProgress(title=title, phases=phase_defs) as progress:
        if not paths.infra_dir.exists():
            raise RuntimeError(f"Rendered infra directory does not exist: {paths.infra_dir}")
        progress.run(
            "strict-readiness",
            lambda: _validate_strict_config(config, include_common_checks=False),
        )
        if mysterybox_payload_requirements:

            def _prepare_mysterybox_payload_values() -> None:
                nonlocal mysterybox_payload_env
                validation_env = os.environ.copy()
                validation_env.update(mysterybox_payload_env)
                if mysterybox_payload_env:
                    _validate_mysterybox_runtime_payload_values(
                        config,
                        environ=validation_env,
                    )
                    return
                mysterybox_payload_env = _collect_mysterybox_runtime_payload_values(config)

            progress.run(
                "mysterybox-payload-values",
                _prepare_mysterybox_payload_values,
            )
        progress.run("vpc-preflight", lambda: validate_vpc_networking_preflight(config))
        if has_mk8s_gpu_stack_compatibility_preflight_targets(config):
            progress.run(
                "mk8s-gpu-stack",
                lambda: validate_mk8s_gpu_stack_compatibility_preflight(config),
            )
        if terraform_required:
            progress.run(
                "backend",
                lambda: _ensure_terraform_backend_ready(config),
            )
            runtime_env = _terraform_runtime_env(config)
            progress.run(
                "quota-readiness",
                lambda: _raise_on_generated_bundle_live_quota_issues(
                    config,
                    paths,
                    manifest=manifest,
                    runtime_env=runtime_env,
                    phase=quota_phase,
                ),
            )

            def _validate_generated_terraform_bundle() -> None:
                _validate_generated_mk8s_resource_name_preflight(
                    config,
                    paths,
                    runtime_env=runtime_env,
                )
                terraform_validate(
                    paths.infra_dir,
                    extra_env=runtime_env,
                    initialize=False,
                )

            progress.run(
                "terraform",
                _validate_generated_terraform_bundle,
            )
        if active_chart_count > 0:
            progress.run(
                "flux",
                lambda: _validate_rendered_flux_manifests(
                    paths,
                    command_name=flux_command_name,
                    manifest=manifest,
                ),
            )
        if portable:
            progress.run(
                "portable",
                lambda: _validate_generated_bundle_portability(paths, manifest or {}),
            )

    _print_mk8s_gpu_validation_warnings(config)
    return mysterybox_payload_env


_TERRAFORM_STATE_NAME_RE = re.compile(r'^\s*name\s*=\s*"([^"]+)"\s*$', re.MULTILINE)


def _terraform_state_resource_name(state_show_text: str) -> str:
    match = _TERRAFORM_STATE_NAME_RE.search(state_show_text)
    return match.group(1).strip() if match is not None else ""


def _managed_mk8s_resource_names_from_terraform_state(
    *,
    paths: ProjectPaths,
    runtime_env: Mapping[str, str] | None,
) -> tuple[set[str], set[str]]:
    managed_mk8s_cluster_names: set[str] = set()
    managed_gpu_cluster_names: set[str] = set()
    for address in terraform_state_list(
        paths.infra_dir,
        extra_env=dict(runtime_env or {}),
        initialize=False,
    ):
        normalized_address = str(address).strip()
        if not normalized_address:
            continue
        if (
            ".nebius_mk8s_v1_cluster.this" not in normalized_address
            and ".nebius_compute_v1_gpu_cluster.this" not in normalized_address
        ):
            continue
        state_show_text = terraform_state_show(
            paths.infra_dir,
            normalized_address,
            extra_env=dict(runtime_env or {}),
            initialize=False,
        )
        resource_name = _terraform_state_resource_name(state_show_text)
        if not resource_name:
            continue
        if ".nebius_mk8s_v1_cluster.this" in normalized_address:
            managed_mk8s_cluster_names.add(resource_name)
        elif ".nebius_compute_v1_gpu_cluster.this" in normalized_address:
            managed_gpu_cluster_names.add(resource_name)
    return managed_mk8s_cluster_names, managed_gpu_cluster_names


def _validate_generated_mk8s_resource_name_preflight(
    config: Any,
    paths: ProjectPaths,
    *,
    runtime_env: Mapping[str, str] | None,
) -> None:
    if not has_mk8s_resource_name_preflight_targets(config):
        return
    managed_mk8s_cluster_names, managed_gpu_cluster_names = (
        _managed_mk8s_resource_names_from_terraform_state(
            paths=paths,
            runtime_env=runtime_env,
        )
    )
    validate_mk8s_resource_name_preflight(
        config,
        managed_mk8s_cluster_names=managed_mk8s_cluster_names,
        managed_gpu_cluster_names=managed_gpu_cluster_names,
    )


def _destroy_rendered_flux_bundle(
    config: Any,
    paths: ProjectPaths,
    manifest: Mapping[str, Any],
    *,
    requested_target_ref: str | None = None,
    all_targets: bool = False,
) -> None:
    if _active_chart_count(config) == 0:
        raise RuntimeError("No enabled apps charts are configured for this project.")
    manifest_targets = _manifest_deploy_targets(manifest)
    if manifest_targets:
        selected_targets = _resolve_selected_deploy_targets(
            manifest,
            requested_target_ref=requested_target_ref,
            all_targets=all_targets,
        )
        target_errors: list[tuple[str, Exception]] = []
        for target in selected_targets:
            target_ref = str(target["target_ref"])
            target_paths = _paths_for_target_flux_dir(paths, target)
            if len(selected_targets) > 1:
                console.print(f"[bold]Target {target_ref}[/bold]")
            try:
                with ExitStack() as stack:
                    kube_env = _prepare_cluster_handoff_kube_env(
                        config,
                        paths,
                        stack=stack,
                        target=target,
                        persist_local_kubeconfig=False,
                    )
                    _delete_post_flux_manifests(target_paths, env=kube_env)
                    delete_rendered_flux(target_paths, extra_env=kube_env, emit=console.print)
                    _delete_rendered_flux_namespaces(target_paths, env=kube_env)
            except Exception as exc:
                if len(selected_targets) == 1:
                    raise
                target_errors.append((target_ref, exc))
                console.print(
                    f"{warning_markup('WARNING:', bold=True)} "
                    f"Rendered app teardown failed for target {target_ref}; "
                    "continuing with remaining targets before reporting the error. "
                    f"Reason: {exc}"
                )
        if target_errors:
            details = "; ".join(f"{target_ref}: {exc}" for target_ref, exc in target_errors)
            raise RuntimeError(
                "Rendered app teardown failed for one or more deploy targets after "
                f"attempting all selected targets: {details}"
            )
        return
    _delete_post_flux_manifests(paths, env=os.environ.copy())
    delete_rendered_flux(paths, extra_env=None, emit=console.print)
    _delete_rendered_flux_namespaces(paths, env=os.environ.copy())


def _destroy_uses_cluster_teardown_for_apps(config: Any, manifest: Mapping[str, Any]) -> bool:
    targets = _manifest_deploy_targets(manifest)
    if _active_chart_count(config) == 0 or not targets:
        return False
    managed_targets = _manifest_managed_deploy_targets(manifest)
    return bool(managed_targets) and len(managed_targets) == len(targets)


def _manifest_has_external_deploy_targets(manifest: Mapping[str, Any]) -> bool:
    return any(
        str(target.get(DEPLOY_TARGET_OWNERSHIP_FIELD, "")).strip() == EXTERNAL_TARGET_OWNERSHIP
        for target in _manifest_deploy_targets(manifest)
    )


def _destroy_should_delete_rendered_flux_first(config: Any, manifest: Mapping[str, Any]) -> bool:
    _ = manifest
    return _active_chart_count(config) > 0


def _destroy_confirmation_text(
    config: Any,
    paths: ProjectPaths,
    manifest: Mapping[str, Any],
) -> tuple[str, str]:
    if _active_chart_count(config) == 0:
        return (
            "Continue and destroy all rendered infra resources for this project?",
            "Destroy will remove all rendered infra resources for this project by running "
            "Terraform destroy against the rendered infra bundle under "
            f"{paths.infra_dir}.",
        )
    if _destroy_uses_cluster_teardown_for_apps(config, manifest):
        return (
            "Continue and destroy all rendered app and infra resources for this project?",
            "Destroy will remove all rendered project resources represented by the generated "
            "manifest by deleting rendered app resources from the handed-off MK8s target first "
            "so Kubernetes finalizers and CSI cleanup can run, then running Terraform destroy "
            f"against the rendered infra bundle under {paths.infra_dir}. This generated bundle "
            "still destroys the handed-off MK8s cluster directly after app teardown.",
        )
    if _manifest_has_external_deploy_targets(manifest):
        return (
            "Continue and delete rendered app resources and destroy only cxcli-owned infra?",
            "Destroy will delete the rendered app resources from the external MK8s target first. "
            "The existing MK8s cluster and node groups are external to cxcli and will not be "
            f"destroyed. Any cxcli-managed infra under {paths.infra_dir} is still destroyed "
            "after app teardown.",
        )
    return (
        "Continue and destroy all rendered app and infra resources for this project?",
        "Destroy will remove all rendered project resources represented by the generated "
        "manifest by deleting the rendered app resources from the target cluster using "
        f"{paths.flux_dir} first and then running Terraform destroy against the rendered "
        f"infra bundle under {paths.infra_dir}.",
    )


def _destroy_generated_artifacts(
    config: Any,
    paths: ProjectPaths,
    manifest: Mapping[str, Any],
    *,
    yes: bool = False,
) -> None:
    terraform_required = _config_has_enabled_infra_components(config)
    if terraform_required:
        _ensure_terraform_backend_ready(config)
    if _destroy_should_delete_rendered_flux_first(config, manifest):
        try:
            _destroy_rendered_flux_bundle(config, paths, manifest, all_targets=True)
        except Exception as exc:
            if terraform_required:
                raise RuntimeError(
                    "Rendered app teardown failed before Terraform destroy; refusing to destroy "
                    "cxcli-managed infra while app resources, Kubernetes finalizers, or CSI "
                    f"cleanup may still need the target cluster. Reason: {exc}"
                ) from exc
            raise RuntimeError(
                "Rendered app teardown failed for an external MK8s target and there is no "
                "cxcli-managed Terraform cluster destroy fallback. App resources may still "
                f"be installed. Reason: {exc}"
            ) from exc
    status_watchers = _manifest_status_watchers(manifest) or _enabled_status_watcher_specs(config)
    if terraform_required:
        _run_terraform_destroy_with_recovery(
            config,
            paths,
            yes=yes,
            initialize=True,
            status_watchers=status_watchers or None,
        )
    else:
        console.print(
            "No cxcli-managed Terraform infra is enabled; skipping Terraform destroy. "
            "External MK8s cluster and node groups were not destroyed."
        )


def _run_terraform_apply_with_status(
    config: Any,
    paths: ProjectPaths,
    *,
    initialize: bool = True,
    status_watchers: list[dict[str, str]] | None = None,
    run_mk8s_preflight: bool = True,
    extra_env: Mapping[str, str] | None = None,
    manifest: Mapping[str, Any] | None = None,
    plan_file: Path | None = None,
    expected_plan_sha256: str | None = None,
) -> None:
    runtime_env = _terraform_runtime_env(config)
    if extra_env:
        runtime_env.update(dict(extra_env))
    validation_env = os.environ.copy()
    validation_env.update(runtime_env)
    _validate_mysterybox_runtime_payload_values(config, environ=validation_env)
    if run_mk8s_preflight:
        validate_vpc_networking_preflight(config)
        if has_mk8s_gpu_stack_compatibility_preflight_targets(config):
            validate_mk8s_gpu_stack_compatibility_preflight(config)
    _raise_on_terraform_gpu_fabric_drift(
        config,
        paths,
        manifest,
        runtime_env=runtime_env,
        initialize=initialize,
    )
    reporting_kwargs: dict[str, Any] = {
        "emit": _print_deployment_status_message,
    }
    if status_watchers:
        reporting_kwargs["status_watchers"] = status_watchers
    with deployment_status_reporting(config, **reporting_kwargs) as reporter:
        try:
            abort_check = reporter.abort_reason if hasattr(reporter, "abort_reason") else None
            apply_kwargs: dict[str, Any] = {
                "extra_env": runtime_env,
                "initialize": initialize,
                "event_callback": reporter.handle_terraform_event,
            }
            if abort_check is not None:
                apply_kwargs["abort_check"] = abort_check
            if plan_file is not None:
                apply_kwargs["plan_file"] = plan_file
            if expected_plan_sha256 is not None:
                apply_kwargs["expected_plan_sha256"] = expected_plan_sha256
            terraform_apply(
                paths.infra_dir,
                **apply_kwargs,
            )
        except RuntimeError as exc:
            raise RuntimeError(
                f"{exc}\n\nLast known deploy status:\n{reporter.snapshot()}"
            ) from exc


def _run_terraform_destroy_with_status(
    config: Any,
    paths: ProjectPaths,
    *,
    initialize: bool = True,
    status_watchers: list[dict[str, str]] | None = None,
) -> None:
    runtime_env = _terraform_runtime_env(config)
    reporting_kwargs: dict[str, Any] = {
        "emit": _print_deployment_status_message,
        "operation": "destroy",
    }
    if status_watchers:
        reporting_kwargs["status_watchers"] = status_watchers
    with deployment_status_reporting(config, **reporting_kwargs) as reporter:
        try:
            abort_check = reporter.abort_reason if hasattr(reporter, "abort_reason") else None
            destroy_kwargs: dict[str, Any] = {
                "extra_env": runtime_env,
                "initialize": initialize,
                "event_callback": reporter.handle_terraform_event,
            }
            if abort_check is not None:
                destroy_kwargs["abort_check"] = abort_check
            terraform_destroy(
                paths.infra_dir,
                **destroy_kwargs,
            )
        except RuntimeError as exc:
            raise RuntimeError(
                f"{exc}\n\nLast known destroy status:\n{reporter.snapshot()}"
            ) from exc


def _run_terraform_destroy_with_recovery(
    config: Any,
    paths: ProjectPaths,
    *,
    yes: bool,
    initialize: bool = True,
    status_watchers: list[dict[str, str]] | None = None,
) -> None:
    current_exc: RuntimeError | None = None
    try:
        _run_terraform_destroy_with_status(
            config,
            paths,
            initialize=initialize,
            status_watchers=status_watchers,
        )
        return
    except RuntimeError as exc:
        current_exc = exc

    if current_exc is not None and _is_terraform_state_lock_failure(current_exc):
        lock_info = _unlock_terraform_state_lock(
            config,
            paths,
            force=False,
        )
        if lock_info is not None:
            console.print(
                "Detected stale Terraform state lock during destroy; "
                f"cleared lock {lock_info.lock_id} owned by {lock_info.who or '(unknown)'} "
                "and retrying Terraform destroy."
            )
            try:
                _run_terraform_destroy_with_status(
                    config,
                    paths,
                    initialize=initialize,
                    status_watchers=status_watchers,
                )
                return
            except RuntimeError as exc:
                current_exc = exc

    try:
        recovered = _attempt_mk8s_node_group_destroy_recovery(
            status_watchers=status_watchers,
            yes=yes,
        )
    except Exception as recovery_exc:
        raise RuntimeError(
            f"{current_exc}\n\nBuilt-in destroy recovery could not remove the stuck MK8s node group: "
            f"{recovery_exc}"
        ) from current_exc
    if recovered:
        console.print("Retrying Terraform destroy after MK8s node-group cleanup.")
        _run_terraform_destroy_with_status(
            config,
            paths,
            initialize=initialize,
            status_watchers=status_watchers,
        )
        return

    if current_exc is None:
        raise RuntimeError("Terraform destroy recovery failed without a captured destroy error.")
    raise current_exc


def _warn_if_flux_gitops_not_bootstrapped(
    config: Any,
    paths: ProjectPaths,
    *,
    extra_env: dict[str, str] | None,
    target_ref: str | None = None,
    print_command: bool = True,
) -> str | None:
    if _active_chart_count(config) == 0:
        return None
    if not extra_env or not extra_env.get("KUBECONFIG"):
        return None
    if flux_bootstrap_resources_installed(extra_env=extra_env):
        return None
    command = f"nebius-cxcli flux bootstrap {shlex.quote(str(paths.generated_dir))}"
    if target_ref:
        command += f" --target {shlex.quote(target_ref)}"
    console.print(
        "[yellow]NOTE:[/yellow] Flux GitOps bootstrap is not configured for this cluster. "
        "Local direct apply succeeded; this is a supported operating mode when you do not want "
        "continuous GitOps sync."
    )
    if print_command:
        console.print(
            "If this cluster should continuously sync from Git, the command below takes the local "
            "generated bundle path; the GitHub repository is inferred from GITHUB_REPOSITORY or "
            f"the git origin under {paths.repo_root}."
        )
    else:
        console.print(
            "If this cluster should continuously sync from Git, the GitOps command in the final "
            "Deployment summary takes the local generated bundle path; the GitHub repository is inferred "
            f"from GITHUB_REPOSITORY or the git origin under {paths.repo_root}."
        )
    console.print(
        "Commit and push the rendered generated/flux path before relying on continuous GitOps sync; "
        "skip this step when local direct apply is the intended workflow."
    )
    if print_command:
        console.print("Optional command to enable GitOps sync:")
        _print_copy_paste_command(command)
    return command


def _current_lock_owner_identity() -> str:
    user = getpass.getuser().strip() or "unknown"
    host = socket.gethostname().strip() or "unknown-host"
    return f"{user}@{host}"


def _active_local_terraform_processes() -> tuple[str, ...]:
    try:
        completed = subprocess.run(
            ["ps", "-axo", "pid=,command="],
            check=True,
            capture_output=True,
            text=True,
            timeout=5,
        )
    except Exception:
        return ()

    current_pid = os.getpid()
    process_pattern = re.compile(
        r"\b(terraform (apply|plan|force-unlock)|nebius-cxcli (deploy|terraform apply|terraform plan|terraform unlock))\b"
    )
    active: list[str] = []
    for raw_line in (completed.stdout or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        pid_text, _, command = line.partition(" ")
        try:
            pid = int(pid_text.strip())
        except ValueError:
            continue
        if pid == current_pid:
            continue
        normalized_command = command.strip()
        if not normalized_command:
            continue
        if process_pattern.search(normalized_command):
            active.append(normalized_command)
    return tuple(active)


def _unlock_terraform_state_lock(
    config: Any,
    paths: ProjectPaths,
    *,
    force: bool,
) -> TerraformStateLockInfo | None:
    if not paths.infra_dir.exists():
        raise RuntimeError(
            f"Rendered infra directory does not exist: {paths.infra_dir}. "
            "Rerun `nebius-cxcli render <config.yaml>` first."
        )
    _ensure_terraform_backend_ready(config)
    runtime_env = _terraform_runtime_env(config)
    settings = backend_settings_from_config(config)
    lock_info = read_state_lock_info(settings, extra_env=runtime_env)
    if lock_info is None:
        return None

    if not force:
        active_processes = _active_local_terraform_processes()
        if active_processes:
            rendered_processes = "\n".join(f"  - {command}" for command in active_processes)
            raise RuntimeError(
                "Refusing to unlock Terraform state while local Terraform/deploy operations appear active:\n"
                f"{rendered_processes}\n"
                "Wait for those commands to finish, or rerun `terraform unlock --force` only after you have confirmed the lock is stale."
            )
        current_owner = _current_lock_owner_identity()
        if not lock_info.who:
            raise RuntimeError(
                "Refusing to unlock Terraform state lock with no owner metadata. "
                "Rerun with `terraform unlock --force` only after you have confirmed that operation is no longer running."
            )
        if lock_info.who != current_owner:
            raise RuntimeError(
                "Refusing to unlock Terraform state lock owned by "
                f"`{lock_info.who}` from current identity `{current_owner}`. "
                "Rerun with `terraform unlock --force` only after you have confirmed that operation is no longer running."
            )

    terraform_force_unlock(paths.infra_dir, lock_info.lock_id, extra_env=runtime_env)
    return lock_info


def _is_terraform_state_lock_failure(exc: Exception) -> bool:
    text = str(exc)
    return (
        "Terraform never acquired the remote state lock" in text
        or "Error acquiring the state lock" in text
    )


def _mk8s_destroy_recovery_targets(
    status_watchers: Sequence[Mapping[str, Any]] | None,
) -> tuple[tuple[str, str], ...]:
    if not status_watchers:
        return ()
    targets: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for watcher in status_watchers:
        kind = str(watcher.get("kind", "")).strip().lower()
        parent_id = str(watcher.get("parent_id", "")).strip()
        resource_name = str(watcher.get("resource_name", "")).strip()
        if kind != "nebius.mk8s.cluster" or not parent_id or not resource_name:
            continue
        target = (parent_id, resource_name)
        if target in seen:
            continue
        seen.add(target)
        targets.append(target)
    return tuple(targets)


def _confirm_mk8s_destroy_recovery_cleanup(
    *,
    yes: bool,
    candidates: Sequence[Mk8sNodeGroupDestroyCandidate],
) -> bool:
    summary = ", ".join(
        f"{candidate.cluster_name}/{candidate.node_group_name}" for candidate in candidates[:3]
    )
    if len(candidates) > 3:
        summary += f", +{len(candidates) - 3} more"
    console.print(
        f"{warning_markup('WARNING:', bold=True)} "
        "Terraform destroy still appears blocked by stuck MK8s node-group create operations: "
        f"{summary}."
    )
    if yes:
        return True
    if not _can_prompt_for_render_overwrite():
        raise RuntimeError(
            "Destroy recovery wants to delete stuck MK8s node groups directly via the Nebius API "
            "before retrying Terraform destroy. Re-run with `--yes` to confirm."
        )
    return _confirm_explicit_action(
        "Delete the stuck MK8s node groups directly via the Nebius API and retry Terraform destroy?"
    )


def _attempt_mk8s_node_group_destroy_recovery(
    *,
    status_watchers: Sequence[Mapping[str, Any]] | None,
    yes: bool,
) -> bool:
    candidates: list[Mk8sNodeGroupDestroyCandidate] = []
    for project_id, cluster_name in _mk8s_destroy_recovery_targets(status_watchers):
        candidates.extend(
            find_stuck_mk8s_node_groups(project_id=project_id, cluster_name=cluster_name)
        )
    if not candidates:
        return False
    if not _confirm_mk8s_destroy_recovery_cleanup(yes=yes, candidates=candidates):
        return False
    for candidate in candidates:
        console.print(
            "Deleting stuck MK8s node group "
            f"{candidate.node_group_name} ({candidate.node_group_id}) from cluster "
            f"{candidate.cluster_name} because the live API still shows an unfinished create "
            f"operation {candidate.create_operation_id}. Reason: {candidate.reason}"
        )
        operation_id = delete_stuck_mk8s_node_group(candidate)
        console.print(
            "Deleted stuck MK8s node group "
            f"{candidate.node_group_name} ({candidate.node_group_id}); "
            f"delete operation {operation_id} completed."
        )
    return True


def _resolve_project_id_for_auth_bootstrap(
    *, project_id: str | None, project_config: Path | None
) -> str:
    if project_id:
        return project_id
    if project_config is None:
        raise RuntimeError("Missing required option: --project-id (or provide --project-config)")
    config = load_config(project_config.resolve())
    return config.client_info.nebius.project_id


def _resolve_client_name_for_auth_bootstrap(
    *,
    client_name: str | None,
    project_config: Path | None,
) -> str:
    if client_name:
        normalized = client_name.strip()
        if normalized:
            return normalized
    if project_config is None:
        raise RuntimeError("Missing required option: --client-name (or provide --project-config)")
    config = load_config(project_config.resolve())
    return str(config.client_info.client_name).strip()


def _github_environment_name_for_identity(*, client_name: str, project_id: str) -> str:
    try:
        return build_github_environment_name(client_name=client_name, project_id=project_id)
    except ValueError as exc:
        raise RuntimeError(str(exc)) from exc


def _resolve_github_repo_slug(
    *,
    explicit_repo_slug: str | None,
    repo_root: Path | None,
) -> str:
    if explicit_repo_slug:
        slug = explicit_repo_slug.strip()
        if "/" not in slug:
            raise RuntimeError("--github-repo must be in '<owner>/<repo>' format")
        return slug
    if repo_root is None:
        raise RuntimeError("GitHub repo could not be resolved; provide --github-repo owner/repo")
    return detect_github_repo_slug(repo_root)


def _resolve_bootstrap_ci_github_target(
    *,
    github_repo: str | None,
    github_token_env: str,
    repo_root: Path,
) -> tuple[str, str]:
    repo_slug = _resolve_github_repo_slug(explicit_repo_slug=github_repo, repo_root=repo_root)
    github_token = read_github_token(preferred_env=github_token_env)
    if github_token:
        return repo_slug, github_token
    raise RuntimeError(
        "GitHub bootstrap reconciliation requires a GitHub token. "
        f"No token found in ${github_token_env}, $GH_TOKEN, or $GITHUB_TOKEN."
    )


def _sync_github_ci_secrets(
    *,
    repo_slug: str,
    github_environment: str,
    github_token: str,
    ci_secrets: dict[str, str],
) -> list[str]:
    payload = dict(ci_secrets)
    payload[FLUX_SECRET_KEY] = github_token
    return upsert_environment_secrets(
        repo_slug=repo_slug,
        token=github_token,
        environment_name=github_environment,
        secrets=payload,
    )


def _load_local_email_settings(*, config_path: Path | None = None) -> EmailSettings:
    return load_email_settings(explicit=config_path)


@dataclass(frozen=True)
class GitHubEmailSyncResult:
    updated_vars: list[str]
    updated_secrets: list[str]
    removed_vars: list[str]
    removed_secrets: list[str]


def _sync_github_email_settings(
    *,
    repo_slug: str,
    github_environment: str,
    github_token: str,
    settings: EmailSettings,
) -> GitHubEmailSyncResult:
    ensure_github_environment(
        repo_slug=repo_slug,
        token=github_token,
        environment_name=github_environment,
    )
    managed_vars = ("SMTP_HOST", "SMTP_PORT", "SMTP_STARTTLS", "SMTP_FROM")
    managed_secrets = ("SMTP_USERNAME", "SMTP_PASSWORD")
    desired_vars = email_environment_variables(settings) if settings.enabled else {}
    desired_secrets = email_secret_values(settings) if settings.enabled else {}
    updated_vars = (
        upsert_environment_variables(
            repo_slug=repo_slug,
            token=github_token,
            environment_name=github_environment,
            variables=desired_vars,
        )
        if desired_vars
        else []
    )
    updated_secrets = (
        upsert_environment_secrets(
            repo_slug=repo_slug,
            token=github_token,
            environment_name=github_environment,
            secrets=desired_secrets,
        )
        if desired_secrets
        else []
    )
    removed_vars = [
        name
        for name in managed_vars
        if name not in desired_vars
        and delete_environment_variable(
            repo_slug=repo_slug,
            token=github_token,
            environment_name=github_environment,
            variable_name=name,
        )
    ]
    removed_secrets = [
        name
        for name in managed_secrets
        if name not in desired_secrets
        and delete_environment_secret(
            repo_slug=repo_slug,
            token=github_token,
            environment_name=github_environment,
            secret_name=name,
        )
    ]
    return GitHubEmailSyncResult(
        updated_vars=updated_vars,
        updated_secrets=updated_secrets,
        removed_vars=removed_vars,
        removed_secrets=removed_secrets,
    )


def _sync_runtime_auth_profile_to_ci_environment(
    *,
    material: RuntimeAuthCacheMaterial,
    client_name: str,
    github_repo: str | None,
    github_token_env: str,
    repo_root_hint: Path | None,
) -> tuple[str, str, list[str]]:
    github_token = read_github_token(preferred_env=github_token_env)
    if not github_token:
        raise RuntimeError(
            "GitHub sync requires a token. "
            f"No token found in ${github_token_env}, $GH_TOKEN, or $GITHUB_TOKEN."
        )

    repo_slug = _resolve_github_repo_slug(
        explicit_repo_slug=github_repo,
        repo_root=repo_root_hint,
    )
    github_environment = _github_environment_name_for_identity(
        client_name=client_name,
        project_id=material.project_id,
    )
    ensure_github_environment(
        repo_slug=repo_slug,
        token=github_token,
        environment_name=github_environment,
    )

    ci_secrets: dict[str, str] = {
        _RUNTIME_AUTH_ACTIVE_PROJECT_ENV: material.project_id,
        "NEBIUS_SA_ID": material.service_account_id,
        "NEBIUS_AUTH_PUBLIC_KEY_ID": material.auth_public_key_id,
        "NEBIUS_AUTH_PRIVATE_KEY_PEM": material.private_key_pem,
    }
    if material.s3_access_key_id:
        ci_secrets["NEBIUS_S3_ACCESS_KEY_ID"] = material.s3_access_key_id
    if material.s3_secret_access_key:
        ci_secrets["NEBIUS_S3_SECRET_ACCESS_KEY"] = material.s3_secret_access_key

    updated = _sync_github_ci_secrets(
        repo_slug=repo_slug,
        github_environment=github_environment,
        github_token=github_token,
        ci_secrets=ci_secrets,
    )
    return repo_slug, github_environment, updated


@dataclass(frozen=True)
class BootstrapResult:
    deployments_root: Path
    project_path: Path
    config_path: Path
    wrote_config: bool

    @staticmethod
    def normalized_config_yaml(
        *,
        config_path: Path,
        config_yaml: str,
        selected_infra: set[str],
        selected_apps: set[str],
        infra_entries: tuple[ComponentEntry, ...],
        app_entries: tuple[ComponentEntry, ...],
    ) -> str:
        parsed_config = yaml.safe_load(config_yaml) or {}
        if not isinstance(parsed_config, dict):
            raise RuntimeError("Generated config template must be a mapping")
        payload = _filter_runtime_payload_for_selected_components(
            payload=parsed_config,
            selected_infra=selected_infra,
            selected_apps=selected_apps,
            infra_entries=infra_entries,
            app_entries=app_entries,
        )
        normalize_runtime_config_payload(payload, base_dir=config_path.parent)
        return yaml.safe_dump(payload, sort_keys=False)


@dataclass(frozen=True)
class SoperatorOnboardConfigTarget:
    config_path: Path
    bootstrap_result: BootstrapResult | None = None
    gitignore_result: DeploymentsGitignoreResult | None = None
    live_region_config_sha256: str = ""

    @property
    def region_from_live_cluster(self) -> bool:
        return bool(self.live_region_config_sha256)

    @staticmethod
    def bootstrap_marker_path(config_path: Path) -> Path:
        return config_path.parent / ".nebius-cxcli" / _SOPERATOR_ONBOARD_BOOTSTRAP_FILENAME

    @classmethod
    def write_bootstrap_marker(
        cls,
        config_path: Path,
        *,
        tenant_id: str,
        project_id: str,
        config_sha256: str,
    ) -> None:
        _write_owner_only_json(
            cls.bootstrap_marker_path(config_path),
            {
                "schema": _SOPERATOR_ONBOARD_BOOTSTRAP_SCHEMA,
                "config_sha256": config_sha256,
                "tenant_id": tenant_id,
                "project_id": project_id,
                "region_mode": "live-derived",
            },
        )

    @classmethod
    def pending_live_region_config_sha256(cls, config_path: Path) -> str:
        marker_path = cls.bootstrap_marker_path(config_path)
        if not marker_path.exists():
            return ""
        try:
            raw = read_owner_only_json(
                marker_path,
                label="Soperator onboarding bootstrap marker",
            )
            with config_path.open("r", encoding="utf-8") as handle:
                payload = yaml.safe_load(handle) or {}
            if not isinstance(payload, Mapping):
                return ""
            _, tenant_id, project_id, _, _ = _identity_values_from_payload(payload)
        except (OSError, RuntimeError, ValueError, yaml.YAMLError):
            return ""
        if not isinstance(raw, Mapping):
            return ""
        config_sha256 = _sha256_file(config_path)
        expected = {
            "schema": _SOPERATOR_ONBOARD_BOOTSTRAP_SCHEMA,
            "config_sha256": config_sha256,
            "tenant_id": tenant_id,
            "project_id": project_id,
            "region_mode": "live-derived",
        }
        return config_sha256 if raw == expected else ""

    @classmethod
    def assert_live_region_authority(
        cls,
        config_path: Path,
        *,
        expected_config_sha256: str,
    ) -> None:
        if cls.pending_live_region_config_sha256(config_path) != expected_config_sha256:
            raise RuntimeError(
                "Soperator onboarding config changed after its pending live-region scaffold "
                "was created. No region or registration was written; restart onboarding "
                "from the current config state."
            )


_SOPERATOR_ONBOARD_BOOTSTRAP_SCHEMA = "nebius-cxcli.soperator-onboard-bootstrap.v1"
_SOPERATOR_ONBOARD_BOOTSTRAP_FILENAME = "soperator-onboard-bootstrap.json"


@dataclass(frozen=True)
class DeploymentsGitignoreResult:
    path: Path | None
    wrote: bool
    repo_root: Path | None = None

    @property
    def inside_git_repo(self) -> bool:
        return self.repo_root is not None


_DEPLOYMENTS_GITIGNORE_BEGIN = "# >>> nebius-cxcli managed ignores >>>"
_DEPLOYMENTS_GITIGNORE_END = "# <<< nebius-cxcli managed ignores <<<"
_DEPLOYMENTS_GITIGNORE_LINES: tuple[str, ...] = (
    _DEPLOYMENTS_GITIGNORE_BEGIN,
    "# Managed by `nebius-cxcli`.",
    "# Keep config.yaml and generated/nebius-cxcli-manifest.json versioned in a private repo.",
    "# Ignore Terraform runtime files and tfvars duplicates recreated from the generated manifest.",
    "# Ignore downloaded WireGuard client configs because they contain private keys.",
    "# Ignore project-local SSH host trust because it contains customer host identity.",
    "# Ignore local cxcli operational checkpoints.",
    "*/*/.nebius-cxcli/",
    "*/*/wireguard-clients/",
    "*/*/generated/ssh_known_hosts",
    "*/*/generated/infra/.terraform/",
    "*/*/generated/infra/*.tfstate",
    "*/*/generated/infra/*.tfstate.*",
    "*/*/generated/infra/.terraform.tfstate.lock.info",
    "*/*/generated/infra/crash.log",
    "*/*/generated/infra/crash.*.log",
    "*/*/generated/infra/*.tfplan",
    "*/*/generated/infra/plan.out",
    "*/*/generated/infra/terraform.auto.tfvars.json",
    "*/*/generated/infra/*.auto.tfvars",
    "*/*/generated/infra/*.auto.tfvars.json",
    _DEPLOYMENTS_GITIGNORE_END,
)


def _render_deployments_gitignore_block() -> str:
    return "\n".join(_DEPLOYMENTS_GITIGNORE_LINES) + "\n"


def _gitignore_has_managed_deployments_block(path: Path) -> bool:
    if not path.exists():
        return False
    content = path.read_text(encoding="utf-8")
    return _DEPLOYMENTS_GITIGNORE_BEGIN in content and _DEPLOYMENTS_GITIGNORE_END in content


def _parent_managed_deployments_gitignore(
    deployments_root: Path,
    *,
    repo_root: Path | None = None,
) -> Path | None:
    repo_root = repo_root or _try_git_root(deployments_root)
    if repo_root is None:
        return None

    resolved_root = deployments_root.resolve()
    for parent in resolved_root.parents:
        try:
            parent.relative_to(repo_root)
        except ValueError:
            break
        gitignore_path = parent / ".gitignore"
        if _gitignore_has_managed_deployments_block(gitignore_path):
            return gitignore_path
        if parent == repo_root:
            break
    return None


def _assert_not_nested_deployments_root(
    deployments_root: Path,
    *,
    repo_root: Path | None = None,
) -> None:
    parent_gitignore = _parent_managed_deployments_gitignore(
        deployments_root,
        repo_root=repo_root,
    )
    if parent_gitignore is None:
        return
    parent_root = parent_gitignore.parent
    raise RuntimeError(
        f"Deployments root '{deployments_root}' is nested under existing cxcli-managed "
        f"deployments root '{parent_root}'. Use '{parent_root}' as the deployments root, "
        "or choose a separate directory outside that root."
    )


def _ensure_deployments_gitignore(
    *,
    deployments_root: Path,
) -> DeploymentsGitignoreResult:
    repo_root = _try_git_root(deployments_root)
    if repo_root is None:
        return DeploymentsGitignoreResult(path=None, wrote=False)

    _assert_not_nested_deployments_root(deployments_root, repo_root=repo_root)
    gitignore_path = deployments_root / ".gitignore"
    block = _render_deployments_gitignore_block()
    existing = gitignore_path.read_text(encoding="utf-8") if gitignore_path.exists() else ""

    if _DEPLOYMENTS_GITIGNORE_BEGIN in existing and _DEPLOYMENTS_GITIGNORE_END in existing:
        pattern = (
            re.escape(_DEPLOYMENTS_GITIGNORE_BEGIN)
            + r".*?"
            + re.escape(_DEPLOYMENTS_GITIGNORE_END)
            + r"\n?"
        )
        updated = re.sub(pattern, block, existing, count=1, flags=re.S)
    else:
        prefix = existing.rstrip("\n")
        updated = f"{prefix}\n\n{block}" if prefix else block

    if updated != existing:
        gitignore_path.write_text(updated, encoding="utf-8")
        return DeploymentsGitignoreResult(
            path=gitignore_path,
            wrote=True,
            repo_root=repo_root,
        )
    return DeploymentsGitignoreResult(
        path=gitignore_path,
        wrote=False,
        repo_root=repo_root,
    )


def _ensure_wireguard_output_gitignore(output_dir: Path, paths: ProjectPaths) -> Path | None:
    default_output_dir = default_wireguard_client_output_dir(paths).resolve()
    if output_dir.resolve() == default_output_dir:
        result = _ensure_deployments_gitignore(deployments_root=paths.deployments_dir)
        return result.path

    output_dir.mkdir(parents=True, exist_ok=True)
    gitignore_path = output_dir / ".gitignore"
    block = "# Managed by `nebius-cxcli wireguard`.\n*\n!.gitignore\n"
    existing = gitignore_path.read_text(encoding="utf-8") if gitignore_path.exists() else ""
    if existing != block:
        gitignore_path.write_text(block, encoding="utf-8")
    return gitignore_path


def _linux_distribution_ids(os_release_path: Path = Path("/etc/os-release")) -> set[str]:
    try:
        text = os_release_path.read_text(encoding="utf-8")
    except OSError:
        return set()
    ids: set[str] = set()
    for line in text.splitlines():
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, raw_value = line.split("=", 1)
        if key not in {"ID", "ID_LIKE"}:
            continue
        value = raw_value.strip().strip('"').strip("'")
        ids.update(item.lower() for item in value.split() if item)
    return ids


def _wireguard_client_install_command(
    *,
    platform_name: str | None = None,
    os_release_path: Path = Path("/etc/os-release"),
) -> str:
    platform = (platform_name or sys.platform).lower()
    if platform == "darwin":
        return "brew install wireguard-tools"
    if platform.startswith("linux"):
        distro_ids = _linux_distribution_ids(os_release_path)
        if distro_ids & {"debian", "ubuntu", "linuxmint", "pop"}:
            return "sudo apt-get update && sudo apt-get install -y wireguard-tools"
        if distro_ids & {"fedora", "rhel", "centos", "rocky", "almalinux"}:
            return "sudo dnf install -y wireguard-tools"
        if distro_ids & {"arch", "manjaro"}:
            return "sudo pacman -S wireguard-tools"
        if distro_ids & {"suse", "opensuse", "opensuse-leap", "sles"}:
            return "sudo zypper install -y wireguard-tools"
        if distro_ids & {"alpine"}:
            return "sudo apk add wireguard-tools"
        return "Install the wireguard-tools package with your Linux distribution package manager"
    if platform.startswith("win"):
        return "Install WireGuard for Windows from https://www.wireguard.com/install/"
    return "Install the WireGuard client tools for your OS from https://www.wireguard.com/install/"


def _wireguard_client_tool_missing() -> bool:
    return shutil.which("wg-quick") is None


def _ensure_customer_scaffold(
    *,
    base_path: Path,
) -> Path:
    deployments_root = _resolve_deployments_root(base_path)
    deployments_root.mkdir(parents=True, exist_ok=True)
    return deployments_root


def _project_config_path(
    *,
    deployments_root: Path,
    tenant_folder: str,
    project_folder: str,
) -> Path:
    return deployments_root / tenant_folder / project_folder / "config.yaml"


def _resolve_create_target_folders(
    *,
    provider_lookup: ProviderOptionLookup,
    tenant_id: str,
    project_id: str,
) -> tuple[str, str]:
    tenant_name, project_name = provider_lookup.resolve_tenant_project_names(
        tenant_id=tenant_id,
        project_id=project_id,
    )
    return (
        normalize_project_folder_name(tenant_name, fallback=tenant_id),
        normalize_project_folder_name(project_name, fallback=project_id),
    )


def _deep_merge_payload(base: Any, override: Any) -> Any:
    if isinstance(base, Mapping) and isinstance(override, Mapping):
        merged = {str(key): _deep_merge_payload(value, value) for key, value in base.items()}
        for key, value in override.items():
            token = str(key)
            if token in merged:
                merged[token] = _deep_merge_payload(merged[token], value)
            else:
                merged[token] = _deep_merge_payload(value, value)
        return merged
    if isinstance(override, list):
        return [_deep_merge_payload(item, item) for item in override]
    return override


def _enabled_ids_from_runtime_payload(
    *,
    payload: dict[str, Any],
    entries: tuple[ComponentEntry, ...],
) -> set[str]:
    selected: set[str] = set()
    entry_ids = {entry.id for entry in entries}

    infra_node = payload.get("infra")
    if isinstance(infra_node, Mapping):
        components = infra_node.get("components")
        if isinstance(components, list):
            for item in components:
                if not isinstance(item, Mapping):
                    continue
                if not bool(item.get("enabled", False)):
                    continue
                component_id = component_type_id(item)
                if component_id in entry_ids:
                    selected.add(component_id)

    apps_node = payload.get("apps")
    if isinstance(apps_node, Mapping):
        charts = apps_node.get("charts")
        if isinstance(charts, list):
            for item in charts:
                if not isinstance(item, Mapping):
                    continue
                if not bool(item.get("enabled", False)):
                    continue
                chart_id = component_type_id(item)
                if chart_id in entry_ids:
                    selected.add(chart_id)

    return selected


def _filter_runtime_payload_for_selected_components(
    *,
    payload: dict[str, Any],
    selected_infra: set[str],
    selected_apps: set[str],
    infra_entries: tuple[ComponentEntry, ...],
    app_entries: tuple[ComponentEntry, ...],
) -> dict[str, Any]:
    runtime_payload = dict(payload)
    infra = runtime_payload.get("infra")
    apps = runtime_payload.get("apps")
    if not isinstance(infra, dict) or not isinstance(apps, dict):
        return runtime_payload

    infra_components = infra.get("components")
    if not isinstance(infra_components, list):
        infra_components = []
    existing_infra_rows: list[dict[str, Any]] = []
    for item in infra_components:
        if not isinstance(item, dict):
            continue
        component_id = component_type_id(item)
        if not component_id:
            continue
        row = dict(item)
        ensure_component_instance_id(row, default_component_id=component_id)
        existing_infra_rows.append(row)
    selected_infra_components: list[dict[str, Any]] = []
    for entry in infra_entries:
        if entry.id not in selected_infra:
            continue
        matched_rows = [row for row in existing_infra_rows if component_type_id(row) == entry.id]
        if not matched_rows:
            row = {
                "id": entry.id,
                INSTANCE_ID_FIELD: entry.id,
                "enabled": True,
                "inputs": {},
            }
            _seed_infra_resource_name_from_instance_id(row, entry)
            matched_rows = [row]
        else:
            for row in matched_rows:
                if not isinstance(row.get("inputs"), Mapping):
                    row["inputs"] = {}
                row["enabled"] = True
                _seed_infra_resource_name_from_instance_id(row, entry)
        selected_infra_components.extend(matched_rows)
    infra["components"] = selected_infra_components
    target_refs = enabled_cluster_target_refs(runtime_payload)
    default_target_ref = target_refs[0] if len(target_refs) == 1 else ""

    app_charts = apps.get("charts")
    if not isinstance(app_charts, list):
        app_charts = []
    existing_app_rows: list[dict[str, Any]] = []
    for item in app_charts:
        if not isinstance(item, dict):
            continue
        chart_id = component_type_id(item)
        if not chart_id:
            continue
        row = dict(item)
        ensure_component_instance_id(row, default_component_id=chart_id)
        existing_app_rows.append(row)
    selected_app_charts: list[dict[str, Any]] = []
    for entry in app_entries:
        if entry.id not in selected_apps:
            continue
        matched_rows = [row for row in existing_app_rows if component_type_id(row) == entry.id]
        if not matched_rows:
            chart_repo = str(entry.chart_repo or "").strip() or None
            chart_name = str(entry.chart_name or "").strip() or None
            if not chart_name:
                chart_repo, chart_name = _chart_source_parts(entry)
            if not chart_name:
                chart_name = entry.id
            chart_repo = _canonical_app_chart_repo(
                chart_repo=str(chart_repo or ""),
                chart_name=chart_name,
            )
            namespace = str(entry.default_namespace or "").strip() or entry.id
            release_name = str(entry.default_release_name or "").strip() or entry.id
            raw_group = str(entry.group or "").strip().lower()
            group = re.sub(r"[^a-z0-9]+", "-", raw_group).strip("-") or "workloads"
            instance_id = (
                target_scoped_app_instance_id(entry.id, target_ref=default_target_ref)
                if default_target_ref
                else entry.id
            )
            row = {
                "id": entry.id,
                INSTANCE_ID_FIELD: instance_id,
                "group": group,
                "enabled": True,
                "repo": str(chart_repo or ""),
                "version": str(entry.version or ""),
                "namespace": namespace,
                "release-name": release_name,
                "values": {},
            }
            matched_rows = [row]
        else:
            for row in matched_rows:
                if not str(row.get("repo", "")).strip():
                    chart_repo = str(entry.chart_repo or "").strip()
                    chart_name = str(entry.chart_name or entry.id).strip()
                    if chart_repo:
                        row["repo"] = _canonical_app_chart_repo(
                            chart_repo=chart_repo,
                            chart_name=chart_name,
                        )
                if not str(row.get("version", "")).strip() and entry.version:
                    row["version"] = str(entry.version)
                if not str(row.get("namespace", "")).strip():
                    row["namespace"] = str(entry.default_namespace or "").strip() or entry.id
                if not str(row.get("release-name", "")).strip():
                    fallback_release_name = str(
                        entry.default_release_name or ""
                    ).strip() or component_instance_id(row)
                    row["release-name"] = fallback_release_name
                if "group" not in row or not str(row.get("group", "")).strip():
                    raw_group = str(entry.group or "").strip().lower()
                    row["group"] = re.sub(r"[^a-z0-9]+", "-", raw_group).strip("-") or "workloads"
                if (
                    target_refs
                    and component_instance_id(row) not in target_refs
                    and default_target_ref
                ):
                    row[INSTANCE_ID_FIELD] = target_scoped_app_instance_id(
                        entry.id,
                        target_ref=default_target_ref,
                    )
                if not isinstance(row.get("values"), Mapping):
                    row["values"] = {}
                row["enabled"] = True
        selected_app_charts.extend(matched_rows)
    apps["charts"] = selected_app_charts
    _materialize_single_target_app_bindings(runtime_payload)

    return runtime_payload


def _selected_cluster_target_component_ids(
    selected_infra: set[str],
    infra_entries: tuple[ComponentEntry, ...],
) -> set[str]:
    return {
        entry.id
        for entry in infra_entries
        if entry.handoff is not None and entry.id in selected_infra
    }


def _app_selection_requires_cluster_target_message() -> str:
    return (
        "Apps are Helm charts and require an enabled MK8s target in this project. "
        "Select infra:mk8s in the same session or remove the app selection."
    )


def _app_selection_without_cluster_target_issue(
    *,
    selected_infra: set[str],
    selected_apps: set[str],
    infra_entries: tuple[ComponentEntry, ...],
) -> str | None:
    if not selected_apps:
        return None
    if _selected_cluster_target_component_ids(selected_infra, infra_entries):
        return None
    if _SOPERATOR_APP_ID in selected_apps:
        return None
    return _app_selection_requires_cluster_target_message()


def _target_bound_app_issues_from_payload(payload: dict[str, Any]) -> list[str]:
    issues: list[str] = []
    target_refs = set(enabled_cluster_target_refs(payload))
    available_targets = ", ".join(sorted(target_refs)) or "(none)"
    seen_keys: dict[tuple[str, str], str] = {}

    enabled_app_rows = _dynamic_enabled_app_chart_rows(payload)
    if enabled_app_rows and not target_refs:
        issues.append(
            "apps.charts requires at least one enabled MK8s target because cxcli apps "
            "are Helm charts installed into Kubernetes"
        )
        return issues

    for row in enabled_app_rows:
        chart_id = str(row["id"])
        instance_id = str(row["instance_id"])
        label = _component_instance_path_label("apps", chart_id, instance_id)
        instance_key = (chart_id, instance_id)
        existing_label = seen_keys.get(instance_key)
        if existing_label is not None:
            issues.append(f"{label} duplicates enabled app chart instance {existing_label}")
            continue
        seen_keys[instance_key] = label

        if target_refs and instance_id not in target_refs:
            issues.append(
                f"{label}.{INSTANCE_ID_FIELD} '{instance_id}' must reference one of "
                f"the enabled cluster targets: {available_targets}"
            )
    return issues


def _active_infra_resource_identity_issues(payload: dict[str, Any]) -> list[str]:
    issues: list[str] = []
    entry_by_id = {entry.id: entry for entry in component_entries("infra")}
    seen_names: dict[tuple[str, str], str] = {}
    seen_instance_ids: dict[str, str] = {}

    for index, row in enumerate(_scope_rows(payload, scope="infra")):
        if not isinstance(row, Mapping) or not bool(row.get("enabled", False)):
            continue
        component_id = component_type_id(row)
        instance_id = component_instance_id(row)
        if not component_id or not instance_id:
            continue
        label = _component_instance_path_label("infra", component_id, instance_id)
        existing_instance_label = seen_instance_ids.get(instance_id)
        if existing_instance_label is not None:
            issues.append(
                f"{label}.{INSTANCE_ID_FIELD} duplicates enabled infra component "
                f"{existing_instance_label}"
            )
        else:
            seen_instance_ids[instance_id] = label

        entry = entry_by_id.get(component_id)
        if entry is None:
            continue
        name_input = _entry_scalar_resource_name_input(entry)
        if not name_input:
            continue
        inputs = row.get("inputs")
        if not isinstance(inputs, Mapping):
            continue
        raw_name = _mapping_path_value(inputs, name_input)
        if not _is_scalar_resource_name_value(raw_name):
            continue
        resource_name = str(raw_name).strip()
        normalized_name = normalize_component_token(resource_name)
        if not normalized_name or not INSTANCE_ID_PATTERN.fullmatch(normalized_name):
            issues.append(
                f"infra.components[{index}].inputs.{name_input} must normalize to a valid "
                "instance_id using lowercase letters, digits, and hyphens"
            )
            continue
        name_key = (component_id, normalized_name)
        existing_name_label = seen_names.get(name_key)
        if existing_name_label is not None:
            issues.append(
                f"{label}.inputs.{name_input} duplicates scalar resource name "
                f"'{normalized_name}' already used by {existing_name_label}"
            )
        else:
            seen_names[name_key] = label
        if instance_id != normalized_name:
            issues.append(
                f"{label}.{INSTANCE_ID_FIELD} '{instance_id}' must match normalized "
                f"inputs.{name_input} '{normalized_name}'"
            )
    return issues


def _selection_change_issues(
    payload: dict[str, Any],
    *,
    include_app_chart_dependencies: bool = True,
) -> list[str]:
    issues: list[str] = []
    issues.extend(
        _component_dependency_issues_from_payload(
            payload,
            include_app_chart_dependencies=include_app_chart_dependencies,
        )
    )
    issues.extend(_active_infra_resource_identity_issues(payload))
    issues.extend(_active_component_input_binding_issues(payload))
    issues.extend(_target_bound_app_issues_from_payload(payload))
    return issues


def _write_runtime_payload_config(
    config_path: Path,
    payload: dict[str, Any],
    *,
    overwrite: bool = False,
    expected_bytes: bytes | None = None,
    expected_absent: bool = False,
) -> bool:
    if expected_bytes is not None and expected_absent:
        raise ValueError("config write cannot expect both existing bytes and an absent path")
    normalize_runtime_config_payload(payload, base_dir=config_path.parent)
    next_config_text = yaml.safe_dump(payload, sort_keys=False)
    current_config_text = None
    if config_path.exists():
        if expected_absent:
            raise FileExistsError(config_path)
        current_bytes = config_path.read_bytes()
        if expected_bytes is not None and current_bytes != expected_bytes:
            raise RuntimeError(
                "recovery-required: config.yaml changed after upgrade planning; the "
                "compare-and-swap was refused and no operation was replaced."
            )
        current_config_text = current_bytes.decode("utf-8")
    elif expected_bytes is not None:
        raise RuntimeError(
            "recovery-required: config.yaml disappeared after upgrade planning; no "
            "operation was written."
        )
    if current_config_text == next_config_text:
        if not overwrite:
            return False
        _write_text_atomic(config_path, next_config_text, expected_absent=expected_absent)
        return True
    _write_text_atomic(config_path, next_config_text, expected_absent=expected_absent)
    return True


def _seed_infra_project_scope_defaults(
    *,
    payload: dict[str, Any],
    infra_entries: tuple[ComponentEntry, ...],
) -> None:
    project_id = _non_empty_text(_read_payload_field(payload, "client_info.nebius.project_id"))
    if not project_id:
        return
    infra_node = payload.get("infra")
    if not isinstance(infra_node, Mapping):
        return
    components = infra_node.get("components")
    if not isinstance(components, list):
        return

    entry_by_id = {entry.id: entry for entry in infra_entries}
    for item in components:
        if not isinstance(item, dict):
            continue
        if not bool(item.get("enabled", False)):
            continue
        component_id = _non_empty_text(item.get("id")).lower()
        if not component_id:
            continue
        inputs = item.get("inputs")
        if not isinstance(inputs, dict):
            continue
        entry = entry_by_id.get(component_id)
        source = _effective_catalog_component_source(row=item, entry=entry)
        if not source:
            continue
        inspection_source = _entry_module_metadata_source(entry, fallback_source=source)
        leaf_names = {
            _normalize_leaf_name(name) for name in module_variable_names(inspection_source)
        }
        if not leaf_names:
            continue
        if entry is not None and entry.status is not None:
            parent_input = str(entry.status.parent_input or "").strip()
            parent_root = _normalize_leaf_name(parent_input.split(".", 1)[0])
            if (
                parent_input
                and parent_root in leaf_names
                and _mapping_path_value(inputs, parent_input) is None
            ):
                _set_mapping_path_value(inputs, parent_input, project_id)
        if "parent_id" in leaf_names and "parent_id" not in inputs:
            inputs["parent_id"] = project_id
        if "project_id" in leaf_names and "project_id" not in inputs:
            inputs["project_id"] = project_id


def _seed_infra_shared_admin_ssh_public_key(
    *,
    payload: dict[str, Any],
    infra_entries: tuple[ComponentEntry, ...],
) -> None:
    shared_public_key = _non_empty_text(
        read_path_with_catalog(payload, "shared.admin_ssh.public_key")
    )
    if not shared_public_key:
        return
    infra_node = payload.get("infra")
    if not isinstance(infra_node, Mapping):
        return
    components = infra_node.get("components")
    if not isinstance(components, list):
        return

    entry_by_id = {entry.id: entry for entry in infra_entries}
    for item in components:
        if not isinstance(item, dict):
            continue
        if not bool(item.get("enabled", False)):
            continue
        component_id = _non_empty_text(item.get("id")).lower()
        if not component_id:
            continue
        inputs = item.get("inputs")
        if not isinstance(inputs, dict):
            continue
        if _non_empty_text(inputs.get("ssh_public_key")):
            continue
        entry = entry_by_id.get(component_id)
        source = _effective_catalog_component_source(row=item, entry=entry)
        if not source:
            continue
        inspection_source = _entry_module_metadata_source(entry, fallback_source=source)
        leaf_names = {
            _normalize_leaf_name(name) for name in module_variable_names(inspection_source)
        }
        if "ssh_public_key" not in leaf_names:
            continue
        inputs["ssh_public_key"] = shared_public_key


@dataclass(frozen=True)
class CIWorkflowBootstrapResult:
    repo_root: Path
    workflow_file: Path
    wrote_workflow: bool
    replaced_workflow: bool = False


def _ensure_ci_workflow_for_deployments_root(
    *,
    deployments_root: Path,
    cli_ref: str,
) -> CIWorkflowBootstrapResult:
    def _normalize_workflow_text(text: str) -> str:
        normalized = text.replace("\r\n", "\n").rstrip("\n")
        return f"{normalized}\n"

    _assert_not_nested_deployments_root(deployments_root)
    repo_root = _require_git_root(deployments_root)
    workflows_path = repo_root / ".github" / "workflows"
    workflow_file = workflows_path / "nebius-deployments.yml"
    deployments_dir_for_ci = _relative_deployments_dir_for_ci(repo_root, deployments_root)
    discover_target_for_ci = _relative_discover_target_for_ci(repo_root, deployments_root)
    expected_workflow = customer_workflow_yaml(
        deployments_dir=deployments_dir_for_ci,
        discover_target=discover_target_for_ci,
        cli_ref=cli_ref,
    )

    workflows_path.mkdir(parents=True, exist_ok=True)

    workflow_preexisted = workflow_file.exists()
    if workflow_preexisted:
        existing_workflow = workflow_file.read_text(encoding="utf-8")
        if _normalize_workflow_text(existing_workflow) == _normalize_workflow_text(
            expected_workflow
        ):
            return CIWorkflowBootstrapResult(
                repo_root=repo_root,
                workflow_file=workflow_file,
                wrote_workflow=False,
                replaced_workflow=False,
            )

    workflow_file.write_text(expected_workflow, encoding="utf-8")
    return CIWorkflowBootstrapResult(
        repo_root=repo_root,
        workflow_file=workflow_file,
        wrote_workflow=True,
        replaced_workflow=workflow_preexisted,
    )


def _scaffold_instance(
    *,
    base_path: Path,
    client_name: str,
    tenant_folder: str,
    project_folder: str,
    tenant_id: str,
    project_id: str,
    region_id: str,
    email: str | None,
    selected_infra: set[str],
    selected_apps: set[str],
    infra_entries: tuple[ComponentEntry, ...],
    app_entries: tuple[ComponentEntry, ...],
    force: bool,
    config_yaml: str | None = None,
    expected_config_absent: bool = False,
) -> BootstrapResult:
    deployments_root = _ensure_customer_scaffold(
        base_path=base_path,
    )
    instance_dir = deployments_root / tenant_folder / project_folder
    config_path = instance_dir / "config.yaml"

    if force and instance_dir.exists():
        shutil.rmtree(instance_dir)

    (instance_dir / "generated" / "infra").mkdir(parents=True, exist_ok=True)
    (instance_dir / "generated" / "flux").mkdir(parents=True, exist_ok=True)
    (instance_dir / "generated" / "reports").mkdir(parents=True, exist_ok=True)

    wrote_config = False
    rendered_config = config_yaml
    if expected_config_absent and config_path.exists():
        raise FileExistsError(config_path)
    if rendered_config is None and (not config_path.exists() or force):
        rendered_config = starter_config_yaml(
            client_name=client_name,
            tenant_id=tenant_id,
            project_id=project_id,
            region_id=region_id,
            email=email,
            selected_infra=selected_infra,
            selected_apps=selected_apps,
            infra_entries=infra_entries,
            app_entries=app_entries,
        )

    if rendered_config is not None:
        next_config_text = BootstrapResult.normalized_config_yaml(
            config_path=config_path,
            config_yaml=rendered_config,
            selected_infra=selected_infra,
            selected_apps=selected_apps,
            infra_entries=infra_entries,
            app_entries=app_entries,
        )
        should_write = (
            force
            or not config_path.exists()
            or config_path.read_text(encoding="utf-8") != next_config_text
        )
        if should_write:
            payload = yaml.safe_load(next_config_text)
            if not isinstance(payload, dict):  # pragma: no cover - normalized invariant
                raise RuntimeError("Generated config template must be a mapping")
            wrote_config = _write_runtime_payload_config(
                config_path,
                payload,
                overwrite=force,
                expected_absent=expected_config_absent,
            )

    config = load_config(config_path, persist_normalized=True)
    paths = resolve_project_paths(config_path, deployments_dir_hint=str(deployments_root))
    validate_path_alignment(config, paths)
    return BootstrapResult(
        deployments_root=deployments_root,
        project_path=instance_dir,
        config_path=config_path,
        wrote_config=wrote_config,
    )


def _path_looks_like_config_yaml(path: Path) -> bool:
    return path.name == "config.yaml" or path.suffix.lower() in {".yaml", ".yml"}


def _resolve_soperator_onboard_config_target(
    target_path: Path,
    *,
    interactive: bool,
    client_name: str | None,
    tenant_id: str | None,
    project_id: str | None,
    region_id: str | None,
    email: str | None,
    infra_entries: tuple[ComponentEntry, ...],
    app_entries: tuple[ComponentEntry, ...],
) -> SoperatorOnboardConfigTarget:
    def _reject_existing_config_creation_flags(config_path: Path) -> None:
        supplied = tuple(
            option
            for option, value in (
                ("--client-name", client_name),
                ("--tenant-id", tenant_id),
                ("--project-id", project_id),
                ("--email", email),
            )
            if value is not None
        )
        if supplied:
            raise RuntimeError(
                f"Existing Soperator config '{config_path}' already owns project identity; "
                "remove project-creation option(s): " + ", ".join(supplied)
            )

    if region_id is not None:
        _region_or_prompt(region_id, interactive=False)
    resolved_path = target_path.resolve()
    if resolved_path.exists() and not resolved_path.is_dir():
        _reject_existing_config_creation_flags(resolved_path)
        return SoperatorOnboardConfigTarget(
            config_path=resolved_path,
            live_region_config_sha256=(
                SoperatorOnboardConfigTarget.pending_live_region_config_sha256(resolved_path)
            ),
        )
    if resolved_path.is_dir():
        if _path_looks_like_config_yaml(resolved_path):
            raise RuntimeError(f"Config path must be a file, not a directory: {resolved_path}")
        direct_config_path = resolved_path / "config.yaml"
        if direct_config_path.exists():
            if direct_config_path.is_dir():
                raise RuntimeError(
                    f"Config path must be a file, not a directory: {direct_config_path}"
                )
            _reject_existing_config_creation_flags(direct_config_path)
            return SoperatorOnboardConfigTarget(
                config_path=direct_config_path.resolve(),
                live_region_config_sha256=(
                    SoperatorOnboardConfigTarget.pending_live_region_config_sha256(
                        direct_config_path
                    )
                ),
            )
    if _path_looks_like_config_yaml(resolved_path):
        return SoperatorOnboardConfigTarget(config_path=resolved_path)

    _validate_deployments_root_target(resolved_path, allow_missing=True)
    deployments_root = _resolve_deployments_root(resolved_path)
    _assert_not_nested_deployments_root(deployments_root)
    resolved_tenant_id = _value_or_prompt(
        tenant_id,
        option_name="--tenant-id",
        prompt_text="Tenant ID",
        interactive=interactive,
    )
    resolved_project_id = _value_or_prompt(
        project_id,
        option_name="--project-id",
        prompt_text="Project ID",
        interactive=interactive,
    )
    provider_lookup = ProviderOptionLookup()
    resolved_tenant_id, resolved_project_id = _validate_tenant_project_ids_or_prompt(
        tenant_id=resolved_tenant_id,
        project_id=resolved_project_id,
        interactive=interactive,
        provider_lookup=provider_lookup,
    )
    resolved_tenant_folder, resolved_project_folder = _resolve_create_target_folders(
        provider_lookup=provider_lookup,
        tenant_id=resolved_tenant_id,
        project_id=resolved_project_id,
    )
    config_path = _project_config_path(
        deployments_root=deployments_root,
        tenant_folder=resolved_tenant_folder,
        project_folder=resolved_project_folder,
    )
    if config_path.exists():
        with config_path.open("r", encoding="utf-8") as handle:
            loaded_payload = yaml.safe_load(handle) or {}
        if not isinstance(loaded_payload, dict):
            raise RuntimeError("Existing config.yaml payload must be a mapping")
        (
            _existing_client_name,
            existing_tenant_id,
            existing_project_id,
            _existing_region_id,
            _existing_email,
        ) = _identity_values_from_payload(loaded_payload)
        if existing_tenant_id != resolved_tenant_id or existing_project_id != resolved_project_id:
            raise RuntimeError(
                "Resolved name-based project path collision: "
                f"{config_path.parent} already belongs to tenant_id/project_id "
                f"'{existing_tenant_id}'/'{existing_project_id}', not "
                f"'{resolved_tenant_id}'/'{resolved_project_id}'. "
                "Pass the existing config.yaml directly or choose a different Nebius scope."
            )
        _ensure_project_auth_identity(
            project_id=existing_project_id,
            client_name=_existing_client_name,
        )
        if interactive:
            if not _confirm_soperator_onboard_existing_config(config_path=config_path):
                console.print("No changes applied.")
                raise typer.Exit(code=0)
        else:
            _warn_soperator_onboard_existing_config(config_path=config_path)
        gitignore_result = _ensure_deployments_gitignore(deployments_root=deployments_root)
        return SoperatorOnboardConfigTarget(
            config_path=config_path.resolve(),
            gitignore_result=gitignore_result,
            live_region_config_sha256=(
                SoperatorOnboardConfigTarget.pending_live_region_config_sha256(config_path)
            ),
        )

    resolved_client_name = _client_name_or_prompt(client_name, interactive=interactive)
    _ensure_project_auth_identity(
        project_id=resolved_project_id,
        client_name=resolved_client_name,
    )
    # A missing onboard region is derived from the existing cluster after discovery.
    # The scaffold still needs a schema-valid temporary value, but must not prompt for it.
    resolved_region_id = _region_or_prompt(region_id, interactive=False)
    resolved_email = _optional_email_or_prompt(email, interactive=interactive)
    region_from_live_cluster = region_id is None
    scaffold_config_yaml: str | None = None
    live_region_config_sha256 = ""
    if region_from_live_cluster:
        scaffold_config_yaml = BootstrapResult.normalized_config_yaml(
            config_path=config_path,
            config_yaml=starter_config_yaml(
                client_name=resolved_client_name,
                tenant_id=resolved_tenant_id,
                project_id=resolved_project_id,
                region_id=resolved_region_id,
                email=resolved_email,
                selected_infra=set(),
                selected_apps=set(),
                infra_entries=infra_entries,
                app_entries=app_entries,
            ),
            selected_infra=set(),
            selected_apps=set(),
            infra_entries=infra_entries,
            app_entries=app_entries,
        )
        live_region_config_sha256 = (
            "sha256:" + hashlib.sha256(scaffold_config_yaml.encode()).hexdigest()
        )
    config_lock_path = config_path.parent / ".nebius-cxcli" / "config.lock"
    with SoperatorOperationLocalLock(config_lock_path):
        if config_path.exists():
            raise RuntimeError(
                f"Soperator onboarding config appeared while the fresh scaffold was being "
                f"prepared: {config_path}. No existing config was overwritten; retry using "
                "that config or a different deployments root."
            )
        if region_from_live_cluster:
            SoperatorOnboardConfigTarget.write_bootstrap_marker(
                config_path,
                tenant_id=resolved_tenant_id,
                project_id=resolved_project_id,
                config_sha256=live_region_config_sha256,
            )
        else:
            SoperatorOnboardConfigTarget.bootstrap_marker_path(config_path).unlink(missing_ok=True)
        try:
            bootstrap_result = _scaffold_instance(
                base_path=deployments_root,
                client_name=resolved_client_name,
                tenant_folder=resolved_tenant_folder,
                project_folder=resolved_project_folder,
                tenant_id=resolved_tenant_id,
                project_id=resolved_project_id,
                region_id=resolved_region_id,
                email=resolved_email,
                selected_infra=set(),
                selected_apps=set(),
                infra_entries=infra_entries,
                app_entries=app_entries,
                force=False,
                config_yaml=scaffold_config_yaml,
                expected_config_absent=True,
            )
        except FileExistsError as exc:
            SoperatorOnboardConfigTarget.bootstrap_marker_path(config_path).unlink(missing_ok=True)
            raise RuntimeError(
                f"Soperator onboarding config was created by another writer: {config_path}. "
                "The competing config was preserved; retry from its current state."
            ) from exc
        if live_region_config_sha256 and _sha256_file(bootstrap_result.config_path) != (
            live_region_config_sha256
        ):
            raise RuntimeError(
                "Fresh Soperator onboarding scaffold did not match its pending live-region "
                "authority marker; retry from the deployments root."
            )
    gitignore_result = _ensure_deployments_gitignore(
        deployments_root=bootstrap_result.deployments_root,
    )
    return SoperatorOnboardConfigTarget(
        config_path=bootstrap_result.config_path.resolve(),
        bootstrap_result=bootstrap_result,
        gitignore_result=gitignore_result,
        live_region_config_sha256=live_region_config_sha256,
    )


@app.command(
    "create",
    short_help="Use DEPLOYMENTS_ROOT to bootstrap one name-based tenant/project folder with config.yaml plus generated/ skeleton.",
    epilog=(
        "Examples: "
        "nebius-cxcli create ./deployments (full interactive wizard); "
        "nebius-cxcli create ./deployments --client-name acme --tenant-id TENANT --project-id PROJECT --region-id eu-north1; "
        "nebius-cxcli create /path/to/deployments-root --client-name client-slug "
        "--tenant-id TENANT_ID --project-id PROJECT_ID "
        "--infra mk8s,vm,wireguard-gw,ssh-jumphost "
        "--no-validate-sources --no-validate-config "
        "(guided infra create with identity and components preselected; add --app none to skip app selection); "
        "nebius-cxcli create /path/to/deployments-root --client-name client-slug "
        "--tenant-id TENANT_ID --project-id PROJECT_ID "
        "--infra mk8s,vm --infra wireguard-gw,ssh-jumphost "
        "--app n8n,gateway-helm --app cert-manager "
        "--no-validate-sources --no-validate-config "
        "(guided create with multiple infra and app choices preselected); "
        "Soperator is intentionally unavailable here; use `nebius-cxcli soperator install` "
        "for a fresh cluster or `nebius-cxcli soperator onboard` for an existing product."
    ),
)
def create_command(
    target_path: Annotated[
        Path,
        typer.Argument(
            metavar="DEPLOYMENTS_ROOT",
            help=_DEPLOYMENTS_ROOT_ARGUMENT_HELP,
        ),
    ],
    client_name: Annotated[
        str | None,
        typer.Option("--client-name", help="Client slug (lowercase letters/digits/hyphens)"),
    ] = None,
    tenant_id: Annotated[
        str | None, typer.Option("--tenant-id", help="Nebius tenant identifier")
    ] = None,
    project_id: Annotated[
        str | None, typer.Option("--project-id", help="Nebius project identifier")
    ] = None,
    region_id: Annotated[
        str | None,
        typer.Option(
            "--region-id",
            help="Nebius region identifier, for example eu-north1 (defaults to eu-north1)",
        ),
    ] = None,
    email: Annotated[
        str | None,
        typer.Option(
            "--email",
            help="Optional notifications email for deploy report updates",
        ),
    ] = None,
    infra_components_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--infra",
            help=(
                "Infra component id(s) to enable (repeat option or pass comma-separated ids; "
                "supports ids or numeric indexes in interactive mode)"
            ),
        ),
    ] = None,
    apps_components_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--app",
            help=(
                "Apps component id(s) to enable (repeat option or pass comma-separated ids; "
                "supports ids or numeric indexes in interactive mode; "
                "requires a managed MK8s target in the same project; "
                "app chart dependencies are auto-resolved when chart metadata is available; "
                "Soperator is not selectable here and is owned by the `soperator` command)"
            ),
        ),
    ] = None,
    app_namespace_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--app-namespace",
            help=(
                "Override app namespace with '<app-id>=<namespace>' (repeatable or comma-separated). "
                "Applies to enabled apps."
            ),
        ),
    ] = None,
    app_releasename_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--app-releasename",
            help=(
                "Override app release name with '<app-id>=<release-name>' "
                "(repeatable or comma-separated). Applies to enabled apps."
            ),
        ),
    ] = None,
    app_version_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--app-version",
            help=(
                "Override app chart version with '<app-id>=<chart-version>' "
                "(repeatable or comma-separated). Defaults come from component_sources.yaml; "
                "with source validation enabled, the requested chart version must resolve before "
                "create writes config.yaml."
            ),
        ),
    ] = None,
    network_ids_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--network-id",
            help=(
                "VPC network ID for selected network-attached infra. Use a bare value only when "
                "one applicable infra component is selected, or scope it as "
                "'infra:<component-id>@<resource-name>=<vpcnetwork-id>'. Repeatable."
            ),
        ),
    ] = None,
    subnet_ids_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--subnet-id",
            help=(
                "VPC subnet ID for selected subnet-attached infra. Use a bare value only when "
                "one applicable infra component is selected, or scope it as "
                "'infra:<component-id>@<resource-name>=<vpcsubnet-id>'. Repeatable."
            ),
        ),
    ] = None,
    network_refs_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--network-ref",
            help=(
                "Planned VPC network ref for selected network-attached infra. Use a bare value only when "
                "one applicable infra component is selected, or scope it as "
                "'infra:<component-id>@<resource-name>=vpc@<vpc-instance>.network_id'. Repeatable."
            ),
        ),
    ] = None,
    subnet_refs_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--subnet-ref",
            help=(
                "Planned VPC subnet ref for selected subnet-attached infra. Use a bare value only when "
                "one applicable infra component is selected, or scope it as "
                "'infra:<component-id>@<resource-name>=vpc@<vpc-instance>.subnets.<subnet-key>.id'. Repeatable."
            ),
        ),
    ] = None,
    validate_sources: Annotated[
        bool,
        typer.Option(
            "--validate-sources/--no-validate-sources",
            help=(
                "Validate infra sources first, then only selected app chart sources "
                "and auto-enabled app dependencies, with a final check for apps "
                "auto-enabled after the wizard before create writes config "
                "(enabled by default)."
            ),
        ),
    ] = True,
    validate_config: Annotated[
        bool,
        typer.Option(
            "--validate-config/--no-validate-config",
            help=(
                "Run post-write runtime validation against the resulting config.yaml "
                "after create finishes (enabled by default). `--no-validate-config` "
                "skips that validation only; create still runs its warning-only live "
                "quota/capacity assessment."
            ),
        ),
    ] = True,
    no_interactive: Annotated[
        bool,
        typer.Option(
            "--no-interactive",
            help=(
                "Disable wizard mode for automation/CI. "
                "When omitted, create always runs in wizard mode."
            ),
        ),
    ] = False,
    force: Annotated[
        bool,
        typer.Option(
            "--force",
            help=(
                "Overwrite the resolved existing project folder from scratch using the "
                "current create inputs and component selections. Existing component values, "
                "generated artifacts, and other files under that project folder are not "
                "preserved. Does not delete the deployments root or other projects."
            ),
        ),
    ] = False,
) -> None:
    """Use DEPLOYMENTS_ROOT to bootstrap one name-based tenant/project folder with config.yaml plus generated/ skeleton, or overwrite an existing resolved project folder from scratch after confirmation unless --force is provided.

    The post-create quota/capacity assessment is warning-only. It is not a
    reservation, not a quota request, and not a wizard-selectable deployment
    gate.
    """
    try:
        _require_generic_selection_excludes_soperator(
            apps_components_opt,
            command="create",
        )
        base_path = target_path.resolve()
        _validate_deployments_root_target(base_path, allow_missing=True)
        deployments_root = _resolve_deployments_root(base_path)
        _assert_not_nested_deployments_root(deployments_root)
        interactive_mode = not no_interactive
        resolved_tenant_id = _value_or_prompt(
            tenant_id,
            option_name="--tenant-id",
            prompt_text="Tenant ID",
            interactive=interactive_mode,
            default_value=None,
        )
        resolved_project_id = _value_or_prompt(
            project_id,
            option_name="--project-id",
            prompt_text="Project ID",
            interactive=interactive_mode,
            default_value=None,
        )
        provider_lookup = ProviderOptionLookup()
        resolved_tenant_id, resolved_project_id = _validate_tenant_project_ids_or_prompt(
            tenant_id=resolved_tenant_id,
            project_id=resolved_project_id,
            interactive=interactive_mode,
            provider_lookup=provider_lookup,
        )
        resolved_tenant_folder, resolved_project_folder = _resolve_create_target_folders(
            provider_lookup=provider_lookup,
            tenant_id=resolved_tenant_id,
            project_id=resolved_project_id,
        )

        existing_config_path = _project_config_path(
            deployments_root=deployments_root,
            tenant_folder=resolved_tenant_folder,
            project_folder=resolved_project_folder,
        )
        had_existing_config = existing_config_path.exists()
        infra_source_validation_ran = False
        if had_existing_config:
            with existing_config_path.open("r", encoding="utf-8") as handle:
                loaded_payload = yaml.safe_load(handle) or {}
            if not isinstance(loaded_payload, dict):
                raise RuntimeError("Existing config.yaml payload must be a mapping")
            (
                _existing_client_name,
                existing_tenant_id,
                existing_project_id,
                _existing_region_id,
                _existing_email,
            ) = _identity_values_from_payload(loaded_payload)
            if (
                existing_tenant_id != resolved_tenant_id
                or existing_project_id != resolved_project_id
            ):
                raise RuntimeError(
                    "Resolved name-based project path collision: "
                    f"{existing_config_path.parent} already belongs to tenant_id/project_id "
                    f"'{existing_tenant_id}'/'{existing_project_id}', not "
                    f"'{resolved_tenant_id}'/'{resolved_project_id}'. "
                    "Move the existing folder or rename one of the Nebius resources before rerunning `create`."
                )
            if not interactive_mode and not force:
                raise RuntimeError(
                    "Existing project found: "
                    f"{existing_config_path.parent}. `create` no longer reconciles existing configs. "
                    "Use `component list/add/remove --config <config.yaml>` for day-2 "
                    "component edits, or rerun with "
                    "`--force` to overwrite this one project folder from scratch."
                )
            if validate_sources:
                _validate_component_sources_or_raise(selected_app_ids=set())
                infra_source_validation_ran = True
            if interactive_mode:
                if force:
                    _warn_existing_project_overwrite(config_path=existing_config_path)
                    console.print(
                        "[dim]`--force` confirms the overwrite. "
                        "This only affects that one resolved project folder.[/dim]"
                    )
                elif not _confirm_existing_project_overwrite(config_path=existing_config_path):
                    console.print("No changes applied.")
                    return
            else:
                _warn_existing_project_overwrite(config_path=existing_config_path)
                console.print(
                    "[dim]`--force` confirms the overwrite in non-interactive mode. "
                    "This only affects that one resolved project folder.[/dim]"
                )
        if validate_sources and not infra_source_validation_ran:
            _validate_component_sources_or_raise(selected_app_ids=set())

        resolved_client_name = _client_name_or_prompt(
            client_name,
            interactive=interactive_mode,
        )
        _ensure_project_auth_identity(
            project_id=resolved_project_id,
            client_name=resolved_client_name,
        )
        resolved_region_id = _region_or_prompt(
            region_id,
            interactive=interactive_mode,
        )
        resolved_email = _optional_email_or_prompt(
            email,
            interactive=interactive_mode,
        )

        infra_entries = _with_infra_provider_groups(component_entries("infra"))
        app_entries = tuple(
            entry for entry in component_entries("apps") if entry.id != _SOPERATOR_APP_ID
        )
        if _SOPERATOR_LIFECYCLE_INTERNAL.get():
            snapshot = _SOPERATOR_RELEASE_SNAPSHOT_OVERRIDE.get()
            release = _non_empty_text(getattr(snapshot, "release", ""))
            if not release:
                raise RuntimeError(
                    "Soperator lifecycle create requires a frozen official upstream release."
                )
            app_entries = (*app_entries, soperator_install_entry(release))

        optional_wizard_mode = interactive_mode
        if interactive_mode:
            selected_infra_raw: set[str] = set()
            selected_apps_raw: set[str] = set()
            while True:
                optional_decision = _wizard_continue_phase(
                    "Continue with optional wizard phases (component selection and fields)?",
                    default=True,
                )
                if _wizard_phase_stop_requested(optional_decision) or not optional_decision:
                    optional_wizard_mode = False
                    selected_infra_raw = _resolve_component_ids(
                        scope="infra",
                        raw_values=infra_components_opt,
                        interactive=False,
                        entries=infra_entries,
                    )
                    selected_apps_raw = _resolve_component_ids(
                        scope="apps",
                        raw_values=apps_components_opt,
                        interactive=False,
                        entries=app_entries,
                    )
                    break

                optional_wizard_mode = True
                selection_stage: ComponentScope = "infra"
                try:
                    while True:
                        try:
                            if selection_stage == "infra":
                                selected_infra_raw = _resolve_component_ids(
                                    scope="infra",
                                    raw_values=infra_components_opt,
                                    interactive=True,
                                    entries=infra_entries,
                                    seed_defaults=selected_infra_raw or None,
                                )
                                selection_stage = "apps"
                                if (
                                    apps_components_opt is None
                                    and not _selected_cluster_target_component_ids(
                                        selected_infra_raw,
                                        infra_entries,
                                    )
                                ):
                                    selected_apps_raw = set()
                                    console.print(
                                        "[dim]Skipping app chart selection because no MK8s "
                                        "target was selected. Select infra:mk8s to add Helm "
                                        "charts or Soperator.[/dim]"
                                    )
                                    break
                            selected_apps_raw = _resolve_component_ids(
                                scope="apps",
                                raw_values=apps_components_opt,
                                interactive=True,
                                entries=app_entries,
                                seed_defaults=selected_apps_raw or None,
                            )
                            app_target_issue = _app_selection_without_cluster_target_issue(
                                selected_infra=selected_infra_raw,
                                selected_apps=selected_apps_raw,
                                infra_entries=infra_entries,
                            )
                            if app_target_issue:
                                console.print(
                                    f"{warning_markup('Invalid app selection:')} {app_target_issue}"
                                )
                                if infra_components_opt is not None:
                                    raise RuntimeError(app_target_issue)
                                selection_stage = "infra"
                                continue
                            break
                        except _WizardBackRequested:
                            if selection_stage == "apps":
                                selection_stage = "infra"
                                continue
                            raise
                except _WizardBackRequested:
                    continue
                except _WizardQuitRequested:
                    optional_wizard_mode = False
                    selected_infra_raw = _resolve_component_ids(
                        scope="infra",
                        raw_values=infra_components_opt,
                        interactive=False,
                        entries=infra_entries,
                    )
                    selected_apps_raw = _resolve_component_ids(
                        scope="apps",
                        raw_values=apps_components_opt,
                        interactive=False,
                        entries=app_entries,
                    )
                    break
                break
        else:
            selected_infra_raw = _resolve_component_ids(
                scope="infra",
                raw_values=infra_components_opt,
                interactive=False,
                entries=infra_entries,
            )
            selected_apps_raw = _resolve_component_ids(
                scope="apps",
                raw_values=apps_components_opt,
                interactive=False,
                entries=app_entries,
            )
        app_namespace_overrides = _parse_component_value_overrides(
            raw_values=app_namespace_opt,
            option_name="--app-namespace",
        )
        app_releasename_overrides = _parse_component_value_overrides(
            raw_values=app_releasename_opt,
            option_name="--app-releasename",
        )
        app_version_overrides = _parse_component_value_overrides(
            raw_values=app_version_opt,
            option_name="--app-version",
        )
        soperator_profile: str | None = _SOPERATOR_INSTALL_PROFILE_OVERRIDE.get()
        if interactive_mode and optional_wizard_mode and _SOPERATOR_APP_ID in selected_apps_raw:
            console.print(
                "[dim]Soperator create materializes the full production MK8s+SFS "
                "bundle. Use `nebius-cxcli soperator onboard "
                "<config.yaml-or-deployments-root>` for existing Nebius MK8s "
                "clusters.[/dim]"
            )
            console.print(
                "[dim]Soperator worker profile controls whether the fresh "
                "production bundle uses CPU-only, GPU-only, or mixed worker "
                "NodeSets before MK8s fields and deployment-testing prompts.[/dim]"
            )
            if soperator_profile is None:
                try:
                    soperator_profile = _prompt_soperator_profile()
                except _WizardQuitRequested:
                    optional_wizard_mode = False
                    soperator_profile = _default_soperator_profile_name()
        elif _SOPERATOR_APP_ID in selected_apps_raw:
            soperator_profile = soperator_profile or _default_soperator_profile_name()
        selected_infra_before_soperator_expansion = set(selected_infra_raw)
        selected_apps_before_soperator_expansion = set(selected_apps_raw)
        selected_infra_raw = _expand_soperator_component_selection(
            selected_infra=selected_infra_raw,
            selected_apps=selected_apps_raw,
            infra_entries=infra_entries,
        )
        selected_apps_raw = _expand_soperator_app_selection(
            selected_apps=selected_apps_raw,
            app_entries=app_entries,
        )
        _print_soperator_selection_adjustments(
            selected_infra_before=selected_infra_before_soperator_expansion,
            selected_apps_before=selected_apps_before_soperator_expansion,
            selected_infra_after=selected_infra_raw,
            selected_apps_after=selected_apps_raw,
        )
        app_target_issue = _app_selection_without_cluster_target_issue(
            selected_infra=selected_infra_raw,
            selected_apps=selected_apps_raw,
            infra_entries=infra_entries,
        )
        if app_target_issue:
            raise RuntimeError(app_target_issue)

        dependency_seed_payload = _dependency_seed_payload(
            client_name=resolved_client_name,
            tenant_id=resolved_tenant_id,
            project_id=resolved_project_id,
            region_id=resolved_region_id,
            email=resolved_email,
            selected_infra=selected_infra_raw,
            selected_apps=selected_apps_raw,
            infra_entries=infra_entries,
            app_entries=app_entries,
            existing_payload=None,
            merge_existing=False,
            app_version_overrides=app_version_overrides,
        )

        dependency_resolution_started = time.monotonic()
        if selected_apps_raw:
            with console.status("[cyan]Resolving app chart dependencies...[/cyan]"):
                selected_infra, selected_apps = _normalize_component_dependencies(
                    selected_infra=selected_infra_raw,
                    selected_apps=selected_apps_raw,
                    infra_entries=infra_entries,
                    app_entries=app_entries,
                    payload_for_app_chart_deps=dependency_seed_payload,
                )
        else:
            selected_infra, selected_apps = _normalize_component_dependencies(
                selected_infra=selected_infra_raw,
                selected_apps=selected_apps_raw,
                infra_entries=infra_entries,
                app_entries=app_entries,
                payload_for_app_chart_deps=dependency_seed_payload,
            )
        dependency_resolution_elapsed = time.monotonic() - dependency_resolution_started
        if dependency_resolution_elapsed >= 1:
            console.print(
                "[dim]App dependency resolution finished in "
                f"{dependency_resolution_elapsed:.1f}s[/dim]"
            )
        source_validated_app_ids: set[str] = set()
        if validate_sources and selected_apps:
            _validate_component_sources_or_raise(
                selected_app_ids=selected_apps,
                include_infra=False,
            )
            source_validated_app_ids.update(selected_apps)

        wizard_completed = True
        starter_payload = _starter_component_payload(
            client_name=resolved_client_name,
            tenant_id=resolved_tenant_id,
            project_id=resolved_project_id,
            region_id=resolved_region_id,
            email=resolved_email,
            selected_infra=selected_infra,
            selected_apps=selected_apps,
            infra_entries=infra_entries,
            app_entries=app_entries,
            app_namespace_overrides=app_namespace_overrides,
            app_releasename_overrides=app_releasename_overrides,
            app_version_overrides=app_version_overrides,
        )
        if soperator_profile is not None:
            _apply_soperator_profile_to_payload(
                starter_payload,
                profile=soperator_profile,
            )
        _apply_vpc_ref_overrides(
            payload=starter_payload,
            selected_infra=selected_infra,
            network_refs=network_refs_opt,
            subnet_refs=subnet_refs_opt,
        )
        _apply_vpc_id_overrides(
            payload=starter_payload,
            selected_infra=selected_infra,
            network_ids=network_ids_opt,
            subnet_ids=subnet_ids_opt,
        )
        final_payload = starter_payload
        _materialize_singleton_provider_defaults(
            payload=final_payload,
            selected_infra=selected_infra,
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_mk8s_image_defaults(
            payload=final_payload,
            selected_infra=selected_infra,
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_vm_image_defaults(
            payload=final_payload,
            selected_infra=selected_infra,
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        materialize_compute_boot_disk_defaults(
            final_payload,
            provider_lookup=provider_lookup,
        )
        _materialize_create_soperator_component_defaults(final_payload)
        selected_apps, mysterybox_eso_app_labels = _ensure_mysterybox_eso_app_dependency_selection(
            final_payload,
            selected_apps=selected_apps,
            app_entries=app_entries,
        )
        _print_mysterybox_eso_app_dependency_adjustment(mysterybox_eso_app_labels)
        if interactive_mode:
            _print_component_selection_summary(
                selected_infra=selected_infra,
                selected_apps=selected_apps,
                infra_entries=infra_entries,
                app_entries=app_entries,
                payload=final_payload,
            )

        if interactive_mode and optional_wizard_mode:
            field_wizard_kwargs: dict[str, Any] = {}
            if soperator_profile is not None:
                field_wizard_kwargs["skip_soperator_profile_prompt"] = True
            field_wizard_kwargs["align_infra_resource_names_before_apps"] = True
            field_wizard_kwargs["prompt_app_version_before_app_config"] = True
            config_yaml_override, wizard_completed = _run_component_field_wizard(
                config_yaml=yaml.safe_dump(final_payload, sort_keys=False),
                selected_infra=selected_infra,
                selected_apps=selected_apps,
                infra_entries=infra_entries,
                app_entries=app_entries,
                provider_lookup=provider_lookup,
                **field_wizard_kwargs,
            )
            parsed_override = yaml.safe_load(config_yaml_override) or {}
            if not isinstance(parsed_override, dict):
                raise RuntimeError("Updated config payload must be a mapping")
            final_payload = parsed_override
            _materialize_planned_vpc_binding_tokens(final_payload)
            selected_apps = _enabled_ids_from_runtime_payload(
                payload=final_payload,
                entries=app_entries,
            )

        _materialize_create_soperator_component_defaults(final_payload)
        selected_apps, mysterybox_eso_app_labels = (
            _materialize_soperator_child_chart_secret_dependencies(
                final_payload,
                selected_apps=selected_apps,
                app_entries=app_entries,
            )
        )
        _print_mysterybox_eso_app_dependency_adjustment(mysterybox_eso_app_labels)
        _materialize_mk8s_image_defaults(
            payload=final_payload,
            selected_infra=selected_infra,
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_vm_image_defaults(
            payload=final_payload,
            selected_infra=selected_infra,
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_singleton_provider_defaults(
            payload=final_payload,
            selected_infra=selected_infra,
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_planned_vpc_binding_tokens(final_payload)
        materialize_compute_boot_disk_defaults(
            final_payload,
            provider_lookup=provider_lookup,
        )
        if not interactive_mode:
            _require_vpc_networking_for_noninteractive(
                payload=final_payload,
                selected_infra=selected_infra,
                infra_entries=infra_entries,
                provider_lookup=provider_lookup,
            )
        gpu_app_selection = resolve_mk8s_gpu_app_selection(
            final_payload,
            selected_app_ids=selected_apps,
            app_entries=app_entries,
        )
        if gpu_app_selection.issues:
            raise RuntimeError(
                "MK8s GPU app defaults are incomplete:\n  - "
                + "\n  - ".join(gpu_app_selection.issues)
            )
        if gpu_app_selection.auto_enabled_app_ids:
            selected_apps = set(gpu_app_selection.selected_app_ids)
            auto_enabled_seed = _starter_component_payload(
                client_name=resolved_client_name,
                tenant_id=resolved_tenant_id,
                project_id=resolved_project_id,
                region_id=resolved_region_id,
                email=resolved_email,
                selected_infra=selected_infra,
                selected_apps=selected_apps,
                infra_entries=infra_entries,
                app_entries=app_entries,
                app_namespace_overrides=app_namespace_overrides,
                app_releasename_overrides=app_releasename_overrides,
                app_version_overrides=app_version_overrides,
            )
            _ensure_payload_contains_component_rows(
                payload=final_payload,
                seed_payload=auto_enabled_seed,
            )
            console.print(
                f"{warning_markup('Adjusted component selection:')} enabling "
                + ", ".join(f"'apps:{item}'" for item in gpu_app_selection.auto_enabled_app_ids)
                + " because the selected MK8s GPU configuration requires them."
            )
        if ensure_mk8s_gpu_app_rows(final_payload, app_entries=app_entries):
            selected_apps = _enabled_ids_from_runtime_payload(
                payload=final_payload,
                entries=app_entries,
            )
        observability_selection = resolve_observability_app_selection(
            final_payload,
            selected_app_ids=selected_apps,
            app_entries=app_entries,
        )
        if observability_selection.issues:
            raise RuntimeError(
                "Observability app defaults are incomplete:\n  - "
                + "\n  - ".join(observability_selection.issues)
            )
        if observability_selection.auto_enabled_app_ids:
            selected_apps = set(observability_selection.selected_app_ids)
            auto_enabled_seed = _starter_component_payload(
                client_name=resolved_client_name,
                tenant_id=resolved_tenant_id,
                project_id=resolved_project_id,
                region_id=resolved_region_id,
                email=resolved_email,
                selected_infra=selected_infra,
                selected_apps=selected_apps,
                infra_entries=infra_entries,
                app_entries=app_entries,
                app_namespace_overrides=app_namespace_overrides,
                app_releasename_overrides=app_releasename_overrides,
                app_version_overrides=app_version_overrides,
            )
            _ensure_payload_contains_component_rows(
                payload=final_payload,
                seed_payload=auto_enabled_seed,
            )
            console.print(
                f"{warning_markup('Adjusted component selection:')} enabling "
                + ", ".join(
                    f"'apps:{item}'" for item in observability_selection.auto_enabled_app_ids
                )
                + " because the selected observability configuration requires them."
            )
        _align_new_infra_instance_ids_with_resource_names(final_payload)
        _materialize_create_soperator_component_defaults(final_payload)
        materialize_compute_boot_disk_defaults(
            final_payload,
            provider_lookup=provider_lookup,
        )
        if ensure_mysterybox_eso_app_rows(final_payload, app_entries=app_entries):
            selected_apps = _enabled_ids_from_runtime_payload(
                payload=final_payload,
                entries=app_entries,
            )
        selected_apps, nfs_csi_app_labels = _ensure_nfs_csi_app_dependency_selection(
            final_payload,
            selected_apps=selected_apps,
            app_entries=app_entries,
        )
        _print_nfs_csi_app_dependency_adjustment(nfs_csi_app_labels)
        materialize_mk8s_gpu_app_values(final_payload)
        materialize_observability_infra_values(final_payload)
        _prune_mk8s_node_group_defaults_without_soperator(
            final_payload,
            infra_entries=infra_entries,
        )
        _refresh_soperator_registration_fingerprints(final_payload)

        create_required_field_issues = (
            _wizard_followup_required_field_issues(
                payload=final_payload,
                infra_entries=infra_entries,
            )
            if interactive_mode and (not optional_wizard_mode or not wizard_completed)
            else []
        )
        if create_required_field_issues:
            _print_incomplete_wizard_no_write_warning(
                issues=create_required_field_issues,
                message="No project config or generated output was written.",
                preserved_path=existing_config_path.parent if had_existing_config else None,
                skipped_path=existing_config_path.parent if not had_existing_config else None,
            )
            raise typer.Exit(code=1)
        _prune_redundant_app_chart_default_values(
            payload=final_payload,
            app_entries=app_entries,
        )
        _refresh_soperator_registration_fingerprints(final_payload)
        if validate_sources:
            selected_apps = _validate_final_enabled_app_sources_or_raise(
                payload=final_payload,
                app_entries=app_entries,
                already_validated_app_ids=source_validated_app_ids,
            )
            requested_version_app_ids = set(app_version_overrides)
            requested_version_app_ids.update(
                _app_chart_ids_with_non_catalog_versions(
                    payload=final_payload,
                    app_entries=app_entries,
                )
            )
            _validate_requested_app_chart_versions_or_raise(
                payload=final_payload,
                candidate_app_ids=requested_version_app_ids,
            )
        selected_infra = _enabled_ids_from_runtime_payload(
            payload=final_payload,
            entries=infra_entries,
        )
        selected_apps = _enabled_ids_from_runtime_payload(
            payload=final_payload,
            entries=app_entries,
        )

        result = _scaffold_instance(
            base_path=base_path,
            client_name=resolved_client_name,
            tenant_folder=resolved_tenant_folder,
            project_folder=resolved_project_folder,
            tenant_id=resolved_tenant_id,
            project_id=resolved_project_id,
            region_id=resolved_region_id,
            email=resolved_email,
            selected_infra=selected_infra,
            selected_apps=selected_apps,
            infra_entries=infra_entries,
            app_entries=app_entries,
            force=force or had_existing_config,
            config_yaml=yaml.safe_dump(final_payload, sort_keys=False),
        )
        if _SOPERATOR_LIFECYCLE_INTERNAL.get():
            _SOPERATOR_INSTALL_CONFIG_RESULT.set(result.config_path.resolve())
        gitignore_result = _ensure_deployments_gitignore(
            deployments_root=result.deployments_root,
        )

        console.print(f"Deployments root: {result.deployments_root}")
        if gitignore_result.path is not None:
            if gitignore_result.wrote:
                console.print(f"Ensured deployments .gitignore: {gitignore_result.path}")
            else:
                console.print(f"Deployments .gitignore up-to-date: {gitignore_result.path}")
        if result.wrote_config:
            if had_existing_config:
                console.print(f"Overwritten project: {result.project_path}")
            else:
                console.print(f"Created project: {result.project_path}")
        else:
            if had_existing_config:
                console.print(
                    f"Project already matched the overwrite target: {result.project_path}"
                )
            else:
                console.print(f"Config up-to-date: {result.config_path}")
        if validate_config:
            _run_runtime_validation(
                config_path=result.config_path,
                strict=False,
                title="Post-create validation",
            )
        quota_report = _warn_on_live_quota_issues(final_payload, phase="create")
        if quota_report.has_confirmed_insufficiency:
            console.print(
                f"{warning_markup('Create completed with quota warnings.')} "
                "Render can continue, but deploy will fail until the required quota is available "
                "and any selected GPU shape has matching Capacity Dashboard capacity."
            )
            _print_quota_remediation_hint(result.config_path, quota_report)
        if not validate_config:
            _print_mk8s_gpu_validation_warnings(final_payload)
        display_payload = final_payload
        with suppress(Exception):
            persisted_payload = yaml.safe_load(result.config_path.read_text(encoding="utf-8"))
            if isinstance(persisted_payload, dict):
                display_payload = persisted_payload
        display_selected_infra = _enabled_ids_from_runtime_payload(
            payload=display_payload,
            entries=infra_entries,
        )
        display_selected_apps = _enabled_ids_from_runtime_payload(
            payload=display_payload,
            entries=app_entries,
        )
        console.print(
            "Enabled infra components: "
            + (", ".join(sorted(display_selected_infra)) if display_selected_infra else "(none)")
        )
        console.print(
            "Enabled apps components: "
            + (", ".join(sorted(display_selected_apps)) if display_selected_apps else "(none)")
        )
        if _active_chart_count(final_payload) > 0 and _config_uses_private_cluster_handoff(
            final_payload
        ):
            console.print(f"[yellow]NOTE:[/yellow] {_private_cluster_handoff_note()}")
        console.print(f"Ensured generated skeleton: {result.config_path.parent / 'generated'}")
        _print_create_next_steps(result.config_path)
        if gitignore_result.inside_git_repo:
            console.print(
                f"{warning_markup('Security warning:')} keep this customer repository private "
                "because the deployments root contains sensitive operational metadata."
            )
    except typer.Exit:
        raise
    except (KeyboardInterrupt, EOFError, typer.Abort):
        console.print("[yellow]Cancelled by user[/yellow].")
        raise typer.Exit(code=130) from None
    except Exception as exc:  # pragma: no cover - CLI surface
        _exit_with_error(exc)


@component_app.command(
    "list",
    short_help="Use --config CONFIG_YAML to inspect enabled instances and available catalog components.",
    epilog=(
        "Examples: "
        "nebius-cxcli component list --config ./deployments/tenant/project/config.yaml "
        "(shows enabled mk8s/sfs/soperator instances and their target_ref bindings)."
    ),
)
def component_list_command(
    config_path: Annotated[
        Path | None,
        typer.Option(
            "--config",
            metavar="CONFIG_YAML",
            help=_COMPONENT_CONFIG_OPTION_HELP,
        ),
    ] = None,
) -> None:
    """List enabled component instances and reusable catalog component types.

    Flags:

      --config <config.yaml>

    Examples:

      nebius-cxcli component list --config <config.yaml>
    """
    try:
        config_path = _require_component_config_option(config_path)
        _config, _paths = _load_context_readonly(config_path)
        payload = to_plain_data(_config)
        if not isinstance(payload, dict):
            raise RuntimeError("config.yaml root must be a mapping")
        infra_entries = _with_infra_provider_groups(component_entries("infra"))
        app_entries = component_entries("apps")
        enabled_infra_specs = _enabled_component_instance_specs(
            payload,
            scope="infra",
            entries=infra_entries,
        )
        enabled_apps_specs = _enabled_component_instance_specs(
            payload,
            scope="apps",
            entries=app_entries,
        )

        console.print(f"Config: {config_path.resolve()}")
        console.print()

        sections = (
            ("Enabled infra component instances", enabled_infra_specs),
            ("Enabled apps component instances", enabled_apps_specs),
        )
        for heading, specs in sections:
            console.print(f"{heading}:")
            if not specs:
                console.print("  (none)")
                console.print()
            else:
                for entry, row in specs:
                    target_suffix = ""
                    if entry.scope == "apps":
                        target_ref = app_chart_target_ref(row)
                        if target_ref:
                            target_suffix = f" on {target_ref}"
                    console.print(
                        f"  {_component_instance_selector_label(entry, instance_id=str(row['instance_id']))}"
                        f"{target_suffix}"
                        f"  ({entry.description})"
                    )
                console.print()

        available_sections = (
            ("Available infra components", infra_entries),
            ("Available apps components", app_entries),
        )
        for heading, entries in available_sections:
            console.print(f"{heading}:")
            if not entries:
                console.print("  (none)")
                console.print()
                continue
            for entry in entries:
                console.print(
                    f"  {_component_selector_label(entry, scope=entry.scope)}"
                    f"  ({entry.description})"
                )
            console.print()
    except Exception as exc:  # pragma: no cover - CLI surface
        _exit_with_error(exc)


@component_app.command(
    "add",
    short_help="Add component selectors to required --config CONFIG_YAML.",
    epilog=(
        "Examples: "
        "nebius-cxcli component add apps:external-secrets@target-mk8s-prod "
        "--config ./deployments/tenant/project/config.yaml --no-interactive "
        "(adds External Secrets to a specific MK8s target_ref); "
        "nebius-cxcli component add managed-postgresql object-storage@logs-bucket "
        "--config ./deployments/tenant/project/config.yaml --no-interactive "
        "(adds multiple components in one call). Soperator lifecycle changes are rejected; "
        "use the `soperator` command group."
    ),
)
def component_add_command(
    component_ids: Annotated[
        list[str] | None,
        typer.Argument(
            metavar="[COMPONENT_SELECTOR]...",
            help=(
                "Optional infra module or app chart selector(s) to add. Use "
                "'<id>', 'infra:<id>', 'apps:<id>', 'all', 'none', or "
                "'<id>@<resource-name-or-target-id>'. Omit to prompt "
                "interactively. Pass the project config with --config; config.yaml "
                "is not a positional argument. The app scope prefix is plural "
                "'apps:', not 'app:'. "
                "For target-bound app charts, use 'apps:<app-id>@<target-id>' "
                "(or bare '<app-id>@<target-id>' when unambiguous); one chart row "
                "is allowed per app id and cluster target, and the suffix becomes "
                "the app row instance_id. Infra-only interactive adds are valid. "
                "In interactive mode, scalar named infra modules prompt for the "
                "resource name first and derive the saved instance_id from that "
                "name. In non-interactive mode, bare infra selectors create the "
                "default named row when absent; use '<id>@<resource-name>' to "
                "choose the resource name or create another named infra row. "
                "Apps are Helm charts and require an enabled MK8s target in the "
                "same project. Soperator is not a generic component mutation; use "
                "`nebius-cxcli soperator install` or `soperator onboard`."
            ),
        ),
    ] = None,
    config_path: Annotated[
        Path | None,
        typer.Option(
            "--config",
            metavar="CONFIG_YAML",
            help=_COMPONENT_CONFIG_OPTION_HELP,
        ),
    ] = None,
    no_interactive: Annotated[
        bool,
        typer.Option(
            "--no-interactive",
            help="Disable interactive selection and field prompts.",
        ),
    ] = False,
    app_namespace_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--app-namespace",
            help=(
                "Override added app namespace with '<app-id>=<namespace>' "
                "(repeatable or comma-separated). Applies to app rows added by this operation."
            ),
        ),
    ] = None,
    app_releasename_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--app-releasename",
            help=(
                "Override added app release name with '<app-id>=<release-name>' "
                "(repeatable or comma-separated). Applies to app rows added by this operation."
            ),
        ),
    ] = None,
    app_version_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--app-version",
            help=(
                "Override added app chart version with '<app-id>=<chart-version>' "
                "(repeatable or comma-separated). Defaults come from component_sources.yaml; "
                "with source validation enabled, the requested chart version must resolve before "
                "component add writes config.yaml."
            ),
        ),
    ] = None,
    network_ids_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--network-id",
            help=(
                "VPC network ID for added network-attached infra. Use a bare value only when "
                "one applicable infra component is added, or scope it as "
                "'infra:<component-id>@<resource-name>=<vpcnetwork-id>'. Repeatable."
            ),
        ),
    ] = None,
    subnet_ids_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--subnet-id",
            help=(
                "VPC subnet ID for added subnet-attached infra. Use a bare value only when "
                "one applicable infra component is added, or scope it as "
                "'infra:<component-id>@<resource-name>=<vpcsubnet-id>'. Repeatable."
            ),
        ),
    ] = None,
    network_refs_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--network-ref",
            help=(
                "Planned VPC network ref for added network-attached infra. Use a bare value only when "
                "one applicable infra component is added, or scope it as "
                "'infra:<component-id>@<resource-name>=vpc@<vpc-instance>.network_id'. Repeatable."
            ),
        ),
    ] = None,
    subnet_refs_opt: Annotated[
        list[str] | None,
        typer.Option(
            "--subnet-ref",
            help=(
                "Planned VPC subnet ref for added subnet-attached infra. Use a bare value only when "
                "one applicable infra component is added, or scope it as "
                "'infra:<component-id>@<resource-name>=vpc@<vpc-instance>.subnets.<subnet-key>.id'. Repeatable."
            ),
        ),
    ] = None,
    validate_sources: Annotated[
        bool,
        typer.Option(
            "--validate-sources/--no-validate-sources",
            help=(
                "Validate infra sources first, then only app chart sources selected "
                "or auto-enabled by this add, with a final check for apps "
                "auto-enabled after the wizard before component add writes config "
                "(enabled by default)."
            ),
        ),
    ] = True,
) -> None:
    """Add source-defined components to an existing project config.yaml.

    Flags:

      --config <config.yaml>
      --no-interactive
      --app-namespace <app-id>=<namespace>
      --app-releasename <app-id>=<release-name>
      --app-version <app-id>=<chart-version>
      --network-id <id-or-scoped-id>
      --subnet-id <id-or-scoped-id>
      --network-ref <ref-or-scoped-ref>
      --subnet-ref <ref-or-scoped-ref>
      --validate-sources --no-validate-sources

    Selector notes:

      Pass the project config with --config <config.yaml>; config.yaml is not a
      positional argument.

      App selectors use the plural apps:<chart-id> scope, for example
      apps:external-secrets@mk8s. The singular app:<chart-id> scope is invalid.

    Examples:

      nebius-cxcli component add --config <config.yaml>

      nebius-cxcli component add infra:vm --config <config.yaml>

      nebius-cxcli component add infra:vm@worker-vm --config <config.yaml> --no-interactive --network-id infra:vm@worker-vm=vpcnetwork-... --subnet-id infra:vm@worker-vm=vpcsubnet-...

      nebius-cxcli component add infra:vm@worker-vm --config <config.yaml> --no-interactive --network-ref infra:vm@worker-vm=vpc@worker-vpc.network_id --subnet-ref infra:vm@worker-vm=vpc@worker-vpc.subnets.worker.id

      nebius-cxcli component add managed-postgresql object-storage@logs-bucket --config <config.yaml> --no-interactive

      nebius-cxcli component add apps:external-secrets@training-cluster --config <config.yaml> --no-interactive

      nebius-cxcli component add apps:gateway-helm@serving-cluster --config <config.yaml> --no-interactive
    """
    try:
        _require_generic_selection_excludes_soperator(
            component_ids,
            command="component add",
        )
        config_path = _require_component_config_option(config_path)
        _config, _paths = _load_context(config_path)
        payload = _load_config_payload(config_path.resolve())
        if validate_sources:
            _validate_component_sources_or_raise(selected_app_ids=set())
        interactive_mode = not no_interactive
        client_name, tenant_id, project_id, region_id, email = _identity_values_from_payload(
            payload
        )
        app_namespace_overrides = _parse_component_value_overrides(
            raw_values=app_namespace_opt,
            option_name="--app-namespace",
        )
        app_releasename_overrides = _parse_component_value_overrides(
            raw_values=app_releasename_opt,
            option_name="--app-releasename",
        )
        app_version_overrides = _parse_component_value_overrides(
            raw_values=app_version_opt,
            option_name="--app-version",
        )
        provider_lookup = ProviderOptionLookup()
        provider_scope_validated = False

        def _ensure_provider_scope_validated() -> None:
            nonlocal tenant_id, project_id, provider_scope_validated
            if provider_scope_validated:
                return
            if interactive_mode:
                console.print(
                    "[dim]Validating Nebius tenant/project scope before "
                    "provider-backed field prompts...[/dim]"
                )
            tenant_id, project_id = _validate_tenant_project_ids_or_prompt(
                tenant_id=tenant_id,
                project_id=project_id,
                interactive=False,
                provider_lookup=provider_lookup,
            )
            provider_scope_validated = True

        infra_entries = _with_infra_provider_groups(component_entries("infra"))
        app_entries = tuple(
            entry for entry in component_entries("apps") if entry.id != _SOPERATOR_APP_ID
        )
        enabled_infra = _enabled_ids_from_runtime_payload(payload=payload, entries=infra_entries)
        enabled_apps = _enabled_ids_from_runtime_payload(payload=payload, entries=app_entries)
        initially_enabled_app_rows = _enabled_app_row_identities_after_single_target_bindings(
            payload
        )
        source_validated_app_ids: set[str] = set()

        raw_tokens = _split_multi_value_tokens(component_ids)
        if not raw_tokens and interactive_mode:
            while True:
                try:
                    requested_infra = _prompt_component_scope_selection(
                        action="add",
                        scope="infra",
                        entries=infra_entries,
                    )
                except (_WizardBackRequested, _WizardQuitRequested):
                    console.print("No component changes applied.")
                    return
                requested_apps: set[str] = set()
                select_apps = not requested_infra
                if requested_infra:
                    apps_decision = _wizard_continue_phase(
                        "Select apps components to add too?",
                        default=None,
                        allow_back=True,
                    )
                    if _wizard_phase_back_requested(apps_decision):
                        continue
                    if _wizard_phase_stop_requested(apps_decision):
                        console.print("No component changes applied.")
                        return
                    select_apps = bool(apps_decision)
                if select_apps:
                    try:
                        requested_apps = _prompt_component_scope_selection(
                            action="add",
                            scope="apps",
                            entries=app_entries,
                        )
                    except _WizardBackRequested:
                        continue
                    except _WizardQuitRequested:
                        console.print("No component changes applied.")
                        return
                app_target_issue = _app_selection_without_cluster_target_issue(
                    selected_infra=set(enabled_infra) | requested_infra,
                    selected_apps=set(enabled_apps) | requested_apps,
                    infra_entries=infra_entries,
                )
                if app_target_issue:
                    console.print(f"{warning_markup('Invalid app selection:')} {app_target_issue}")
                    continue
                break
            add_targets = [
                *(
                    _ComponentAddTarget(
                        scope="infra",
                        component_id=component_id,
                        allocate_new_infra_instance_if_enabled=True,
                    )
                    for component_id in sorted(requested_infra)
                ),
                *(
                    _ComponentAddTarget(scope="apps", component_id=component_id)
                    for component_id in sorted(requested_apps)
                ),
            ]
        elif not raw_tokens and not interactive_mode:
            raise RuntimeError(
                "Specify at least one component id, or omit --no-interactive to choose components interactively."
            )
        else:
            add_targets = _resolve_component_add_targets(
                tokens=raw_tokens,
                infra_entries=infra_entries,
                app_entries=app_entries,
            )

        if not add_targets:
            console.print("No components selected for add.")
            return

        requested_infra_types = {
            target.component_id for target in add_targets if target.scope == "infra"
        }
        requested_apps_types = {
            target.component_id for target in add_targets if target.scope == "apps"
        }
        selected_infra_raw = set(enabled_infra) | requested_infra_types
        selected_apps_raw = set(enabled_apps) | requested_apps_types
        app_target_issue = _app_selection_without_cluster_target_issue(
            selected_infra=selected_infra_raw,
            selected_apps=selected_apps_raw,
            infra_entries=infra_entries,
        )
        if app_target_issue:
            raise RuntimeError(app_target_issue)
        dependency_seed_payload = _dependency_seed_payload(
            client_name=client_name,
            tenant_id=tenant_id,
            project_id=project_id,
            region_id=region_id,
            email=email,
            selected_infra=selected_infra_raw,
            selected_apps=selected_apps_raw,
            infra_entries=infra_entries,
            app_entries=app_entries,
            existing_payload=payload,
            merge_existing=True,
            app_version_overrides=app_version_overrides,
        )
        dependency_resolution_started = time.monotonic()
        app_chart_dependency_payload = dependency_seed_payload if requested_apps_types else None
        selected_infra, selected_apps = _normalize_component_dependencies(
            selected_infra=selected_infra_raw,
            selected_apps=selected_apps_raw,
            infra_entries=infra_entries,
            app_entries=app_entries,
            payload_for_app_chart_deps=app_chart_dependency_payload,
        )
        dependency_resolution_elapsed = time.monotonic() - dependency_resolution_started
        if dependency_resolution_elapsed >= 1:
            console.print(
                "[dim]App dependency resolution finished in "
                f"{dependency_resolution_elapsed:.1f}s[/dim]"
            )

        auto_added_infra_types = (selected_infra - enabled_infra) - requested_infra_types
        auto_added_apps_types = (selected_apps - enabled_apps) - requested_apps_types
        apps_to_validate = (selected_apps - enabled_apps) | requested_apps_types
        if validate_sources and apps_to_validate:
            _validate_component_sources_or_raise(
                selected_app_ids=apps_to_validate,
                include_infra=False,
            )
            source_validated_app_ids.update(apps_to_validate)
        add_targets.extend(
            _ComponentAddTarget(scope="infra", component_id=component_id)
            for component_id in sorted(auto_added_infra_types)
        )
        add_targets.extend(
            _ComponentAddTarget(scope="apps", component_id=component_id)
            for component_id in sorted(auto_added_apps_types)
        )

        if interactive_mode:
            resolved_add_targets = _prompt_infra_add_resource_names(
                payload=payload,
                add_targets=add_targets,
                infra_entries=infra_entries,
            )
            if resolved_add_targets is None:
                console.print("No component changes applied.")
                return
            add_targets = resolved_add_targets

        if interactive_mode and not _wizard_continue_phase(
            "Add selected components to config.yaml now?",
            default=True,
        ):
            console.print("No component changes applied.")
            return

        next_payload = copy.deepcopy(payload)
        _scope_rows(next_payload, scope="infra")
        _scope_rows(next_payload, scope="apps")

        added_infra_instances: list[str] = []
        added_apps_instances: list[str] = []
        added_apps_selectors: list[str] = []
        added_infra_labels: list[str] = []
        added_apps_labels: list[str] = []
        added_app_rows: list[dict[str, Any]] = []
        skipped_add_labels: list[str] = []
        infra_lookup = {entry.id: entry for entry in infra_entries}
        app_lookup = {entry.id: entry for entry in app_entries}
        for target in add_targets:
            entry = (
                infra_lookup.get(target.component_id)
                if target.scope == "infra"
                else app_lookup.get(target.component_id)
            )
            if entry is None:
                raise RuntimeError(
                    f"Component '{target.component_id}' is no longer available in the active catalog."
                )
            existing_label = _enabled_component_add_label(
                payload=next_payload,
                entry=entry,
                requested_instance_id=target.requested_instance_id,
                allow_unassigned_app_target=interactive_mode,
            )
            if (
                existing_label
                and target.scope == "infra"
                and target.requested_instance_id is None
                and target.allocate_new_infra_instance_if_enabled
                and interactive_mode
            ):
                existing_label = None
            if existing_label:
                if existing_label not in skipped_add_labels:
                    skipped_add_labels.append(existing_label)
                continue
            row = _append_component_instance_row(
                payload=next_payload,
                entry=entry,
                requested_instance_id=target.requested_instance_id,
                allow_unassigned_app_target=interactive_mode,
            )
            instance_id = component_instance_id(row)
            if target.scope == "infra":
                added_infra_instances.append(instance_id)
                added_infra_labels.append(component_instance_label(entry.id, instance_id))
            else:
                added_apps_instances.append(instance_id)
                added_app_rows.append(row)
                app_label = component_instance_label(entry.id, instance_id)
                added_apps_selectors.append(app_label)
                added_apps_labels.append(app_label)
        if not added_infra_instances and not added_apps_instances:
            console.print(f"Config up-to-date: {config_path.resolve()}")
            if skipped_add_labels:
                console.print(
                    f"{warning_markup('Skipped already-enabled components:')} "
                    + ", ".join(skipped_add_labels)
                )
            _print_component_edit_config_only_note()
            _print_component_edit_next_steps(config_path)
            return

        _materialize_single_target_app_bindings(next_payload)
        _raise_if_soperator_production_service_layout_invalid(next_payload)
        _ensure_provider_scope_validated()
        _seed_infra_project_scope_defaults(
            payload=next_payload,
            infra_entries=infra_entries,
        )
        _seed_infra_shared_admin_ssh_public_key(
            payload=next_payload,
            infra_entries=infra_entries,
        )
        materialize_shared_defaults(
            payload=next_payload,
            infra_entries=infra_entries,
            app_entries=app_entries,
        )
        _apply_vpc_ref_overrides(
            payload=next_payload,
            selected_infra=set(added_infra_instances),
            network_refs=network_refs_opt,
            subnet_refs=subnet_refs_opt,
        )
        _apply_vpc_id_overrides(
            payload=next_payload,
            selected_infra=set(added_infra_instances),
            network_ids=network_ids_opt,
            subnet_ids=subnet_ids_opt,
        )
        wizard_completed = True
        _materialize_singleton_provider_defaults(
            payload=next_payload,
            selected_infra=set(added_infra_instances),
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_mk8s_image_defaults(
            payload=next_payload,
            selected_infra=set(added_infra_instances),
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_vm_image_defaults(
            payload=next_payload,
            selected_infra=set(added_infra_instances),
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        materialize_compute_boot_disk_defaults(
            next_payload,
            provider_lookup=provider_lookup,
        )
        selected_apps, mysterybox_eso_app_labels = _ensure_mysterybox_eso_app_dependency_selection(
            next_payload,
            selected_apps=selected_apps,
            app_entries=app_entries,
        )
        if mysterybox_eso_app_labels:
            for app_label in mysterybox_eso_app_labels:
                if app_label not in added_apps_selectors:
                    added_apps_selectors.append(app_label)
                if app_label not in added_apps_labels:
                    added_apps_labels.append(app_label)
            _print_mysterybox_eso_app_dependency_adjustment(mysterybox_eso_app_labels)
        config_yaml_override = yaml.safe_dump(next_payload, sort_keys=False)
        if interactive_mode:
            skipped_components: set[tuple[ComponentScope, str, str]] = set()
            config_yaml_override, wizard_completed = _run_component_field_wizard(
                config_yaml=config_yaml_override,
                selected_infra=set(added_infra_instances),
                selected_apps=set(added_apps_selectors),
                infra_entries=infra_entries,
                app_entries=app_entries,
                provider_lookup=provider_lookup,
                skipped_components=skipped_components,
                prompt_app_version_before_app_config=True,
            )
            parsed_override = yaml.safe_load(config_yaml_override) or {}
            if not isinstance(parsed_override, dict):
                raise RuntimeError("Updated config payload must be a mapping")
            next_payload = parsed_override
            _materialize_planned_vpc_binding_tokens(next_payload)
            skipped_infra_labels, skipped_infra_app_labels = (
                _remove_skipped_component_add_infra_rows(
                    payload=next_payload,
                    skipped_components=skipped_components,
                    added_infra_labels=added_infra_labels,
                    infra_entries=infra_entries,
                )
            )
            if skipped_infra_labels:
                skipped_infra_label_set = set(skipped_infra_labels)
                skipped_infra_app_label_set = set(skipped_infra_app_labels)
                console.print(
                    f"{warning_markup('Skipped newly added infra components:')} "
                    + ", ".join(skipped_infra_labels)
                )
                added_infra_labels = [
                    label for label in added_infra_labels if label not in skipped_infra_label_set
                ]
                added_infra_instances = [
                    component_instance_id(row)
                    for row in next_payload.get("infra", {}).get("components", [])
                    if isinstance(row, dict)
                    and component_instance_label(component_type_id(row), component_instance_id(row))
                    in set(added_infra_labels)
                ]
                if skipped_infra_app_label_set:
                    added_apps_selectors = [
                        label
                        for label in added_apps_selectors
                        if label not in skipped_infra_app_label_set
                    ]
                    added_apps_labels = [
                        label
                        for label in added_apps_labels
                        if label not in skipped_infra_app_label_set
                    ]
                    added_app_rows = [
                        row
                        for row in added_app_rows
                        if component_instance_label(
                            component_type_id(row), component_instance_id(row)
                        )
                        not in skipped_infra_app_label_set
                    ]
                    added_apps_instances = [component_instance_id(row) for row in added_app_rows]
                if not added_infra_instances and not added_apps_selectors:
                    console.print("No component changes applied.")
                    return
            selected_infra = _enabled_ids_from_runtime_payload(
                payload=next_payload,
                entries=infra_entries,
            )
            selected_apps = _enabled_ids_from_runtime_payload(
                payload=next_payload,
                entries=app_entries,
            )

        selected_apps, mysterybox_eso_app_labels = _ensure_mysterybox_eso_app_dependency_selection(
            next_payload,
            selected_apps=selected_apps,
            app_entries=app_entries,
        )
        if mysterybox_eso_app_labels:
            for app_label in mysterybox_eso_app_labels:
                if app_label not in added_apps_selectors:
                    added_apps_selectors.append(app_label)
                if app_label not in added_apps_labels:
                    added_apps_labels.append(app_label)
            _print_mysterybox_eso_app_dependency_adjustment(mysterybox_eso_app_labels)
        _materialize_mk8s_image_defaults(
            payload=next_payload,
            selected_infra=set(added_infra_instances),
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_vm_image_defaults(
            payload=next_payload,
            selected_infra=set(added_infra_instances),
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_singleton_provider_defaults(
            payload=next_payload,
            selected_infra=set(added_infra_instances),
            infra_entries=infra_entries,
            provider_lookup=provider_lookup,
        )
        _materialize_planned_vpc_binding_tokens(next_payload)
        materialize_compute_boot_disk_defaults(
            next_payload,
            provider_lookup=provider_lookup,
        )
        if not interactive_mode:
            _require_vpc_networking_for_noninteractive(
                payload=next_payload,
                selected_infra=set(added_infra_instances),
                infra_entries=infra_entries,
                provider_lookup=provider_lookup,
            )
        gpu_app_selection = resolve_mk8s_gpu_app_selection(
            next_payload,
            selected_app_ids=selected_apps,
            app_entries=app_entries,
        )
        if gpu_app_selection.issues:
            raise RuntimeError(
                "MK8s GPU app defaults are incomplete:\n  - "
                + "\n  - ".join(gpu_app_selection.issues)
            )
        before_gpu_app_labels = set(_enabled_app_instance_labels(next_payload))
        if gpu_app_selection.auto_enabled_app_ids:
            selected_apps = set(gpu_app_selection.selected_app_ids)
            (
                identity_client_name,
                identity_tenant_id,
                identity_project_id,
                identity_region_id,
                identity_email,
            ) = _identity_values_from_payload(next_payload)
            auto_enabled_seed = _starter_component_payload(
                client_name=identity_client_name,
                tenant_id=identity_tenant_id,
                project_id=identity_project_id,
                region_id=identity_region_id,
                email=identity_email,
                selected_infra=selected_infra,
                selected_apps=selected_apps,
                infra_entries=infra_entries,
                app_entries=app_entries,
            )
            _ensure_payload_contains_component_rows(
                payload=next_payload,
                seed_payload=auto_enabled_seed,
            )
            next_payload = _filter_runtime_payload_for_selected_components(
                payload=next_payload,
                selected_infra=selected_infra,
                selected_apps=selected_apps,
                infra_entries=infra_entries,
                app_entries=app_entries,
            )
            console.print(
                f"{warning_markup('Adjusted component selection:')} enabling "
                + ", ".join(f"'apps:{item}'" for item in gpu_app_selection.auto_enabled_app_ids)
                + " because the selected MK8s GPU configuration requires them."
            )
        before_gpu_app_instances = {
            component_instance_id(row)
            for row in next_payload.get("apps", {}).get("charts", [])
            if isinstance(row, dict)
        }
        if ensure_mk8s_gpu_app_rows(next_payload, app_entries=app_entries):
            selected_apps = _enabled_ids_from_runtime_payload(
                payload=next_payload,
                entries=app_entries,
            )
            for row in next_payload.get("apps", {}).get("charts", []):
                if not isinstance(row, dict):
                    continue
                instance_id = component_instance_id(row)
                if instance_id in before_gpu_app_instances:
                    continue
                label = component_instance_label(component_type_id(row), instance_id)
                if label not in added_apps_labels:
                    added_apps_labels.append(label)
        for label in _new_enabled_app_instance_labels(
            next_payload,
            before_labels=before_gpu_app_labels,
            app_ids=gpu_app_selection.auto_enabled_app_ids,
        ):
            if "@" in label:
                with suppress(ValueError):
                    added_apps_labels.remove(label.split("@", maxsplit=1)[0])
            if label not in added_apps_labels:
                added_apps_labels.append(label)
        observability_selection = resolve_observability_app_selection(
            next_payload,
            selected_app_ids=selected_apps,
            app_entries=app_entries,
        )
        if observability_selection.issues:
            raise RuntimeError(
                "Observability app defaults are incomplete:\n  - "
                + "\n  - ".join(observability_selection.issues)
            )
        before_observability_app_labels = set(_enabled_app_instance_labels(next_payload))
        if observability_selection.auto_enabled_app_ids:
            selected_apps = set(observability_selection.selected_app_ids)
            (
                identity_client_name,
                identity_tenant_id,
                identity_project_id,
                identity_region_id,
                identity_email,
            ) = _identity_values_from_payload(next_payload)
            auto_enabled_seed = _starter_component_payload(
                client_name=identity_client_name,
                tenant_id=identity_tenant_id,
                project_id=identity_project_id,
                region_id=identity_region_id,
                email=identity_email,
                selected_infra=selected_infra,
                selected_apps=selected_apps,
                infra_entries=infra_entries,
                app_entries=app_entries,
            )
            _ensure_payload_contains_component_rows(
                payload=next_payload,
                seed_payload=auto_enabled_seed,
            )
            next_payload = _filter_runtime_payload_for_selected_components(
                payload=next_payload,
                selected_infra=selected_infra,
                selected_apps=selected_apps,
                infra_entries=infra_entries,
                app_entries=app_entries,
            )
            console.print(
                f"{warning_markup('Adjusted component selection:')} enabling "
                + ", ".join(
                    f"'apps:{item}'" for item in observability_selection.auto_enabled_app_ids
                )
                + " because the selected observability configuration requires them."
            )
        for label in _new_enabled_app_instance_labels(
            next_payload,
            before_labels=before_observability_app_labels,
            app_ids=observability_selection.auto_enabled_app_ids,
        ):
            if "@" in label:
                with suppress(ValueError):
                    added_apps_labels.remove(label.split("@", maxsplit=1)[0])
            if label not in added_apps_labels:
                added_apps_labels.append(label)
        infra_renames = _align_new_infra_instance_ids_with_resource_names(
            next_payload,
            selected_instance_ids=set(added_infra_instances),
        )
        if infra_renames:
            added_infra_instances = [
                infra_renames.get(instance_id, instance_id) for instance_id in added_infra_instances
            ]
            added_infra_labels = [
                component_instance_label(component_type_id(row), component_instance_id(row))
                for row in next_payload.get("infra", {}).get("components", [])
                if isinstance(row, dict) and component_instance_id(row) in added_infra_instances
            ]
        _materialize_single_target_app_bindings(next_payload)
        materialize_compute_boot_disk_defaults(
            next_payload,
            provider_lookup=provider_lookup,
        )
        if ensure_mysterybox_eso_app_rows(next_payload, app_entries=app_entries):
            selected_apps = _enabled_ids_from_runtime_payload(
                payload=next_payload,
                entries=app_entries,
            )
        selected_apps, nfs_csi_app_labels = _ensure_nfs_csi_app_dependency_selection(
            next_payload,
            selected_apps=selected_apps,
            app_entries=app_entries,
        )
        for label in nfs_csi_app_labels:
            if label not in added_apps_labels:
                added_apps_labels.append(label)
        _print_nfs_csi_app_dependency_adjustment(nfs_csi_app_labels)
        materialize_mk8s_gpu_app_values(next_payload)
        materialize_observability_infra_values(next_payload)
        _prune_mk8s_node_group_defaults_without_soperator(
            next_payload,
            infra_entries=infra_entries,
        )
        _refresh_soperator_registration_fingerprints(next_payload)

        add_required_field_issues = (
            _wizard_followup_required_field_issues(
                payload=next_payload,
                infra_entries=infra_entries,
            )
            if interactive_mode and not wizard_completed
            else []
        )
        if add_required_field_issues:
            _print_incomplete_wizard_no_write_warning(
                issues=add_required_field_issues,
                message="No config.yaml changes were written.",
                preserved_path=config_path.resolve(),
            )
            raise typer.Exit(code=1)

        selection_issues = _selection_change_issues(
            next_payload,
            include_app_chart_dependencies=bool(requested_apps_types),
        )
        if selection_issues:
            raise RuntimeError(
                "Component add would leave config.yaml with unresolved dependencies:\n  - "
                + "\n  - ".join(selection_issues)
            )
        _prune_redundant_app_chart_default_values(
            payload=next_payload,
            app_entries=app_entries,
        )
        _refresh_soperator_registration_fingerprints(next_payload)
        newly_enabled_app_identities = {
            (
                component_type_id(row),
                component_instance_id(row),
            )
            for row in _dynamic_enabled_app_chart_rows(next_payload)
            if (
                component_type_id(row),
                component_instance_id(row),
            )
            not in initially_enabled_app_rows
        }
        newly_enabled_app_ids = {app_id for app_id, _instance_id in newly_enabled_app_identities}
        _apply_app_release_overrides(
            payload=next_payload,
            selected_apps=newly_enabled_app_ids,
            selected_app_identities=newly_enabled_app_identities,
            namespace_overrides=app_namespace_overrides,
            release_name_overrides=app_releasename_overrides,
            version_overrides=app_version_overrides,
        )
        if validate_sources:
            final_app_ids_to_validate = _enabled_app_ids_for_new_rows(
                payload=next_payload,
                previous_identities=initially_enabled_app_rows,
            )
            selected_apps = _validate_final_enabled_app_sources_or_raise(
                payload=next_payload,
                app_entries=app_entries,
                already_validated_app_ids=source_validated_app_ids,
                candidate_app_ids=final_app_ids_to_validate,
            )
            requested_version_app_identities = {
                identity
                for identity in newly_enabled_app_identities
                if identity[0] in set(app_version_overrides)
            }
            requested_version_app_identities.update(
                _app_chart_identities_with_non_catalog_versions(
                    payload=next_payload,
                    app_entries=app_entries,
                )
                & newly_enabled_app_identities
            )
            _validate_requested_app_chart_versions_or_raise(
                payload=next_payload,
                candidate_app_identities=requested_version_app_identities,
            )

        wrote_config = _write_runtime_payload_config(config_path.resolve(), next_payload)
        if wrote_config:
            console.print(f"Updated: {config_path.resolve()}")
        else:
            console.print(f"Config up-to-date: {config_path.resolve()}")
        if not interactive_mode:
            if added_infra_labels:
                console.print("Added infra components: " + ", ".join(added_infra_labels))
            if added_apps_labels:
                console.print(
                    "Added apps components: "
                    + ", ".join(_target_aware_added_app_labels(next_payload, added_apps_labels))
                )
        if skipped_add_labels:
            console.print(
                f"{warning_markup('Skipped already-enabled components:')} "
                + ", ".join(skipped_add_labels)
            )
        if _active_chart_count(next_payload) > 0 and _config_uses_private_cluster_handoff(
            next_payload
        ):
            console.print(f"[yellow]NOTE:[/yellow] {_private_cluster_handoff_note()}")
        _print_component_edit_config_only_note()
        _print_component_edit_next_steps(config_path)
    except typer.Exit:
        raise
    except (KeyboardInterrupt, EOFError, typer.Abort):
        console.print("[yellow]Cancelled by user[/yellow].")
        raise typer.Exit(code=130) from None
    except Exception as exc:  # pragma: no cover - CLI surface
        _exit_with_error(exc)


@soperator_app.command(
    "onboard",
    short_help="Adopt one existing, supported Soperator cluster into cxcli config.",
    epilog=(
        "Examples: "
        "nebius-cxcli soperator onboard ./deployments/tenant/project/config.yaml; "
        "nebius-cxcli soperator onboard ./deployments --client-name acme "
        "--tenant-id TENANT --project-id PROJECT --region-id eu-north1 "
        "--cluster-id CLUSTER_ID --target-id existing-cluster --no-interactive. "
        "Pass a config path to update an existing project, or pass a deployments root "
        "to create a project config under the deployments root, then choose one existing "
        "Nebius MK8s cluster from the project. "
        "--cluster-id selects the Nebius MK8s cluster to adopt. --target-id is only "
        "the optional cxcli logical target id saved as deploy.targets[].instance_id; "
        "when omitted, cxcli derives it from the live cluster name. "
        "Core onboarded Soperator operations use Nebius API and Kubernetes "
        "API/kubeconfig access; they do not SSH from the operator workstation "
        "into login or worker nodes. "
        "The command proves one exact installed release against its official upstream "
        "tag and records immutable Nebius, Kubernetes, and Soperator source identity. "
        "It never chooses an upgrade target, storage migration, or compute migration. "
        "Missing, ambiguous, incomplete, or unofficial products write no Soperator target. "
        "After onboarding, inspect the separately resolved plan with "
        "soperator upgrade <config.yaml> --target <target> --dry-run, or run "
        "the upgrade directly with nebius-cxcli soperator upgrade <config.yaml> "
        "--target <target> --execute --approve."
    ),
)
def soperator_onboard_command(
    target_path: Annotated[
        Path,
        typer.Argument(
            metavar="CONFIG_OR_DEPLOYMENTS_ROOT",
            help=_SOPERATOR_ONBOARD_TARGET_ARGUMENT_HELP,
        ),
    ],
    client_name: Annotated[
        str | None,
        typer.Option(
            "--client-name",
            help=(
                "Client slug for new config creation from a deployments root "
                "(lowercase letters/digits/hyphens)."
            ),
        ),
    ] = None,
    tenant_id: Annotated[
        str | None,
        typer.Option(
            "--tenant-id",
            help="Nebius tenant identifier for new config creation from a deployments root.",
        ),
    ] = None,
    project_id: Annotated[
        str | None,
        typer.Option(
            "--project-id",
            help="Nebius project identifier for new config creation from a deployments root.",
        ),
    ] = None,
    region_id: Annotated[
        str | None,
        typer.Option(
            "--region-id",
            help=(
                "Optional Nebius region for new config creation or an expected-region "
                "assertion for an existing cluster. The live cluster region is verified."
            ),
        ),
    ] = None,
    email: Annotated[
        str | None,
        typer.Option(
            "--email",
            help="Optional notifications email for new config creation from a deployments root.",
        ),
    ] = None,
    cluster_id_opt: Annotated[
        str | None,
        typer.Option(
            "--cluster-id",
            help=(
                "Nebius MK8s cluster id to adopt, for example mk8scluster-e00.... "
                "Non-interactive onboarding uses this id to generate a temporary "
                "kubeconfig through the Nebius API."
            ),
        ),
    ] = None,
    target_id_opt: Annotated[
        str | None,
        typer.Option(
            "--target-id",
            help=(
                "Optional cxcli logical target id to save as deploy.targets[].instance_id. "
                "When omitted, cxcli derives it from the live MK8s cluster name."
            ),
        ),
    ] = None,
    kube_context_opt: Annotated[
        str | None,
        typer.Option(
            "--kube-context",
            help=(
                "Optional kubectl context override for discovery. By default cxcli uses "
                "--cluster-id to generate temporary access through the Nebius API. When "
                "provided, cxcli binds the context to --cluster-id by comparing the "
                "kube-system namespace UID through both access paths, and fails closed "
                "when either identity is unknown or they differ."
            ),
        ),
    ] = None,
    access_opt: Annotated[
        str,
        typer.Option(
            "--access",
            help=(
                "MK8s API endpoint to use when generating temporary kubeconfig from "
                "--cluster-id: external or internal."
            ),
        ),
    ] = "external",
    interactive: Annotated[
        bool,
        typer.Option(
            "--interactive/--no-interactive",
            help=(
                "Prompt for project/cluster selection when running from a terminal. "
                "Non-interactive use requires --cluster-id; --target-id is optional."
            ),
        ),
    ] = True,
) -> None:
    """Register an existing official Soperator product without choosing an upgrade path."""
    try:
        _register_existing_soperator_target(
            target_path=target_path,
            client_name=client_name,
            tenant_id=tenant_id,
            project_id=project_id,
            region_id=region_id,
            email=email,
            cluster_id=cluster_id_opt,
            target_id=target_id_opt,
            kube_context=kube_context_opt,
            access=access_opt,
            interactive=interactive,
        )
        return
    except typer.Exit:
        raise
    except (KeyboardInterrupt, EOFError, typer.Abort, _WizardQuitRequested):
        console.print("[yellow]Cancelled by user[/yellow].")
        raise typer.Exit(code=130) from None
    except Exception as exc:  # pragma: no cover - CLI surface
        _exit_with_error(exc)


_SOPERATOR_PUBLIC_DISCOVERY_RUNTIME = SoperatorPublicDiscoveryRuntime(
    handoff_spec_for_identity=_mk8s_cluster_handoff_spec_for_identity,
    write_kubeconfig_file=_write_kubeconfig_file,
    read_kubernetes_uid=_read_kube_system_namespace_uid,
    collect_snapshot=collect_kubectl_soperator_snapshot,
    command_status=_command_status,
    console=console,
)
_soperator_public_discovery_provider_observation = (
    _SOPERATOR_PUBLIC_DISCOVERY_RUNTIME.provider_observation
)
_soperator_public_discovery_provider_context = _SOPERATOR_PUBLIC_DISCOVERY_RUNTIME.provider_context
_soperator_public_discovery_region = _SOPERATOR_PUBLIC_DISCOVERY_RUNTIME.region
_run_soperator_public_discovery_command = _SOPERATOR_PUBLIC_DISCOVERY_RUNTIME.run


def _order_soperator_commands() -> None:
    commands = {
        command.name: command
        for command in soperator_app.registered_commands
        if command.name is not None
    }
    if set(commands) != set(_SOPERATOR_COMMAND_ORDER):
        raise RuntimeError("Soperator command registry differs from its canonical contract")
    soperator_app.registered_commands[:] = [commands[name] for name in _SOPERATOR_COMMAND_ORDER]


_order_soperator_commands()


@component_app.command(
    "remove",
    short_help="Remove component selectors from --config CONFIG_YAML.",
    epilog=(
        "Examples: "
        "nebius-cxcli component remove infra:mk8s "
        "--config ./deployments/tenant/project/config.yaml --no-interactive "
        "(non-interactive; removes the MK8s row and apps bound to its target_ref, unless "
        "that target is Soperator-owned). Soperator lifecycle changes are rejected."
    ),
)
def component_remove_command(
    component_ids: Annotated[
        list[str] | None,
        typer.Argument(
            metavar="[COMPONENT_SELECTOR]...",
            help=(
                "Optional enabled infra module or app chart selector(s) to remove. Use "
                "'<id>', 'infra:<id>', 'apps:<id>', 'all', 'none', '<row-id>', or "
                "'<id>@<resource-name-or-target-id>'. For scalar named infra, the "
                "row id is the normalized resource name; for target-bound app charts, "
                "it is the target id. Omit to prompt interactively. Already-absent "
                "selectors are skipped. If multiple rows match the same component "
                "type, pass the exact row id or '<id>@<resource-name-or-target-id>' "
                "to remove one config.yaml row. Removing a cluster target also "
                "removes app rows and deploy.targets[] settings bound to that target."
            ),
        ),
    ] = None,
    config_path: Annotated[
        Path | None,
        typer.Option(
            "--config",
            metavar="CONFIG_YAML",
            help=_COMPONENT_CONFIG_OPTION_HELP,
        ),
    ] = None,
    no_interactive: Annotated[
        bool,
        typer.Option(
            "--no-interactive",
            help="Disable interactive selection and confirmation prompts.",
        ),
    ] = False,
) -> None:
    """Remove enabled component rows from an existing project config.yaml.

    Flags:

      --config <config.yaml>
      --no-interactive

    Examples:

      nebius-cxcli component remove vm@worker-vm --config <config.yaml> --no-interactive

      nebius-cxcli component remove managed-postgresql@analytics-pg --config <config.yaml> --no-interactive

      nebius-cxcli component remove gateway-helm@serving-cluster --config <config.yaml> --no-interactive
    """
    try:
        _require_generic_selection_excludes_soperator(
            component_ids,
            command="component remove",
        )
        config_path = _require_component_config_option(config_path)
        payload = _read_config_payload(config_path.resolve())
        interactive_mode = not no_interactive

        infra_entries = _with_infra_provider_groups(component_entries("infra"))
        app_entries = tuple(
            entry for entry in component_entries("apps") if entry.id != _SOPERATOR_APP_ID
        )
        infra_lookup = {entry.id: entry for entry in infra_entries}
        enabled_infra_specs = _enabled_component_instance_specs(
            payload,
            scope="infra",
            entries=infra_entries,
        )
        enabled_app_specs = _enabled_component_instance_specs(
            payload,
            scope="apps",
            entries=app_entries,
        )

        raw_tokens = _split_multi_value_tokens(component_ids)
        skipped: tuple[str, ...] = ()
        if not raw_tokens and interactive_mode:
            requested_infra_instances = _prompt_component_instance_selection(
                action="remove",
                scope="infra",
                specs=tuple(enabled_infra_specs),
            )
            requested_app_instances = _prompt_component_instance_selection(
                action="remove",
                scope="apps",
                specs=tuple(enabled_app_specs),
            )
            remove_targets = [
                *(
                    _ComponentRemoveTarget(
                        scope="infra",
                        component_id=str(row["id"]),
                        instance_id=str(row["instance_id"]),
                    )
                    for _entry, row in enabled_infra_specs
                    if str(row["instance_id"]) in requested_infra_instances
                ),
                *(
                    _ComponentRemoveTarget(
                        scope="apps",
                        component_id=str(row["id"]),
                        instance_id=str(row["instance_id"]),
                    )
                    for _entry, row in enabled_app_specs
                    if str(row["instance_id"]) in requested_app_instances
                ),
            ]
        elif not raw_tokens and not interactive_mode:
            raise RuntimeError(
                "Specify at least one component id, or omit --no-interactive to choose components interactively."
            )
        else:
            remove_targets, skipped = _resolve_component_remove_targets(
                tokens=raw_tokens,
                payload=payload,
                infra_entries=infra_entries,
                app_entries=app_entries,
            )
            for component_id in skipped:
                console.print(
                    f"{warning_markup('Skipped already-absent component:')} {component_id}"
                )

        soperator_target_refs = set(_soperator_lifecycle_target_refs(payload))
        if any(
            target.component_id == _SOPERATOR_APP_ID
            or (target.scope == "infra" and target.instance_id in soperator_target_refs)
            for target in remove_targets
        ):
            raise RuntimeError(
                "`nebius-cxcli component remove` cannot remove a Soperator app or its "
                "cluster target. Use `nebius-cxcli soperator destroy CONFIG --target TARGET`."
            )

        _config, _paths = _load_context(config_path)
        payload = _load_config_payload(config_path.resolve())

        if not remove_targets:
            console.print("No components selected for remove.")
            if skipped:
                console.print(f"Config up-to-date: {config_path.resolve()}")
                _print_component_edit_next_steps(config_path)
            return

        if interactive_mode and not _wizard_continue_phase(
            "Remove selected components from config.yaml now?",
            default=None,
        ):
            console.print("No component changes applied.")
            return

        next_payload = copy.deepcopy(payload)
        removed_infra_labels: list[str] = []
        removed_app_labels: list[str] = []
        removed_cluster_targets: set[str] = set()
        for target in remove_targets:
            removed = _remove_component_instance_row(
                payload=next_payload,
                scope=target.scope,
                instance_id=target.instance_id,
                component_id=target.component_id,
            )
            if removed is None:
                continue
            label = component_instance_label(target.component_id, target.instance_id)
            if target.scope == "infra":
                removed_infra_labels.append(label)
                removed_entry = infra_lookup.get(target.component_id)
                if removed_entry is not None and removed_entry.handoff is not None:
                    removed_cluster_targets.add(target.instance_id)
            else:
                removed_app_labels.append(label)
        if removed_cluster_targets:
            removed_target_app_labels = _remove_target_scoped_app_rows(
                payload=next_payload,
                target_instance_ids=removed_cluster_targets,
            )
            for label in removed_target_app_labels:
                if label not in removed_app_labels:
                    removed_app_labels.append(label)
            _remove_deploy_target_rows(
                payload=next_payload,
                target_instance_ids=removed_cluster_targets,
            )
        selection_issues = _selection_change_issues(next_payload)
        if selection_issues:
            raise RuntimeError(
                "Component remove would leave config.yaml with unresolved dependencies:\n  - "
                + "\n  - ".join(selection_issues)
            )

        wrote_config = _write_runtime_payload_config(config_path.resolve(), next_payload)
        if wrote_config:
            console.print(f"Updated: {config_path.resolve()}")
        else:
            console.print(f"Config up-to-date: {config_path.resolve()}")
        console.print(
            "Removed infra components: "
            + (", ".join(removed_infra_labels) if removed_infra_labels else "(none)")
        )
        console.print(
            "Removed apps components: "
            + (", ".join(removed_app_labels) if removed_app_labels else "(none)")
        )
        _print_component_edit_config_only_note()
        _print_component_edit_next_steps(config_path)
    except (KeyboardInterrupt, EOFError, typer.Abort):
        console.print("[yellow]Cancelled by user[/yellow].")
        raise typer.Exit(code=130) from None
    except Exception as exc:  # pragma: no cover - CLI surface
        _exit_with_error(exc)


@app.command(
    "bootstrap-ci",
    short_help="Use CONFIG_YAML to reconcile the customer GitHub workflow, email settings, and optional CI auth.",
    epilog=(
        "Examples: "
        "nebius-cxcli bootstrap-ci ./deployments/tenant/project/config.yaml "
        "(reconciles .github/workflows, email config, and canonical project auth secrets); "
        "nebius-cxcli bootstrap-ci ./config.yaml --github-repo acme/cluster-config --cli-ref main "
        "(customizes the CI workflow's repo and cxcli branch ref)."
    ),
)
def bootstrap_ci_command(
    config_path: Annotated[
        Path,
        typer.Argument(
            metavar="CONFIG_YAML",
            help=(
                "Path to project config.yaml inside the target customer git repository "
                "(<tenant-folder>/<project-folder>/config.yaml). The file must already exist inside that repo checkout."
            ),
        ),
    ],
    github_repo: Annotated[
        str | None,
        typer.Option(
            "--github-repo",
            help=(
                "Optional override for the target GitHub repository slug '<owner>/<repo>' "
                "used for workflow bootstrap reconciliation, email setting sync, and optional Nebius auth bootstrap. "
                "Normally auto-detected from the target repository origin remote."
            ),
        ),
    ] = None,
    github_token_env: Annotated[
        str,
        typer.Option(
            "--github-token-env",
            help=(
                "Environment variable name holding the GitHub token used for GitHub workflow/environment reconciliation, "
                "email setting sync, and optional auth bootstrap (falls back to GH_TOKEN/GITHUB_TOKEN)."
            ),
        ),
    ] = "GH_TOKEN",
    cli_ref: Annotated[
        str | None,
        typer.Option(
            "--cli-ref",
            help=(
                "Git ref used by the generated customer workflow when it installs nebius-cxcli "
                "(branch, tag, or commit SHA). Defaults to the current release tag for stable "
                "builds, otherwise 'main'."
            ),
        ),
    ] = None,
) -> None:
    """Generate or reconcile the CLI-managed customer GitHub workflow and environment settings for one project config.yaml."""
    try:
        config, paths = _load_context(config_path)
        resolved_cli_ref = str(cli_ref or "").strip() or default_cli_ref()
        repo_root = _require_git_root(paths.deployments_dir)
        github_environment = _github_environment_name_for_identity(
            client_name=str(config.client_info.client_name),
            project_id=str(config.client_info.nebius.project_id),
        )
        resolved_github_repo, github_token = _resolve_bootstrap_ci_github_target(
            github_repo=github_repo,
            github_token_env=github_token_env,
            repo_root=repo_root,
        )
        email_settings = _load_local_email_settings()
        workflow = _ensure_ci_workflow_for_deployments_root(
            deployments_root=paths.deployments_dir,
            cli_ref=resolved_cli_ref,
        )
        gitignore_result = _ensure_deployments_gitignore(
            deployments_root=paths.deployments_dir,
        )

        material = _runtime_auth_cache_material(
            project_id=str(config.client_info.nebius.project_id),
            client_name=str(config.client_info.client_name),
        )
        if material is None:
            raise RuntimeError("Canonical runtime auth cache is missing after project preflight")
        material = _ensure_runtime_auth_s3_material(material)
        _export_runtime_auth_material(material)
        _synced_repo, _synced_environment, synced_auth_secrets = (
            _sync_runtime_auth_profile_to_ci_environment(
                material=material,
                client_name=str(config.client_info.client_name),
                github_repo=github_repo,
                github_token_env=github_token_env,
                repo_root_hint=workflow.repo_root,
            )
        )
        email_sync = _sync_github_email_settings(
            repo_slug=resolved_github_repo,
            github_environment=github_environment,
            github_token=github_token,
            settings=email_settings,
        )

        console.print(f"Repository root: {workflow.repo_root}")
        if resolved_github_repo:
            console.print(f"GitHub repository: {resolved_github_repo}")
        if workflow.wrote_workflow:
            if workflow.replaced_workflow:
                console.print(f"Updated: {workflow.workflow_file}")
            else:
                console.print(f"Created: {workflow.workflow_file}")
        else:
            console.print(f"Workflow already aligned: {workflow.workflow_file}")
        if gitignore_result.path is not None:
            if gitignore_result.wrote:
                console.print(f"Ensured deployments .gitignore: {gitignore_result.path}")
            else:
                console.print(f"Deployments .gitignore up-to-date: {gitignore_result.path}")
        console.print(f"GitHub environment: {github_environment}")
        console.print(f"Workflow CLI ref: {resolved_cli_ref}")
        if email_settings.enabled:
            console.print(
                "Email settings synced: "
                f"{len(email_sync.updated_vars)} environment variable(s), "
                f"{len(email_sync.updated_secrets)} secret(s)"
            )
            if email_sync.removed_vars or email_sync.removed_secrets:
                console.print(
                    "Removed stale email settings: "
                    f"{len(email_sync.removed_vars)} environment variable(s), "
                    f"{len(email_sync.removed_secrets)} secret(s)"
                )
        else:
            if email_sync.removed_vars or email_sync.removed_secrets:
                console.print(
                    "Local email settings are disabled; cleared GitHub email settings: "
                    f"{len(email_sync.removed_vars)} environment variable(s), "
                    f"{len(email_sync.removed_secrets)} secret(s)"
                )
            else:
                console.print(
                    "Local email settings are disabled and GitHub email settings are already absent."
                )
        console.print(f"Canonical Nebius auth secrets synced: {len(synced_auth_secrets)} secret(s)")
        console.print("CI bootstrap completed.")
    except Exception as exc:  # pragma: no cover - CLI surface
        _exit_with_error(exc)


